void input(){
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) scanf("%d", &p[i]);
}

void dfs(int x, int lab){
    visited[x] = lab;
    if (visited[p[x]] == 0) dfs(p[x], lab); else
    if (visited[p[x]] == lab) s = x;
}

void init(){
    int c = 0;
    for (int i = 1; i <= n; i++) adj[p[i]].push_back(i);
    for (int i = 1; i <= n; i++)
        if (!visited[i]) {
            c++;
            dfs(i, c);
        }
    int u = s; c = 1;
    visited[s] = -1;
    while (p[u] != s){
        u = p[u];
        visited[u] = -1;
        c++;
    }
}

void cal(int x){
    int cnt[4] = {0, 0, 0, 0};
    for (int i = 0; i < adj[x].size(); i++)
    if (visited[adj[x][i]] != -1){
        cal(adj[x][i]);
        cnt[val[adj[x][i]]] = 1;
    }
    val[x] = 0;
    while (cnt[val[x]] != 0) val[x]++;
}

void solve(){
    if (c == n){
        if (c % 2 == 0) cout << "POSSIBLE" << endl; else cout << "IMPOSSIBLE" << endl;
        return;
    }
    for (int i = 1; i <= n; i++)
        if (visited[i] == -1) cal(i);
    int turn = 0;
    bool check = false;
    while (!check){
        turn++;
        if (turn == 4) {
            cout << "IMPOSSIBLE" << endl;
            return;
        }
        check = true;
        int u = s;
        do {
            int cnt[4] = {0, 0, 0, 0};
            for (int i = 0; i < adj[u].size(); i++)
                cnt[val[adj[u][i]]] = 1;
            int tmp = 0;
            while (cnt[tmp] != 0) tmp++;
            if (val[u] != tmp){
                check = false;
                val[u] = tmp;
            }
            u = p[u];
        } while (u != s);
    }
    cout << "POSSIBLE" << endl;
//    cout << s << endl;
//    for (int i = 1; i <= n; i++) cout << val[i] << ' ';
}

