namespace scc_space
{
	void dfs(int v_, vector<bool>&used_, vector<int>G_[], vector<int>&vs_)
	{
		used_[v_] = true;
		for (int nxt : G_[v_])
		{
			if (!used_[nxt])dfs(nxt, used_, G_, vs_);
		}
		vs_.push_back(v_);
	}

	void rdfs(int v_, int k_, vector<bool>&used_, vector<vector<int>>&rG_, vector<int>&top)
	{
		used_[v_] = true;
		top[v_] = k_;
		for (int nxt : rG_[v_])
		{
			if (!used_[nxt])rdfs(nxt, k_, used_, rG_, top);
		}
	}
}

//頂点数n_のグラフG_の強連結成分分解をする
//topに強連結成分のトポロジカル順序が格納される
//(top[i]==top[j]のとき、iとjは強連結である。)
//戻り値:強連結成分の個数
int scc(vector<int>G_[], int n_, vector<int>&top)
{
	using namespace scc_space;
	top.resize(n_);
	vector<vector<int>>rG_(n_);
	for (int i = 0; i < n_; ++i)
	{
		for (int to : G_[i])
		{
			rG_[to].push_back(i);
		}
	}
	vector<bool>used(n_, false);
	vector<int>vs;
	for (int v = 0; v < n_; ++v)
	{
		if (!used[v])dfs(v, used, G_, vs);
	}
	fill(used.begin(), used.end(), false);
	int k = 0;
	for (int i = vs.size() - 1; i >= 0; --i)
	{
		if (!used[vs[i]])rdfs(vs[i], k++, used, rG_, top);
	}
	return k;
}

vector<int>path[234567 * 6];//mod 6ごとに0,1,2,非0,非1,非2

vector<int>graph[234567];
int invgr[234567];
int N;

bool firstpath[234567];
int f(int v)
{
	if (firstpath[v])return v;
	firstpath[v] = true;
	return f(invgr[v]);
}

int br(int v)
{
	if (graph[v].size() == 0)return 0;
	assert(graph[v].size() == 1);
	return 1 + br(graph[v][0]);
}

int main(void)
{
	cin >> N;
	for (int i = 0; i < N; ++i)
	{
		int p;
		cin >> p;
		--p;
		graph[p].push_back(i);
		invgr[i] = p;
	}
	int v = f(0);
	vector<int>cycle;
	cycle.push_back(v);
	int now = v;
	for (;;)
	{
		now = invgr[now];
		if (now == cycle.front())break;
		cycle.push_back(now);
	}
	int period = cycle.size();
	//cycle.push_back(cycle.front());
	for (int i = 0; i < period; ++i)
	{
		//cycle[i] <- cycle[i+1]
		int S = i;
		int T = (i + 1) % period;
		int lef = cycle[S];
		int now = cycle[T];
		if (graph[now].size() == 1)
		{
			//0->1
			//1->0
			//2->0
			path[S * 6 + 0].push_back(T * 6 + 0 + 3);
			path[S * 6 + 0].push_back(T * 6 + 1 + 0);
			path[S * 6 + 0].push_back(T * 6 + 2 + 3);
			path[S * 6 + 1].push_back(T * 6 + 0 + 0);
			path[S * 6 + 1].push_back(T * 6 + 1 + 3);
			path[S * 6 + 1].push_back(T * 6 + 2 + 3);
			path[S * 6 + 2].push_back(T * 6 + 0 + 0);
			path[S * 6 + 2].push_back(T * 6 + 1 + 3);
			path[S * 6 + 2].push_back(T * 6 + 2 + 3);
		}
		else
		{
			assert(graph[now].size() == 2);
			int down = -1;
			if (graph[now][0] != lef)
			{
				down = graph[now][0];
			}
			else if (graph[now][1] != lef)
			{
				down = graph[now][1];
			}
			//else assert(false); 
			int dnum = br(down) % 2;
			if (dnum == 0)
			{
				//0->1
				//1->2
				//2->1
				path[S * 6 + 0].push_back(T * 6 + 0 + 3);
				path[S * 6 + 0].push_back(T * 6 + 1 + 0);
				path[S * 6 + 0].push_back(T * 6 + 2 + 3);
				path[S * 6 + 1].push_back(T * 6 + 0 + 3);
				path[S * 6 + 1].push_back(T * 6 + 1 + 3);
				path[S * 6 + 1].push_back(T * 6 + 2 + 0);
				path[S * 6 + 2].push_back(T * 6 + 0 + 3);
				path[S * 6 + 2].push_back(T * 6 + 1 + 0);
				path[S * 6 + 2].push_back(T * 6 + 2 + 3);
			}
			else
			{
				//0->2
				//1->0
				//2->0
				path[S * 6 + 0].push_back(T * 6 + 0 + 3);
				path[S * 6 + 0].push_back(T * 6 + 1 + 3);
				path[S * 6 + 0].push_back(T * 6 + 2 + 0);
				path[S * 6 + 1].push_back(T * 6 + 0 + 0);
				path[S * 6 + 1].push_back(T * 6 + 1 + 3);
				path[S * 6 + 1].push_back(T * 6 + 2 + 3);
				path[S * 6 + 2].push_back(T * 6 + 0 + 0);
				path[S * 6 + 2].push_back(T * 6 + 1 + 3);
				path[S * 6 + 2].push_back(T * 6 + 2 + 3);
			}
		}
	}
	vector<int>top;
	scc(path, period * 6, top);
	for (int i = 0; i < period; ++i)
	{
		for (int d = 0; d < 3; ++d)
		{
			if (top[i * 6 + d] == top[i * 6 + d + 3])
			{
				//i = 非i
				cout << "IMPOSSIBLE\n";
				return 0;
			}
			if (top[i * 6 + d] == top[i * 6 + (d + 1) % 3])
			{
				//i = (i+1)
				cout << "IMPOSSIBLE\n";
				return 0;
			}
		}
		int not0 = top[i * 6 + 3];
		int not1 = top[i * 6 + 4];
		int not2 = top[i * 6 + 5];
		if (not0 == not1 && not1 == not2)
		{
			cout << "IMPOSSIBLE\n";
			return 0;
		}
	}
	cout << "POSSIBLE\n";
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int N=2e5+10;
int n,pre[N],deg[N],q[N],size,vis[N],C,ans[N];
vector<int> e[N];
bool test(int x){
	q[size=1]=x;
	for (int i=1;i<=size;i++){
		int v=q[i];
		C++;
		for (int j=0;j<e[v].size();j++) vis[ans[e[v][j]]]=C;
		while (vis[ans[v]]==C) ans[v]++;
		if (!--deg[pre[v]]) q[++size]=pre[v];
	}
	for (int i=1;i<=n;i++){
		C++;
		for (int j=0;j<e[i].size();j++) vis[ans[e[i][j]]]=C;
		int Ans=0;
		while (vis[Ans]==C) Ans++;
		if (Ans!=ans[i]) return 0;
	}
	return 1;
}
int circle;
void find_cir(int x){
	static int vis[N],C;C++;
	while (!vis[x]) vis[x]=C,x=pre[x];
	if (vis[x]==C) circle=x;
}
int Deg[N],Ans[N];
void work(){
	for (int i=1;i<=n;i++) find_cir(i);
	int x=circle;
	for (int i=1;i<=n;i++) Deg[i]=deg[i],Ans[i]=ans[i];
	C++;
	for (int i=0;i<e[x].size();i++) if (!deg[e[x][i]]) vis[ans[e[x][i]]]=C;
	while (vis[ans[x]]==C) ans[x]++;
	deg[pre[x]]--;deg[x]--;
	if (test(pre[x])) return;
	for (int i=1;i<=n;i++) deg[i]=Deg[i],ans[i]=Ans[i];
	C++;
	for (int i=0;i<e[x].size();i++) if (!deg[e[x][i]]) vis[ans[e[x][i]]]=C;
	while (vis[ans[x]]==C) ans[x]++;
	for (ans[x]++;vis[ans[x]]==C;ans[x]++);
	deg[pre[x]]--;deg[x]--;
	if (!test(pre[x])) puts("IMPOSSIBLE"),exit(0);
}
int main()
{
	scanf("%d",&n);
	for (int i=1;i<=n;i++) scanf("%d",&pre[i]),e[pre[i]].push_back(i);
	for (int i=1;i<=n;i++) deg[i]=e[i].size();
	for (int i=1;i<=n;i++) if (!deg[i]) q[++size]=i;
	for (int i=1;i<=size;i++){
		int v=q[i];
		C++;
		for (int j=0;j<e[v].size();j++) vis[ans[e[v][j]]]=C;
		while (vis[ans[v]]==C) ans[v]++;
		if (!--deg[pre[v]]) q[++size]=pre[v];
	}
	if (size!=n) work();
	puts("POSSIBLE");
	return 0;
}

#include<cstdio>
const int MaxN=200010;
int N,p[MaxN],deg[MaxN],stk[MaxN];
struct edge{int to;edge*next;}E[MaxN],*fir[MaxN];
bool vis[MaxN];
int f[MaxN][2],cir[MaxN],len,nxt[MaxN*2];
int dfn[MaxN*2],now=1;
void work(){

	for(int i=1;i<=N;i++){
		scanf("%d",p+i);
		deg[p[i]]++;
		E[i]=(edge){i,fir[p[i]]};
		fir[p[i]]=E+i;
	}
	int*tp=stk;
	for(int i=1;i<=N;i++)if(!deg[i])*tp++=i;
	while(tp>stk){
		int x=*--tp;
		for(edge*e=fir[x];e;e=e->next)vis[*f[e->to]]=1;
		while(vis[*f[x]])++*f[x];
		for(edge*e=fir[x];e;e=e->next)vis[*f[e->to]]=0;
		if(!--deg[p[x]])*tp++=p[x];
	}
	int o=0;
	for(int i=1;!o;i++)if(deg[i])o=i;
	for(int i=o;;){
		cir[len++]=i;
		for(edge*e=fir[i];e;e=e->next)if(!deg[e->to])vis[*f[e->to]]=1;
		while(vis[*f[i]])++*f[i];
		for(f[i][1]=*f[i]+1;vis[f[i][1]];++f[i][1]);
		for(edge*e=fir[i];e;e=e->next)if(!deg[e->to])vis[*f[e->to]]=0;
		if((i=p[i])==o)break;
	}
	for(int i=0;i<len;i++){
		nxt[i]=(i+1)%len+(f[cir[i]][0]==f[cir[(i+1)%len]][0])*len;
		nxt[i+len]=(i+1)%len+(f[cir[i]][1]==f[cir[(i+1)%len]][0])*len;
	}
	for(int i=0;i<len;i++){
		int la=now,x=i,mv=now;
		while(!dfn[x]){
			dfn[x]=now++;
			if(x<len)mv=dfn[x];
			x=nxt[x];
		}
		if(dfn[x]>=la&&now-dfn[x]==len&&mv>=dfn[x]){
			puts("POSSIBLE");
			return;
		}
	}
	puts("IMPOSSIBLE");
}
int main(){
	//freopen("in.txt","r",stdin);
	//freopen("out.txt","w",stdout);
	while(scanf("%d",&N)==1){
		for(int i=1;i<=N;i++)fir[i]=0,deg[i]=*f[i]=dfn[i-1]=dfn[i+N-1]=0;
		now=1;len=0;
		work();
	}
}

#include<bits/stdc++.h>
using namespace std;
const int N=2050000;
inline int rd(register int x=0,register char ch=getchar(),register int f=0){
	for(;!isdigit(ch);ch=getchar()) f=ch=='-';
	for(;isdigit(ch);ch=getchar()) x=(x<<1)+(x<<3)+ch-48;
	return f?-x:x;
}
int n,B;
int head[N],to[N<<1],nxt[N<<1],sta[N],vis[N],a[N],al[N];
vector<int> scc;

void lnk(int x,int y){
	to[++B]=y,nxt[B]=head[x],head[x]=B;
}
void dfs(int x,int prt){
	if(vis[x]){
		//printf("-> %d %d %d %d\n",x,prt,vis[x],sta[0]);
		for(int i=vis[x];i<=sta[0];++i) scc.push_back(sta[i]);
		return;
	}
	sta[++sta[0]]=x,vis[x]=sta[0];
	for(int i=head[x];i;i=nxt[i]) if(to[i]!=prt) dfs(to[i],x);
	vis[x]=0;--sta[0];
}
void DFS(int x,int prt){
	for(int i=head[x];i;i=nxt[i]) if(to[i]!=prt&&!vis[to[i]]) DFS(to[i],x);
	for(int i=head[x];i;i=nxt[i]) if(to[i]!=prt&&!vis[to[i]]) al[a[to[i]]]=1;
	while(al[a[x]]) ++a[x];
	for(int i=head[x];i;i=nxt[i]) if(to[i]!=prt&&!vis[to[i]]) al[a[to[i]]]=0;
}
int main(){
	n=rd();
	for(int i=1;i<=n;++i) lnk(rd(),i);
	for(int i=1;i<=n;++i) if(!scc.size()) dfs(i,0);
	for(auto x:scc) vis[x]=1;
	for(auto x:scc) DFS(x,0);
	int mx=-n-100,mn=n+100;
	for(auto x:scc) mx=max(mx,a[x]),mn=min(mn,a[x]);
	puts((mx==mn&&scc.size()%2!=0)?"IMPOSSIBLE":"POSSIBLE");
}

#include <bits/stdc++.h>
#define int long long
#define P(x) cout << x << endl
#define D(x) P(#x << ": " << x)
#define F(i,n) for (int i=0; i<(int)(n); i++)
#define DEC(i,n) for (int i=(int)(n); --i>=0;)
#define S(s) (int)((s).size())
#define ALL(v) v.begin(), v.end()
#define MI(a,v) a = min(a,(v))
#define MA(a,v) a = max(a,(v))
#define V vector
#define pb push_back
#define mt make_tuple
using namespace std;
const int N=2e5;
int n, p[N], ass[N];
V<int> ch[N];
bitset<N> vis;

int se(V<int> a) {
    sort(ALL(a));
    int cur = 0;
    F(i,S(a)) {
        if (a[i] != i)
            break;
        cur++;
    }
    return cur;
}

// false if cycle
bool assign(int u, int root) {
    if (vis[u]) return true;
    vis[u] = true;
    V<int> chv;
    for (int v : ch[u]) {
        if (v == root)
            return false;
        else if (!assign(v, root))
            return false;
        else {
            chv.pb(ass[v]);
        }
    }
    ass[u] = se(chv);
    return true;
}

bool test(V<int> cy, int x) {
    //P(x);
    int val[S(cy)+1];
    val[0] = x;
    F(i,S(cy)+1) if (i) {
        int pre = cy[i-1], cur = cy[i%S(cy)];
        V<int> chv;
        for (int v : ch[cur]) if (v != pre)
            chv.pb(ass[v]);
        chv.pb(val[i-1]);
        val[i] = se(chv);
    }
    //F(i,S(cy)+1) cout<<val[i]<<" \n"[i==S(cy)];
    return (val[S(cy)] == x);
}

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cin>>n;
    F(i,n) {
        cin>>p[i];
        p[i]--;
        ass[i] = -1;
        ch[p[i]].pb(i);
    }
    F(i,n) assign(i, i);
    //F(i,n) cout<<ass[i]<<" \n"[i==n-1];
    int start=-1;
    F(i,n) if (ass[i]==-1) {
        start = i;
        break;
    }
    V<int> cy;
    cy.pb(start);
    int cur=p[start];
    while (cur != start) {
        cy.pb(cur);
        cur = p[cur];
    }
    //for (int u : cy) P(u);
    //P("");
    V<int> chstart;
    for (int v : ch[start]) if (ass[v] != -1)
        chstart.pb(ass[v]);
    int sse = se(chstart);
    chstart.pb(sse);
    int sse2 = se(chstart);
    if (!(test(cy, sse) || test(cy, sse2)))
        cout<<"IM";
    P("POSSIBLE");
}

#include <algorithm>
