const int N = 2e5 + 5; 
using namespace std; 

int n, fa[N], head[N], cnte, vis[N], cir[N], mex[N];
struct edge { int to, nxt; } e[N << 1]; 

template < typename T >
inline T read()
{
	T x = 0, w = 1; char c = getchar();
	while(c < '0' || c > '9') { if(c == '-') w = -1; c = getchar(); }
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x * w; 
}

inline void adde(int u, int v) { e[++cnte] = (edge) { v, head[u] }, head[u] = cnte; }

void dfs(int u)
{
	for(int i = head[u]; i; i = e[i].nxt)
		if(!cir[e[i].to]) dfs(e[i].to);
	for(int i = head[u]; i; i = e[i].nxt)
		if(!cir[e[i].to]) vis[mex[e[i].to]] = 1;
	int x = 0;
	while(vis[x]) x++;
	mex[u] = x;
	for(int i = head[u]; i; i = e[i].nxt)
		if(!cir[e[i].to]) vis[mex[e[i].to]] = 0; 
}

int main()
{
#ifndef ONLINE_JUDGE
	freopen("cpp.in", "r", stdin); 
#endif
	n = read <int> ();
	for(int i = 1; i <= n; i++) fa[i] = read <int> (), adde(fa[i], i);
	int u = 1;
	while(!vis[u]) vis[u] = 1, u = fa[u];
	for(int i = 0; i <= n; i++) vis[i] = 0; 
	while(!cir[u]) cir[u] = 1, u = fa[u];
	int mn = n + 1, mx = 0, cnt = 0;
	for(int i = 1; i <= n; i++)
	{
		if(!cir[i]) continue;
		dfs(i), cnt++;
		mx = max(mx, mex[i]), mn = min(mn, mex[i]); 
	}
	puts((mx == mn) && (cnt & 1) ? "IMPOSSIBLE" : "POSSIBLE"); 
	return 0; 
}

