const int N = 500000;
int n;
int a[N], used[N], out[N], cycle[N], p[N], mark[N], t, b[N], q[N], k[N];
set < pair < int, int > > s;
vector < int > g[N], G[N], in[N], c[N];
void dfs(int v){
    used[v] = 1;
    for (auto u: g[v]){
        if (u != p[v] && used[u] == 1 && cycle[u] == 0){
            cycle[v] = 1;
            while(v != u){
                v = p[v];
                cycle[v] = 1;

            }
        } else
        if (used[u] == 0){
            p[u] = v;
            dfs(u);
        }
    }
    used[v] = 2;
}
bool check(int v){
    t = -1;
    int res = -1;
    for (auto u: G[v]){
        t = max(t, mark[u]);
        b[mark[u]] = 1;
    }
    for (int i = 0; i <= t + 1; i++){
        if (b[i] == 0 && res == -1){
            res = i;
        }
        b[i] = 0;
    }
    return res;
}
void tr(int V, int x){
    for (auto i: c[V]) if (x == i) return;
    for (int j = 0; j <= n; j++){
        if (!cycle[j]) continue;
        q[j] = 0;
        mark[j] = 0;
    }
    int pr;
    mark[V] = x;
    int v = V;
    for (auto u: in[V]) if (cycle[u]) v = u;
    pr = x;
    int ff = 0;
    while(v != V){
        int y = 0;
        for (auto u: c[v]){
            y = max(y, u);
            b[u] = 1;
        }
        b[pr] = 1;
        y = max(b[pr], y);
        for (int j = 0; j <= y + 1; j++){
            if (b[j] == 0){
                if (q[v] == 1) continue;
                mark[v] = j;
                q[v] = 1;
            }
            b[j] = 0;
        }
        pr = mark[v];
        for (auto u: in[v]) if (cycle[u]) v = u;
    }
    if (pr == mark[V]) return;
    int y = mark[V];
    int z = 1;
    for (auto u: G[v]){
        y = max(mark[u], y);
        b[mark[u]] = 1;
    }
    for (int i = 0; i <= mark[V]; i++){
        if (b[i] == 0 && i < mark[V]) z = 0;
        b[i] = 0;
    }
    if (!z) return;
    cout << "POSSIBLE";
    exit(0);
}
