    cin >> n;
    for (int i = 1; i <= n; i++){
        int u, v;
        cin >> u;
        v = i;
        g[u].pb(v);
        g[v].pb(u);
        G[u].pb(v);
        in[v].pb(u);
        out[u]++;
    }
    dfs(1);
    for (int i = 1; i <= n; i++) s.insert({out[i], i});
    while(1){
        auto x = *s.begin();
        s.erase(s.begin());
        if (x.F != 0) break;
        if (cycle[x.S]) continue;
        int f = check(x.S);
        mark[x.S] = f;
        for (auto u: in[x.S]){
            s.erase({out[u], u});
            out[u]--;
            s.insert({out[u], u});
        }
    }
    for (int i = 1; i <= n; i++) k[i] = -1;
    for (int i = 1; i <= n; i++)
    if (cycle[i]){
        for (auto u: G[i]){
            if (cycle[u]) continue;
            c[i].pb(mark[u]);
            k[i] = max(k[i], mark[u]);
        }
    }
    for (int i = 1; i <= n; i++)
    if (cycle[i]){
        vector < int > cand;
        for (auto j: c[i]) b[j] = 1;
        for (int j = 0; j <= n + 2; j++){
            if (b[j] == 0) cand.pb(j);
            b[j] = 0;
        }
        tr(i, cand[0]);
        tr(i, cand[1]);
        cout << "IMPOSSIBLE";
        return 0;
    }
}

