bool dfs_findloop(int v){
    used[v]=true;
    bool res=true;
    for(int u:G[v]){
        if(!used[u])res &= !dfs_findloop(u);
        else res=false;
    }
    if(!res)loop.push_back(v);
    return !res;
}

void add_G(int from,int to){
    G[from].push_back(to);
    rG[to].push_back(from);
}

int dfs_grundy(int v){
    set<int> used_g;
    for(int u:G[v])used_g.insert(dfs_grundy(u));
    int res=0;
    while(true){
        if(used_g.count(res)==0)return res;
        res++;
    }

}

int dfs_solve(int v,int k){
    used[v]=true;
    int rec;
    if(k==grundyP[v].first)rec = grundyP[v].second;
    else rec=grundyP[v].first;
    for(int u:G[v])if(isloop[u]&&!used[u])return dfs_solve(u,rec);
    return rec;
}


