inline int get(int now)
{
	cnt++;
	for(int e=first[now];e;e=edges[e].next)
		visit[edges[e].val]=cnt;
	int i;
	for(i=0;visit[i]==cnt;i++);
	return i;
}
int main()
{
	int n;
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		scanf("%d",&outgo[i]);
		du[outgo[i]]++;
	}
	queue<int> q;
	for(int i=1;i<=n;i++)
		if(!du[i])
			q.push(i);
	int visitcnt=0;
	while(!q.empty())
	{
		int now=q.front();
		q.pop();
		visitcnt++;
		int to=outgo[now];
		a[now]=get(now);
		te++;
		edges[te].val=a[now];
		edges[te].next=first[to];
		first[to]=te;
		if(!(--du[to]))
			q.push(to);
	}
	if((n-visitcnt)%2==0)
	{
		puts("POSSIBLE");
		return 0;
	}
	int k=-1;
	for(int i=1;i<=n;i++)
		if(du[i])
		{
			int tmp=get(i);
			if(k==-1)
				k=tmp;
			if(k!=tmp)
			{
				puts("POSSIBLE");
				return 0;
			}
		}
	puts("IMPOSSIBLE");
	return 0;
}

