    used[v]=1;
    int rec =(k==grundyP[v][0] ? grundyP[v][1] : grundyP[v][0]);
    for(int u:rG[v])if((isloop[u])&&(used[u]==0))return dfs_solve(u,rec);
    return rec;
}


