const int MAXN = 2e5 + 5;

struct Edge
{
	int next,to;
}e[MAXN];
int head[MAXN],etot=0;
inline void add(int u,int v)
{
	e[++etot]=(Edge){ head[u],v};
	head[u]=etot;
}

int pre[MAXN];

vector<int> cir;
bool vis[MAXN];
int dfs_cir(int u)
{
	vis[u] = 1;
	for(int i=head[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(vis[v]){ cir.push_back(u); return v;}

		int res = dfs_cir(v);
		if(res){ cir.push_back(u); return res==u? 0: res;}
	}
	return 0;
}

bool incir[MAXN];

int val[MAXN];
vector<int> nxt[MAXN];
void get_val(int u)
{
	for(int i=head[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(incir[v]) continue;
		get_val(v);

		nxt[u].push_back(val[v]);
	}

	sort(nxt[u].begin(),nxt[u].end());

	int need = 0;
	for(int i=0; i<(int)nxt[u].size(); ++i)
	{
		if(nxt[u][i] > need){ val[u] = need; return;}
		if(nxt[u][i] == need) ++need;
	}
	val[u] = need;
}

bool check(int val_lst)
{
	int lst = val_lst;

	for(int k=0; k<(int)cir.size(); ++k)
	{
		int u = cir[k];
		if(val[u] == lst)
		{
			int need = lst + 1;
			bool flag = 0;
			for(int i=0; i<(int)nxt[u].size(); ++i)
			{
				if(nxt[u][i] > need){ lst = need; flag=1; break;}
				if(nxt[u][i] == need) ++need;
			}
			if(!flag) lst = need;
		}
		else lst = val[u];
	}
	return lst == val_lst;
}

