#include <bits/stdc++.h>
using namespace std;

struct Edge {
	int from, to;
	Edge(int f, int t) : from(f), to(t) {}
};

using Edges = vector<Edge>;
using Graph = vector<Edges>;
vector<int> tarjan(const Graph& g) {
	int n = g.size(), idx = 0, k = 0, s = 0;
	vector<int>ord(n, -1), low(n), onS(n), cmp(n), stk(n);
	function<void(int)>dfs;
	dfs = [&](int v) {
		ord[v] = low[v] = idx++;
		stk[s++] = v;
		onS[v] = true;
		for (auto &e : g[v]) {
			int w = e.to;
			if (ord[w] == -1) {
				dfs(w);
				low[v] = min(low[v], low[w]);
			}
			else if (onS[w]) {
				low[v] = min(low[v], ord[w]);
			}
		}
		if (low[v] == ord[v]) {
			while (1) {
				int w = stk[--s];
				onS[w] = false;
				cmp[w] = k;
				if (w == v)break;
			}
			++k;
		}
	};
	for (int v = 0; v<n; ++v)
		if (ord[v] == -1)dfs(v);
	return cmp;
}

int dfs(int v, const Graph& G) {
	set<int> s;
	for (auto to : G[v]) {
		s.insert(dfs(to.to, G));
	}
	int res = 0;
	auto it = s.begin();
	while (it != s.end() && *it == res) {
		res++;
		it++;
	}
	return res;
}

int main()
{
	int N;
	cin >> N;
	Graph G(N), rG(N);
	for (int i = 0, pi; i < N; i++) {
		cin >> pi; pi--;
		G[pi].emplace_back(pi, i);
		rG[i].emplace_back(i, pi);
	}
	auto v = tarjan(G);
	int V = 0;
	for (int i = 0; i < N; i++) {
		V = max(V, v[i] + 1);
	}
	if (V == 1) {
		cout << (N % 2 ? "IMPOSSIBLE" : "POSSIBLE") << endl;
	}
	else {
		vector<int> cnt(V);
		int rt = 0;
		for (int i = 0; i < N; i++) {
			cnt[v[i]]++;
			if (v[i] > 1) {
				rt = v[i];
			}
		}
		int co = 0;
		for (int i = 0; i < N; i++) {
			for (auto to : G[i]) {
				if (v[i] == rt && v[to.to] != rt && dfs(to.to, G) == 0) {
					co++;
				}
			}
		}
		cout << (co == (N - V + 1) ? "IMPOSSIBLE" : "POSSIBLE") << endl;
	}
	return 0;
}

