int loop(int p){
    if(searched[p] == 1){
        circle[p] = 1;
        return p;
    }
    visited[p] = 1;
    searched[p] = 1;
    int f = -1;
    for(int i = 0;i < graph[p].size();i++){
        int r = loop(graph[p][i]);
        if(r != -1 && r != p){
            f = r;
        }
    }
    searched[p] = 0;
    if(f > -1){
        circle[p] = 1;
        return f;
    }
    return -1;
}

void decide(int p){
    vector<int> t(graph[p].size()+1,0);
    for(int i = 0;i < graph[p].size();i++){
        if(decided[graph[p][i]] == -1) decide(graph[p][i]);
        if(decided[graph[p][i]] < t.size())
            t[decided[graph[p][i]]] = 1;
    }
    for(int i = 0;i < t.size();i++){
        if(t[i] == 0){
            decided[p] = i;
            break;
        }
    }
}

