                } else {
                    b = graph[i][j];
                }
            }
            break;
        }
    }
    int small,big;
    for(int i = 0;i < n;i++){
        if(asign[i] == 0){
            small = i;
            for(int j = i+1;j < n;j++){
                if(asign[j] == 0){
                    big = j;
                    break;
                }
            }
