int N;
pair<int, int> dfs(const Graph& g, int s, const vector<bool>& cycle)
{
    if (g.edge[s].empty()) {
        return make_pair(0, 1);
    } else {
        set<int> st;
        int c = 0;
        for (const int p : g.edge[s]) {
            if (cycle[p]) {
                continue;
            }
            c++;
            const int child = dfs(g, p, cycle).first;
            st.insert(child);
        }
        if (c == 0) {
            return make_pair(0, 1);
        }
        int first = -1;
        int second = -1;
        for (int i = 0; i <= N; i++) {
            if (st.find(i) == st.end()) {
                if (first == -1) {
                    first = i;
                } else if (second == -1) {
                    second = i;
                    break;
                }
            }
        }
        return make_pair(first, second);
    }
}

int main()
{
    cin >> N;
