    Graph rev(N);

    for (ll i = 0; i < N; i++) {
        int from;
        cin >> from;
        from--;
        g.addEdge(from, i);
        rev.addEdge(i, from);
    }

    int pos = 0;
    for (int i = 0; i < 2 * N; i++) {
        pos = rev.edge[pos][0];
    }
    vector<bool> cycle(N, false);
    vector<int> comp;
    for (int i = 0; i < 2 * N; i++) {
        if (cycle[pos]) {
            break;
        }
        comp.push_back(pos);
        cycle[pos] = true;
        pos = rev.edge[pos][0];
    }
    reverse(comp.begin(), comp.end());

    const int size = comp.size();
    const auto pi = dfs(g, comp[0], cycle);
    int miss = 0;
    for (int d = 0; d < 2; d++) {
        int next = (d == 0) ? pi.first : pi.second;
        const int start = (d == 1) ? pi.first : pi.second;
        for (int i = 1; i < size; i++) {
            const int p = comp[i];
            const auto q = dfs(g, p, cycle);
            next = (q.first == next) ? q.second : (q.second == next) ? q.first : -1;
            if (next == -1) {
                miss++;
                continue;
            }
        }

        if (next != start) {
            miss++;
            continue;
        }
    }
