using namespace std;

vector<vector<int>> adjlist,  rev;
vector<int> inDegree;
vector<set<int>> taken, taken2;
vector<int> grundies, grundies2;

int grundy(int v) {
  int res = 0;
  while (taken[v].count(res)) res++;
  return res;
}

int grundy2(int v) {
  int res = 0;
  while (taken[v].count(res)) res++;
  res++;
  while (taken[v].count(res)) res++;
  return res;
}

bool check(vector<int> &grundies) {
  for (int v = 0; v < (int)adjlist.size(); v++) {
    set<int> taken;
    for (int w : rev[v]) {
      taken.insert(grundies[w]);
    }
    int first = 0;
    while (taken.count(first)) first++;
    if (first != grundies[v]) return false;
  }
  return true;
}

bool possible(int v, vector<int> &grundies, vector<set<int>> &taken) {
  while (grundies[v] == -1) {
    grundies[v] = grundy(v);
    taken[adjlist[v][0]].insert(grundies[v]);
    v = adjlist[v][0];
  }
  return check(grundies);
}

int main() {
  int n;
  scanf("%d", &n);
  adjlist.resize(n);
  rev.resize(n);
  inDegree.resize(n);
  taken.resize(n);
  grundies.assign(n,  -1);
  for (int i = 0; i < n; i++) {
    int p;
    scanf("%d", &p);
    p--;
    adjlist[i].push_back(p);
    rev[p].push_back(i);
    inDegree[p]++;
  }
  queue<int> q;
  for (int i = 0; i < n; i++) {
    if (inDegree[i] == 0) {
      q.push(i);
    }
  }
  while (!q.empty()) {
    int v = q.front();
    q.pop();
    grundies[v] = grundy(v);
    for (int w : adjlist[v]) {
      taken[w].insert(grundies[v]);
      inDegree[w]--;
      if (inDegree[w] == 0) {
        q.push(w);
      }
    }
  }
  int cycleVert = 0;
  while (!inDegree[cycleVert]) cycleVert++;
  int cand1 = grundy(cycleVert);
  int cand2 = grundy2(cycleVert);

  taken2 = taken;
  grundies2 = grundies;

  grundies[cycleVert] = cand1;
  for (int w : adjlist[cycleVert]) {
    taken[w].insert(cand1);
    inDegree[w]--;
  }
  grundies2[cycleVert] = cand2;
  for (int w : adjlist[cycleVert]) {
    taken2[w].insert(cand2);
    inDegree[w]--;
  }

  if (possible(adjlist[cycleVert][0], grundies, taken) ||
      possible(adjlist[cycleVert][0], grundies2, taken2)) printf("POSSIBLE\n");
  else printf("IMPOSSIBLE\n");
  return 0;
}

