const int mod=998244353,MAX=200005,INF=1<<30;

int V,cmp[MAX];
vector<int> G[MAX],rG[MAX],vs;//vsがトポソの逆順になってる
bool used[MAX];

void add_edge(int from,int to){
    G[from].push_back(to);
    rG[to].push_back(from);
}

void DFS(int v){
    used[v]=1;
    for(int i=0;i<G[v].size();i++){
        if(used[G[v][i]]==0) DFS(G[v][i]);
    }
    vs.push_back(v);
}

void rDFS(int v,int k){
    used[v]=1;
    cmp[v]=k;
    for(int i=0;i<rG[v].size();i++){
        if(used[rG[v][i]]==0) rDFS(rG[v][i],k);
    }
}

int scc(){
    memset(used,0,sizeof(used));
    vs.clear();
    for(int v=0;v<V;v++){
        if(used[v]==0) DFS(v);
    }

    memset(used,0,sizeof(used));
    int k=0;
    for(int i=vs.size()-1;i>=0;i--){
        if(used[vs[i]]==0) rDFS(vs[i],k++);
    }
    return k;
}
int num;

int mex[MAX],mex2[MAX];

void DFS(int u,int p,int root,int d){
    set<int> SE;
    if(G[u].size()==0){
        return;
    }
    for(int to:G[u]){
        if(cmp[to]==num) continue;

        DFS(to,u,root,d+1);

        SE.insert(mex[to]);
    }

    for(int i=0;;i++){
        if(SE.count(i)==0){
            mex[u]=i;
            if(u==root){
                i++;
                while(SE.count(i)) i++;
                mex2[u]=i;
            }
            break;
        }
    }
}

int S[MAX];

bool ans=false;

void solve(int u,int p,int root,bool c){
    if(u==root){
        if(S[u]==-1){
            if(!c) S[u]=mex[u];
            else S[u]=mex2[u];

            for(int to:rG[u]){
                if(cmp[to]==num) solve(to,u,root,0);
            }
        }else{
            int a;
            if(mex[u]==S[p]) a=mex2[u];
            else a=mex[u];

            if(a==S[u]) ans=true;
        }
    }else{
        if(mex[u]==S[p]) S[u]=mex2[u];
        else S[u]=mex[u];

        for(int to:rG[u]){
            if(cmp[to]==num) solve(to,u,root,0);
        }
    }
}

