void dfs1(int v){
    used[v] = 1;
    for (auto u: g[v]){
        if (used[u]){
            if (u == p[v] || cycle[u]) continue;
            cycle[v] = 1;
            while(v != u){
                v = p[v];
                cycle[v] = 1;
            }
        } else{
            p[u] = v;
            dfs1(u);
        }
    }
}
void dfs2(int v){
    for (auto u: G[v]){
        if (cycle[u]) continue;
        dfs2(u);
        c[v].pb(mark[u]);
    }
    sort(c[v].begin(), c[v].end());
    if (cycle[v]) return;
    mark[v] = -1;
    int pr = -1;
    for (auto i: c[v]){
        if (pr + 1 != i && i > pr){
            mark[v] = pr + 1;
            return;
        }
        pr = i;
    }
    if (mark[v] == -1) mark[v] = pr + 1;
}
void tr(int v, int x){
    memset(b, 0, sizeof(b));
    mark[v] = x;
    int pr = x;
    int v0 = v;
    for (auto u: in[v]) if (cycle[u]){
        v = u;
