int N;
const int M = 200000;
const int INF = 1e9;
int prv[M], prv_cnt[M], grundy[M];
vector<int> nxt[M];
bitset<M> cycle;
int c;

void find_cycle(){
    int i = 0;
    bitset<M> visited;
    stack<int> st;
    while(true){
        visited[i] = true;
        st.push(i);
        if(visited[prv[i]]){
            c = prv[i];
            while(true){
                int j = st.top(); st.pop();
                cycle[j] = true;
                if(prv[i] == j) return;
            }
        }
        i = prv[i];
    }
}

int calc_grundy(int i){
    vector<int> v = {INF};
    for(int j : nxt[i]) v.push_back(grundy[j]);
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    for(int i=0; i<v.size(); i++){
        if(v[i] != i) return i;
    }
}

vector<int> calc_grundy_cand2(int i){
    vector<int> v = {INF, INF+1};
    for(auto j : nxt[i]) if(!cycle[j]) v.push_back(grundy[j]);
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    vector<int> ans;
    for(int i=0; i<v.size(); i++){
        if(v[i] != i + ans.size()) ans.push_back(i);
        if(ans.size() == 2) return ans;
    }
}

void trim(){
    queue<int> que;
    bitset<M> visited;
    for(int i=0; i<N; i++){
        if(prv_cnt[i] == 0){
            grundy[i] = 0;
            que.push(i);
        }
    }
    while(que.size()){
        int i = que.front(); que.pop();
        if(cycle[i] || visited[i]) continue;
        visited[i] = true;
        grundy[i] = calc_grundy(i);
        que.push(i);
    }
}

void check(int num){
    grundy[c] = num;
    int i = prv[c];
    while(i != c){
        grundy[i] = calc_grundy(i);
        i = prv[i];
    }

    if(calc_grundy(c) == grundy[c]){
        cout << "POSSIBLE" << endl;
        exit(0);
    }
}

int main(){
    cin >> N;
    for(int i=0; i<N; i++){
        cin >> prv[i];
        prv[i]--;
        nxt[prv[i]].push_back(i);
        prv_cnt[prv[i]]++;
    }

    find_cycle();
    trim();
    auto cand = calc_grundy_cand2(c);
    for(int num : cand) check(num);
    cout << "IMPOSSIBLE" << endl;
    return 0;
}

