#include <bits/stdc++.h>
using namespace std;
const int MAX_N=2e5+10;

int N,pos=-1;
vector<int> G[MAX_N];
bool seen[MAX_N],finished[MAX_N];
stack<int> hist;
set<int> cycle;
int par[MAX_N],grundy[MAX_N][2];

void dfs1(int v){
    seen[v]=true; hist.emplace(v);
    for (int u:G[v]){
        if (finished[u]) continue;
        if (seen[u]&&!finished[u]){
            pos=u; return;
        }
        dfs1(u);
        if (~pos) return;
    }
    finished[v]=true; hist.pop();
}

void dfs2(int v,int p){
    set<int> mex;
    for (int u:G[v]){
        if (u==p) continue;
        if (p<0&&cycle.count(u)) continue;
        dfs2(u,v);
        mex.emplace(grundy[u][0]);
    }
    if (~p){
        for (int i=0;;++i){
            if (!mex.count(i)){
                grundy[v][0]=i;
                break;
            }
        }
    } else {
        int ok=0;
        for (int i=0;;++i){
            if (!mex.count(i)){
                if (ok){grundy[v][1]=i; break;}
                else {grundy[v][0]=i; ok=1;}
            }
        }
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N; cin >> N;
    for (int i=0;i<N;++i){
        cin >> par[i];
        G[--par[i]].emplace_back(i);
    }
    for (int i=0;i<N;++i){
        if (!seen[i]) dfs1(i);
    }
    while(!hist.empty()){
        int t=hist.top(); hist.pop();
        cycle.emplace(t);
        if (t==pos) break;
    }
    for (int v:cycle) dfs2(v,-1);
    int s=*cycle.begin();
    for (int i=0;i<2;++i){
        vector<int> res(N);
        int now=s; res[s]=grundy[s][i];
        while(par[now]!=s){
            int p=par[now];
            res[p]=(res[now]==grundy[p][0]?grundy[p][1]:grundy[p][0]);
            now=p;
        }
        if ((res[now]==grundy[s][0])==i){
            cout << "POSSIBLE" << '\n';
            return 0;
        }
    }
    cout << "IMPOSSIBLE" << '\n';
}

