inline int mux(set<int> &st){
	int i = 0;
	for (set<int>::iterator it = st.begin(); it != st.end(); ++it){
		if (i == *it)++i;
		else return i;
	}
	return i;
}

void go(int v){
	vis[v] = 1;
	set<int> st1, st2;
	bool bad = false;
	f(i, 0, g[v].size()){
		int u = g[v][i];
		if (vis[u] == 1){
