int n, lo[200010], hi[200010], dp[2][2][200010], fin;
vi ed[200010], vec;
bitset<200010> cyc, vis;

bool dfs(int u) {
	vis[u] = 1;
	for(int v: ed[u]) {
		if (!vis[v]) {
			if (dfs(v)) {
				vec.pb(u);
				cyc[u] = 1;
				return 1;
			}
		} else {
			cyc[u] = 1;
			vec.pb(u);
			return 1;
		}
	}
	return 0;
}

void dfs2(int u) {
	for(int v: ed[u]) {
		if (!cyc[v]) dfs2(v);
	}
	vi arr;
	for(int v: ed[u]) if (!cyc[v]) arr.pb(lo[v]);
	sort(arr.begin(), arr.end());
	int ans = 0;
	for (int v: arr) if (v == ans) ans++;
	lo[u] = ans++;
	for (int v: arr) if (v == ans) ans++;
	hi[u] = ans;
}

int bt(int st, int n, int cur) {
	if (cur == fin - 1) {
		if (n == 0 && st == 0) return lo[vec[0]] != lo[vec[cur]]; 
		if (n == 1 && st == 0) return lo[vec[0]] == lo[vec[cur]]; 
		if (n == 0 && st == 1) return hi[vec[0]] != lo[vec[cur]]; 
		if (n == 1 && st == 1) return hi[vec[0]] == lo[vec[cur]];
	}
	if (dp[st][n][cur] != -1) return dp[st][n][cur];
	if (n == 0) {
		if (lo[vec[cur]] != lo[vec[cur + 1]] && bt(st,0,cur + 1)) return dp[st][n][cur] = 1;
		if (lo[vec[cur]] != hi[vec[cur + 1]] && bt(st,1,cur + 1)) return dp[st][n][cur] = 1;
	} else {
		if (lo[vec[cur]] == lo[vec[cur + 1]] && bt(st,0,cur + 1)) return dp[st][n][cur] = 1;
		if (lo[vec[cur]] == hi[vec[cur + 1]] && bt(st,1,cur + 1)) return dp[st][n][cur] = 1; 
	}
	return dp[st][n][cur] = 0;
}


