int DecomposeNamori(int v) {
  if (state[v] == 2) {
    return 0;
  }

  if (state[v] == 1) {
    state[v] = 2;
    return 1;
  }

  assert(state[v] == 0);
  state[v] = 1;
  int res = DecomposeNamori(nxt[v]);
  if (res == 1) {
    cycle.eb(v);
    if (state[v] == 2) return 0;
    state[v] = 2;
    return 1;
  }
  assert(res == 0);
  es[nxt[v]].eb(v);
  state[v] = 2;
  return 0;
}

int CalcGrundy(int v) {
  vector<char> num(es[v].size());
  int ret = es[v].size();
  for (int u : es[v]) {
    int t = CalcGrundy(u);
    if (t >= num.size()) continue;
    num[t] = 1;
  }

  rep(t, ret) {
    if (!num[t]) return t;
  }
  return ret;
}

multiset<int> CalcMex(int v) {
  multiset<int> ret;
  for (int u : es[v]) {
    ret.insert(CalcGrundy(u));
  }
  return ret;
}

int Mex(multiset<int> &ms) {
  int ret = ms.size();
  rep(t, ret) {
    if (!ms.count(t)) return t;
  }
  return ret;
}

