void dfs(int u) {
	vis[u] = 1;
	val[u] = mex(vs[u]);
	vs[p[u]].insert(val[u]);
	outdeg[p[u]]--;
	if (outdeg[p[u]]==0) dfs(p[u]);
}

bool ok(int u, int vv) {
	int v = u;
	val[u] = vv;
	while (p[v] != u) {
		set<int> st = vs[p[v]];
		st.insert(val[v]);
		int vc = mex(st);
		val[p[v]] = vc;
		vis[v] = 1;
		v = p[v];
	}
	la = v;
	return val[u] != val[v];
}

int main() {
	scanf("%d", &n);
	FOR(i,n) scanf("%d", &p[i]);
	FOR(i,n) p[i]--;
	FOR(i,n) outdeg[p[i]]++;
	FOR(i,n) if (!vis[i] && outdeg[i]==0) dfs(i);
	FOR(i,n) if (!vis[i]) {
		int v1 = mex(vs[i]);
		if (!ok(i, v1)) {
			vs[i].insert(v1);
			int v2 = mex(vs[i]);
			if (!ok(i, v2) || val[la] != v1) {
				printf("IMPOSSIBLE\n");
				return 0;
			}
		}
	}
	printf("POSSIBLE\n");
	return 0;
}

