void DFS1(int u) {
  instack[u] = true;
  for (auto& v : a[u]) {
    if (pre[v] < 0) {
      pre[v] = u;
      DFS1(v);
    } else {
      if (instack[v]) {
        assert(C.empty());
        int w = u;
        while (w != v) {
          circle[w] = true;
          C.push_back(w);
          w = pre[w];
        }
        circle[v] = true;
        C.push_back(v);
        reverse(C.begin(), C.end());
      }
    }
  }
  instack[u] = false;
}

void DFS(int u) {
  dp[u] = -1;
  for (auto& v : a[u]) {
    if (circle[v]) continue;
    DFS(v);
    dp[u] = max(dp[u], dp[v]);
  }
  dp[u] += 1;
}

int main() {
