    --x;
    a[x].push_back(i);
  }
  fill(pre, pre + n, -1);
  for (int i = 0; i < n; ++i) {
    if (pre[i] >= 0) continue;
    pre[i] = i;
    DFS1(i);
  }
  for (auto& u : C) {
    DFS(u);
  }
  bool found = false;
  for (int i = 0; i < C.size(); ++i) {
    if (dp[C[i]]) found = true;
  }
  if (!found) {
    puts(C.size() % 2 == 0 ? "POSSIBLE" : "IMPOSSIBLE");
    return 0;
  }
  C.push_back(C[0]);
  for (int i = 0; i < C.size() - 1; ++i) {
    if (dp[C[i]] && dp[C[i + 1]] && dp[C[i]] == dp[C[i + 1]]) {
      dp[C[i + 1]]++;
    }
  }
  found = false;
  for (int i = 0; i < C.size() - 1; ++i) {
    if (dp[C[i]] && dp[C[i + 1]] && dp[C[i]] == dp[C[i + 1]]) {
      found = true;
    }
  }
  puts(!found ? "POSSIBLE" : "IMPOSSIBLE");
  return 0;
}

