using namespace std;
const int maxn = 200200, mx = 7;
vector<int> cycle;
int p[maxn], out[maxn], val[maxn], is_out[maxn], cnt[mx][maxn];
bool can[mx][mx][mx][maxn];
bool solve(int fs, int ls, int hs, int at){
	if(can[fs][ls][hs][at]) return false;
	can[fs][ls][hs][at] = true;
	int who = cycle[at];
	if(at + 1 == cycle.size()){
		cnt[fs][who]++;
		for(int v = 0; v < mx - 1; v++){
			if(cnt[v][who]) continue;
			if(v == ls) continue;
			if(hs != mx - 1 && hs != v) continue;
			int sm = 0, eq = 0;
			for(int j = 0; j < v; j++){
				sm += cnt[j][who] > 0;
				if(cnt[j][who] == 0) eq = j;
			}
			if(sm == v){
				return true;
			}
		}
		cnt[fs][who]--;
	} else if(at == 0){
		for(int v = 0; v < mx - 1; v++){
			if(cnt[v][who]) continue;
			int sm = 0, eq = 0;
			for(int j = 0; j < v; j++){
				sm += cnt[j][who] > 0;
				if(cnt[j][who] == 0) eq = j;
			}
			if(sm == v){
				if(solve(v, v, mx - 1, at + 1)) return true;
			} else if(sm == v - 1){
				if(solve(v, v, eq, at + 1)) return true;	
			}
		}
	} else {
		for(int v = 0; v < mx - 1; v++){
			if(v == ls) continue;
			if(cnt[v][who]) continue;
			if(hs != mx - 1 && hs != v) continue;
			int sm = 0, eq = 0;
			for(int j = 0; j < v; j++){
				sm += cnt[j][who] > 0;
				if(cnt[j][who] == 0) eq = j;
			}
			if(sm == v){
				if(solve(fs, v, mx - 1, at + 1)) return true;
			} else if(sm == v - 1){
				if(solve(fs, v, eq, at + 1)) return true;	
			}
		}
	}
	return false;
}
int main(){
	int n; cin >> n;
	for(int i = 0; i < n; i++){
		cin >> p[i]; p[i]--;
		out[p[i]]++;
	}
	set<pair<int,int> > outs;
	for(int i = 0; i < n; i++){
		outs.insert({out[i], i});
	}
	while(!outs.empty()){
		if(outs.begin()->first) break;
		int ot, v; tie(ot, v) = *outs.begin(); outs.erase(outs.begin());
		if(!cnt[0][v]) val[v] = 0;
		else val[v] = 1;
		is_out[v] = 1;
		cnt[val[v]][p[v]]++;
		outs.erase({out[p[v]], p[v]});
		out[p[v]]--;
		outs.insert({out[p[v]], p[v]});
	}
	for(int i = 0; i < n; i++){
		if(!is_out[i]){
			int u = i;
			do {
				cycle.push_back(u);
				u = p[u];
			} while(u != i);
			reverse(cycle.begin(), cycle.end());
			break;
		}
	}
	if(solve(mx - 1, mx - 1, mx - 1, 0)) cout << "POSSIBLE" << endl;
	else cout << "IMPOSSIBLE" << endl;
	return 0;
}

