constexpr int INF=1e9;
constexpr int MOD=1e9+7;
constexpr double EPS=1e-9;

int mex(vi a)
{
	sort(all(a));
	if(a.empty()||a[0]>0)
		return 0;
	rep(i,a.size()-1)
		if(a[i]+1<a[i+1])
			return a[i]+1;
	return a.back()+1;
}

int calc(const vvi& g,int u,vi& grundy)
{
	if(grundy[u]!=-1)
		return grundy[u];
	vi a;
	for(int v:g[u])
		a.push_back(calc(g,v,grundy));
	return grundy[u]=mex(a);
}

bool check(const vvi& g,const vi& grundy)
{
	rep(u,g.size())
		for(int v:g[u])
			if(grundy[u]==grundy[v])
				return false;
	return true;
}

int main()
{
	for(int n;cin>>n&&n;){
		vi p(n);
		vvi g(n);
		rep(i,n){
			cin>>p[i]; p[i]--;
			g[p[i]].push_back(i);
		}

		vi on_cycle(n);
		int root=0;
		rep(i,n) root=p[root];
		for(int v=root;!on_cycle[v];v=p[v])
			on_cycle[v]=1;

		vi grundy(n,-1);
		rep(i,n) if(on_cycle[i])
			for(int v:g[i]) if(!on_cycle[v])
				calc(g,v,grundy);

		bool ok=false;
		{
			int next=-1;
			for(int v:g[root]) if(on_cycle[v])
				next=v;

			vi a;
			for(int v:g[root]) if(!on_cycle[v])
				a.push_back(grundy[v]);
			int x=mex(a);
			grundy[root]=x;
			calc(g,next,grundy);
			ok|=check(g,grundy);

			a.push_back(x);
			int y=mex(a);
			grundy[root]=y;
			for(int v=p[root];v!=root;v=p[v])
				grundy[v]=-1;
			ok|=check(g,grundy);
		}
		cout<<(ok?"POSSIBLE":"IMPOSSIBLE")<<endl;
	}
}

