using namespace std;
const int Q=230123;
int las[Q],e[Q<<1],nn[Q<<1];
int inc=0;
void ins(int x,int y)
{
	e[++inc]=y;
	nn[inc]=las[x];
	las[x]=inc;
}
int Time=0;
int vis[Q];
int flag;
int fa[Q];
int cir[Q]={0},tot=0;
int isrt[Q];
void ddd(int x)
{
	if(flag)return;
	vis[x]=Time;
	if(vis[fa[x]]){
		if(vis[fa[x]]==vis[x]){
			int t=x;
			do{
				cir[++tot]=t;
				isrt[t]=1;
				t=fa[t];
			}while(t!=x);
		}
		return;
	}
	ddd(fa[x]);
}
int mx[Q];
int cnt[Q];
void dfs(int x)
{
	for(int t=las[x];t;t=nn[t]){
		int y=e[t];
		if(isrt[y])continue;
		dfs(y);
	}
	++Time;
	for(int t=las[x];t;t=nn[t]){
		int y=e[t];
		if(isrt[y])continue;
		cnt[mx[y]]=Time;
	}
	for(mx[x]=0;cnt[mx[x]]==Time;++mx[x]);
}
int main()
{
	int n;
	int x;
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
		scanf("%d",&x),ins(x,i),fa[i]=x;
	for(int i=1;i<=n;i++)
		if(!vis[i])++Time,ddd(i);
	Time=0;
	if(tot%2==0)return puts("POSSIBLE")&0;
	for(int i=1;i<=tot;i++)
		dfs(cir[i]);
	for(int i=2;i<=tot;i++)
		if(mx[cir[i]]!=mx[cir[i-1]])
		return puts("POSSIBLE")&0;
	puts("IMPOSSIBLE");
	return 0;
}

