void dfs(int x){
  if(xc!=0 || yc!=0) return;
  used[x]=1;
  for(auto y:g[x]){
    if(xc!=0 || yc!=0) return;
    if(used[y] && (pr!=y || !e)){
      xc=x, yc=y;
      break;
    }
    if(used[y]) continue;
    pr=x; e=0;
    dfs(y);
  }
  for(auto y:gr[x]){
    if(xc!=0 || yc!=0) return;
    if(used[y] && (pr!=y || e)){
      xc=y, yc=x;
      break;
    }
    if(used[y]) continue;
    pr=x; e=1;
    dfs(y);
  }
}

void dfs2(int x){
  set<int> st;
  for(auto y:g[x]){
    if(x==xc && y==yc) continue;
    if(a[y]>=0){
      st.insert(a[y]);
    }else{
      dfs2(y);
      st.insert(a[y]);
    }
  }
  if(st.empty()){
    a[x]=0;
    return;
  }
  for(int i=0; ; i++){
    if(st.find(i)==st.end()){
      a[x]=i;
      return;
    }
  }
}

