int tot = 0, fir[N], nxt[N << 1], to[N << 1];

inline void addEdge(int u, int v) {
    nxt[++tot] = fir[u], fir[u] = tot, to[tot] = v;
}

int n, inc[N], cntc, cir[N], val[N], use[N], pre[N];

inline void getcircle() {
    int x = 1;
    while (!inc[x]) inc[x] = 1, x = pre[x];
    memset(inc, 0, sizeof inc);
    while (!inc[x]) inc[cir[++cntc] = x] = 1, x = pre[x];
}

void getmex(int u) {
    for (rint i = fir[u], v; i; i = nxt[i]) {
        v = to[i];
        if (inc[v]) continue;
        getmex(v);
        use[val[v]] = 1;
    }
    while (use[val[u]]) ++val[u];
    for (rint i = fir[u]; i; i = nxt[i])
        use[val[to[i]]] = 0;
}

