using namespace std;
const int N=2e5+5;
set<int>se[N];
typedef set<int>::iterator it;
int n,now,v[N],c[N],b[N],nex[N],head[N];
struct each{
	int a,id;
}a[N];
queue<int>que;
inline int read(){
	register int x=0;
	register char ch=getchar();
	while(ch<'0'||ch>'9')	ch=getchar();
	while(ch>='0'&&ch<='9')	x=x*10+(ch^48),ch=getchar();
	return x;
}
bool com(each x,each y){
	return x.a>y.a;
}
void addedges(int x,int y){
	nex[++now]=head[x],++b[y];
	head[x]=now,v[now]=y;
}
int get(int x){
	int last=-1;
	it i=se[x].begin();
	for(;i!=se[x].end();++i)
		if(last+1==*i)	++last;
		else	break;
	return ++last;
}
int tm[N];
int main(){

	n=read();
	for(register int i=1;i<=n;i++)
		addedges(i,read());
	for(register int i=1;i<=n;i++)
		if(!b[i])	que.push(i);
	while(!que.empty()){
		int x=que.front();
		int k=get(x); que.pop();
		for(register int i=head[x];i;i=nex[i]){
			se[v[i]].insert(k);
			if(!(--b[v[i]]))	que.push(v[i]);
		}
	}
	now=0;
	for(register int i=1;i<=n;i++)
		if(b[i]) a[++now]=(each){get(i),i};

	sort(a+1,a+now+1,com);
	int lim=min(10000000/now,now);
	for(register int i=1;i<=lim;i++){
		for(register int j=1;j<=now;j++)
			c[a[j].id]=b[a[j].id];
		int nu=a[i].id;
		tm[nu]=a[i].a;
		que.push(nu);
		while(!que.empty()){
			int x=que.front();
			tm[x]=get(x),que.pop();
			for(int i=head[x];i;i=nex[i])
				if(c[v[i]]){
					se[v[i]].insert(tm[x]);
					if(v[i]==nu){
						if(tm[x]==tm[nu])	break;
						else{
							puts("POSSIBLE");
							return 0;
						}
					}
					if((--c[v[i]])==0)	que.push(v[i]);
				}
		}
		for(register int j=1;j<=now;j++)
			for(register int k=head[a[j].id];k;k=nex[k])
				se[v[k]].erase(tm[a[j].id]);
	}
	puts("IMPOSSIBLE");
	return 0;
}

