typedef long long int64;
typedef pair<int, int> ii;
const int INF = 1 << 30;
const int MOD = 1e9 + 7;

const int N = 2e5 + 10;
vector<int> a[N];
vector<int> C;
bool circle[N];
int pre[N];
int dp[N];
bool instack[N];

void DFS1(int u) {
  instack[u] = true;
  for (auto& v : a[u]) {
    if (pre[v] < 0) {
      pre[v] = u;
      DFS1(v);
    } else {
      if (instack[v]) {
        assert(C.empty());
        int w = u;
        while (w != v) {
          circle[w] = true;
          C.push_back(w);
          w = pre[w];
        }
        circle[v] = true;
        C.push_back(v);
        reverse(C.begin(), C.end());
      }
    }
  }
  instack[u] = false;
}

void DFS(int u) {
  dp[u] = -1;
  for (auto& v : a[u]) {
    if (circle[v]) continue;
    DFS(v);
    dp[u] = max(dp[u], dp[v]);
  }
  dp[u] += 1;
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    int x;
    scanf("%d", &x);
    --x;
    a[x].push_back(i);
  }
  fill(pre, pre + n, -1);
  for (int i = 0; i < n; ++i) {
    if (pre[i] >= 0) continue;
    pre[i] = i;
    DFS1(i);
  }
  for (auto& u : C) {
    DFS(u);
  }
  bool found = false;
  for (int i = 0; i < C.size(); ++i) {
    if (dp[i]) found = true;
  }
  if (!found) {
    puts(C.size() % 2 == 0 ? "POSSIBLE" : "IMPOSSIBLE");
    return 0;
  }
  C.push_back(C[0]);
  for (int i = 0; i < C.size() - 1; ++i) {
    if (dp[C[i]] && dp[C[i + 1]] && dp[C[i]] == dp[C[i + 1]]) {
      dp[C[i + 1]]++;
    }
  }
  found = false;
  for (int i = 0; i < C.size() - 1; ++i) {
    if (dp[C[i]] && dp[C[i + 1]] && dp[C[i]] == dp[C[i + 1]]) {
      found = true;
    }
  }
  puts(!found ? "POSSIBLE" : "IMPOSSIBLE");
  return 0;
}

