const int MR = 2e5 + 10;

int d[MR], v[MR];

vector<int> g[MR];

vector < int > cykl, S;

int done[MR], srt[MR], cnt;

bool wCyklu[MR];

void dfs(int nr)
{
	done[nr] = 1;
	S.push_back(nr);

	for (int i : g[nr])
		if (done[i] == 1)
		{
			FORD(j, S.size(), 0)
			{
				cykl.push_back(S[j]);
				wCyklu[cykl.back()] = 1;
				if (S[j] == i)
					break;
			}
		}
		else if (!done[i])
			dfs(i);

	S.pop_back();
	done[nr] = 2;

	srt[cnt++] = nr;
}

int main()
{
	int N;
