	REP(i, N)
	{
		int p;
		scanf("%d", &p); p--;
		g[p].push_back(i);
	}

	REP(i, N)
		if (!done[i])
			dfs(i);

	if (cykl.size() % 2 == 0)
	{
		printf("POSSIBLE\n");
		return 0;
	}

	// wyznacz wartosci az do cyklu
	REP(i, N)
	{
		set<int> pom;
		for (int nr : g[srt[i]])
			if (!wCyklu[nr])
				pom.insert(v[nr]);
		FORQ(j,0,g[srt[i]].size())
			if (pom.find(j) == pom.end())
			{
				v[srt[i]] = j;
				break;
			}
	}

	// zobacz czy wszystkie wartosci taie same
