/**** main function ****/

ll V, p;
vector<ll> G[200000];
vector<ll> rG[200000];
vector<ll> vs;
bool used[200000];
ll cmp[200000];

void add_edge(ll from, ll to) {
  G[from].push_back(to);
  rG[to].push_back(from);
}

void dfs(ll v) {
  used[v] = true;
  for (ll i = 0; i < G[v].size(); i++) {
    if (!used[G[v][i]]) dfs(G[v][i]);
  }
  vs.push_back(v);
}

void rdfs(ll v, ll k) {
  used[v] = true;
  cmp[v] = k;
  for (ll i = 0; i < rG[v].size(); i++) {
    if (!used[rG[v][i]]) rdfs(rG[v][i], k);
  }
}

ll scc() {
  memset(used, 0, sizeof(used));
  vs.clear();
  for (ll v = 0; v < V; v++) {
    if (!used[v]) dfs(v);
  }
  memset(used, 0, sizeof(used));
  ll k = 0;
  for (ll i = vs.size() - 1; i >= 0; i--) {
    if (!used[vs[i]]) rdfs(vs[i], k++);
  }
  return k;
}

ll counter[200001], c2[200001];

ll dfs2(ll num, ll t) {
  if (G[num].size() <= 1) return 0;
  if (t == 0) return dfs2(G[num][0], 0) + 1;
  if (cmp[G[num][0]] == cmp[num]) return dfs2(G[num][1], 0) + 1;
  return dfs2(G[num][0], 0) + 1;
}

int main() {
  scanf("%lld", &V);
  for (ll i = 0; i < V; i++) scanf("%lld", &p), add_edge(p-1, i);
  scc();
  for (ll i = 0; i < V; i++) counter[cmp[i]]++;
  ll mx = 0, num;
  for (ll i = 0; i < V; i++) if (counter[i] > mx) mx = counter[i], num = i;
  if (mx % 2 == 0) {
    bool ok = true;
    ll before = -2;
    while (c2[num] == 0) {
      c2[num] = 1;
      ll t = dfs2(num, 1);
      if (t == 0) before = -before;
      else if (before == t) { ok = false; break; }
      else before = t;
      if (cmp[G[num][0]] == cmp[num]) num = G[num][0];
      else num = G[num][1];
    }
    if (ok) printf("POSSIBLE\n");
    else printf("IMPOSSIBLE\n");
  } else if (mx == 3 && V != 3) {
    ll c[3], t = 0;
    for (ll i = 0; i < V; i++) if (num == cmp[i]) c[t++] = dfs2(i, 1);
    sort(c, c + 3);
    if (c[0] == 0 && c[1] == 0) {
      if (c[2] % 2) printf("POSSIBLE\n");
      else printf("IMPOSSIBLE\n");
    } else {
      ll g = 0;
      for (ll i = 0; i < 3; i++) if (c[i] % 2 == 0) g++;
      if (g == 1) printf("POSSIBLE\n");
      else printf("IMPOSSIBLE\n");
    }
  } else printf("IMPOSSIBLE\n");
}

#include <bits/stdc++.h>

using std::swap;

const int N=2e5+10;

struct Edge{ int to,next; }way[N<<1];

int n,num[N],tot,In[N],app[N],val[N],val1[N],val2[N];
bool cir[N],vis[N];

void Build(int a,int b) { way[++tot]=(Edge){b,num[a]}; num[a]=tot; }

void Init() {
	scanf("%d",&n);
	for (int i=1;i<=n;++i) scanf("%d",&In[i]);
}

void Dfs(int x,int fa) {
	for (int i=num[x];i;i=way[i].next) {
		int v=way[i].to;
		Dfs(v,x);
	}
	for (int i=num[x];i;i=way[i].next) {
		int v=way[i].to;
		app[val[v]]++;
	}
	int cnt=fa?1:2;
	for (int i=0;cnt;++i) if (!app[i]) {
		if (cnt==2) val2[x]=i;
		else val[x]=val1[x]=i; 
		cnt--;
	}
	for (int i=num[x];i;i=way[i].next) {
		int v=way[i].to;
		app[val[v]]--;
	}
}

void Solve() {
	int rt=1; while (!vis[rt]) vis[rt]=1,rt=In[rt];
	while (!cir[rt]) cir[rt]=1,rt=In[rt];
	for (int i=1;i<=n;++i) if (!cir[i]) Build(In[i],i);
	for (int i=1;i<=n;++i) if (cir[i]) Dfs(i,0);
	for (int i=1;i<=n;++i) if (cir[i]) {
		for (int j=1;j<=n;++j) if (cir[j]) {
			val[j]=-1;
			if (val2[j]<val1[j]) swap(val1[j],val2[j]);
		}
		val[i]=val1[i]; 
		int x=In[i],pre=i;
		do{
			if (val[pre]==val1[x]) val[x]=val2[x];
			else val[x]=val1[x];
			pre=x; x=In[x];
		}while (x!=In[i]);
		if (val1[i]==val[i]) { printf("POSSIBLE\n"); return ; }

		for (int j=1;j<=n;++j) if (cir[j]) val[j]=-1;
		val[i]=val2[i]; x=In[i],pre=i;
		do{
			if (val[pre]==val1[x]) val[x]=val2[x];
			else val[x]=val1[x];
			pre=x; x=In[x];
		}while (x!=In[i]);
		if (val2[i]==val[i]) { printf("POSSIBLE\n"); return ; }
		else { printf("IMPOSSIBLE\n"); return ; }
		break;
	}
}

int main() {
	Init();
	Solve();
	return 0;
}

#include <bits/stdc++.h>
#define RI register int

using namespace std;

int const MAXN = 2e5 + 5;
struct Edges { int to, next; } e[MAXN];
int head[MAXN], tot;
int vis[MAXN], Ring[MAXN], stk[MAXN], top, a[MAXN], cnt;
int ok[MAXN][201], b[MAXN];

inline void addedge(int from, int to) {
  e[++tot] = (Edges){to, head[from]};
  head[from] = to;
}

void Dfs(int now) {
  if (vis[now]) {
    while (stk[top] != now) a[++cnt] = stk[top--];
    a[++cnt] = stk[top--];
    return;
  }
  stk[++top] = now;
  vis[now] = 1;
  for (RI i = head[now]; i; i = e[i].next)
    Dfs(e[i].to);
  --top;
}

void Work(int now) {
  for (RI i = head[now]; i; i = e[i].next)
    if (!Ring[e[i].to])
      Work(e[i].to), ok[now][b[e[i].to]] = 1;
  for (RI i = 0; i < 200; ++i)
    if (!ok[now][i])
      return b[now] = i, void();
}

int main() {
//  freopen("a.in", "r", stdin);
  ios :: sync_with_stdio(0);
  cin.tie(0), cout.tie(0);
  int n; cin >> n;
  int tmp = 0;
  for (RI i = 1, x; i <= n; ++i) {
    cin >> x, addedge(x, i);
    if (!tmp) tmp = x;
  }
  Dfs(tmp);
  if (cnt % 2 == 0) return puts("POSSIBLE"), 0;
