    for (int i = 0; i < n; ++i) {
        if (dg[i] == 0) q.push(i); 
    }
    vector<int> used(n), sg(n);
    while (!q.empty()) {
        int x = q.front(); q.pop();
        for (int u : g[x]) used[sg[u]] = 1;
        while (used[sg[x]]) sg[x]++;
        for (int u : g[x]) used[sg[u]] = 0;
        if (--dg[p[x]] == 0) q.push(p[x]);
    }
    vector<int> nxt(n, -1), prv(n, -1), upd(n, 0);
    vector<int> cycle;
    for (int i = 0; i < n; ++i) {
        if (dg[i] != 0) {
            for (int u : g[i]) if (dg[u] == 0) used[sg[u]] = 1;
            while (used[sg[i]]) sg[i]++;
            upd[i] = !used[sg[i] + 1];
            for (int u : g[i]) if (dg[u] == 0) used[sg[u]] = 0;
            for (int u : g[i]) if (dg[u] > 0) { 
                nxt[i] = u;
                prv[u] = i;
            }
            cycle.push_back(i);
        }
    }
    bool ok = true;
    for (int u : cycle) ok &= sg[u] != sg[nxt[u]];
    if (ok) {
        puts("POSSIBLE");
        return 0;
    }
    for (int u : cycle) {
        if (upd[u]) {
            ++sg[u];
            int x = u;
            for (int i = 0; i + 1 < cycle.size(); ++i) {
                int r = prv[x];
                for (int k : g[r]) used[sg[k]] = 1;
                sg[r] = 0;
                while (used[sg[r]]) sg[r]++;
                for (int k : g[r]) used[sg[k]] = 0;
                x = r;
            }
            bool ok = sg[nxt[u]] == sg[u] - 1;
            for (int v : cycle) ok &= sg[v] != sg[nxt[v]];
            if (ok) puts("POSSIBLE");
            else puts("IMPOSSIBLE");
            return 0;
        }
    }
    puts("IMPOSSIBLE");
}

