    if(a[v] != -1) {
        return a[v];
    }
    visited[v] = true;
    set<int> s;
    for(auto to : g[v]) {
        if(to == prev) {
            continue;
        }
        if(visited[to] && a[to] == -1) {
            continue;
        }
        if(!visited[to]) {
            s.insert(dfs(to, v, g, a, visited));
        } else {
            s.insert(a[to]);
        }
    }
    for(int i = 0; ; ++i) {
        if(s.count(i) == 0) {
            return a[v] = i;
        }
    }
}

