int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin >> N;
    vector<int> p(N);
    rep(i,N) {
        cin >> p[i];
        --p[i];
    }

    vector<int> seen(N);
    int c = 0;
    while (!seen[c]) {
        seen[c] = 1;
        c = p[c];
    }
    set<int> circle;
    while (!circle.count(c)) {
        circle.emplace(c);
        c = p[c];
    }
    if (~(int)circle.size()&1) {
        cout << "POSSIBLE" << ln;
        return 0;
    }
    vector<vector<int>> G(N);
    rep(i,N) {
        if (circle.count(i)) continue;
        G[p[i]].emplace_back(i);
    }
    auto dfs=[&](auto&& self, int v)->int {
        for (auto nv : G[v]) {
            if (self(self,nv)==0) return 1;
        }
        return 0;
    };
    int cnt = 0;
    for (auto c : circle) {
        cnt += dfs(dfs,c);
    }

    cout << ((cnt==0 or cnt==(int)circle.size()) ? "IMPOSSIBLE" : "POSSIBLE") << ln;
}

