vi cyc;

vi seen;

int mx(int i,int o=-1) {
	//if (mex[i]!=-1) return mex[i];
	seen.clear();
	for (int j:al[i]) if (j!=o) seen.push_back(mex[j]);
	sort(seen.begin(),seen.end());
	seen.resize(unique(seen.begin(),seen.end())-seen.begin());
	for (int c=0;c<seen.size();c++) if (seen[c]!=c) {
		return mex[i]=c;
	}
	return mex[i]=seen.size();
}

bool tmx(int i) {
	int v=mex[i];
	mex[i]=-1;
	bool res=mx(i)==v;
	mex[i]=v;
	return res;
}

bool consist() {
	for (int i:cyc) if (!tmx(i)) return 0;
	return 1;
}


bool dfs(int i) {
	if (vis[i]) return 0;
	if (act[i]) return 1;
	act[i]=1;
	bool incyc=0;
	for (int j:al[i]) {
		incyc=incyc||dfs(j);
	}
	vis[i]=1;
	if (incyc) {
		cyc.push_back(i);
		return 1;
	}

	mx(i);
	return 0;
}

