			if (!consist()) {
				mex[cyc.back()]=mx0;
				for (int j=0;j+1<cyc.size();j++) {
					mex[cyc[j]]=-1;
					mx(cyc[j]);
				}
				if (!consist()) {
					cout << "IMPOSSIBLE\n";
