const int N = 2e5 + 1;
vector<int> g[N];
vector<int> w;
int u[N];
int c[N];
void dfs1(int v) {
    u[v] = 1;
    w.pb(v);
    for (int t : g[v]) {
        if (!u[t]) dfs1(t);
        else if (u[t] == 1) {
            for (int j = (int)w.size() - 1; j >= 0; --j) {
                c[w[j]] = 1;
                if (w[j] == t) break;
            }
        }
    }
    w.pop_back();
    u[v] = 2;
}

int a[N];
void dfs2(int v) {
    set<int> mex;
    for (int to : g[v])
        if (!c[to]) {
            dfs2(to);
            mex.insert(a[to]);
        }
    for (int i = 0; ; ++i)
        if (mex.find(i) == mex.end()) {
            a[v] = i;
            break;
        }
}

void dfs3(int v) {
    set<int> mex;
    u[v] = 1;
    w.pb(v);
    for (int to : g[v]) {
        if (!u[to]) {
            if(c[to]) dfs3(to);
            dbg(v, to, a[to]);
        }
        mex.insert(a[to]);
    }

    for (int i = 0; ; ++i)
        if (mex.find(i) == mex.end()) {
            a[v] = i;
            break;
        }    
}

int main() {

    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        int p;
        cin >> p;
        g[p].pb(i);
    }

    for (int i = 1; i <= n; ++i)
        if (!u[i])
            dfs1(i);

    dbg("dfs1");

    for (int i = 1; i <= n; ++i)
        if (c[i])
            dfs2(i);
    dbg("dfs2");

    int v = -1;
    for (int i = 1; v == -1 && i <= n; ++i)
        if (c[i])
            v = i;

    dbg(v);
    int b;
    {
        set<int> mex;
        for (int to : g[v])
            if (!c[to])
                mex.insert(a[to]);

        for (int i = a[v] + 1; ; ++i)
            if (mex.find(i) == mex.end()) {
                b = i;
                break;
            }
    }

    memset(u, 0, sizeof u);
    int was = a[v];
    dfs3(v);

    if (was == a[v]) {
        cout << "POSSIBLE\n";
        return 0;
    }
    dbg(b);
    a[v] = b;

    memset(u, 0, sizeof u);
    was = a[v];
    dfs3(v);

    if (was == a[v]) {
        cout << "POSSIBLE\n";
        return 0;
    }

    cout << "IMPOSSIBLE\n";

    return 0;
}

