const int MAXN = 200000 + 1000;

int n;
vector<int> edg[MAXN], redg[MAXN];
vector<int> cir;
bool onc[MAXN], vis[MAXN];
int val[MAXN];

int find_circle(int x)
{
	vis[x] = true;
	for(int i = 0; i < redg[x].size(); i++)
	{
		int y = redg[x][i], tmp = vis[y] ? y : find_circle(y);
		if(tmp)
			cir.push_back(x), onc[x] = true;
		return x == tmp ? 0 : tmp;
	}
	return 0;
}

bool h[MAXN];
void assign_tree(int x)
{
	for(int i = 0; i < edg[x].size(); i++)
		if(!onc[edg[x][i]])
		{
			int y = edg[x][i];
			assign_tree(y);
			h[val[y]] = true;
		}
	val[x] = 0;
	while(h[val[x]])
		val[x]++;
	for(int i = 0; i < edg[x].size(); i++)
		if(!onc[edg[x][i]])
			h[val[edg[x][i]]] = false;
}

void yes()
{
	cout << "POSSIBLE" << endl;
	exit(0);
}

void no()
{
	cout << "IMPOSSIBLE" << endl;
	exit(0);
}

void assign_circle()
{
	for(int i = (int)cir.size() - 1; i >= 0; i--)
	{
		int x = cir[i];
		for(int j = 0; j < edg[x].size(); j++)
			h[val[edg[x][j]]] = true;
		val[x] = 0;
		while(h[val[x]])
			val[x]++;
		for(int j = 0; j < edg[x].size(); j++)
			h[val[edg[x][j]]] = false;
	}
}

void work()
{
	int cir0 = cir[0];
	for(int i = 0; i < edg[cir0].size(); i++)
		if(!onc[edg[cir0][i]])
			h[val[edg[cir0][i]]] = true;
	int tmp1 = 0, tmp2 = 0;
	while(h[tmp1])
		tmp1++;
	tmp2 = tmp1 + 1;
	while(h[tmp2])
		tmp2++;
	for(int i = 0; i < edg[cir0].size(); i++)
		if(!onc[edg[cir0][i]])
			h[val[edg[cir0][i]]] = false;

	val[cir0] = tmp1;
	assign_circle();
	// for(int i = 1; i <= n; i++)
	// 	cout << val[i] << endl;
	if(val[cir0] == tmp1)
		yes();
	val[cir0] = tmp2;
	assign_circle();
	if(val[cir0] == tmp2)
		yes();
	no();
}

int main()
{
	ios::sync_with_stdio(false);
	// freopen("1.in", "r", stdin);
	// freopen("1.out", "w", stdout);

	cin >> n;
	for(int i = 1; i <= n; i++)
	{
		int x;
		cin >> x;
		edg[x].push_back(i), redg[i].push_back(x);
	}
	find_circle(1);

	// for(int i = 0; i < cir.size(); i++)
	// 	cerr << cir[i] << endl;

	for(int i = 0; i < cir.size(); i++)
		assign_tree(cir[i]);

	work();


	return 0;
}

