int rec(int v){
	vector<int> s;
	for(int i=0;i<G[v].size();i++){
		if(cmp[G[v][i]]==loop_idx)continue;
		s.pb(rec(G[v][i]));
	}
	sort(all(s));
	s.erase(unique(all(s)),s.end());
	for(int i=0;i<s.size();i++){
		if(s[i]!=i)return i;
	}
	return (int)s.size();
}
int main(){
	cin >> N;
	for(int i=0;i<N;i++){
		int p;
		cin >> p;
		p--;
		add_edge(p,i);
	}
	for(int i=0;i<N;i++){
		if(!used[i])dfs(i);
	}
	reverse(all(vec));
	int k=0;
	memset(used,false,sizeof(used));
	int l=-1;
	for(int i=0;i<vec.size();i++){
		if(!used[vec[i]]){
			rdfs(vec[i],k);
			if(sz[k]>1){
				l=vec[i];
				loop_idx=k;
			}
			k++;
		}
	}
	memset(used,false,sizeof(used));
	find_loop(l,loop_idx);
	for(int i=0;i<loop.size();i++){
		root_val.pb(rec(loop[i]));
		if(root_val.back()==-1){
			cout << "IMPOSSIBLE" << endl;
			return 0;
		}
	}
	//print(root_val);
	vector<int> tmp = root_val;
	int M = root_val.size();
	for(int i=M-1;i>0;i--){
		if(tmp[(i+1)%M]==tmp[i])tmp[i]++;
	}
	if(tmp[0]!=tmp[1]){
		cout << "POSSIBLE" << endl;
		return 0;
	}
	tmp = root_val;
