typedef  tree< int , null_type, less<int>, rb_tree_tag, tree_order_statistics_node_update> ordered_set;

const int N = 500000;
int used[N], cycle[N], deg[N], p[N], b[N], mark[N], n;
vector < int > g[N], G[N], in[N], c[N];
void dfs1(int v){
    used[v] = 1;
    for (auto u: g[v]){
        if (used[u]){
            if (u == p[v]|| cycle[u]) continue;
            cycle[v] = 1;
            while(v != u){
                v = p[v];
                cycle[v] = 1;
            }
        } else{
            p[u] = v;
            dfs1(u);
        }
    }
}
void dfs2(int v){
    for (auto u: G[v]){
        if (cycle[u]) continue;
        dfs2(u);
        c[v].pb(mark[u]);
    }
    sort(c[v].begin(), c[v].end());
    if (cycle[v]) return;
    mark[v] = -1;
    int pr = -1;
    for (auto i: c[v]){
        if (pr + 1 != i && i > pr){
            mark[v] = pr + 1;
            return;
        }
        pr = i;
    }
    if (mark[v] == -1) mark[v] = pr + 1;
}
void tr(int v, int x){
    memset(b, 0, sizeof(b));
    mark[v] = x;
    int pr = x;
    int v0 = v;
    for (auto u: in[v]) if (cycle[u]){
        v = u;
        break;
    }
    while(v != v0){
        for (auto i: c[v]) b[i] = v;
        b[pr] = v;
        for (int i = 0; i <= n + 2; i++){
            if (b[i] != v){
                mark[v] = i;
                break;
            }
        }
        pr = mark[v];
        for (auto u: in[v]) if (cycle[u]){
            v = u;
            break;
        }
    }
    if (mark[v0] != pr){
        cout << "POSSIBLE";
        exit(0);
    }
}
main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    cin >> n;
    for (int i = 1; i <= n; i++){
        int u, v;
        cin >> u;
        v = i;
        g[v].pb(u);
        g[u].pb(v);
        G[u].pb(v);
        in[v].pb(u);
        deg[u]++;
    }
    dfs1(1);
    for (int i = 1; i <= n; i++) if (cycle[i]) dfs2(i);
    for (int i = 1; i <= n; i++){
        if (cycle[i]){
            vector < int > cand;
            for (auto j: c[i]) b[j] = 1;
            for (int j = 0; j <= n + 5; j++) if (b[j] == 0) cand.pb(j);
            tr(i, cand[0]);
            tr(i, cand[1]);
            cout << "IMPOSSIBLE";
            return 0;
        }
    }
}

