int N;
vector<int> G[200000];
bool used[200000];
int grundy[200000];

int dfs(int i) {
	if (used[i]) return grundy[i];
	used[i] = true;
	if (G[i].empty()) return grundy[i] = 0;
	set<int> s;
	for (int to : G[i]) {
		int val = dfs(to);
		s.insert(val);
	}
	if(s.count(-1) > 0) return grundy[i] = -1;
	int ret = 0;
	while (s.count(ret) > 0) ++ret;
	return grundy[i] = ret;
}

bool loop(int i) {
	set<int> s;
	for (int to : G[i]) {
		int val = grundy[to];
		s.insert(val);
	}
	int p = 0;
	while (s.count(p) > 0) ++p;
	Fill(used, false);
	grundy[i] = p;
	if (dfs(i) == p) return true;
	Fill(used, false);
	grundy[i] = p + 1;
	if (dfs(i) == p + 1) return true;
	return false;
}

int main() {
	cin >> N;
	REP(i, 0, N) {
		int a;
		cin >> a;
		G[a - 1].push_back(i);
	}
	Fill(grundy, -1);
	REP(i, 0, N) {
		if (used[i]) continue;
		dfs(i);
	}
	int* it = find(grundy, grundy + N, -1);
	cout << (loop(it - grundy) ? "" : "IM") << "POSSIBLE" << endl;
	return 0;
}

