int g[N],minn[N];

void go(int cur)
{
	if(use[cur])
	{
		for(int i=0;i<N;i++)
			if(use[i])
				cycle[i]=1;
		return;
	}
	if(mark[cur])	return;
	use[cur]=1;
	mark[cur]=1;
	for(auto x:v[cur])
		go(x);
	use[cur]=0;
}

void compute(int cur)
{
	for(auto x:v[cur])
		if(g[x]==-1)
		{
			compute(x);
			reach[cur][g[x]]++;
		}
	for(g[cur]=0;reach[cur][g[cur]];g[cur]++);
}

int main()
{
	clr(cycle);
	clr(use);
	clr(mark);
	int n,i;
	sd(n);
	for(i=1;i<=n;i++)
	{
		sd(p[i]);
		v[p[i]].PB(i);
	}
	for(i=1;i<=n;i++)
	{
		if(mark[i])	continue;
		go(i);
	}
	for(i=1;i<=n;i++)
		g[i]=-1;
	for(i=1;i<=n;i++)
	{
		if(g[i]!=-1 || cycle[i])	continue;
		compute(i);
	}
	int cur;
	for(cur=1;cycle[cur]==0;cur++);

	for(i=1;i<=n;i++)
	{
		if(cycle[i]==0)	continue;
		for(auto x:v[i])
			if(!cycle[x])
				reach[i][g[x]]=1;
		for(minn[i]=0;reach[i][minn[i]];minn[i]++);
	}
	int cnt=0;
	for(;cnt<1000000;cnt++,cur=p[cur])
	{
		reach[p[cur]][g[cur]]--;
		for(g[cur]=minn[cur];reach[cur][g[cur]];g[cur]++);
		reach[p[cur]][g[cur]]++;
	}
	// for(i=1;i<=n;i++)
	// 	cout<<g[i]<<' ';
	// cout<<'\n';
	for(i=1;i<=n;i++)
	{
		reach[i].clear();
		for(auto x:v[i])
			reach[i][g[x]]++;
		int j;
		for(j=0;reach[i][j];j++);
		if(j!=g[i])
			break;
	}
	if(i<=n)
		printf("IMPOSSIBLE\n");
	else
		printf("POSSIBLE\n");
}

#include <bits/stdc++.h>

using namespace std;

const int INF = 1e9;

vector< vector<int> > g;

bool dfs(int cur, vector<int>& used, vector<int>& cycle) {
	if (used[cur] == 1) {
		cycle[cur] = true;
		return true;
	}
	used[cur] = 1;
	for (int nex : g[cur]) {
		if (dfs(nex, used, cycle)) {
			cycle[cur] = true;
			return true;
		}
	}
	used[cur] = 2;
	return false;
}

int solve(int cur, vector<int>& cycle, vector<int>& grundy) {
	if (grundy[cur] != INF) return grundy[cur];
	set<int> s;
	for (int nex : g[cur]) {
		if (cycle[nex]) continue;
		int x = solve(nex, cycle, grundy);
		s.insert(x);
	}
	int res = 0;
	while (s.find(res) != s.end()) res++;
	return grundy[cur] = res;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;
	cin >> n;
	g.resize(n);
	for (int i = 0; i < n; i++) {
		int p;
		cin >> p;
		p--;
		g[p].push_back(i);
	}
	vector<int> used(n, 0), cycle(n, false);
	for (int i = 0; i < n; i++) {
		if (used[i]) continue;
		dfs(i, used, cycle);
	}
	int x = -1, cnt = 0;
	bool ans = true;
	vector<int> grundy(n, INF);
	for (int i = 0; i < n; i++) {
		if (cycle[i]) {
			cnt++;
			int y = solve(i, cycle, grundy);
			if (x == -1) {
				x = y;
				ans = false;
			} else if (x != y) {
				ans = true;
				break;
			}
		}
	}
	if (!ans) ans = (cnt % 2 == 0);
	cout << (ans ? "POSSIBLE" : "IMPOSSIBLE") << endl;
	return 0;
}

