		}
		get_color(to);
		have.pb(col[to]);
	}
	sort(have.begin(), have.end());
	int to_color = 0;
	for(int c : have)
	{
		if(c > to_color)
			break;
		if(c < to_color)
			continue;
		to_color++;
	}
	col[x] = to_color;
}

