bool is_connected(vector<int> p)
{
    int n = p.size();
    vector<vector<int>> e(n);
    for (int i = 0; i < n; i++)
    {
        e[p[i]].push_back(i);
        e[i].push_back(p[i]);
    }

    vector<int> d(n, -1);
    d[0] = 0;

    deque<int> q;
    q.push_back(0);

    while (!q.empty())
    {
        int v = q.front();
        q.pop_front();

        for (int u: e[v])
        {
            if (d[u] == -1)
            {
                d[u] = d[v] + 1;
                q.push_back(u);
            }
        }
    }

    for (int i = 0; i < n; i++)
        if (d[i] == -1)
            return false;

    return true;
}

