using namespace std;

const int N = 200 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n;
int p[N], deg[N], res[N];
vector<int> vec[N], G[N];

bool read() {
    if (!(cin >> n))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> p[i];

    return true;
}

bool check(int v, int x) {
    res[v] = x;
    vec[p[v]].emplace_back(x);

    for (int u = p[v]; u != v; u = p[u]) {
        auto vv = vec[u];
        sort(vv.begin(), vv.end());
        vv.resize(unique(vv.begin(), vv.end()) - vv.begin());

        for (int i = 0; res[u] == -1; ++i)
            if (i >= vv.size() || i != vv[i])
                res[u] = i;

        vec[p[u]].emplace_back(res[u]);
    }

    for (int v = 0; v < n; ++v) {
        vector<int> vv;

        for (auto to : G[v])
            vv.emplace_back(res[to]);

        sort(vv.begin(), vv.end());
        vv.resize(unique(vv.begin(), vv.end()) - vv.begin());

        for (int i = 0; ; ++i)
            if (i >= vv.size() || i != vv[i]) {
                if (res[v] != i)
                    return false;

                break;
            }
    }

    return true;
}

void solve() {
    for (int i = 0; i < n; ++i) {
        ++deg[--p[i]];
        G[p[i]].emplace_back(i);
    }

    fill(res, res + n, -1);
    queue<int> Q;

    for (int i = 0; i < n; ++i)
        if (deg[i] == 0)
            Q.push(i);

    for (; !Q.empty(); Q.pop()) {
        auto v = Q.front();
        sort(vec[v].begin(), vec[v].end());
        vec[v].resize(unique(vec[v].begin(), vec[v].end()) - vec[v].begin());

        for (int i = 0; res[v] == -1; ++i)
            if (i >= vec[v].size() || i != vec[v][i])
                res[v] = i;

        vec[p[v]].emplace_back(res[v]);

        if (--deg[p[v]] == 0)
            Q.push(p[v]);
    }

    vector<int> cc;

    for (int v = 0; v < n; ++v)
        if (res[v] == -1)
            cc.emplace_back(v);

    assert(!cc.empty());
    auto v = cc[0];
    vector<int> mex, vv = vec[v];

    for (int k = 0; k < 2; ++k) {
        sort(vv.begin(), vv.end());
        vv.resize(unique(vv.begin(), vv.end()) - vv.begin());

        for (int i = 0; mex.size() != k + 1; ++i)
            if (i >= vv.size() || i != vv[i])
                mex.emplace_back(i);

        vv.emplace_back(mex.back());
    }

    if (check(v, mex[0])) {
        cout << "POSSIBLE\n";
        return ;
    }

    for (const auto& u : cc) {
        res[u] = -1;
        vec[u].pop_back();
    }

    if (check(v, mex[1])) {
        cout << "POSSIBLE\n";
        return ;
    }

    cout << "IMPOSSIBLE\n";
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

