typedef long long ll;
const int max_n=200005;
int vis[max_n],tot;
vector<int> stk;
int n;
vector<int> G[max_n];
vector<int> cycle;
void dfs(int u){
    stk.push_back(u);
    vis[u]=tot;
    for(auto v:G[u]){
        if(!vis[v])dfs(v);
        else if(vis[v]==tot){
            while(1){
                int x=stk.back();stk.pop_back();
                cycle.push_back(x);
                if(x==v)break;
            }
            return;
        }
    }
    if(!stk.empty())stk.pop_back();
}
int sg[max_n];
int SG(int u){
    if(~sg[u])return sg[u];
    set<int> s;
    for(auto v:G[u])if(!vis[v])s.insert(SG(v));
    for(int i=0;;i++)if(s.count(i)==0)return sg[u]=i;
}
int main(){
    scanf("%d",&n);
    for(int i=1;i<=n;i++){
        int x;scanf("%d",&x);
        G[x].push_back(i);
    }
    for(int i=1;i<=n;i++){
        if(!vis[i]){
            ++tot;
            dfs(i);
        }
    }
    reverse(cycle.begin(),cycle.end());
    if(cycle.empty())printf("POSSIBLE\n");
    else{
        for(int i=1;i<=n;i++)vis[i]=0;
        for(int i=1;i<=n;i++)sg[i]=-1;
        for(auto x:cycle)vis[x]=1;
        for(auto &x:cycle)x=SG(x);
        bool f=false;
        for(int t=0;t<2;t++){
            int pre=cycle.back()+t;
            for(auto x:cycle){
                if(pre==x)pre=x+1;
                else pre=x;
            }
            f|=pre==cycle.back()+t;
        }
        if(f)printf("POSSIBLE\n");
        else printf("IMPOSSIBLE\n");
    }
    return 0;
}

