using namespace std;


void dfs(int u, vector<int> &ans, vector<vector<int>> &from, vector<vector<int>> &to) {

    FOE(v, to[u]) {
        if (ans[v] == -1) {
            if (from[v].size() == 1) {
                if (ans[u] == 0) {
                    ans[v] = 1;
                }
                else {
                    ans[v] = 0;
                }
                dfs(v, ans, from, to);
            }

        }
    }
}

bool check(int u, vector<int> &ans, vector<vector<int>> &from, vector<vector<int>> &to) {
    int v = to[u][0];
    while (true) {
        unordered_set<int> s;
        FOE(x, from[v]) {
            s.insert(ans[x]);
        }

        FOR(i, 0, s.size() + 2) {
            if (s.find(i) == s.end()) {
                if (ans[v] != -1) {
                    return ans[v] == i;
                }
                ans[v] = i;
                break;
            }
        }

        v = to[v][0];
    }
}

