    FOR(i, 0, N) {
        if (from[i].empty()) {
            ans[i] = 0;
        }
    }
    FOR(i, 0, N) {
        if (ans[i] == 0) {
            dfs(i, ans, from, to);
        }
    }

    int start = -1;
    FOR(i, 0, N) {
        if (ans[i] == -1) {
            if (start == -1) {
                start = i;
            }
            if (from[i].size() != 1) {
                start = i;
            }
        }
    }
    if (start == -1) {
        start = 0;
    }


    set<int> c;
    FOE(u, from[start]) {
        c.insert(ans[u]);
    }

    FOR(i, 0, c.size() + 2) {
