struct Graph {
    Graph(ll n)
    {
        edge.resize(n);
    }
    void addEdge(ll from, ll to)
    {
        edge[from].push_back(to);
    }
    vector<vector<ll>> edge;
};

ll N;
pair<ll, ll> dfs(const Graph& g, ll s, const vector<bool>& cycle, vector<ll>& value)
{
    multiset<ll> st;
    for (const ll p : g.edge[s]) {
        if (cycle[p]) {
            continue;
        }
        const ll child = dfs(g, p, cycle, value).first;
        st.insert(child);
    }
    ll first = -1;
    ll second = -1;
    for (ll i = 0; i <= 2 * N; i++) {
        if (st.find(i) == st.end()) {
            if (first == -1) {
                first = i;
            } else if (second == -1) {
                second = i;
                break;
            }
        }
    }
    value[s] = first;
    assert(first >= 0 and second > first);
    return make_pair(first, second);
}

int main()
{
    cin >> N;
    Graph g(N);
    Graph rev(N);

    for (ll i = 0; i < N; i++) {
        ll from;
        cin >> from;
        from--;
        g.addEdge(from, i);
        rev.addEdge(i, from);
    }

    ll pos = 0;
    for (ll i = 0; i < 2 * N; i++) {
        pos = rev.edge[pos][0];
    }
    vector<bool> cycle(N, false);
    vector<ll> comp;
    for (ll i = 0; i < 2 * N; i++) {
        if (cycle[pos]) {
            break;
        }
        comp.push_back(pos);
        cycle[pos] = true;
        pos = rev.edge[pos][0];
    }
    const ll size = comp.size();

    for (ll i = 1; i < size; i++) {
        assert(rev.edge[comp[i - 1]][0] == comp[i]);
    }
    assert(rev.edge[comp[size - 1]][0] == comp[0]);

    vector<ll> value(N, 0);
    const auto pi = dfs(g, comp[0], cycle, value);

    for (ll d = 0; d < 2; d++) {
        ll prev = (d == 0) ? pi.first : pi.second;
        value[comp[0]] = prev;
        for (ll i = 1; i < size; i++) {
            const ll p = comp[i];
            const auto q = dfs(g, p, cycle, value);
            prev = (q.first == prev) ? q.second : q.first;
            value[comp[i]] = prev;
        }
        if (prev != value[comp[0]]) {
            for (ll i = 0; i < N; i++) {
                multiset<ll> st;
                for (const ll c : g.edge[i]) {
                    st.insert(value[c]);
                }
                for (ll j = 0; j < value[i] - 1; j++) {
                    assert(st.find(j) != st.end());
                }
            }

            cout << "POSSIBLE" << endl;
            return 0;
        }
    }
    cout << "IMPOSSIBLE" << endl;

    return 0;
}

