VVi G;
Vi grn;

int dfs(int u) {
  if (grn[u] != -1) return grn[u];

  int d = sz(G[u]);
  Vb seen(d+1);
  for (int v : G[u]) {
    int g = dfs(v);
    if (g <= d) seen[g] = true;
  }
  rep(i, d+1) if (!seen[i]) return grn[u] = i;
  return -1;
}



int main() {
  int n; cin >> n;
  Vi p(n); cin >> p;
  rep(i, n) --p[i];

  int x = 0;
  Vb seen(n);
  while (!seen[x]) {
    seen[x] = true;
    x = p[x];
  }

  Vb cyc(n);
  while (!cyc[x]) {
    cyc[x] = true;
    x = p[x];
  }

  G.assign(n, Vi());
  grn.assign(n, -1);
  rep(i, n) G[p[i]].push_back(i);

  Vi rs;
  rep(i, n) if (cyc[i]) {
    for (auto j : G[i]) if (!cyc[j]) rs.push_back(j);
  }

  for (auto r : rs) dfs(r);

  int s = -1;
  int cm = n;
  rep(i, n) if (cyc[i]) {
    int d = sz(G[i]);
    if (d < cm) s = i, cm = d;
  }

  set<int> S;
  rep(i, cm+1) S.insert(i);
  for (auto v : G[s]) S.erase(grn[v]);

  if (sz(S) > 2) S.erase(next(S.begin(), 2), S.end());


  for (auto g : S) {
    grn[s] = g;
    int u = p[s];
    while (u != s) {
      dfs(u);
      u = p[u];
    }
    grn[s] = -1;
    if (g == dfs(s)) {
      cout << "POSSIBLE\n";
      return 0;
    }
    u = p[u];
    while (u != s) {
      grn[u] = -1;
      u = p[u];
    }
  }

  cout << "IMPOSSIBLE\n";
}

