int n, Q[201000], head, tail, Deg[201000], v[201000], D[201000], E[201000];
vector<int> F[201000];
bool Pos(int a, int d) {
	D[a] = d;
	int x = a, i;
	while (1) {
		x = E[x];
		for (i = 0; i < F[x].size(); i++) {
			v[D[F[x][i]]] = -x;
		}
		for (i = 0;; i++)if (v[i] != -x)break;
		if (x == a && i != d)return false;
		D[x] = i;
		if (x == a)return true;
	}
}
int main() {
	int i, x;
	scanf("%d", &n);
	for (i = 1; i <= n; i++) {
		scanf("%d", &x);
		E[i] = x;
		F[x].push_back(i);
		Deg[x]++;
	}
	for (i = 1; i <= n; i++) {
		if (!Deg[i])Q[++tail] = i;
	}
	while (head < tail) {
		x = Q[++head];
		for (i = 0; i < F[x].size(); i++) {
			v[D[F[x][i]]] = x;
		}
		for (i = 0;; i++)if (v[i] != x)break;
		D[x] = i;
		int y = E[x];
		Deg[y]--;
		if (!Deg[y]) Q[++tail] = y;
	}
	for (i = 1; i <= n; i++)if (Deg[i])break;
	x = i;
	for (i = 0; i < F[x].size(); i++)if(!Deg[F[x][i]])v[D[F[x][i]]] = x;
	for (i = 0;; i++)if (v[i] != x)break;
