	for (i = i + 1;; i++)if (v[i] != x)break;
	int r2 = i;
	if (Pos(x, r1))puts("POSSIBLE");
	else {
		if (Pos(x, r2))puts("POSSIBLE");
		else puts("IMPOSSIBLE");
	}
}

