using namespace std;

int mex(set<int> x)
{
    int r = 0;
    while(x.count(r))
        r++;
    return r;
}

const int maxn = 6e5;
vector<int> G[maxn], Gt[maxn];

void add_edge(int u, int z1, int v, int z2)
{
    int U = u + maxn / 2 * z1;
    int V = v + maxn / 2 * z2;
    G[U].push_back(V);
    Gt[V].push_back(U);
}

int used[maxn];

void dfs(int v, vector<int> *G, vector<int> &st)
{
    if(used[v])
        return;
    used[v] = 1;
    for(auto u: G[v])
        dfs(u, G, st);
    st.push_back(v);
}

void try2sat()
{
    vector<int> top_sort;
    for(int i = 0; i < maxn; i++)
        dfs(i, G, top_sort);
    memset(used, 0, sizeof(used));
    for(auto v: top_sort)
    {
        if(used[v])
            continue;
        vector<int> comp;
        dfs(v, Gt, comp);
        set<int> lol;
        for(auto u: comp)
        {
            lol.insert(u);
            if(lol.count(u ^ 1))
            {
                cout << "IMPOSSIBLE\n";
                exit(0);
            }
        }
    }
    cout << "POSSIBLE\n";
}

signed main()
{
    //freopen("input.txt", "r", stdin);
    ios::sync_with_stdio(0);
    cin.tie(0);
    int n;
    cin >> n;
    int p[n], cnt[n] = {0};
    set<pair<int, int>> vrt;
    for(int i = 0; i < n; i++)
    {
        cin >> p[i];
        p[i]--;
        vrt.erase({cnt[p[i]], p[i]});
        cnt[p[i]]++;
        vrt.insert({cnt[p[i]], p[i]});
    }
    set<int> banned[n];
    while(begin(vrt)->first == 0)
    {
        int v = begin(vrt)->second;
        vrt.erase(begin(vrt));
        vrt.erase({cnt[p[v]], p[v]});
        cnt[p[v]]--;
        vrt.insert({cnt[p[v]], p[v]});
        banned[p[v]].insert(mex(banned[v]));
    }
    int m[n][2];
    for(auto it: vrt)
    {
        int v = it.second;
        m[v][0] = mex(banned[v]);
        banned[v].insert(m[v][0]);
        m[v][1] = mex(banned[v]);
    }
    for(auto it: vrt)
    {
        int v = it.second;
        int u = p[v];
        for(int z1 = 0; z1 <= 1; z1++)
            for(int z2 = 0; z2 <= 1; z2++)
                if(m[u][z1] == m[v][z2])
                {
                    add_edge(u, z1, v, !z2);
                    add_edge(v, z2, u, !z1);
                }
        if(m[u][0] == m[v][0])
        {
            add_edge(u, 1, v, 0);
        }
        else if(m[u][0] == m[v][1])
        {
            add_edge(u, 1, v, 1);
        }
        else
        {
            add_edge(u, 1, u, 0);
        }
    }
    try2sat();
}

