void tpsort(int v)
{
	used[v] = true;
	for(int i = 0; i < G[v].size(); i++){
		if(used[G[v][i]]) continue;
		tpsort(G[v][i]);
	}
	topo.push_back(v);
}

void dfs(int v, int id)
{
	used[v] = true;
	scc[v] = id;
	for(int i = 0; i < revG[v].size(); i++){
		if(used[revG[v][i]]) continue;
		dfs(revG[v][i], id);
	}
}

int main(void)
{
	cin >> N;
	int p;
	for(int i = 1; i <= N; i++){
		cin >> p;
		G[p].push_back(i);
		revG[i].push_back(p);
	}

	for(int i = 1; i <= N; i++){
		if(!used[i]) tpsort(i);
	}
	reverse(topo.begin(), topo.end());

	for(int i = 1; i <= N; i++) used[i] = false;
	for(int i = 0; i < topo.size(); i++){
		if(!used[topo[i]]) dfs(topo[i], i);
	}

	for(int i = 1; i <= N; i++) cout << scc[i] << " ";
	cout << endl;

	set<int> s;
	lpid = -1;
	for(int i = 1; i <= N; i++){
		if(s.count(scc[i])){
			lpid = scc[i];
			lpstart = i;
			break;
		}
		s.insert(scc[i]);
	}
	if(lpid == -1){
		cout << "POSSIBLE" << endl;
		return 0;
	}

	reverse(topo.begin(), topo.end());

	int v, g;
	for(int i = 0; i < topo.size(); i++){
		s.clear();
		v = topo[i];
		for(int j = 0; j < G[v].size(); j++){
			if(grundy[G[v][j]] == -1 || scc[G[v][j]] == lpid){
				grundy[v] = -1;
				goto end;
			}
			s.insert(grundy[G[v][i]]);
		}
		g = 0;
		while(s.count(g)) g++;
		grundy[v] = g;
		end:;
	}

	for(int k = 0; k < 2; k++){
		v = lpstart;
		s.clear();
		for(int i = 0; i < G[v].size(); i++){
			s.insert(grundy[G[v][i]]);
		}
		g = 0;
		while(s.count(g)) g++;
		if(k == 1){
			g++;
			while(s.count(g)) g++;
		}
		grundy[v] = g;

		while(1){
			v = revG[v][0];
			if(v == lpstart) break;

			s.clear();
			for(int j = 0; j < G[v].size(); j++){
				s.insert(grundy[G[v][j]]);
			}
			g = 0;
			while(s.count(g)) g++;
			grundy[v] = g;
		}

		s.clear();
		for(int j = 0; j < G[v].size(); j++){
			s.insert(grundy[G[v][j]]);
		}
		g = 0;
		while(s.count(g)) g++;
		if(grundy[v] == g){
			cout << "POSSIBLE" << endl;
			return 0;
		}
	}

	cout << "IMPOSSIBLE" << endl;
	return 0;
}

