const int MAXN = 200010;
struct edge{int t,w,next;}edges[MAXN<<1];
int head[MAXN],top = 1;
void add(int f,int t,int w = 0){
	edges[++top].next = head[f];
	edges[top].t = t;
	edges[top].w = w;
	head[f] = top;
}
bool vis[MAXN],inloop[MAXN],flag[MAXN<<1];
int loop[MAXN],cnt,pa[MAXN];
void getloop(int x){
	vis[x] = true;
	for(int i = head[x];i;i = edges[i].next){
		int t = edges[i].t;
		if(flag[i]||flag[i^1])continue;
		flag[i] = flag[i^1] = true;
		if(vis[t]){
			loop[++cnt] = t;
			inloop[t] = true;
			for(int p = x;p!=t;p = pa[p]){
				loop[++cnt] = p;
				inloop[p] = true;
			}
		}
		pa[t] = x;
		getloop(t);
	} 
}
int mark[MAXN];
int dp[MAXN],dfn;
void dfs(int x){
	vis[x] = true;
	for(int i = head[x];i;i = edges[i].next){
		int t = edges[i].t;
		if(inloop[t]||vis[t])continue;
		dfs(t);
	}
	dfn++;
	for(int i = head[x];i;i = edges[i].next){
		int t = edges[i].t;
		if(inloop[t])continue;
		mark[dp[t]] = dfn;
	}
	dp[x] = 0;
	while(mark[dp[x]]==dfn)dp[x]++;
}
int main(){
