void input()
{
    read(N);
    for (int i = 1; i <= N; ++i) {
        read(P[i]);
        G[P[i]].push_back(i);
    }
}

bool vis[MAXN];
bool oncycle[MAXN];
int min[MAXN], sec[MAXN];

int dfs(int u)
{
    vector<int> list;
    for (int i = 0; i < SZ(G[u]); ++i) {
        int v = G[u][i];
        if (!oncycle[v])
            list.push_back(dfs(v));
    }
    std::sort(ALL(list));
    list.push_back(+oo);
    int i = 0, p = 0;
    for (; list[p] == i; ++i, ++p) { }
    min[u] = i++;
    for (; list[p] == i; ++i, ++p) { }
    sec[u] = i;
    return min[u];
}

void solve()
{
    for (int i = 1; i <= N; ++i) {
        if (vis[i])
            continue;
        int j = i;
        for (; !vis[j]; j = P[j]) {
            vis[j] = true;
        }
        for (; !oncycle[j]; j = P[j]) {
            oncycle[j] = true;
        }
    }
    for (int i = 1; i <= N; ++i) {
        if (oncycle[i])
            dfs(i);
    }

    // for (int i = 1; i <= N; ++i) {
    //     if (oncycle[i])
    //         printf("%d: min=%d, sec=%d\n", i, min[i], sec[i]);
    // }

    std::fill(vis + 1, vis + N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        if (vis[i] || !oncycle[i])
            continue;
        int last = min[i];
        vis[i] = true;
        for (int j = P[i]; j != i; j = P[j]) {
            last = (last == min[j] ? sec[j] : min[j]);
            vis[j] = true;
        }
        if (last != min[i])
            continue;
        last = sec[i];
        for (int j = P[i]; j != i; j = P[j]) {
            last = (last == min[j] ? sec[j] : min[j]);
        }
        if (last != min[i]) {
            puts("IMPOSSIBLE");
            return;
        }
    }
    puts("POSSIBLE");
}

