struct Union_find{
	Union_find(int n){par.resize(n),iota(_all(par),0);}
	int find(int x){return (par[x]==x)?x:par[x]=find(par[x]);}
	void unite(int a,int b){a=find(a),b=find(b);par[a]=b;}
	bool same(int a,int b){return find(a)==find(b);}
	vector<int> par;
};


const int limit = 200010;
int deg[limit];
int grundy[limit];
vector<int> graph[limit];

int main(void){
	int n;
	cin >> n;
	vector<int> p(n);
	rep(i,n) cin >> p[i],p[i]--;

	rep(i,n) deg[p[i]]++,grundy[i]=-1;

	queue<int> q;
	rep(i,n) if(deg[i]==0) q.push(i),grundy[i]=0;

	vector<int> visited(n,0);

	while(!q.empty()){
		int cur = q.front(); q.pop();
		if(visited[cur]) continue;
		visited[cur] = 1;

		const int par = p[cur];
		if(grundy[par] == -1)
			grundy[par] = grundy[cur]^1;
		else
			grundy[par]++;

		q.push(par);
	}

	bool ok = true;

	rep(i,n) graph[p[i]].push_back(i);

	rep(i,n){
		set<int> s;
		for(auto &j:graph[i]) s.insert(grundy[j]);
		int hoge = 0;
		while(s.find(hoge)!=end(s)) hoge++;
		if(grundy[i]!=hoge) ok = false;
	}

	bool special = true;
	rep(i,n) if(grundy[i]!=-1) special = false;

	if(special){
		ok = true;
		Union_find uf(n);
		rep(i,n) uf.unite(p[i],i);
		vector<int> num(n,0);
		rep(i,n) num[uf.find(i)]++;
		rep(i,n){
			if(num[i]==0) continue;
			if(num[i]%2==1) ok = false;
		}
	}

	if(ok)
		puts("POSSIBLE");
	else
		puts("IMPOSSIBLE");


	return 0;
}

