		if (now == cycle.front())break;
		cycle.push_back(now);
	}
	int period = cycle.size();
	//cycle.push_back(cycle.front());
	for (int i = 0; i < period; ++i)
	{
		//cycle[i] <- cycle[i+1]
		int S = i;
		int T = (i + 1) % period;
		int lef = cycle[S];
		int now = cycle[T];
		if (graph[now].size() == 1)
		{
			//0->1
			//1->0
			//2->0
			path[S * 6 + 0].push_back(T * 6 + 0 + 3);
			path[S * 6 + 0].push_back(T * 6 + 1 + 0);
			path[S * 6 + 0].push_back(T * 6 + 2 + 3);
			path[S * 6 + 1].push_back(T * 6 + 0 + 0);
			path[S * 6 + 1].push_back(T * 6 + 1 + 3);
			path[S * 6 + 1].push_back(T * 6 + 2 + 3);
			path[S * 6 + 2].push_back(T * 6 + 0 + 0);
			path[S * 6 + 2].push_back(T * 6 + 1 + 3);
			path[S * 6 + 2].push_back(T * 6 + 2 + 3);
		}
		else
		{
			assert(graph[now].size() == 2);
			int down = -1;
			if (graph[now][0] != lef)
			{
				down = graph[now][0];
			}
			else if (graph[now][1] != lef)
			{
				down = graph[now][1];
			}
			else assert(false); 
			int dnum = br(down) % 2;
			if (dnum == 0)
			{
				//0->1
				//1->2
				//2->1
				path[S * 6 + 0].push_back(T * 6 + 0 + 3);
				path[S * 6 + 0].push_back(T * 6 + 1 + 0);
				path[S * 6 + 0].push_back(T * 6 + 2 + 3);
				path[S * 6 + 1].push_back(T * 6 + 0 + 3);
				path[S * 6 + 1].push_back(T * 6 + 1 + 3);
				path[S * 6 + 1].push_back(T * 6 + 2 + 0);
				path[S * 6 + 2].push_back(T * 6 + 0 + 3);
				path[S * 6 + 2].push_back(T * 6 + 1 + 0);
				path[S * 6 + 2].push_back(T * 6 + 2 + 3);
			}
			else
			{
				//0->2
				//1->0
				//2->0
				path[S * 6 + 0].push_back(T * 6 + 0 + 3);
				path[S * 6 + 0].push_back(T * 6 + 1 + 3);
				path[S * 6 + 0].push_back(T * 6 + 2 + 0);
				path[S * 6 + 1].push_back(T * 6 + 0 + 0);
				path[S * 6 + 1].push_back(T * 6 + 1 + 3);
				path[S * 6 + 1].push_back(T * 6 + 2 + 3);
				path[S * 6 + 2].push_back(T * 6 + 0 + 0);
				path[S * 6 + 2].push_back(T * 6 + 1 + 3);
				path[S * 6 + 2].push_back(T * 6 + 2 + 3);
			}
		}
	}
	vector<int>top;
	scc(path, period * 6, top);
	for (int i = 0; i < period; ++i)
	{
		for (int d = 0; d < 3; ++d)
		{
			if (top[i * 6 + d] == top[i * 6 + d + 3])
			{
				//i = 非i
				cout << "IMPOSSIBLE\n";
				return 0;
			}
			if (top[i * 6 + d] == top[i * 6 + (d + 1) % 3])
			{
				//i = (i+1)
				cout << "IMPOSSIBLE\n";
				return 0;
			}
		}
	}
	cout << "POSSIBLE\n";
	return 0;
}

#include<bits/stdc++.h>
using namespace std;

int main() {
  int N;
  cin >> N;
  vector<int> P(N);
  for(auto& p: P) cin >> p, --p;

  vector<vector<int>> G(N);
  for(auto v=0; v<N; ++v) G[P[v]].emplace_back(v);

  vector<int> Grundy(N, -1);

  queue<int> q;
  for(auto v=0; v<N; ++v) if(G[v].empty()) q.emplace(v);
  while(!q.empty()) {
    auto u = q.front();
    auto p = P[u];
    q.pop();
    set<int> S;
    for(auto v: G[u]) S.emplace(Grundy[v]);
    for(auto i=0; i<N; ++i) if(!S.count(i)) {
      Grundy[u] = i;
      break;
    }
    if(G[p].size()==1) q.emplace(p);
  }

  function<int(vector<int>&, int)> dfs = [&](auto& g, auto u) {
    if(g[u]!=-1) return g[u];
    set<int> S;
    for(auto v: G[u]) S.emplace(dfs(g, v));
    for(auto i=0; i<N; ++i) if(!S.count(i)) return g[u] = i;
    assert(false);
  };

  auto check = [&](auto& g) {
    for(auto u=0; u<N; ++u) {
      set<int> S;
      for(auto v: G[u]) {
        if(g[u]==g[v]) return false;
        S.emplace(g[v]);
      }
      for(auto i=0; i<g[u]; ++i) if(!S.count(i)) return false;
    }
    return true;
  };

  auto ok = false;
  for(auto u=0; u<N; ++u) if(Grundy[u]==-1) {
    set<int> S;
    for(auto v: G[u]) S.emplace(Grundy[v]);
    auto i=0;
    for(; i<N; ++i) if(!S.count(i)) break;
    for(auto g: {i, i+1}) {
      auto dup = Grundy;
      dup[u] = g;
      for(auto v=0; v<N; ++v) if(dup[v]==-1) dfs(dup, v);
      if(check(dup)) ok = true;
    }
    break;
  }
  cout << (ok ? "POSSIBLE" : "IMPOSSIBLE") << endl;
}

