using namespace std;
typedef long long LL;
const int maxn = 200005;

int ehead[maxn],ecnt;
struct edge {
	int u,v,next;
}edg[maxn];
void add(int u,int v) {
	edg[++ecnt]=(edge){u,v,ehead[u]};
	ehead[u]=ecnt;
}
bool vis[maxn],ins[maxn],onring[maxn],flag;
int n,a[maxn],fa[maxn],stk[maxn],top,bac[maxn];
void dfs(int u)
{
	vis[u]=ins[u]=true;
	for (int v,j=ehead[u];j&&!flag;j=edg[j].next) 
	if (ins[v=edg[j].v]) {
		onring[v]=flag=true;stk[++top]=v;
		for (int j=u;j!=v;j=fa[j])
			onring[j]=true,stk[++top]=j;
	}
	else if (!vis[v]) fa[v]=u,dfs(v);
	ins[u]=false;
}
int calc1(int u)
{
	for (int v,j=ehead[u];j;j=edg[j].next)
	if (!onring[v=edg[j].v]) bac[a[v]]++;
	int w=0;while (bac[w]) ++w;
	for (int v,j=ehead[u];j;j=edg[j].next)
	if (!onring[v=edg[j].v]) bac[a[v]]--;
	return w;
}
int calc2(int u)
{
	for (int j=ehead[u];j;j=edg[j].next)
		bac[a[edg[j].v]]++;
	int w=0;while (bac[w]) ++w;
	for (int j=ehead[u];j;j=edg[j].next)
		bac[a[edg[j].v]]--;
	return w;
}
void dfs2(int u)
{
	for (int v,j=ehead[u];j;j=edg[j].next)
	if (!onring[v=edg[j].v]) dfs2(v);
	a[u]=calc1(u);
}
