        p[i]--;
        vrt.erase({cnt[p[i]], p[i]});
        cnt[p[i]]++;
        vrt.insert({cnt[p[i]], p[i]});
    }
    set<int> banned[n];
    while(begin(vrt)->first == 0)
    {
        int v = begin(vrt)->second;
        vrt.erase(begin(vrt));
        vrt.erase({cnt[p[v]], p[v]});
        cnt[p[v]]--;
        vrt.insert({cnt[p[v]], p[v]});
        banned[p[v]].insert(mex(banned[v]));
    }
    int m[n][2];
    for(auto it: vrt)
    {
        int v = it.second;
        m[v][0] = mex(banned[v]);
        banned[v].insert(m[v][0]);
        m[v][1] = mex(banned[v]);
    }
    for(auto it: vrt)
    {
