void topu() {
	static int q[maxN]; int h = 0, t = 0;
	rep (i, 1, n) if (deg[i] == 0) q[++t] = i;
	while (h != t) {
		int x = q[++h], y = bac[x];
		if (--deg[y] == 0) q[++t] = y;
	}
	rep (i, 1, n) if (deg[i]) {
		lop[tl = 1] = i;
		for (int x = bac[i]; x != i; x = bac[x]) lop[++tl] = x;
		rep (i, 1, tl) vis[lop[i]] = 1;
		break;
	}
}

void dfs(int x, int fa) {
	static int q[maxN];
	int tq = 0;
	fore (e, x, y) if (y != fa && !vis[y]) {
		dfs(y, x);
		q[++tq] = val[y][0];
	}
	sort(q+1, q+tq+1);
	tq = unique(q+1, q+tq+1) - (q+1);
	for (int cur = 0, i = 1; ; ++ cur) {
		if (i <= tq && q[i] == cur) {++ i; continue;}
		if (!val[x][0]) val[x][0] = cur;
		else if (!val[x][1]) {val[x][1] = cur; break;}
	}
}

bool ok(int x, int y, int kd) {
