  used[v] = true;
  cmp[v] = k;
  for (ll i = 0; i < rG[v].size(); i++) {
    if (!used[rG[v][i]]) rdfs(rG[v][i], k);
  }
}

ll scc() {
  memset(used, 0, sizeof(used));
  vs.clear();
  for (ll v = 0; v < V; v++) {
    if (!used[v]) dfs(v);
  }
  memset(used, 0, sizeof(used));
  ll k = 0;
  for (ll i = vs.size() - 1; i >= 0; i--) {
    if (!used[vs[i]]) rdfs(vs[i], k++);
  }
  return k;
}

ll counter[200001];

int main() {
  scanf("%lld", &V);
  for (ll i = 0; i < V; i++) scanf("%lld", &p), add_edge(p-1, i);
  scc();
  for (ll i = 0; i < V; i++) counter[cmp[i]]++;
  ll mx = 0, num;
  for (ll i = 0; i <= V; i++) if (counter[i] > mx) mx = counter[i], num = i;
  if (mx % 2 == 0) printf("POSSIBLE\n");
  else if (mx == 3 && V != 3) {
    ll counter = 0;
    for (ll i = 0; i <= V; i++) if (num == cmp[i]) if (G[i].size() > 1) counter++;
    if (counter == 3) printf("IMPOSSIBLE\n");
    else printf("POSSIBLE\n");
  } else printf("IMPOSSIBLE\n");
}

