	for(register int i=1;i<=n;i++)
		++b[p[i]=read()];
	for(register int i=1;i<=n;i++)
		if(!b[i])	que.push(i);
	while(!que.empty()){
		int x=que.front(),k=get(x);
		que.pop(),se[p[x]].insert(k);
		if(!(--b[p[x]]))	que.push(p[x]);
	}
	int st;
	for(int i=1;i<=n;i++)
		if(b[i]){
			st=i,que.push(i);
			break;
		}
	while(!que.empty()){
		int x=que.front();
		que.pop(),tm[x]=get(x);
		if(se[p[x]].count(tm[x]))	vis[x]=1;
		se[p[x]].insert(tm[x]);
		if(p[x]==st){
			if(tm[x]==tm[st])	break;
			else{
				puts("POSSIBLE");
				return 0;
			}
		}
		que.push(p[x]);
	}
	for(int i=1;i<=n;i++)
		if(b[i]&&!vis[i])	se[p[i]].erase(tm[i]);
	int end=tm[st];
	que.push(st),se[st].insert(end);
	while(!que.empty()){
		int x=que.front();
		que.pop(),tm[x]=get(x);
		se[p[x]].insert(tm[x]);
		if(p[x]==st){
			if(tm[x]!=end)	break;
			else{
				puts("POSSIBLE");
				return 0;
			}
		}
		que.push(p[x]);
	}
	puts("IMPOSSIBLE");
	return 0;
}

#include <cstdio>
#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

const int N = 2e5 + 5;

std::vector <int> e[N];
int vis[N];
std::pair <int, int> val[N];

int get_mex(std::set<int>& mex) {
    int p = 0;
    for (auto i : mex) {
        if (p != i)
            break;
        ++p;
    }
    return p;
}

void dfs(int u, int p = 0) {
    std::set <int> mex1;
    std::set <int> mex2;
    vis[u] = 1;
    bool is_cycle = false;
    for (int v : e[u]) {
        if (v != p) {
            if (vis[v] == 1) {
                is_cycle = true;
                continue;
            }
            if (vis[v] == 0)
                dfs(v, u);
            mex1.insert(val[v].first);
            mex2.insert(val[v].second);
        }
    }
    val[u].first = get_mex(mex1);
    if (is_cycle)
        mex2.insert(val[u].first);
    val[u].second = get_mex(mex2);

    vis[u] = 2;
}

bool check(int u) {
    std::set<int> mex1, mex2;
    for (int v : e[u]) {
        mex1.insert(val[v].first);
        mex2.insert(val[v].second);
    }
    return (mex1.count(val[u].first) && mex2.count(val[u].second));
}

bool solve() {
    int n, u;
    std::cin >> n;
    for (int i = 1; i <= n; ++i) {
        scanf("%d", &u);
        e[u].push_back(i);
    }

    for (int i = 1; i <= n; ++i) {
        if (!vis[i])
            dfs(i);
    }
    for (int i = 1; i <= n; ++i) {
        if (check(i)) {
            std::cout << "IMPOSSIBLE" << std::endl;
            return 0;
        }
    }
    std::cout << "POSSIBLE" << std::endl;

    return 0;
}

