int _main()
{
        ll n;
        llin(n);

        V<ll> plist;
        plist.pb(-1LL);
        llina(plist, n);

        V<ll> children[n+1];
        srep (i, 1, n+1LL) children[plist[i]].pb(i);

        ll leaf = -1LL;
        srep (i, 1, n+1LL) {
                if (children[i].empty()) {
                        leaf = i;
                        break;
                }
        }

        if (leaf < 0LL) {
                cout << ((n & 1LL) ? "IMPOSSIBLE" : "POSSIBLE");
                return 0;
        }

        V<ll> tour;
        ll pos[n+1];
        rep (i, n+1) pos[i] = -1LL;
        int idx = 0;

        tour.pb(leaf);
        pos[leaf] = idx;

        for ( ; ; ) {
                ll last = tour[idx];
                ll next = plist[last];
                if (pos[next] >= 0) {
                        idx = pos[next];
                        break;
                }
                tour.pb(next);
                pos[next] = ++idx;
        }

        V<ll> loop;
        bool inloop[n+1];
        memset(inloop, 0, sizeof(inloop));
        rrep (i, tour.size()) {
                loop.pb(tour[i]);
                inloop[tour[i]] = true;
                if (i <= idx) break;
        }

        ll alist[n+1];
        rep(i, n+1) alist[i] = -1LL;

        ll child_check_count[n+1];
        memset(child_check_count, 0, sizeof(child_check_count));

        for (auto loopnode : loop) {
                queue<ll> leaves;
                queue<ll> q;

                q.push(loopnode);
                for ( ; !(q.empty()); ) {
                        ll node = q.front(); q.pop();
                        if (children[node].empty()) leaves.push(node);
                        for (auto child : children[node]) {
                                if (!inloop[child]) q.push(child);
                        }
                }

                for ( ; !(leaves.empty()); ) {
                        ll node = leaves.front(); leaves.pop();
                        set<ll> aset;
                        for (auto child : children[node]) {
                                aset.insert(alist[child]);
                        }
                        alist[node] = 0LL;
                        for (auto in_aset : aset) {
                                if (alist[node] < in_aset) break;
                                alist[node]++;
                        }
                        ll p = plist[node];
                        child_check_count[p]++;
                        if (child_check_count[p] >= children[p].size() &&
                            !(inloop[p])) {
                                leaves.push(p);
                        }
                }
        }

        ll startloop = loop[0];

        set<ll> aset;
        for (auto child : children[startloop]) {
                if (!inloop[child]) aset.insert(alist[child]);
        }

        ll a_tmp = 0LL;
        ll a_cand[2] = {-1LL, -1LL};
        int i = 0;
        for (auto in_aset : aset) {
                if (a_tmp < in_aset) {
                        while (a_tmp < in_aset) {
                                a_cand[i++] = a_tmp++;
                                if (i >= 2) break;
                        }
                }
                if (i >= 2) break;
                a_tmp++;
        }
        if (a_cand[0] < 0LL) a_cand[0] = a_tmp++;
        if (a_cand[1] < 0LL) a_cand[1] = a_tmp++;

        rep (i, 2) {
                ll lalist[n+1];
                rep (i, n+1) lalist[i] = alist[i];
                lalist[startloop] = a_cand[i];
                ll node = startloop;
                for ( ; ; ) {
                        node = plist[node];
                        set<ll> aset;
                        for (auto child : children[node]) {
                                aset.insert(lalist[child]);
                        }
                        ll tmp = 0LL;
                        for (auto in_aset : aset) {
                                if (tmp < in_aset) break;
                                tmp++;
                        }
                        if (node == startloop) {
                                if (lalist[node] == tmp) {
                                        cout << "POSSIBLE";
                                        return 0;
                                }
                                break;
                        }
                        lalist[node] = tmp;
                }
        }

        cout << "IMPOSSIBLE";

        return 0;
}

