		for(int next : v[node]){
			mex[val[next]] = node;
		}
		for(int i = 0 ; i < val[node] ; ++i){
			if(mex[i] != node){
				return 0;
			}
		}
		if(mex[val[node]] == node){
			return 0;
		}
	}
	return 1;
}
int get(int node){
	for(int next : v[node]){
		if(done[next]){
			mex[val[next]] = node;
		}
	}
	for(int i = 0 ; ; ++i){
		if(mex[i] != node){
			return i;
		}
	}
}
int main(){
	scanf("%d" , &n);
	for(int i = 1 ; i <= n ; ++i){
		scanf("%d" , p + i);
		v[p[i]].emplace_back(i);
		rv[i].emplace_back(p[i]);
		++indeg[i];
		++outdeg[p[i]];
	}
	for(int i = 1 ; i <= n ; ++i){
		if(!outdeg[i]){
			que.push(i);
		}
	}
	while(!que.empty()){
		int node = que.front();
		que.pop();
		done[node] = 1;
		for(int next : v[node]){
			mex[val[next]] = node;
		}
		for(int i = 0 ; ; ++i){
			if(mex[i] != node){
				val[node] = i;
				break;
			}
		}
		for(int prev : rv[node]){
			--outdeg[prev];
			if(!outdeg[prev]){
				que.push(prev);
			}
		}
	}
	for(int i = 1 ; i <= n ; ++i){
		if(!done[i]){
			tmp.emplace_back(i);
		}
	}
	if(tmp.empty()){
		printf("POSSIBLE\n");
		return 0;
	}
	memset(mex , 0 , sizeof(mex));
	for(int node : tmp){
		for(int next : v[node]){
			if(done[next]){
				mex[val[next]] = node;
			}
		}
		for(int i = 0 ; ; ++i){
			if(mex[i] != node){
				cur[node] = i;
				break;
			}
		}
	}
	memset(mex , 0 , sizeof(mex));
	int who = -1;
	for(int node : tmp){
		if(who == -1 || cur[who] > cur[node]){
			who = node;
		}
	}
	bool ok = 0;
	for(int node : tmp){
		if(cur[node] != cur[who]){
			ok = 1;
		}
	}
	if(ok){
		while(1){
			int nxt;
			for(int next : v[who]){
				if(!done[next]){
					nxt = next;
				}
			}
			if(cur[nxt] == cur[who]){
				who = nxt;
			}
			else{
				break;
			}
		}
	}
	int x = who;
	do{
		val[x] = get(x);
		done[x] = 1;
		x = rv[x].back();
	}while(x != who);
	memset(mex , 0 , sizeof(mex));
	if(check()){
		printf("POSSIBLE\n");
	}
	else{
		printf("IMPOSSIBLE\n");
	}
}

