    if (visited[adj[x][i]] != -1){
        cal(adj[x][i]);
        cnt[val[adj[x][i]]] = 1;
    }
    if (cnt[0] == 0) val[x] = 0; else
    if (cnt[1] == 0) val[x] = 1; else
    val[x] = 2;
}

