#define maxn 200005
#define rep(i,j,k) for(int i=(j),LIM=(k);i<=LIM;i++)
#define per(i,j,k) for(int i=(j),LIM=(k);i>=LIM;i--)
using namespace std;

int n,fa[maxn];
int info[maxn],Prev[maxn<<1],to[maxn<<1],cnt_e;
void Node(int u,int v){ Prev[++cnt_e]=info[u],info[u]=cnt_e,to[cnt_e]=v; }

int ar[maxn],onc[maxn],a[maxn];
int vis[maxn],sta[maxn],tp;
void dfs0(int u,int ff){
	vis[u] = 1;
	sta[++tp] = u;
	for(int i=info[u],v;i;i=Prev[i]) if((v=to[i])^ff){
		if(!vis[v]) dfs0(v,u);
		else if(!onc[v]){
			for(int t=-1;t!=v;){
				t = sta[tp--];
				ar[++ar[0]] = t;
				onc[t] = 1;
			}
			per(i,ar[0],1) sta[++tp] = ar[i];
		}
	}
	if(sta[tp] == u) tp--;
}

void dfs1(int u,int ff){
	static int vis[maxn],tim;
	for(int i=info[u],v;i;i=Prev[i]) if((v=to[i]) ^ ff && !onc[v])
		dfs1(v,u);
	++tim;
	for(int i=info[u],v;i;i=Prev[i]) if((v=to[i]) ^ ff && !onc[v])
		vis[a[v]] = tim;
	a[u] = 0;
	for(;vis[a[u]] == tim; a[u]++);
}

