	rep(i,1,n){
		scanf("%d",&fa[i]);
		Node(fa[i],i),Node(i,fa[i]);
	}
	dfs0(1,0);
	rep(i,1,ar[0]) dfs1(ar[i],0);
	set<int>st;
	rep(i,1,ar[0]) st.insert(a[ar[i]]);
	if((ar[0] & 1) && st.size() == 1)
		puts("IMPOSSIBLE");
	else 
		puts("POSSIBLE");
}

