			return col[y] == cond;
		}else{
			bad[z].push_back(y==x?val:col[y]);
			sort(bad[z].begin(),bad[z].end());
			bad[z].resize(unique(bad[z].begin(),bad[z].end())-bad[z].begin());
			for(col[z] = 0; col[z] < bad[z].size() && bad[z][col[z]] == col[z]; col[z]++);
