void AddEdge(int u,int v) {G[v].push_back(u);in[v]++;to[++e]=v;nxt[e]=first[u];first[u]=e;}
int Q[maxn],S[maxn];
int work(int x) {
	memset(S,0,sizeof(S));
	int y=x;
	do {
		y=p[y];
		if(B[y]>=0) break;
		rep(i,0,G[y].size()-1) {
			S[B[G[y][i]]]++;
		}
		rep(i,0,3) if(!S[i]) {B[y]=i;break;}
		rep(i,0,3) S[i]=0;
	}while(y!=x);
	rep(x,1,n) {
		rep(i,0,G[x].size()-1) S[B[G[x][i]]]++;
		rep(i,0,B[x]-1) if(!S[i]) return 0;
		if(S[B[x]]) return 0;
		rep(i,0,3) S[i]=0;
	}
//	rep(i,1,n) printf("%d%c",B[i],i==n?'\n':' ');
	return 1;
}
int solve() {
	memset(A,-1,sizeof(A));
	int l=1,r=0;
	rep(i,1,n) if(!in[i]) Q[++r]=i,A[i]=0;
	while(l<=r) {
		int x=Q[l++];vis[x]=1;
		for(int i=first[x];i;i=nxt[i]) if(!(--in[to[i]])) Q[++r]=to[i];
		rep(i,0,G[x].size()-1) S[A[G[x][i]]]++;
		A[x]=0;while(S[A[x]]) A[x]++;
		rep(i,0,G[x].size()-1) S[A[G[x][i]]]--;
	}
	rep(i,1,n) if(!vis[i]) {
		rep(j,0,G[i].size()-1) S[A[G[i][j]]]++;
		int v=0;while(S[v]) v++;
		rep(j,0,G[i].size()-1) S[A[G[i][j]]]--;
		rep(j,1,n) B[j]=A[j];
		B[i]=v;if(work(i)) return 1;
		rep(j,1,n) B[j]=A[j];
		B[i]=v+1;if(work(i)) return 1;
		return 0;
	}
}
