int calc_grundy(const int v, const std::vector<int> &val) {
    std::set<int> s;
    for (const int to : g[v]) {
        if (val[to] >= 0) s.insert(val[to]);
    }
    for (int i = 0; ; i++) if (!s.count(i)) return i;
}

bool dfs(const int v) {
    if (state[v] == 2) return val[v] == -1;
    if (state[v] == 1) return true;
    bool ret = false;
    state[v] = 1;
    for (const int to : g[v]) {
        if (dfs(to)) ret = true;
    }

    if (!ret) val[v] = calc_grundy(v, val);
    else loop.push_back(v);

    state[v] = 2;

    return ret;
}

int main() {
    int n;
    std::cin >> n;

    g.resize(n); val.resize(n, -1); state.resize(n);
    for (int i = 0; i < n; i++) {
        int p;
        std::cin >> p;
        --p;
        g[p].push_back(i);
    }

    for (int i = 0; i < n; i++) dfs(i);

    if (loop.empty()) {
        std::cout << "POSSIBLE" << std::endl;
        return 0;
    }

    const int s = loop.front();

    std::vector<int> cands;

    {
        std::set<int> ss;
        for (const int to : g[s]) ss.insert(val[to]);
        for (int i = 0; cands.size() < 2; i++) {
            if (!ss.count(i)) cands.push_back(i);
        }
    }

    bool ret = false;
    for (const int c : cands) {
        auto v(val);
        v[s] = c;

        for (int i = 1; i < loop.size(); i++) v[loop[i]] = calc_grundy(loop[i], v);

        std::vector<int> has(c + 1);
        for (const int to : g[s]) if (0 <= v[to] && v[to] <= c) has[v[to]] = 1;

        if (std::all_of(has.begin(), has.end() - 1, [](const int i) { return i > 0; }) && !has.back()) ret = true;
    }

    std::cout << (ret ? "POSSIBLE" : "IMPOSSIBLE") << std::endl;

    return 0;
}

