int N, Head[Max_N], To[Max_N], Next[Max_N], root;
int dfsclock, Pre[Max_N], Lowlink[Max_N], scctot, sccno[Max_N];
vector<int> SCC[Max_N];
stack<int> S;

inline bool comp(const int &u, const int &v)
{
	return Pre[u] < Pre[v];
}

void Tarjan(int u)
{
	int v;
	S.push(u), Pre[u] = Lowlink[u] = ++dfsclock;
	for (int i = Head[u];i;i = Next[i])
		if (!Pre[v = To[i]])
			Tarjan(v), Lowlink[u] = min(Lowlink[u], Lowlink[v]);
		else
			if (!sccno[v])
				Lowlink[u] = min(Lowlink[u], Pre[v]);
	if (Pre[u] == Lowlink[u])
	{
		++scctot;
		while (true)
		{
			v = S.top(), S.pop(), SCC[sccno[v] = scctot].push_back(v);
			if (u == v)
				break;
		}
		if (SCC[scctot].size() > 1)
			root = scctot, sort(SCC[root].begin(), SCC[root].end(), comp);
	}
}

int SG[Max_N];
bool done[Max_N];

int getSG(const vector<int> &V)
{
	for (int i = 0;i < V.size();++i)
		done[V[i]] = true;
	int Ret;
	for (int i = 0;;++i)
		if (done[i] == false)
		{
			Ret = i;
			break;
		}
	for (int i = 0;i < V.size();++i)
		done[V[i]] = false;
	return Ret;
}

void dfsTree(int u)
{
	vector<int> Son;
	for (int i = Head[u], v;i;i = Next[i])
		dfsTree(v = To[i]), Son.push_back(SG[v]);
	SG[u] = getSG(Son);
}

int main()
{
	Get_Val(N);
	for (int t = 1, s;t <= N;++t)
	{
		Get_Val(s);
		if (s == t)
		{
			puts("IMPOSSIBLE");
			return 0;
		}
		To[t] = t, Next[t] = Head[s], Head[s] = t;
	}
	for (int i = 1;i <= N;++i)
		if (!Pre[i])
			Tarjan(i);
	for (int j = 0, u;j < SCC[root].size();++j)
	{
		u = SCC[root][j];
		for (int i = Head[u], v;i;i = Next[i])
			if (sccno[v] != root)
				dfsTree(v);
	}
	vector<int> Son;
	for (int i = Head[SCC[root][0]], v;i;i = Next[i])
		if (sccno[v = To[i]] != root)
			Son.push_back(SG[v]);
	SG[SCC[root][0]] = getSG(Son);
	for (int j = SCC[root].size() - 1, u;j;--j)
	{
		u = SCC[root][j], Son.clear();
		for (int i = Head[u];i;i = Next[i])
			Son.push_back(SG[To[i]]);
		SG[u] = getSG(Son);
	}
	Son.clear();
	for (int i = Head[SCC[root][0]];i;i = Next[i])
		Son.push_back(SG[To[i]]);
	if (getSG(Son) == SG[SCC[root][0]])
	{
		puts("POSSIBLE");
		return 0;
	}
	Son.clear();
	for (int i = Head[SCC[root][0]], v;i;i = Next[i])
		if (sccno[v = To[i]] != root)
			Son.push_back(SG[v]);
	Son.push_back(getSG(Son)), SG[SCC[root][0]] = getSG(Son);
	for (int j = SCC[root].size() - 1, u;j;--j)
	{
		u = SCC[root][j], Son.clear();
		for (int i = Head[u];i;i = Next[i])
			Son.push_back(SG[To[i]]);
		SG[u] = getSG(Son);
	}
	Son.clear();
	for (int i = Head[SCC[root][0]];i;i = Next[i])
		Son.push_back(SG[To[i]]);
	if (getSG(Son) == SG[SCC[root][0]])
	{
		puts("POSSIBLE");
		return 0;
	}
	puts("IMPOSSIBLE");
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int maxn = 200200, mx = 7;
vector<int> cycle;
int p[maxn], out[maxn], val[maxn], is_out[maxn], cnt[mx][maxn];
bool can[mx][mx][mx][maxn];
bool solve(int fs, int ls, int hs, int at){
	if(can[fs][ls][hs][at]) return false;
	can[fs][ls][hs][at] = true;
	int who = cycle[at];
	if(at + 1 == cycle.size()){
		cnt[fs][who]++;
		for(int v = 0; v < mx - 1; v++){
			if(cnt[v][who]) continue;
			if(v == ls) continue;
			if(hs != mx - 1 && hs != v) continue;
			int sm = 0, eq = 0;
			for(int j = 0; j < v; j++){
				sm += cnt[j][who] > 0;
				if(cnt[j][who] == 0) eq = j;
			}
			if(sm == v){
				return true;
			}
		}
		cnt[fs][who]--;
	} else if(at == 0){
		for(int v = 0; v < mx - 1; v++){
			if(cnt[v][who]) continue;
			int sm = 0, eq = 0;
			for(int j = 0; j < v; j++){
				sm += cnt[j][who] > 0;
				if(cnt[j][who] == 0) eq = j;
			}
			if(sm == v){
				if(solve(v, v, mx - 1, at + 1)) return true;
			} else if(sm == v - 1){
				if(solve(v, v, eq, at + 1)) return true;	
			}
		}
	} else {
		for(int v = 0; v < mx - 1; v++){
			if(v == ls) continue;
			if(cnt[v][who]) continue;
			if(hs != mx - 1 && hs != v) continue;
			int sm = 0, eq = 0;
			for(int j = 0; j < v; j++){
				sm += cnt[j][who] > 0;
				if(cnt[j][who] == 0) eq = j;
			}
			if(sm == v){
				if(solve(fs, v, mx - 1, at + 1)) return true;
			} else if(sm == v - 1){
				if(solve(fs, v, eq, at + 1)) return true;	
			}
		}
	}
	return false;
}
int main(){
	int n; cin >> n;
	for(int i = 0; i < n; i++){
		cin >> p[i]; p[i]--;
		out[p[i]]++;
	}
	set<pair<int,int> > outs;
	for(int i = 0; i < n; i++){
		outs.insert({out[i], i});
	}
	while(!outs.empty()){
		if(outs.begin()->first) break;
		int ot, v; tie(ot, v) = *outs.begin(); outs.erase(outs.begin());
		for(int i = 0; i < mx - 1; i++){
			if(i == mx - 2){
				val[v] = mx - 2;
				break;
			}
			if(!cnt[i][v]){
				val[v] = i;
				break;
			}
		}
		is_out[v] = 1;
		cnt[val[v]][p[v]]++;
		outs.erase({out[p[v]], p[v]});
		out[p[v]]--;
		outs.insert({out[p[v]], p[v]});
	}
	for(int i = 0; i < n; i++){
		if(!is_out[i]){
			int u = i;
			do {
				cycle.push_back(u);
				u = p[u];
			} while(u != i);
			reverse(cycle.begin(), cycle.end());
			break;
		}
	}
	if(solve(mx - 1, mx - 1, mx - 1, 0)) cout << "POSSIBLE" << endl;
	else cout << "IMPOSSIBLE" << endl;
	return 0;
}

