    for (int i = 0; i < n; i++)
    {
        if (repeated[v[i]])
            break;

        loop.push_back(v[i]);
        repeated[v[i]] = true;
    }
    assert(loop.size() > 1);

    vector<vector<int>> e(n);
    vector<int> out_deg(n, 0);
    for (int i = 0; i < n; i++)
    {
        out_deg[p[i]]++;
        e[p[i]].push_back(i);
    }

    vector<char> used = repeated;

    vector<int> mark(n, -1);
    for (int i = 0; i < n; i++)
    {
        if (!used[i] && out_deg[i] == 0)
        {
            int now = i;
            int cur = 0;
            while (!used[now])
            {
                used[now] = true;
                mark[now] = cur;
                cur = 1 - cur;
                now = p[now];
            }
        }
    }

    for (int i = 0; i < n; i++)
    {
        assert(used[i]);
        assert(repeated[i] || mark[i] != -1);
