int mark[MAX_N];
int od[MAX_N];
int a[MAX_N];

int main2() {
  int N = nextInt();
  REP(i, N) g[i].clear();
  memset(mark, 0, sizeof(mark));
  memset(od, 0, sizeof(od));
  memset(a, -1, sizeof(a));

  REP(i, N) {
    int p = nextInt() - 1;
    g[p].push_back(i);
    rev[i] = p;
  }
  // REP(i, N) {
    // cout << i << " : ";
    // pv (ALL(g[i]));
  // }
  REP(i, N) od[i] = (int)g[i].size();
  // pv(od, od + N);
  queue<int> q;
  REP(i, N) if (od[i] == 0) q.push(i);

  if (q.size() == 0) {
    cout << ( N % 2 == 0 ? "POSSIBLE" : "IMPOSSIBLE")  << endl;
    return 0;
  }

  for (;q.size() > 0;) {
    int v = q.front(); q.pop();
    // cout << "v=" << v << endl;
    mark[v] = 1;
    if (--od[ rev[v] ] == 0) {
      q.push(rev[v]);
    }
  }
  int ei, ej;
  REP(i, N) {
    for (int j : g[i]) {
      if (mark[i] == 0 && mark[j] == 0) {
        ei = i;
        ej = j;
        goto BK;
      }
    }
  }
  BK:

  REP(i, N) od[i] = (int)g[i].size();
  od[ej]--;
  REP(i, N) if (od[i] == 0) q.push(i);

  for (;q.size() > 0;) {
    int v = q.front(); q.pop();
    set<int> s;
    for (int u : g[v]) {
      if (v == ei && u == ej) continue;
      s.insert(a[u]);
    } 
    int num = 0;
    while (s.count(num) > 0) num++;
    a[v] = num;
    mark[v] = 1;
    if (--od[ rev[v] ] == 0) {
      q.push(rev[v]);
    }
  }
  // pv(a, a + N);
  if (a[ei] == a[ej]) {
    cout << "IMPOSSIBLE" << endl;
  } else {
    cout << "POSSIBLE" << endl;
  }
  return 0;
}

