#define N 1000006
#define rint register int
using namespace std;

int tot = 0, fir[N], nxt[N << 1], to[N << 1];

inline void addEdge(int u, int v) {
    nxt[++tot] = fir[u], fir[u] = tot, to[tot] = v;
}

int n, vis[N], nx[N], inc[N], cntc, cir[N], val[N], use[N];

inline void dfs(int u) {
    //if (vis[u]) return ;
    if (nx[u]) {
        inc[u] = 1, cir[++cntc] = u;
        for (rint i = nx[u]; i != u; i = nx[i])
            inc[i] = 1, cir[++cntc] = i;
        return ;
    }
    for (rint i = fir[u], v; i; i = nxt[i])
        nx[u] = v = to[i], dfs(v);
    nx[u] = 0;
    vis[u] = 1;
}

void getmex(int u) {
    for (rint i = fir[u], v; i; i = nxt[i]) {
        v = to[i];
        if (inc[v]) continue;
        getmex(v);
        use[val[v]] = 1;
    }
    while (use[val[u]]) ++val[u];
    for (rint i = fir[u]; i; i = nxt[i])
        if (!inc[to[i]]) use[val[to[i]]] = 0;
}

int main() {
    cin >> n;
    for (rint i = 1, u; i <= n; ++i)
        scanf("%d", &u), addEdge(u, i);
    for (rint i = 1; i <= n; ++i) dfs(i);
    for (rint i = 1; i <= cntc; ++i) getmex(cir[i]);
    bool check = 1;
    for (rint i = 1; i < cntc; ++i)
        if (val[cir[i]] != val[cir[i + 1]]) check = 0;
    if (check && cntc % 2) puts("IMPOSSIBLE");
    else puts("POSSIBLE");
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int MN = 200010;

int N;
int P[MN], vis[MN];
vector<int> adj[MN];
int tin[MN], par[MN], timer;
vector<int> cycle;

void dfs0(int u) {
    tin[u] = timer++;

    for(int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(tin[v] != -1) {
            if(tin[v] < tin[u]) {
                int t = u;
                while(1) {
                    cycle.push_back(t);
                    if(t == v) break;
                    t = par[t];
                }
            }
            continue;
        }
        par[v] = u;
        dfs0(v);
    }
}

int del[MN], dp[MN];

void dfs1(int u) {
    vector<int> tmp;
    for(int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(del[v]) continue;
        dfs1(v);
        tmp.push_back(dp[v]);
    }
    sort(tmp.begin(), tmp.end());

    int pos = 0;
    for(int i = 0; i < MN; i++) {
        while(pos < tmp.size() && tmp[pos] < i) pos++;
        if(pos == tmp.size() || tmp[pos] != i) {
            dp[u] = i;
            break;
        }
    }
}

int main() {
    scanf("%d", &N);

    for(int i = 0; i < N; i++) {
        int p; scanf("%d", &p);
        p--;
        adj[p].push_back(i);
        P[i] = p;
    }

    int u = 0;
    while(!vis[u]) {
        vis[u] = 1;
        u = P[u];
    }

    memset(tin, -1, sizeof(tin));
    dfs0(u);

    for(int i = 0; i < cycle.size(); i++) del[ cycle[i] ] = 1;
    for(int i = 0; i < cycle.size(); i++) {
        dfs1(cycle[i]);
    }
    for(int i = dp[ cycle.back() ]; i <= dp[ cycle.back() ] + 1; i++) {
        int pre = i;
        for(int j = 0; j < cycle.size(); j++) {
            int u = cycle[j];

            vector<int> tmp;
            for(int k = 0; k < adj[u].size(); k++) {
                int v = adj[u][k];
                if(del[v]) continue;
                tmp.push_back(dp[v]);
            }
            tmp.push_back(pre);
            sort(tmp.begin(), tmp.end());

            int pos = 0;
            for(int k = 0; k < MN; k++) {
                while(pos < tmp.size() && tmp[pos] < k) pos++;
                if(pos == tmp.size() || tmp[pos] != k) {
                    pre = k;
                    break;
                }
            }
        }
        if(pre == i) {
            printf("POSSIBLE");
            return 0;
        }
    }
    printf("IMPOSSIBLE");
}

#include <cstdio>
#include <set>
using namespace std;
const int N=200005;
int n,pre[N],cnex[N];
int h[N],tot;
struct Edge{
	int v,next;
}e[N*2];
int a[N],len,mex[N][2];
inline void addEdge(int u,int v){
	e[++tot]=(Edge){v,h[u]}; h[u]=tot;
}
void readData(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++){
		scanf("%d",&pre[i]);		
		addEdge(pre[i],i);
	}
}
void findCircle(int u){
	static int stk[N],top=0;
	static bool vis[N];
	stk[++top]=u;
	vis[u]=true;
	if(vis[pre[u]]){
		int v=pre[u];
		cnex[v]=u;
		for(;stk[top]!=v;top--){
			cnex[stk[top]]=stk[top-1];
			a[++len]=stk[top];
		}
		a[++len]=v;
		return;
	}
	findCircle(pre[u]);
}
void dfs(int u,int dep){
	for(int i=h[u],v;i;i=e[i].next)
		if((v=e[i].v)!=cnex[u])
			dfs(v,dep+1);
	multiset<int> s;
	s.clear();
	for(int i=h[u],v;i;i=e[i].next)
		if((v=e[i].v)!=cnex[u])
			s.insert(mex[v][0]);
	for(mex[u][0]=0;s.find(mex[u][0])!=s.end();mex[u][0]++);
	if(dep==0)
		for(mex[u][1]=mex[u][0]+1;s.find(mex[u][1])!=s.end();mex[u][1]++);
}
bool run(int x){
	int last=x;
	for(int i=len-1;i>=1;i--){
		int u=a[i];
		last=(mex[u][0]==last)?mex[u][1]:mex[u][0];
	}
	last=(mex[a[len]][0]==last)?mex[a[len]][1]:mex[a[len]][0];
	return x==last;
}
bool judge(){
	for(int i=1;i<=len;i++)
		dfs(a[i],0);
	return run(mex[a[len]][0])||run(mex[a[len]][1]);
}
int main(){
	readData();
	findCircle(1);
	puts(judge()?"POSSIBLE":"IMPOSSIBLE");
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int maxn = 2e5 + 6;
const int lm = 23;

typedef struct mex {
	bool occ[lm];

	void init() {
		for (int i = 0; i < lm; i++) occ[i] = false;
	}
	int get() {
		for (int i = 0; i < lm; i++) if (!occ[i]) return i;
		return lm;
	}
	void add(int x) {
		if (x >= lm) return;
		occ[x] = true;
	}
} mex;


int out[maxn];
int p[maxn];
mex S[maxn];
mex T[maxn];
bool vis[maxn];
queue<int> Q;

int n;

int main() {
	ios::sync_with_stdio(false); cin.tie(0);	
	cin>>n;

	for (int i = 1; i <= n; i++) {
		out[i] = p[i] = 0; S[i].init(); T[i].init(); vis[i] = false;
	}

	for (int i = 1; i <= n; i++) {
		cin>>p[i]; out[p[i]]++;
	}

	Q = *new queue<int>();
	for (int i = 1; i <= n; i++) {
		if (out[i] == 0) Q.push(i);
	}

	while (Q.size() > 0) {
		int z = Q.front(); Q.pop(); vis[z] = true;
		int mv = S[z].get();
		int y = p[z];
		out[y]--; S[y].add(mv);
		if (out[y] == 0) Q.push(y);
	}

	int u = 0;

	for (int i = 1; i <= n; i++) {
		if (vis[i] == false) { u = i; break; }
	}

	for (int t = 0; t < lm; t++) {

		for (int i = 1; i <= n; i++) {
			T[i] = S[i];
		}

		int x = u, lv = t;
		while (p[x] != u) {
			int y = p[x];
			S[y].add(lv);
			x = y; lv = S[x].get();
		}

		// p[x] == u

		S[u].add(S[x].get());
		if (S[u].get() == t) {
			cout<<"POSSIBLE"<<endl; return 0;
		}

		for (int i = 1; i <= n; i++) {
			S[i] = T[i];
		}
	}

	cout<<"IMPOSSIBLE"<<endl;
}

