//題意の条件は「遷移先に含まれない最小の非負整数を書く」と言い換えらえる。木やDAGの場合は書き方が一意に定まる。
//なもりグラフの場合は、木を含むか・単なるループかによって書き方が異なる。単なるループの場合、ループ長の偶奇で判定できる。
//木を含む場合は、木の根を一つ取ってきて書く数aを決めると、書き方が一意に定まる。aは2通り程度試せばよい…と思う。最後に矛盾判定をすればよい。
//実装は、グラフの辺の向きを逆にすると簡単。逆にする：i -> p_i

#include <iostream>
#include <queue>
#include <set>
#include <vector>
#define rep(i, n) for(i = 0; i < n; i++)
using namespace std;

int n;
int p[200000], inV[200000];
set<int> gset[200000];
int g[200000];
int g2[200000];
bool isTree[200000];
vector<int> et[200000];

bool check(int start, int val) {
	int i, j;
	rep(i, n) g2[i] = g[i];
	g2[start] = val;

	//ループ内の頂点について、grundy数を決める.	
	int pos = start;
	while (true) {
		int npos = p[pos];
		if (npos == start) break;
		g2[npos] += (g2[pos] == g2[npos]);
		pos = npos;
	}

	//rep(i, n) cout << g2[i] << " ";
	//cout << endl;

	//矛盾判定 (元のグラフで考える)
	rep(i, n) gset[i].clear();
	rep(i, n) et[p[i]].push_back(i);
	rep(i, n) {
		rep(j, et[i].size()) gset[i].insert(g2[et[i][j]]);
		rep(j, n) if (gset[i].find(j) == gset[i].end()) break;
		if (j != g2[i]) { return false; }
	}
	return true;
}

int main() {
	int i, j;
	queue<int> que;

	cin >> n;
	rep(i, n) { cin >> p[i]; p[i]--; inV[p[i]]++; }
	rep(i, n) { if (!inV[i]) que.push(i); }

	while (!que.empty()) {
		int v = que.front(); que.pop();
		rep(i, n) if (gset[v].find(i) == gset[v].end()) break;
		g[v] = i;
		gset[v].clear();
		gset[p[v]].insert(g[v]);
		inV[p[v]]--;
		if (!inV[p[v]]) que.push(p[v]);
	}

	rep(i, n) isTree[i] = (gset[i].size() > 0);
	rep(i, n) if (isTree[i]) break;
	if (i == n) { cout << ((n % 2) ? "IMPOSSIBLE" : "POSSIBLE") << endl; return 0; }

	rep(i, n) {
		if (!isTree[i]) continue;
		rep(j, n) if (gset[i].find(j) == gset[i].end()) break;
		g[i] = j;
	}

	rep(i, n) if (isTree[i]) break;
	int start = i, g0 = g[start];

	rep(i, 2) if (check(start, g0 + i)) { cout << "POSSIBLE" << endl; return 0; }
	cout << "IMPOSSIBLE" << endl;
	return 0;
}

