const int N = 200000;
VI e[N], ef[N], er[N];
int dist[N], reach[N], c, loop[N], len;
int in[N], out[N], gd[N];

bool dfs(int now, int past){
    reach[now] = 1;
    bool f = false, g = false;
    for (int next : e[now]){
        if (next == past) continue;
        if (reach[next]){
            c = next;
            len = dist[now] - dist[next] + 1;
            f = true;
        }else{
            dist[next] = dist[now] + 1;
            g |= dfs(next, now);
        }
    }
    for (int next : e[now]){
        if (next == c && !f) g = false;
    }
    loop[now] = f | g;
    return f | g;
}

int main(void){
    int n;
    cin >> n;
    REP(i,n){
        int p;
        scanf("%d", &p);
        p--;
        e[i].push_back(p);
        e[p].push_back(i);
        ef[p].push_back(i);
        er[i].push_back(p);
        in[i]++;
        out[p]++;
    }

    queue<int> que;
    REP(i,n){
        if (out[i] == 0) que.push(i);
    }

    REP(i,n) gd[i] = -1;

    while (!que.empty()){
        int x = que.front();
        que.pop();
        set<int> st;
        for (int y : ef[x]){
            st.insert(y);
        }
        if (st.empty()) gd[x] = 0;
        else{
            int i = 0;
            for (int j : st){
                if (j != i){
                    break;
                }
                i++;
            }
            gd[x] = i;
        }
        for (int y : er[x]){
            out[y]--;
            if (out[y] == 0) que.push(y);
        }
    }

    bool exi = true;
    REP(i,n){
        for (int next : ef[i]){
            if (loop[next]) continue;
            if (gd[next] == 0 || gd[next] == 1) exi = true;
        }
    }
    cout << (len % 2 == 0 || exi ? "POSSIBLE" : "IMPOSSIBLE") << endl;
    return 0;
}

