int scc(){
    memset(used,0,sizeof(used));
    vs.clear();
    for(int v=0;v<V;v++){
        if(used[v]==0) DFS(v);
    }

    memset(used,0,sizeof(used));
    int k=0;
    for(int i=vs.size()-1;i>=0;i--){
        if(used[vs[i]]==0) rDFS(vs[i],k++);
    }
    return k;
}
int num;
bool leaf[MAX][2];

void DFS(int u,int p,int root,int d){
    if(G[u].size()==0){
        leaf[root][(d+1)%2]=1;
        return;
    }
    for(int to:G[u]){
        if(to==p) continue;
        if(cmp[to]==num) continue;

        DFS(to,u,root,d+1);
    }
}

