                        T[i]=1;
                        c=0;
                    }else{
                        S[u]=i;
                        break;
                    }
                }
            }

            for(int to:rG[u]){
                if(to==p) continue;
                if(cmp[to]==num) solve(to,u,root,0);
            }
        }else{
            for(int i=0;i<2;i++) if(leaf[u][i]) T[i]=1;
            T[S[p]]=1;

            for(int i=0;i<4;i++){
                if(T[i]==0){
                    if(S[u]==i) ans=true;
                    break;
                }
            }
        }
    }else{
        for(int i=0;i<2;i++) if(leaf[u][i]) T[i]=1;
        T[S[p]]=1;

        for(int i=0;i<4;i++){
            if(T[i]==0){
                S[u]=i;
                for(int to:rG[u]){
                    if(to==p) continue;
                    if(cmp[to]==num) solve(to,u,root,0);
                }
                break;
            }
        }
    }
