bool dfs(int v,int par){
	for(int to : G[v]){
		if(used[to] == par){
			cycle.push_back(v);
			return true;
		}else if(used[to] != -1) continue;
		used[to] = v;
		if(dfs(to,par)){
			cycle.push_back(v);
			return true;
		}
	}
	return false;
}
int calc(int v,int ext){
	if(a[v] != -1) return a[v];
	set<int> st;
	for(int to : G[v]){
		if(to == ext) continue;
		st.insert(calc(to,-1));
	}
	a[v] = 0;
	while(st.count(a[v])) a[v]++;
	return a[v];
}

