    for (auto i: c[V]) if (x == i) return;
    for (int j = 0; j <= n; j++){
        q[j] = 0;
        mark[j] = 0;
    }
    int pr;
    mark[V] = x;
    int v = V;
    for (auto u: in[V]) if (cycle[u]) v = u;
    pr = x;
    int ff = 0;
    while(v != V){
        int y = 0;
        for (auto u: c[v]){
            y = max(y, u);
            b[u] = 1;
        }
        b[pr] = 1;
        y = max(b[pr], y);
        for (int j = 0; j <= y + 1; j++){
            if (b[j] == 0){
                if (q[v] == 1) continue;
                mark[v] = j;
                q[v] = 1;
            }
            b[j] = 0;
        }
        pr = mark[v];
        for (auto u: in[v]) if (cycle[u]) v = u;
    }
    if (pr == mark[V]) return;
    cout << "POSSIBLE";
    exit(0);
}
