        for(int u:G[v])
            if(!isloop[u])
                grundy[v].insert(dfs_grundy(u));

    for(int v:loop){
        int res=-1;
        while(grundyP[v].size()<2){
            if(grundy[v].count(++res)==0)
                grundyP[v].push_back(res);
        }
