int n;
vector<int> es[200000], esr[200000];

int cn;
vector<int> cy;

void cycle() {
	int v = 0;
	vector<int> temp;
	REP(i, n + 1) {
		temp.push_back(v);
		v = esr[v][0];
	}
	int t = temp[temp.size() - 1];
	cy.push_back(t);
	REP(i, n + 1) {
		int u = temp[temp.size() - 2 - i];
		cy.push_back(u);
		if (u == t) break;
	}
	cn = cy.size() - 1;
}

int gr[200000][2], cand[200000];

int dfs(int v, int u) {
	int candi = 0;
	REP(i, es[v].size()) if (es[v][i] != u) cand[candi++] = dfs(es[v][i], -1);
	sort(cand, cand + candi);
	gr[v][0] = 0;
	REP(i, candi) {
		if (cand[i] == gr[v][0]) ++gr[v][0];
		else if (cand[i] > gr[v][0]) {
			gr[v][1] = gr[v][0] + 1;
			FOR(j, i, candi) {
				if (cand[j] == gr[v][1]) ++gr[v][1];
				else if (cand[i] > gr[v][1]) break;
			}
			break;
		}
	}
	if (gr[v][1] <= gr[v][0]) gr[v][1] = gr[v][0] + 1;
	return gr[v][0];
}

int arr[200001];

bool solve(int a) {
	arr[0] = a;
	REP(i, cn - 1) {
		int v = cy[cn - 1 - i];
		if (gr[v][0] == arr[i]) arr[i + 1] = gr[v][1];
		else arr[i + 1] = gr[v][0];
	}
	return arr[cn - 1] != a;
}

