		es[p].push_back(i);
		esr[i].push_back(p);
	}
	cycle();
	REP(i, cn) dfs(cy[i], cy[i + 1]);
	cout << (solve(gr[cy[0]][0]) || solve(gr[cy[0]][1]) ? "POSSIBLE" : "IMPOSSIBLE") << endl;
	return 0;
}

