using namespace std;

int const N = 1234567;

int was[N], g[N], ng[N], p[N], cycle[N];

vector<int> edges[N];

int dfs(int v, int bad) {
  if (g[v] >= 0) return g[v];
  int children = (int) edges[v].size();
  for (int i = 0; i <= children; i++) was[i] = false;
  for (int to : edges[v]) {
    if (to == bad) continue;
    dfs(to, bad);
  }
  for (int to : edges[v]) {
    if (to == bad) continue;
    int got = dfs(to, bad);
    if (got <= children) was[got] = true;
  }
  int i = 0;
  while (was[i]) ++i;
  g[v] = i;
  return i;
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", p + i);
