    g[i] = -1;
  }
  int v = 0;
  for (int i = 0; i < n; i++) v = p[v];
  int cc = 0;
  int start = v;
  while (true) {
    cycle[cc++] = v;
    v = p[v];
    if (start == v) break;
  }
  dfs(cycle[0], cycle[cc - 1]);
  int gv = g[cycle[0]];
  for (int i = 0; i < n; i++) ng[i] = g[i];
  for (int value = gv; value <= gv + 1; value++) {
    for (int i = 0; i < n; i++) g[i] = ng[i];
    g[cycle[0]] = value;
    for (int i = 0; i < cc; i++) {
      int v = cycle[i];
      if (g[v] < 0) dfs(v, -1);
    }
    int last = cycle[cc - 1];
    if (value == gv && g[last] == gv) {
      continue;
    }
    if (value == gv + 1 && g[last] != gv) continue;
    puts("POSSIBLE");
    return 0;
  }
  puts("IMPOSSIBLE");
}

