pii go(vvi& adj, int loc) {
    vi pres;
    trav (ch, adj[loc])
        pres.pb(go(adj, ch).f);
    dedup(pres);

    int mex = 0;
    while (mex < sz(pres) && pres[mex] == mex) mex++;
    int nex = mex + 1;
    while (nex-1 < sz(pres) && pres[nex-1] == nex) nex++;

    return {mex,nex};
}

