int PG[200050][2];

int dfs1(int u) {
  if (vis[u] == 1) {
    return u;
  }
  vis[u] = 1;
  int t = dfs1(rev[u]);
  if (t >= 0) {
      return t;
  }
  return -1;
}

void calc(int u) {
  if (to[u].empty()) {
    G[u] = 0;
    return;
  }

  for (const int v : to[u]) {
    calc(v);
  }
  for (const int v : to[u]) {
    T[G[v]] = 1;
  }
  for (int g = 0; ; ++g) {
    if (T[g] == 0) {
      G[u] = g;
      break;
    }
  }
  for (const int v : to[u]) {
    T[G[v]] = 0;
  }
}

