  for (int i = 0; i < N; ++i) {
    int p = in() - 1;
    to[p].push_back(i);
    rev[i] = p;
  }

  vector<int> cyc;
  const int c0 = dfs1(0);
  for (int u = c0; ;) {
    inC[u] = 1;
    cyc.push_back(u);
    u = rev[u];
    if (u == c0) {
      break;
    }
  }
  reverse(cyc.begin(), cyc.end());

  for (int i = 0; i < N; ++i) {
    if (inC[i]) {
      for (const int u : to[i]) {
        if (!inC[u]) {
          calc(u);
        }
      }
    }
  }

  const int M = cyc.size();
  for (int i = 0; i < M; ++i) {
    int c = cyc[i];
    for (const int u : to[c]) {
      if (!inC[u]) {
        T[G[u]] = 1;
      }
    }
    for (int g = 0, k = 0; k < 2; ++g) {
      if (T[g] == 0) {
        PG[i][k++] = g;
      }
    }
    for (const int u : to[c]) {
      if (!inC[u]) {
        T[G[u]] = 0;
      }
    }
  }

  vector<clause> cs;
  for (int i = 0; i < M; ++i) {
    int c = i, nxt = (i + 1) % M;
    int r = PG[c][0];
    int k = -1;
    for (int j = 0; j < 2; ++j) {
      if (PG[nxt][j] == r) {
        k = j;
      }
    }
    if (k < 0) {
      cs.emplace_back(VAR(c), VAR(c));
    } else {
      cs.emplace_back(VAR(c), k == 0 ? VAR(nxt) : NOT(VAR(nxt)));
    }

    for (int a = 0; a < 2; ++a) {
      for (int b = 0; b < 2; ++b) {
        if (PG[c][a] == PG[nxt][b]) {
          cs.emplace_back(a == 0 ? NOT(VAR(c)) : VAR(c), b == 0 ? NOT(VAR(nxt)) : VAR(nxt));
        }
      }
    }
  }

  puts(two_satisfiability(M, cs) ? "POSSIBLE" : "IMPOSSIBLE");

  return 0;
}

