	while (!visited[cur]) {
		if ((1 << res[cur]) & newHas[cur]) return false;
		visited[cur] = true;
		newHas[nxt[cur]] |= 1 << res[cur];
		cur = nxt[cur];
		for (int j = 0; j < 5; ++j) if (!(newHas[cur] & (1 << j))) {
			res[cur] = j;
			break;
		}
		if (res[cur] == -1) return false;
	}
	if (cur != st || res[cur] != x) return false;

	for (int j = 0; j < res[cur]; ++j) if (!(newHas[cur] & (1 << j))) return false;
	if ((1 << res[cur]) & newHas[cur]) return false;
	return true;

}


void solve() {
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		scanf("%d", nxt + i);
