			return 0;
		}
	}
	return 1;
}
int get(int node){
	for(int next : v[node]){
		if(done[next]){
			mex[val[next]] = node;
		}
	}
	for(int i = 0 ; ; ++i){
		if(mex[i] != node){
			return i;
		}
	}
