		scanf("%d" , p + i);
		v[p[i]].emplace_back(i);
		rv[i].emplace_back(p[i]);
		++indeg[i];
		++outdeg[p[i]];
	}
	for(int i = 1 ; i <= n ; ++i){
		if(!outdeg[i]){
			que.push(i);
		}
	}
	while(!que.empty()){
		int node = que.front();
		que.pop();
		done[node] = 1;
		for(int next : v[node]){
			mex[val[next]] = node;
		}
		for(int i = 0 ; ; ++i){
			if(mex[i] != node){
				val[node] = i;
				break;
			}
		}
		for(int prev : rv[node]){
			--outdeg[prev];
			if(!outdeg[prev]){
				que.push(prev);
			}
		}
	}
	for(int i = 1 ; i <= n ; ++i){
		if(!done[i]){
			tmp.emplace_back(i);
		}
	}
