struct UnionFind {
	vector<int> data;
	void init(int n) { data.assign(n, -1); }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) { return root(x) == root(y); }
	int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
	int size(int x) { return -data[root(x)]; }
};

int main() {
	int N;
	while (~scanf("%d", &N)) {
		vector<int> p(N);
		for (int i = 0; i < N; ++ i)
			scanf("%d", &p[i]), -- p[i];
		vector<int> deg(N);
		rep(i, N)
			++ deg[p[i]];
		vector<int> que;
		rep(i, N) if(deg[i] == 0)
			que.push_back(i);
		for (int qh = 0; qh != que.size(); ++ qh) {
			int i = que[qh];
			if(-- deg[p[i]] == 0)
				que.push_back(p[i]);
		}
		vector<vi> children(N);
		rep(i, N)
			children[p[i]].push_back(i);
		vector<bool> vis(N);
		vector<int> xs(N, -1);
		for (int i : que) {
			for (int j : children[i])
				vis[xs[j]] = true;
			int x = 0;
			for (; vis[x]; ++ x);
			xs[i] = x;
			for (int j : children[i])
				vis[xs[j]] = false;
		}
		vector<int> cycle;
		rep(i, N) if (xs[i] == -1) {
			int j = i;
			do {
				cycle.push_back(j);
				j = p[j];
			} while (j != i);
			break;
		}
		int K = (int)cycle.size();
		vector<int> A(K), B(K);
		rep(k, K) {
			int i = cycle[k];
			for (int j : children[i]) if(xs[j] != -1)
				vis[xs[j]] = true;
			int x = 0;
			for (; vis[x]; ++ x);
			A[k] = x;
			++ x;
			for (; vis[x]; ++ x);
			B[k] = x;
			for (int j : children[i]) if (xs[j] != -1)
				vis[xs[j]] = false;
		}
		UnionFind uf;
		uf.init(K * 2 + 2);
		rep(k, K) {
			int l = (k + K - 1) % K;
			if (A[k] == A[l]) {
				//(x_l = 0) <-> (x_k = 1)
				uf.unionSet(k * 2 + 0, l * 2 + 1);
				uf.unionSet(k * 2 + 1, l * 2 + 0);
			} else if (A[k] == B[l]) {
				//(x_l = 1) <-> (x_k = 1)
				uf.unionSet(k * 2 + 0, l * 2 + 0);
				uf.unionSet(k * 2 + 1, l * 2 + 1);
			} else {
				//x_k = 0
				uf.unionSet(k * 2 + 0, K * 2 + 0);
				uf.unionSet(k * 2 + 1, K * 2 + 1);
			}
		}
		bool ans = true;
		rep(k, K + 1)
			ans &= !uf.findSet(k * 2 + 0, k * 2 + 1);
		puts(ans ? "POSSIBLE" : "IMPOSSIBLE");
	}
	return 0;
}

