        cik[curr] = 1;
        curr = par[curr];
        if (curr == naso) break;
	}
	for (int i=1; i<=n; i++) {
        calc(i);
	}
	if (probaj(naso, val[par[naso]])) {
        cout << "POSSIBLE";
	} else if (probaj(par[naso], val[par[naso]])) {
