					for (int i = 0;i < normal[now].size();++i) {
						already[getting[normal[now][i]]] = true;
					}
					for (int i = 0;i >= 0;++i) {
						if (already[i] == false) {
							getting[now] = i;
							break;
						}
					}
					for (int i = 0;i < reversed[now].size();++i) {
						already_size[reversed[now][i]]++;
						if (already_size[reversed[now][i]] == normal[reversed[now][i]].size()) {
							geko.push(reversed[now][i]);
						}
					}
				}
			}
			for (int i = 1;i <= n;++i) {
				map<int, int> nau;
				for (int q = 0;q < normal[i].size();++q) {
					if (getting[i] == getting[normal[i][q]]) {
						goto cantfail;
					}
					nau[getting[normal[i][q]]] = true;
				}
				for (int i = 0;i < getting[i];++i) {
					if (nau[i] == false) {
						goto cantfail;
					}
				}
			}
			cout << "POSSIBLE" << endl;
			return 0;
		cantfail:;
		}
		cout << "IMPOSSIBLE" << endl;
		return 0;
}

