typedef long long li;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li n;
    cin >> n;
    vector<vector<li>> g(n);
    vector<li> rev(n);

    for (int i = 0; i < n; ++i) {
        li fr;
        cin >> fr;
        fr--;
        rev[i] = fr;
        g[fr].push_back(i);
    }

    vector<bool> vis(n);
    li loop = 0;
    while (not vis[loop]) {
        vis[loop] = true;
        loop = rev[loop];
    }

    if (loop == -1) {
        // unreachable
        cout << "POSSIBLE" << endl;
        cerr << "unreachable" << endl;
        return 0;
    }

    vector<li> indegs(n);
    queue<li> q;
    for (int i = 0; i < n; ++i) {
        indegs[i] = g[i].size();
        if (indegs[i] == 0) {
            q.emplace(i);
        }
    }

    vector<li> grundy(n, -1);
    const auto calc_grundy = [&](const li pos) {
        set<li> nexts;
        for (auto &next : g[pos]) {
            nexts.insert(grundy[next]);
        }
        for (int i = 0; i < n; ++i) {
            if (nexts.find(i) == nexts.end()) {
                return i;
            }
        }
    };

    while (not q.empty()) {
        auto pos = q.front();
        q.pop();
        grundy[pos] = calc_grundy(pos);
        const li prev = rev[pos];
        if (--indegs[prev] == 0) {
            q.emplace(prev);
        }
    }

    vector<li> candidates;
    set<li> nexts;
    for (auto &next : g[loop]) {
        nexts.emplace(grundy[next]);
    }
    for (int i = 0; i < n && candidates.size() < 2; ++i) {
        if (nexts.find(i) == nexts.end()) {
            candidates.push_back(i);
        }
    }

    for (int i = 0; i < 2; ++i) {
        const li candidate = candidates[i];
        grundy[loop] = candidate;
        li pos = rev[loop];
        while (pos != loop) {
            grundy[pos] = calc_grundy(pos);
            pos = rev[pos];
        }

        if (calc_grundy(loop) == candidate) {
            cout << "POSSIBLE" << endl;
            return 0;
        }
    }
    cout << "IMPOSSIBLE" << endl;
    return 0;
}

