void solve(int N, vector<int> p){
	g.assign(N,Edges());
	REP(u,N)g.addEdge(p[u],u);
	auto s(stronglyConnectedComponents(g));
	unordered_set<int> cyc;
	REP(i,s.scc.size()){
		if(s.scc[i].size()>1){
			cyc.insert(ALL(s.scc[i]));
			break;
		}
	}
	assert(cyc.size()>0);
	gr.assign(N,-1);
	nxt.assign(N,-1);
	rev_nxt.assign(N,-1);
	for(auto &&u:cyc){
		bool found = false;
		for(auto &&e:g[u]){
			if(EXIST(e.dst,cyc)){
				nxt[u] = e.dst;
				rev_nxt[e.dst] = u;
				found = true;
			}
		}
		assert(found);
	}
	int start = *cyc.begin();
	for(int u = start;;){
		loop.push_back(u);
		u = nxt[u];
		if(u==start)break;
	}
	rev_loop = loop;
	reverse(ALL(rev_loop));

	/*
	REP(i,loop.size()){
		nxt[loop[i]] = loop[(i+1)%loop.size()];
		rev_nxt[rev_loop[i]] = rev_loop[(i+1)%loop.size()];
	}
	*/
	int max_g = -1;
	REP(i,loop.size()){
		max_g = max(max_g, dfs1(loop[i]));
	}
	for(int t=0;t<=max_g+4;t++){
		gr[rev_loop[0]] = t;
		for(int i=1;i<rev_loop.size() + 1;i++){
			unordered_set<int> st;
			int u = rev_loop[i%rev_loop.size()];
			for(auto &e:g[u]){
				st.insert(gr[e.dst]);
			}
			for(int i=0;;i++){
				if(st.find(i)==st.end()){
					gr[u] = i;
					break;
				}
			}
		}
		if(gr[rev_loop[0]]==t){
			cout<<"POSSIBLE"<<endl;
			return;
		}
	}
	cout<<"IMPOSSIBLE"<<endl;
}

