i32 calc_mex(std::vector<i32> vec) {
  std::sort(vec.begin(), vec.end());
  i32 res = 0;
  for (auto x: vec) {
    if (res < x) return res;
    ++res;
  }
  return res;
}

int main() {
  i32 N;
  std::cin >> N;
  std::vector<i32> parent(N);
  std::vector<i32> degree(N);
  for (auto &x: parent) {
    std::cin >> x;
    --x;
    ++degree[x];
  }
  std::queue<i32> que;
  for (auto i: range(0, N)) {
    if (degree[i] == 0) {
      que.push(i);
    }
  }
  std::vector<i32> num(N, -1);
  std::vector<std::vector<i32>> children(N); 
  while (!que.empty()) {
    i32 u = que.front();
    que.pop();
    num[u] = calc_mex(children[u]);
    children[parent[u]].push_back(num[u]);
    --degree[parent[u]];
    if (degree[parent[u]] == 0) {
      que.push(parent[u]);
    }
  }
  std::vector<i32> cycle;
  for (auto i: range(0, N)) {
    if (num[i] == -1) {
      cycle.push_back(i);
    }
  }
  i32 last = cycle.front();
  i32 first = parent[last];
  std::sort(children[first].begin(), children[first].end());
  i32 mex = 0, mex2 = -1;
  for (auto x: children[first]) {
    if (mex < x) {
      if (mex2 == -1) mex2 = mex;
      else break;
    }
    ++mex;
  }
  if (mex2 == -1) {
    mex2 = mex;
    ++mex;
  }
  auto fill_in = [&](i32 initial) {
    i32 cur = first;
    num[cur] = initial;
    while (parent[cur] != first) {
      auto vec = children[parent[cur]];
      vec.push_back(num[cur]);
      cur = parent[cur];
      num[cur] = calc_mex(vec);
    }
  };
  fill_in(mex);
  if (num[last] == mex2) {
    std::cout << "POSSIBLE\n";
    return 0;
  }
  fill_in(mex2);
  if (num[last] != mex2) {
    std::cout << "POSSIBLE\n";
    return 0;
  }
  std::cout << "IMPOSSIBLE\n";
  return 0;
}

