bool check(const graph::Graph<true> &g, const graph::Graph<true> &ig, bool inc) {
    ll n = g.size();

    std::queue<ll> que;
    vec<ll> ans(n, -1);
    vec<bool> pushed(n, false);

    auto push_q = [&](ll i) {
        if (pushed[i]) return;
        pushed[i] = true;
        que.push(i);
    };

    auto pop_q = [&] {
        ll ret = que.front();
        que.pop();
        return ret;
    };

    for (ll i = 0; i < n; i++) if (g[i].size() == 0) push_q(i);

    if (que.empty()) return n % 2 == 0;

    while (que.size()) {
        ll cur = pop_q();
        vec<ll> ch;
        bool und = false;
        for (auto &&e : g[cur]) {
            ll c = e.first;
            if (ans[c] == -1) {
                und = true;
                continue;
            }
            ch.push_back(ans[c]);
        }
        sort(ALL(ch));
        ll a = 0, idx = 0;
        for (; idx < ch.size(); a++, idx++) {
            if (ch[idx] == a) continue;
            if (inc && und) {
                inc = false;
                a++;
            }
            if (ch[idx] != a) break;
        }
        if (inc && und) {
            inc = false;
            a++;
        }
        ans[cur] = a;
        for (auto &&e : ig[cur]) {
            ll nxt = e.first;
            push_q(nxt);
        }
    }


    for (ll i = 0; i < n; i++) {
        std::set<ll> ch;
        ll a = ans[i];
        for (auto &&e : g[i]) {
            ll j = e.first;
            if (ans[i] == ans[j]) return false;
            if (ans[j] < ans[i]) ch.insert(ans[j]);
        }
        if (ch.size() < a) return false;
    }
    return true;
}

