	for (i=1;i<=n;i++) if (du[i]==1) break;
	d[++j]=i;
	i=0;
	while (i<j) {
		i++;
		for (k=h[d[i]];k;k=E[k].n) if (du[E[k].s]==1 && E[k].s!=d[1]) d[++j]=E[k].s;
	}
	f[d[j]]=a[d[j]];
	for (i=j-1;i;i--) {
		if (a[d[i]]==f[d[i+1]]) f[d[i]]=b[d[i]];
		else f[d[i]]=a[d[i]];
	}
	if (f[d[1]]!=f[d[j]]) return puts("POSSIBLE"),0;
	f[d[j]]=b[d[j]];
	for (i=j-1;i;i--) {
		if (a[d[i]]==f[d[i+1]]) f[d[i]]=b[d[i]];
		else f[d[i]]=a[d[i]];
	}
	if (f[d[1]]==a[d[j]]) return puts("POSSIBLE"),0;
	puts("IMPOSSIBLE");
}

#include <bits/stdc++.h>

using namespace std;

const int INF = 1e9;

vector< vector<int> > g;

bool dfs(int cur, vector<int>& used, vector<int>& cycle) {
	if (used[cur] == 1) {
		cycle[cur] = true;
		return true;
	}
	used[cur] = 1;
	for (int nex : g[cur]) {
		if (dfs(nex, used, cycle)) {
			cycle[cur] = true;
			return true;
		}
	}
	used[cur] = 2;
	return false;
}

int solve(int cur, vector<int>& cycle, vector<int>& grundy) {
	if (grundy[cur] != INF) return grundy[cur];
	int res = 0;
	for (int nex : g[cur]) {
		if (cycle[nex]) continue;
		int x = solve(nex, cycle, grundy);
		if (res == x) res++;
	}
	return grundy[cur] = res;
}

