	}
	vector<int> used(n, 0), cycle(n, false);
	for (int i = 0; i < n; i++) {
		if (used[i]) continue;
		dfs(i, used, cycle);
	}
	int x = -1, cnt = 0;
	bool ans = true;
	vector<int> grundy(n, INF);
	for (int i = 0; i < n; i++) {
		if (cycle[i]) {
			cnt++;
			int y = solve(i, cycle, grundy);
			if (x == -1) {
				x = y;
				ans = false;
			} else if (x != y) {
				ans = true;
				break;
			}
		}
	}
	assert(!ans);
	if (!ans) ans = (cnt % 2 == 0);
	cout << (ans ? "POSSIBLE" : "IMPOSSIBLE") << endl;
	return 0;
}

