int g;

int func(int p[], int c, bool chk[]) {
  chk[c] = true;
  if (chk[p[c]]) {
    return c;
  }

  chk[p[c]] = true;
  return func(p, p[c], chk);
}

int dfs(vector<int> v[], int c, int r, int a[], bool flag) {
  if (v[c].size() == 0) {
    a[c] = 0;
    return 0;
  }

  vector<int> pool;
  bool has = false;
  for (int i = 0; i < v[c].size(); i++) {
    if (v[c][i] == r && flag) {
      has = true;
    } else {
      pool.push_back(dfs(v, v[c][i], r, a, flag));
    }
  }
  sort(pool.begin(), pool.end());
  unique(pool.begin(), pool.end());
  for (int i = 0; i < pool.size(); i++) {
    if (pool[i] != i) {
      if (has && flag) {
        has = false;
        g = i;
        pool.push_back(i);
        sort(pool.begin(), pool.end());
        continue;
      } else {
        return a[c] = i;
      }
    }
  }

  int ret = (has && flag) ? pool.size() + 1 : pool.size();
  if (has && flag) {
    g = pool.size();
  }

  return a[c] = ret;
}

