#include<bits/stdc++.h>
using namespace std;
int a[200005];
int tag[200005];
bool incircle[200005];
bool vis[200005];
int val[200005];
struct edge
{
    int y;
    edge * next;
};
edge * li[200005];
edge * new_edge()
{
    static edge a[200005];
    static int top=0;
    return &a[top++];
}
void insert_edge(int x,int y)
{
    edge * t=new_edge();
    t->y=y;
    t->next=li[x];
    li[x]=t;
}
bool tags[200005];
void dfs(int x)
{
    if (vis[x]) return;
    vis[x]=true;
    edge * t;
    for (t=li[x];t!=0;t=t->next)
    {
        if (incircle[t->y]) continue;
        dfs(t->y);
    }
    if (incircle[x]) return;
    for (t=li[x];t!=0;t=t->next)
    {
        if (incircle[t->y]) continue;
        tags[val[t->y]]=true;
    }
    int i;
    for (i=0;;i++)
    {
        if (tags[i]) continue;
        break;
    }
    val[x]=i;
    for (t=li[x];t!=0;t=t->next)
    {
        if (incircle[t->y]) continue;
        tags[val[t->y]]=false;
    }
}
int main()
{
    int n;
    scanf("%d",&n);
    int i;
    for (i=0;i<n;i++)
    {
        scanf("%d",&a[i]);
        a[i]--;
        insert_edge(a[i],i);
    }
    int now=0;
    for (i=0;i<n;i++)
    {
        now=a[now];
    }
    for (i=0;i<n;i++)
    {
        incircle[now]=true;
        now=a[now];
    }
    for (i=0;i<n;i++)
    {
        if (vis[now]) break;
        dfs(now);
        now=a[now];
    }
    int j;
    for (j=0;j<=25;j++)
    {
        edge * t;
        for (t=li[now];t!=0;t=t->next)
        {
            if (incircle[t->y])
            {
                continue;
            }
            if (val[t->y]==j)
            {
                //Error!
                break;
            }
        }
        if (t!=0) continue;
        val[now]=j;
        int x;
        for (x=a[now];x!=now;x=a[x])
        {
            for (t=li[x];t!=0;t=t->next)
            {
                tags[val[t->y]]=true;
            }
            int i;
            for (i=0;;i++)
            {
                if (tags[i]) continue;
                break;
            }
            val[x]=i;
            for (t=li[x];t!=0;t=t->next)
            {
                tags[val[t->y]]=false;
            }
        }
        for (t=li[x];t!=0;t=t->next)
        {
            tags[val[t->y]]=true;
        }
        int i;
        for (i=0;;i++)
        {
            if (tags[i]) continue;
            break;
        }
        if (i==val[now])
        {
            puts("POSSIBLE");
            return 0;
        }
        for (t=li[x];t!=0;t=t->next)
        {
            tags[val[t->y]]=false;
        }
    }
