//題意の条件は「遷移先に含まれない最小の非負整数を書く」と言い換えらえる。木やDAGの場合は書き方が一意に定まる。
//なもりグラフの場合は、木を含むか・単なるループかによって書き方が異なる。単なるループの場合、ループ長の偶奇で判定できる。
//木を含む場合は、木の根を一つ取ってきて書く数aを決めると、書き方が一意に定まる。aは2通り程度試せばよい…と思う。最後に矛盾判定をすればよい。
//実装は、グラフの辺の向きを逆にすると簡単。逆にする：i -> p_i

#include <iostream>
#include <queue>
#include <set>
#include <vector>
#define rep(i, n) for(i = 0; i < n; i++)
using namespace std;

int n;
int p[200000], inV[200000];
set<int> gset[200000];
int g[200000];
int g2[200000];
bool isTree[200000];
vector<int> et[200000];

bool check(int start, int val) {
	int i, j;
	rep(i, n) g2[i] = g[i];
	g2[start] = val;

	//ループ内の頂点について、grundy数を決める.	
	int pos = start;
	while (true) {
		int npos = p[pos];
		if (npos == start) break;
		g2[npos] += (g2[pos] == g2[npos]);
		pos = npos;
	}

	//rep(i, n) cout << g2[i] << " ";
	//cout << endl;

	//矛盾判定 (元のグラフで考える)
	rep(i, n) gset[i].clear();
	rep(i, n) {
		rep(j, et[i].size()) gset[i].insert(g2[et[i][j]]);
		rep(j, n) if (gset[i].find(j) == gset[i].end()) break;
		if (j != g2[i]) { return false; }
	}
	return true;
}

int main() {
	int i, j;
	queue<int> que;

	cin >> n;
	rep(i, n) { cin >> p[i]; p[i]--; inV[p[i]]++; }
	rep(i, n) { if (!inV[i]) que.push(i); }

	while (!que.empty()) {
		int v = que.front(); que.pop();
		rep(i, n) if (gset[v].find(i) == gset[v].end()) break;
		g[v] = i;
		gset[v].clear();
		gset[p[v]].insert(g[v]);
		inV[p[v]]--;
		if (!inV[p[v]]) que.push(p[v]);
	}

	rep(i, n) isTree[i] = (gset[i].size() > 0);
	rep(i, n) if (isTree[i]) break;
	if (i == n) { cout << ((n % 2) ? "IMPOSSIBLE" : "POSSIBLE") << endl; return 0; }

	rep(i, n) {
		if (!isTree[i]) continue;
		rep(j, n) if (gset[i].find(j) == gset[i].end()) break;
		g[i] = j;
	}

	rep(i, n) if (isTree[i]) break;
	int start = i, g0 = g[start];
	rep(i, n) et[p[i]].push_back(i);

	rep(i, 400) if (check(start, g0 + i)) { cout << "POSSIBLE" << endl; return 0; }
	cout << "IMPOSSIBLE" << endl;
	return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int MN = 200010;

int N;
int P[MN], vis[MN];
vector<int> adj[MN];
int tin[MN], par[MN], timer;
vector<int> cycle;

void dfs0(int u) {
    tin[u] = timer++;

    for(int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(tin[v] != -1) {
            if(tin[v] < tin[u]) {
                int t = u;
                while(1) {
                    cycle.push_back(t);
                    if(t == v) break;
                    t = par[t];
                }
            }
            continue;
        }
        par[v] = u;
        dfs0(v);
    }
}

int del[MN], dp[MN];

void dfs1(int u) {
    vector<int> tmp;
    for(int i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if(del[v]) continue;
        dfs1(v);
        tmp.push_back(dp[v]);
    }
    sort(tmp.begin(), tmp.end());

    int pos = 0;
    for(int i = 0; i < MN; i++) {
        while(pos < tmp.size() && tmp[pos] < i) pos++;
        if(pos == tmp.size() || tmp[pos] != i) {
            dp[u] = i;
            break;
        }
    }
}

void solve(int x) {
    int pre = x;
    for(int j = 0; j < cycle.size(); j++) {
        int u = cycle[j];

        vector<int> tmp;
        for(int k = 0; k < adj[u].size(); k++) {
            int v = adj[u][k];
            if(del[v]) continue;
            tmp.push_back(dp[v]);
        }
        tmp.push_back(pre);
        sort(tmp.begin(), tmp.end());

        int pos = 0;
        for(int k = 0; k < MN; k++) {
            while(pos < tmp.size() && tmp[pos] < k) pos++;
            if(pos == tmp.size() || tmp[pos] != k) {
                pre = k;
                break;
            }
        }
    }
    if(pre == x) {
        printf("POSSIBLE");
        exit(0);
    }
}

int main() {
    scanf("%d", &N);

    for(int i = 0; i < N; i++) {
        int p; scanf("%d", &p);
        p--;
        adj[p].push_back(i);
        P[i] = p;
    }

    int u = 0;
    while(!vis[u]) {
        vis[u] = 1;
        u = P[u];
    }

    memset(tin, -1, sizeof(tin));
    dfs0(u);

    for(int i = 0; i < cycle.size(); i++) del[ cycle[i] ] = 1;
    for(int i = 0; i < cycle.size(); i++) {
        dfs1(cycle[i]);
    }
    solve(dp[ cycle.back() ]);

    vector<int> tmp;
    for(int i = 0; i < adj[ cycle.back() ].size(); i++) {
        int v = adj[ cycle.back() ][i];
        if(del[v]) continue;
        tmp.push_back(dp[v]);
    }
    tmp.push_back(dp[ cycle.back() ]);
    sort(tmp.begin(), tmp.end());

    int pos = 0;
    for(int i = 0; i < MN; i++) {
        while(pos < tmp.size() && tmp[pos] < i) pos++;
        if(pos == tmp.size() || tmp[pos] != i) {
            solve(i);
            break;
        }
    }
    printf("IMPOSSIBLE");
}

