#include <bits/stdc++.h>

const int maxn = 2e5 + 3;
int n, p[maxn], d[maxn], fd[maxn], la[maxn];
char vis[maxn], fv[maxn];
std::vector<int> pre[maxn], fp[maxn];

int mex(std::vector<int> &v) {
	if(v.empty() || v.front() > 0)
		return 0;
	for(int i = 0; i + 1 < v.size(); ++i)
	if(v[i + 1] - v[i] > 1)
		return v[i] + 1;
	return v.back() + 1;
}

bool dfs(int u) {
	vis[u] = 1;
	std::sort(pre[u].begin(), pre[u].end());
	la[u] = mex(pre[u]);
	pre[p[u]].push_back(la[u]);
	if(!--d[p[u]] && !vis[p[u]])
		dfs(p[u]);
}

bool check() {
	for(int i = 1; i <= n; ++i)
	if(la[i] == la[p[i]])
		return false;
	for(int i = 1; i <= n; ++i)
	if(la[i] != mex(pre[i]))
		return false;
	return true;
}

int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i) {
		scanf("%d", p + i);
