int n;

vector<vector<int>> adj;

vector<int> cycle;

void dfs(int u) {
    visited[u] = 1;

    for (auto& v : adj[u]) {
        if (!visited[v] && !incycle[v]) dfs(v);
    }

    for (auto& v : adj[u]) {
        if (!incycle[v]) s[grundy[v]] = u;
    }

    grundy[u] = 0;
    while (s[grundy[u]] == u) {
        grundy[u]++;
    }

    nextgrundy[u] = grundy[u] + 1;
    while (s[nextgrundy[u]] == u) {
        nextgrundy[u]++;
    }
}

int main() {
