    int i = 1;

    while (!visited[i]) {
        visited[i] = 1;
        i = p[i];
    }

    // i is in cycle

    memset(incycle, 0, sizeof incycle);

    while (!incycle[i]) {
        cycle.PB(i);
        incycle[i] = 1;
        i = p[i];
    }

//    PR0(cycle, cycle.size());

    memset(visited, 0, sizeof visited);
    memset(s, -1, sizeof s);

    for (i = 1; i <= n; i++) {
        if (!visited[i]) {
            dfs(i);
        }
    }

//    PR0(grundy, n+1);
//    PR0(nextgrundy, n+1);

    // case 1
    set<int> x = {grundy[cycle[0]]};

    for (i = 1; i < cycle.size(); i++) {
        int u = cycle[i];

        set<int> y;

        if (x.count(grundy[u])) {
            y.insert(nextgrundy[u]);
        }

        if (x.count(grundy[u]) == 0 || x.size() > 1) {
            y.insert(grundy[u]);
        }

        x = y;
    }

    if (x.count(grundy[cycle[0]]) == 0 || x.size() > 1) {
        printf("POSSIBLE\n");
        return 0;
    }

    x = {nextgrundy[cycle[0]]};

    for (i = 1; i < cycle.size(); i++) {
        int u = cycle[i];

        set<int> y;

        if (x.count(grundy[u])) {
            y.insert(nextgrundy[u]);
        }

        if (x.count(grundy[u]) == 0 || x.size() > 1) {
            y.insert(grundy[u]);
        }

        x = y;
    }

    if (x.count(grundy[cycle[0]])) {
        printf("POSSIBLE\n");
        return 0;
    }

    printf("IMPOSSIBLE\n");
    return 0;
}

