int N;
int IN[200000];
vector<int> G[200000];
bool used[200000];
int T[200000];
vector<int> vs;

bool dfs1(int x) {
  if (used[x]) return true;
  used[x] = true;
  bool f = false;
  for (int t : G[x]) {
    f |= dfs1(t);
  }
  return f;
}
int mex1(set<int> &s) {
  int i = 0;
  while (true) {
    if (s.find(i) == s.end()) return i;
    i++;
  }
}
int mex2(set<int> &s) {
  int i = 0;
  int ctr = 0;
  while (true) {
    if (s.find(i) == s.end()) {
      ctr++;
      if (ctr == 2) return i;
    }
    i++;
  }
}

int dfs2(int x, int p) {
  if (T[x] != -1) return T[x];
  set<int> V;
  for (int t : G[x]) {
    if (t == p) continue;
    V.insert(dfs2(t, -1));
  }
  return T[x] = mex1(V);
}
set<int> dfs2s(int x, int p) {
  set<int> V;
  for (int t : G[x]) {
    if (t == p) continue;
    V.insert(dfs2(t, -1));
  }
  return V;
}

signed main() {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> N;
  rep(i, N) {
    int p;
    cin >> p;
    p--;
    G[p].pb(i);
    IN[i] = p;
  }
  int V = -1;
  rep(i, N) {
    if (dfs1(i)) {
      V = i;
      break;
    }
  }
  assert(V != -1);
  int s = V;
  vs.pb(V);
  while (true) {
    s = IN[s];
    if (s == V) break;
    vs.pb(s);
  }
  /*
  for (int v :vs){
    cout<<v+1<<",";
  }
  cout<<"\n";
  */

  set<int> mp = dfs2s(V, vs.back());
  vector<int> cand;
  cand.pb(mex1(mp));
  cand.pb(mex2(mp));
  for (int w : cand) {
    rep(i, N) T[i] = -1;
    T[V] = w;
    int last = -1;
    for (int v : vs) {
      if (v == V) continue;
      last = dfs2(v, -1);
    }
    set<int> xmp(mp);
    xmp.insert(last);
    if (mex1(xmp) == w) {
      cout << "POSSIBLE\n";
      return 0;
    }
  }
  cout << "IMPOSSIBLE\n";
  return 0;
}

