const int MAXN = 234567;
vector<int> G[MAXN];
int color[MAXN]; // 0 non visit 1 = visiting 2 = finish
int oncycle[MAXN], mex[MAXN], par[MAXN];
int tmpmex[MAXN];
bool mexnum[MAXN];

void dfs(int cur) {
    color[cur] = 1;
    //printf("cur = %d\n", cur);
    for (int i : G[cur]) {
        if (color[i] == 1) {
            //printf("cur = %d i = %d\n", cur, i);
            oncycle[i] = oncycle[cur] = 1;
            continue;
        }
        if (!color[i]) dfs(i);
        if (oncycle[i] == 1) {
            //printf("2 cur = %d i = %d\n", cur, i);
            oncycle[cur] = 1;
        }
    }
    for (int i = 0; i <= (int)G[cur].size(); i++)
        mexnum[i] = false;
    for (int i : G[cur]) {
        if (oncycle[i]) continue;
        mexnum[mex[i]] = 1;
    }
    for (int i = 0; ; i++)
        if (!mexnum[i]) {
            mex[cur] = i;
            break;
        }
    color[cur] = 2;
}

bool check(int tg, int ans) {
    tmpmex[tg] = ans;
    int cur = par[tg];
    //printf("tg = %d ans = %d\n", tg, ans);
    while (cur != tg) {
        for (int i = 0; i <= (int)G[cur].size(); i++)
            mexnum[i] = false;
        for (int i : G[cur])
            mexnum[tmpmex[i]] = 1;
        for (int i = 0; ; i++)
            if (!mexnum[i]) {
                tmpmex[cur] = i;
                break;
            }
        cur = par[cur];
    }
    memset(mexnum, 0, sizeof(mexnum));
    for (int i : G[tg])
        mexnum[tmpmex[i]] = 1;
    int ansmex = 0;
    while (mexnum[ansmex])
        ansmex++;
    return tmpmex[tg] == ansmex;
}

bool solve(int tg, int N) {
    for (int i = 0; i < N; i++)
        tmpmex[i] = mex[i];
    if (check(tg, tmpmex[tg])) return true;
    for (int i = 0; i < N; i++)
        tmpmex[i] = mex[i];
    memset(mexnum, 0, sizeof(mexnum));
    for (int i : G[tg]) {
        if (oncycle[i]) continue;
        mexnum[tmpmex[i]] = 1;
    }
    int ans = 0, cnt = 0;
