      num[v] = mex(v, num);
      c[rev[v]]--;
      if(c[rev[v]]==0 && num[rev[v]]==-1) q.push(rev[v]);
      last = v;
    }
    return last;
  };

  {
    queue<int> q;
    rep(i,n) if(cnt[i]==0) q.push(i);
    bfs(q,a,cnt);
