int dfs2(int v){
	if(!G[v].size()) return a[v] = 0;
	vector<int> vec;
	for(int i = 0;i < G[v].size();i++){
		if(!flag[G[v][i]]) vec.push_back(dfs2(G[v][i]));
	}
	if(!vec.size()) return a[v] = -1;
	sort(all(vec));
	vec.erase(unique(all(vec)),vec.end());
	int prev = -1;
	if(vec[0] != 0) return a[v] = 0;
	for(int i = 0;i < vec.size();i++){
		if(prev + 1 != vec[i]) return a[v] = prev;
		prev++;
	}
	return a[v] = prev + 1;
}

