	if (vec[0] != 0) return 0;

	for (int i = 0; i < vec.size() - 1; ++i) {
		if (vec[i] + 1 < vec[i + 1]) return vec[i] + 1;
	}
	return vec.back() + 1;
}

int decide(int p)
{
	if (grundy[p] != -1) return grundy[p];
	vector<int> ch;
	for (int q : graph[p]) {
		ch.push_back(decide(q));
	}
	return grundy[p] = cgrundy(ch);
}

bool solve(int p, int v)
{
	for (int i = 0; i < N; ++i) grundy[i] = -1;
	grundy[p] = v;

	for (int i = 0; i < N; ++i) decide(i);

	vector<int> ch;
	for (int q : graph[p]) {
		ch.push_back(decide(q));
	}

	return v == cgrundy(ch);
}

int main()
{
	scanf("%d", &N);
	for (int i = 0; i < N; ++i) {
		scanf("%d", P + i);
		--P[i];
		graph[P[i]].push_back(i);
		oncyc[i] = false;
	}

	int r = 0;
	for (int i = 0; i < 2 * N; ++i) r = P[r];

	vector<int> cyc;
	int r2 = r;
	do {
		cyc.push_back(r2);
		r2 = P[r2];
	} while (r2 != r);

	for (int p : cyc) oncyc[p] = true;

	vector<int> ori;
	for (int q : graph[r]) {
		if (!oncyc[q]) {
			ori.push_back(decide(q));
		}
	}

	int low = cgrundy(ori);
	bool ret = false;
	ret |= solve(r, low);
	ret |= solve(r, low + 1);
	puts(ret ? "POSSIBLE" : "IMPOSSIBLE");

	return 0;
}

