void dfs(int i) {
  if(onCircuit[i]) return;
  if(used[i]) return;
  used[i] = 1;
  set<int> st;
  for(int j : orig[i]) {
    assert(onCircuit[j] == false);
    dfs(j);
    st.insert(num[j]);
  }
  int t=0;
  while(st.count(t)) t++;
  num[i] = t;
}

