#include <bits/stdc++.h>

using std::swap;

const int N=1e5+10;

struct Edge{ int to,next; }way[N<<1];

int n,num[N],tot,In[N],app[N],val[N],val1[N],val2[N];
bool cir[N],vis[N];

void Build(int a,int b) { way[++tot]=(Edge){b,num[a]}; num[a]=tot; }

void Init() {
	scanf("%d",&n);
	for (int i=1;i<=n;++i) scanf("%d",&In[i]);
}

void Dfs(int x,int fa) {
	for (int i=num[x];i;i=way[i].next) {
		int v=way[i].to;
		Dfs(v,x);
	}
	for (int i=num[x];i;i=way[i].next) {
		int v=way[i].to;
		app[val[v]]++;
	}
	int cnt=fa?1:2;
	for (int i=0;cnt;++i) if (!app[i]) {
		if (cnt==2) val2[x]=i;
		else val[x]=val1[x]=i; 
		cnt--;
	}
	for (int i=num[x];i;i=way[i].next) {
		int v=way[i].to;
		app[val[v]]--;
	}
}

void Solve() {
	int rt=1; while (!vis[rt]) vis[rt]=1,rt=In[rt];
	while (!cir[rt]) cir[rt]=1,rt=In[rt];
	for (int i=1;i<=n;++i) if (!cir[i]) Build(In[i],i);
	for (int i=1;i<=n;++i) vis[i]=0;
	for (int i=1;i<=n;++i) if (cir[i]) Dfs(i,0);
	for (int i=1;i<=n;++i) if (cir[i]) {
		for (int j=1;j<=n;++j) if (cir[j]) {
			val[j]=-1;
			if (val2[j]<val1[j]) swap(val1[j],val2[j]);
		}
		val[i]=val1[i]; 
		int x=In[i],pre=i;
		while (x!=i) {
			if (val[pre]==val1[x]) val[x]=val2[x];
			else val[x]=val1[x];
			pre=x; x=In[x];
		}
		if (val[pre]!=val[i]) { printf("POSSIBLE\n"); return ; }

		for (int j=1;j<=n;++j) if (cir[j]) val[j]=-1;
		val[i]=val2[i]; x=In[i],pre=i;
		while (x!=i) {
			if (val[pre]==val1[x]) val[x]=val2[x];
			else val[x]=val1[x];
			pre=x; x=In[x];
		}
		if (val[pre]!=val[i]) { printf("POSSIBLE\n"); return ; }
		else { printf("IMPOSSIBLE\n"); return ; }
		break;
	}
}

int main() {
	Init();
	Solve();
	return 0;
}

