struct scc_t{
	vector<vector<int> > scc;
	vector<int> id;
};
void visit(const Graph &g, int v, scc_t &ret,
		stack<int> &S, vector<bool> &inS,
		vector<int> &low, vector<int> &num, int& time) {
	low[v] = num[v] = time;
	time++;
	S.push(v); inS[v] = true;
	for(const auto &e:g[v]){
		int w = e.dst;
		if (num[w] == -1) {
			visit(g, w, ret, S, inS, low, num, time);
			low[v] = min(low[v], low[w]);
		} else if (inS[w])
			low[v] = min(low[v], num[w]);
	}
	if (low[v] == num[v]) {
		ret.scc.push_back(vector<int>());
		while (1) {
			int w = S.top(); S.pop(); inS[w] = false;
			ret.scc.back().push_back(w);
			if (v == w) break;
		}
	}
}
scc_t stronglyConnectedComponents(const Graph& g) {
	const int n = g.size();
	scc_t ret{vector<vector<int> >(),vector<int>(n,-1)};
	vector<int> low(n,-1), num(n,-1);
	stack<int> S;
	vector<bool> inS(n);
	int time = 0;
	REP(u, n) if (num[u] == -1) visit(g, u, ret, S, inS, low, num, time);
	REP(i,ret.scc.size())REP(j,ret.scc[i].size())ret.id[ret.scc[i][j]] = i;
	return ret;
}
