    }
  } 
  while (!que.empty()) {
    int v = que.front(); que.pop();
    int val = get(v);
    st[p[v]].insert(val);
    cnt[p[v]]--;
    if (cnt[p[v]] == 0)
      que.push(p[v]);
  }
