    if (add[u] != -1)
      st[u].erase(add[u]);
    u = p[u];
    if (u == v)
      break;
  }
  if (add[v] != -1)
    st[v].erase(add[v]);
  memset(add, -1, sizeof add);
  memset(c, -1, sizeof c);
  ok = 1;
  u = v;
  int rem = get(v);
  st[v].insert(rem);
  c[v] = get(v);
  st[v].erase(rem);

  while (1) {
    int pp = p[u];
    if (!st[pp].count(c[u])) {
      add[pp] = c[u];
      st[pp].insert(c[u]);
    }
    if (pp == v) {
      if (!cek(v, c[v]))
        ok = 0;
      break;
    }
    c[pp] = get(pp);
    u = pp;
  }
  puts(ok ? "POSSIBLE" : "IMPOSSIBLE");
  return 0;
}

