const int Nmax = 2e5 + 5;
int n, i, x, go[Nmax], j, val[Nmax];
bool used[Nmax], active[Nmax];
vector<int> v[Nmax];

bool dfs(int node)
{
    if(active[node]) return 1;
    used[node] = 1;
    active[node] = 1;

    for(auto it : v[node])
        if(dfs(it)) return 1;

    active[node] = 0;
    return 0;
}

void grundy(int node)
{
    for(auto it : v[node])
        if(val[it] == -1) grundy(it);

    for(int i = 0; i <= v[node].size(); ++i) used[i] = 0;
    for(auto it : v[node]) used[val[it]] = 1;

    for(int i = 0; val[node] == -1; ++i)
        if(!used[i]) val[node] = i;
}

