bool found;
vector<int> cicle, stk;

bool mrk[maxn];

void dfs(int v) {
    used[v] = 1;
    stk.push_back(v);

    for(auto u: adj[v])
	if(!used[u])
	    dfs(u);
	else
	    if(used[u] == 1) {
		found = true;

		for(int k = stk.size() - 1; k >= 0; --k) {
		    int c = stk[k];

		    cicle.push_back(c);
		    mrk[c] = true;

		    if(c == u)
			break;
		}
	    }

    stk.pop_back();
    used[v] = 2;
}

int g[maxn];

void dfsGrundy(int v) {
    set<int> Set;

    for(auto u: adj[v])
	if(!mrk[u]) {
	    dfsGrundy(u);
	    Set.insert(g[u]);
	}

    int k = 0;

    while(Set.find(k) != Set.end()) ++k;

    g[v] = k;
}

int G[maxn];

bool check() {
    int sz = cicle.size();

    for(int i = sz - 2; i >= 0; --i) {
	int c = cicle[i];
	int nx = cicle[i + 1];

	if(G[nx] != G[c])
	    continue;

	++G[c];
    }

    int First = cicle[0];
    int Last = cicle[sz - 1];

    if(G[First] == G[Last])
	return false;

    return true;
}

bool testCicle() {
    int sz = cicle.size();

    for(int i = 0; i < sz; ++i)
	G[cicle[i]] = g[cicle[i]];

    if(check())
	return true;

    for(int i = 0; i < sz; ++i)
	G[cicle[i]] = g[cicle[i]];

    ++G[cicle[sz - 1]];

    if(check())
	return true;

    return false;
}

bool solve() {
    for(int v = 1; v <= n; ++v)
	if(!used[v])
	    dfs(v);

    if(!found)
	return true;

    for(auto u: cicle)
	dfsGrundy(u);

    return testCicle();
}

