void add(int x,int y){
	num++;
	mem[num].to=y; mem[num].next=head[x];
	head[x]=num;
}

void topsort(){
	int i,k,u,j;
	memset(dp,-1,sizeof(dp));
	for (i=1;i<=n;i++)
		if (!d[i]){
			q.push(i);
			vis[i]=1;
		}
	while (!q.empty()){
		k=q.front(); q.pop(); vis[k]=1;
		cnt=0; sig=0;
		for (j=head[k];j;j=mem[j].next){
			u=mem[j].to;
			a[++cnt]=dp[u];
		}
		sort(a+1,a+1+cnt);
		for (j=1;j<=cnt;j++)
			if (sig!=a[j]) break;
		else sig++;
		dp[k]=sig;
		u=p[k]; d[u]--;
		if (!d[u]){
			vis[u]=1; q.push(u);
		}
	}
}

void solve(){
	int k,u,j,st;
	st=b[1]; k=p[b[1]];
	while (k!=st){
		cnt=0; sig=0;
		for (j=head[k];j;j=mem[j].next){
			u=mem[j].to;
			a[++cnt]=f[u];
		}
		sort(a+1,a+1+cnt);
		for (j=1;j<=cnt;j++)
			if (sig!=a[j]) break;
		else sig++;
		f[k]=sig;
		if (p[k]!=st) k=p[k];
		else break;
	}
	cnt=0; sig=0;
	for (j=head[st];j;j=mem[j].next){
		u=mem[j].to;
		a[++cnt]=f[u];
	}
	sort(a+1,a+1+cnt);
	for (j=1;j<=cnt;j++)
		if (sig!=a[j]) break;
	else sig++;
	if (sig==f[st]) flag=1;
}

void init(){
	int i,j,k,u; cnt=tot=0;
	for (i=1;i<=n;i++)
		if (!vis[i]) b[++tot]=i;
	k=b[1];
	for (i=1;i<=n;i++) f[i]=dp[i];
	for (j=head[k];j;j=mem[j].next){
		u=mem[j].to;
		if (vis[u]) a[++cnt]=f[u];
	}
	sort(a+1,a+1+cnt); sig=0;
	for (i=1;i<=cnt;i++)
		if (sig!=a[i]) break;
	else sig++;
	f[k]=sig;
	solve();
	f[k]++;
	solve();
}

