vector<int> loop;
bool used[200001];
bool isloop[200001];
int N;

vector<int> grundyP[200001];

bool dfs_findloop(int v){
    used[v]=true;
    bool res=false;
    for(int u:G[v]){
        if(!used[u]){
            if(dfs_findloop(u))res=true;
        }else res=true;
    }
    if(res)loop.push_back(v);
    return res;
}

void add_G(int from,int to){
    G[from].push_back(to);
    rG[to].push_back(from);
}

int dfs_grundy(int v){
    set<int> used_g;
    for(int u:G[v])used_g.insert(dfs_grundy(u));
    int res=-1;
    while(true)if(used_g.count(++res)==0)return res;

}

int dfs_solve(int v,int k){
    used[v]=true;
    int rec =(k==grundyP[v][0] ? grundyP[v][1] : grundyP[v][0]);
    for(int u:rG[v])if((isloop[u])&&(!used[u]))return dfs_solve(u,rec);
    return rec;
}


int main(){
    cin>>N;
    REP(i,N){
        int p;cin>>p;p--;
        add_G(p,i);
    }
    set<int> grundy[N];

    fill_n(used,N,false);
    fill_n(isloop,N,false);
    REP(i,N)if(!used[i])dfs_findloop(i);
    for(int v:loop)isloop[v]=true;
    for(int v:loop)for(int u:G[v])if(!isloop[u])grundy[v].insert(dfs_grundy(u));
    for(int v:loop){
        int res=-1;
        while(grundyP[v].size()<2){
            if(grundy[v].count(++res)==0)grundyP[v].push_back(res);
        }
    }

    int root=loop[0];
    fill_n(used,N,false);
    if(dfs_solve(root,-1)!=grundyP[root][0]){
        cout<<"POSSIBLE"<<endl;
    }else{
        fill_n(used,N,false);
        if(dfs_solve(root,grundyP[root][0])==grundyP[root][0]) {
            cout << "POSSIBLE" << endl;
        }else{
            cout<<"IMPOSSIBLE"<<endl;
        }
    }
    return 0;
}

