using namespace std;

vector<int> G[200200];
int N;

int vals[200200];

int root;
int prv[200200];

queue<int> que;

int deg[200200];

void input(){
	scanf("%d", &N);
	for(int i = 0; i < N; ++i){
		int p;
		scanf("%d", &p);
		p--;
		G[p].push_back(i);
		prv[i] = p;
	}
}

bool upd(int &x, int &y, int v){
	if(x == -1){
		x = v;
		return false;
	}else if(y == -1){
		y = v;
		return true;
	}else return true;
}

bool solve2(bool flg){
	for(int i = 0; i < N; ++i){
		deg[i] = G[i].size();
		if(G[i].size() == 0) que.push(i);
		vals[i] = -1;
	}
	while(!que.empty()){
		int v = que.front();
		que.pop();
		if(G[v].size() == 0){
			vals[v] = 0;
		}else{
			vector<int> tmp;
			for(int i = 0; i < G[v].size(); ++i){
				tmp.push_back(vals[G[v][i]]);
			}
			tmp.push_back(-1);
			tmp.push_back(N + 1);
			sort(tmp.begin(), tmp.end());
			for(int i = 0; i + 1 < tmp.size(); ++i){
				int x = tmp[i], y = tmp[i + 1];
				if(y != x + 1 && x != y){
					vals[v] = x + 1;
					break;
				}
			}
		}
		deg[prv[v]]--;
		if(deg[prv[v]] == 0){
			que.push(prv[v]);
		}
	}
	int root = -1;
	for(int i = 0; i < N; ++i){
		if(vals[i] == -1){
			root = i;
			break;
		}
	}
	vector<int> tmp;
	for(int i = 0; i < G[root].size(); ++i){
		tmp.push_back(vals[G[root][i]]);
	}
	tmp.push_back(N + 10);
	int cand1 = -1, cand2 = -1;
	for(int i = 0; i + 1 < tmp.size(); ++i){
		int x = tmp[i], y = tmp[i + 1];
		bool ok = false;
		for(int v = x + 1; v < y; ++v){
			bool flg = upd(cand1, cand2, v);
			if(flg){
				ok = flg;
				break;
			}
		}
		if(ok) break;
	}
	if(flg){
		vals[root] = cand1;
	}else{
		vals[root] = cand2;
	}
	int v = prv[root];
	while(v != root){
		vector<int> tmp;
		for(int i = 0; i < G[v].size(); ++i){
			tmp.push_back(vals[G[v][i]]);
		}
		tmp.push_back(-1);
		tmp.push_back(N + 1);
		sort(tmp.begin(), tmp.end());
		for(int i = 0; i + 1 < tmp.size(); ++i){
			int x = tmp[i], y = tmp[i + 1];
			if(y != x + 1 && x != y){
				vals[v] = x + 1;
				break;
			}
		}
		v = prv[v];
	}
	tmp.clear();
	for(int i = 0; i < G[root].size(); ++i){
		tmp.push_back(vals[G[root][i]]);
	}
	sort(tmp.begin(), tmp.end());
	tmp.erase(unique(tmp.begin(), tmp.end()), tmp.end());
	if(tmp.size() != vals[root]) return false;
	for(int i = 0; i < tmp.size(); ++i){
		if(tmp[i] != i) return false;
	}
	return true;
}

bool solve(){
	bool flg = solve2(false);
	if(flg) return true;
	flg = solve2(true);
	if(flg) return true;
	return false;
}

int main(){
	input();
	bool flg = solve();
	if(flg) printf("POSSIBLE\n");
	else printf("IMPOSSIBLE\n");
	return 0;
}

