int N, Head[Max_N], To[Max_N], Next[Max_N], root;
int dfsclock, Pre[Max_N], Lowlink[Max_N], scctot, sccno[Max_N];
vector<int> SCC[Max_N];
stack<int> S;

inline bool comp(const int &u, const int &v)
{
	return Pre[u] < Pre[v];
}

void Tarjan(int u)
{
	int v;
	S.push(u), Pre[u] = Lowlink[u] = ++dfsclock;
	for (int i = Head[u];i;i = Next[i])
		if (!Pre[v = To[i]])
			Tarjan(v), Lowlink[u] = min(Lowlink[u], Lowlink[v]);
		else
			if (!sccno[v])
				Lowlink[u] = min(Lowlink[u], Pre[v]);
	if (Pre[u] == Lowlink[u])
	{
		++scctot;
		while (true)
		{
			v = S.top(), S.pop(), SCC[sccno[v] = scctot].push_back(v);
			if (u == v)
				break;
		}
		if (SCC[scctot].size() > 1)
			root = scctot, sort(SCC[root].begin(), SCC[root].end(), comp);
	}
}

int SG[Max_N];
bool done[Max_N];

int getSG(const vector<int> &V)
{
	for (int i = 0;i < V.size();++i)
		done[V[i]] = true;
	int Ret;
	for (int i = 0;;++i)
		if (done[i] == false)
		{
			Ret = i;
			break;
		}
	for (int i = 0;i < V.size();++i)
		done[V[i]] = false;
	return Ret;
}

void dfsTree(int u)
{
	vector<int> Son;
	for (int i = Head[u], v;i;i = Next[i])
		dfsTree(v = To[i]), Son.push_back(SG[v]);
	SG[u] = getSG(Son);
}

int main()
{
	Get_Val(N);
	for (int t = 1, s;t <= N;++t)
	{
		Get_Val(s);
		To[t] = t, Next[t] = Head[s], Head[s] = t;
	}
	for (int i = 1;i <= N;++i)
		if (!Pre[i])
			Tarjan(i);
	for (int j = 0, u;j < SCC[root].size();++j)
	{
		u = SCC[root][j];
		for (int i = Head[u], v;i;i = Next[i])
			if (sccno[v = To[i]] != root)
				dfsTree(v);
	}
	vector<int> Son;
	for (int i = Head[SCC[root][0]], v;i;i = Next[i])
		if (sccno[v = To[i]] != root)
			Son.push_back(SG[v]);
	SG[SCC[root][0]] = getSG(Son);
	for (int j = SCC[root].size() - 1, u;j;--j)
	{
		u = SCC[root][j], Son.clear();
		for (int i = Head[u];i;i = Next[i])
			Son.push_back(SG[To[i]]);
		SG[u] = getSG(Son);
	}
	Son.clear();
	for (int i = Head[SCC[root][0]];i;i = Next[i])
		Son.push_back(SG[To[i]]);
	if (getSG(Son) == SG[SCC[root][0]])
	{
		puts("POSSIBLE");
		return 0;
	}
	Son.clear();
	for (int i = Head[SCC[root][0]], v;i;i = Next[i])
		if (sccno[v = To[i]] != root)
			Son.push_back(SG[v]);
	Son.push_back(getSG(Son)), SG[SCC[root][0]] = getSG(Son);
	for (int j = SCC[root].size() - 1, u;j;--j)
	{
		u = SCC[root][j], Son.clear();
		for (int i = Head[u];i;i = Next[i])
			Son.push_back(SG[To[i]]);
		SG[u] = getSG(Son);
	}
	Son.clear();
	for (int i = Head[SCC[root][0]];i;i = Next[i])
		Son.push_back(SG[To[i]]);
	if (getSG(Son) == SG[SCC[root][0]])
	{
		puts("POSSIBLE");
		return 0;
	}
	puts("IMPOSSIBLE");
	return 0;
}

