int vis[MAXN], mark[MAXN];
vector<int> sta, cir;

int val[MAXN];

bool DFS(int u){
	vis[u] = true;
	sta.push_back(u);
	for (auto &x: E[u]){
		if (mark[x.nd])
			continue;

		mark[x.nd] = true;
		int v = x.st;
		eput(u, v);
		if (vis[v]){
			for (; sta.back() != v; sta.pop_back())
				cir.push_back(sta.back());
			cir.push_back(v);
			return true;
		}
		if (DFS(v))
			return true;
	}
	sta.pop_back();
	return false;
}

void DFS1(int u){
	vis[u] = true;

	vector<int> son;
	for (auto &x: E[u]){
		int v = x.st;
		if (vis[v])
			continue;
		DFS1(v);
		son.push_back(val[v]);
	}
	for (int &i = val[u] = 0; i < son.size() && son[i] == i; ++i);
}

int main(){
	scanf("%d", &n);
	for (int u, v, i = 1; i <= n; ++i){
		scanf("%d", &u);
		p[i] = u;
		E[i].emplace_back(u, i);
		E[u].emplace_back(i, i);
	}
	DFS(1);

	eput(cir);

	fill_n(vis + 1, n, false);
	for (auto &u: cir)
		vis[u] = true;
	if (p[cir[0]] != cir[1])
		reverse(all(cir));
	for (auto &u: cir)
		DFS1(u), eput(val[u]);

	int same = true;
	for (auto &u: cir)
		same &= val[u] == val[cir[0]];
	if (same){
		puts(cir.size() & 1 ? "IMPOSSIBLE" : "POSSIBLE");
		return 0;
	}
	else
		puts("POSSIBLE");

	int k = 0;
	for (int i = 1; i < cir.size(); ++i)
		if (val[cir[i - 1]] > val[cir[i]]){
			k = i;
			break;
		}
	for (int i = 1; i < cir.size(); ++i){
		int u = (k + i - 1) % cir.size();
		int v = (k + i) % cir.size();
		if (val[u] == val[v])
			++val[v];
	}
	return 0;
}

