using namespace std;

int mex(set<int> x)
{
    int r = 0;
    while(x.count(r))
        r++;
    return r;
}

const int maxn = 6e5;
vector<int> G[maxn], Gt[maxn];

void add_edge(int u, int z1, int v, int z2)
{
    int U = u + maxn / 2 * z1;
    int V = v + maxn / 2 * z2;
    G[U].push_back(V);
    Gt[V].push_back(U);
}

int used[maxn];

void dfs(int v, vector<int> *G, vector<int> &st)
{
    if(used[v])
        return;
    used[v] = 1;
    for(auto u: G[v])
        dfs(u, G, st);
    st.push_back(v);
}

void try2sat()
{
    vector<int> top_sort;
    dfs(0, G, top_sort);
    reverse(begin(top_sort), end(top_sort));
    memset(used, 0, sizeof(used));
    for(auto v: top_sort)
    {
        if(used[v])
            continue;
        vector<int> comp;
        dfs(v, Gt, comp);
        set<int> lol;
        for(auto u: comp)
        {
            lol.insert(u);
            if(lol.count(u ^ 1))
            {
                cout << "IMPOSSIBLE\n";
                exit(0);
            }
        }
    }
    cout << "POSSIBLE\n";
}

