int N, a[200020];
Vec< Vec< int > > adj;
Vec< Vec< int > > radj;

int dfs(int v) {
	if (a[v] == 1) return 0;
	a[v] = 1;
	assert((int)adj[v].size() == 1);
	for (int u : adj[v]) return dfs(u) + 1;
	return 0;
}

void solveA() {
	bool flag = true;
	for_(v,0,N) {
		if (a[v] != -1) continue;
		flag &= (dfs(v) % 2 == 0);
	}
	puts(flag ? "POSSIBLE" : "IMPOSSIBLE");
}

void aDfs(int v, int c) {
	if ((int)adj[v].size() > 1) {
		a[v] = adj[v].size();
		return;
	}
	a[v] = c;
	for (int u : radj[v]) aDfs(u, 1 - c);
}

void solveB() {
	Vec< Vec< int > > rev(N, Vec< int >());
	Vec< int > deg(N, 0);

	for_(v,0,N) {
		if (a[v] != -1) continue;
		for (int u : adj[v]) if (a[u] == -1) { rev[u].push_back(v); ++deg[v]; }
	}

	queue< int > que;
	for_(v,0,N) if (a[v] == -1 && deg[v] == 0) que.push(v);

	while (!que.empty()) {
		int v = que.front(); que.pop();

		vector< int > nums;
		for (int u : adj[v]) nums.push_back(a[u]);
		sort(allof(nums));

		if (nums[0] != 0) a[v] = 0;
		else a[v] = nums.back() + 1;

		for (int u : rev[v]) {
			--deg[u];
			if (deg[u] == 0) que.push(u);
		}
	}

	for_(v,0,N) cerr << a[v] << " ";
	cerr << endl;

	bool flag = true;
	for_(v,0,N) {
		if (a[v] == 0 || adj[v].size() == 0) continue;
		set< int > nums;
		for (int u : adj[v]) nums.insert(a[u]);
		flag &= ((int)nums.size() == a[v] && (*nums.begin()) == 0 && (*nums.rbegin()) == a[v] - 1);
	}
	puts(flag ? "POSSIBLE" : "IMPOSSIBLE");
}

int main() {
	cin >> N;
	adj.assign(N, Vec< int >());
	radj.assign(N, Vec< int >());

	for_(i,0,N) {
		int p;
		cin >> p;
		--p;
		adj[p].push_back(i);
		radj[i].push_back(p);
	}

	minit(a, -1);
	for_(v,0,N) {
		if (adj[v].size() == 0) {
			a[v] = 0;
			aDfs(v, 0);
		}
	}


	if (*max_element(a, a + N) == -1) {
		solveA();
	} else {
		solveB();
	}
}

