int N;
int P[200011];
VI G[200011];
VI R[200011];

bool use[200011];
int par[200011];

int A[200011], C[200011];

void MAIN() {
    scanf("%d", &N);
    REP (i, N) scanf("%d", P+i), P[i]--;
    REP (i, N) {
	G[P[i]].push_back(i);
    }

    int s = 0;
    REP (i, N) s = P[s];
    VI cycle;
    while (!use[s]) {
	use[s] = true;
	cycle.push_back(s);
	s = P[s];
    }

    memset(C, -1, sizeof C);
    VI ord;
    EACH (e, cycle) {
	ord.clear();
	ord.push_back(*e);
	par[*e] = *e;
	for (int i=0; i<(int)ord.size(); i++) {
	    int v = ord[i];
	    EACH (f, G[v]) if (!use[*f] && *f != par[v]) {
		par[*f] = v;
		ord.push_back(*f);
	    }
	}

	for (int i=ord.size(); i--;) {
	    int v = ord[i];
	    EACH (f, G[v]) if (!use[*f] && *f != par[v]) {
		C[A[*f]] = v;
	    }

	    REP (j, N+1) if (C[j] != v) {
		A[v] = j;
		break;
	    }
	}
    }
    REP (add, 2) {
	int prv = A[cycle.back()] + add;
	REP (i, cycle.size()) {
	    int v = cycle[i];
	    if (A[v] == prv) {
		prv = A[v] + 1;
	    } else {
		prv = A[v];
	    }
	}
	if (prv == A[cycle.back()] + add) {
	    puts("POSSIBLE");
	    return;
	}
    }
    puts("IMPOSSIBLE");
}

