const int MAX_N = 212345;
vector<int> g[MAX_N];
int grundy[MAX_N];
int parent[MAX_N];
int deg[MAX_N];

bool check(int v, int parent_grundy, int begin, int begin_grundy) {
  set<int> vis;
  for (int child : g[v]) if (grundy[child] != -1) vis.insert(grundy[child]);
  vis.insert(parent_grundy);
  int x = 0;
  while (vis.count(x) > 0) x++;

  if (v == begin) {
    return x == begin_grundy;
  }
  return check(parent[v], x, begin, begin_grundy);
}

int main2() {
  REP(i, MAX_N) g[i].clear();
  CLR(grundy, -1);
  CLR(deg, 0);

  int N = nextInt();
  REP(i, N) {
    int p = nextInt() - 1;
    g[p].push_back(i);
    parent[i] = p;
  }
  REP(i, N) deg[i] = g[i].size();

  queue<int> q;
  REP(i, N) if (deg[i] == 0) { q.push(i); }

  int done = 0;
  while (q.size() > 0) {
    int v = q.front(); q.pop();

    deg[parent[v]]--;
    if (deg[parent[v]] == 0) { q.push(parent[v]); }

    set<int> vis;
    for (int child : g[v]) vis.insert(grundy[child]);
    int x = 0;
    while (vis.count(x) > 0) x++;
    grundy[v] = x;
    done++;
  }

  bool ans = false;
  REP(i, N) if (grundy[i] == -1) {
    vector<int> cand;
    set<int> vis;
    for (int child : g[i]) if (grundy[child] != -1) vis.insert(grundy[child]);
    for (int x = 0; cand.size() < 2; x++) {
      if (vis.count(x) == 0) cand.push_back(x);
    }
    ans = (check(parent[i], cand[0], i, cand[0]) || check(parent[i], cand[1], i, cand[1]));
    break;
  }

  cout << (ans ? "POSSIBLE":"IMPOSSIBLE") << endl;
  return 0;
}

