int n;
int nxt[N];
int state[N];
int f[N];
bool ring[N];
int has[N];
int newHas[N];
bool visited[N];
int res[N];

int st = -1;

bool check(int x) {
	for (int i = 1; i <= n; ++i) {
		newHas[i] = has[i];
		visited[i] = false;
		res[i] = -1;
	}
	int cur = st;
	res[cur] = x;

	while (!visited[cur]) {
		if ((1 << res[cur]) & newHas[cur]) return false;
		for (int j = 0; j < res[cur]; ++j) if (!(newHas[cur] & (1 << j))) return false;
		visited[cur] = true;
		newHas[nxt[cur]] |= 1 << res[cur];
		cur = nxt[cur];
		for (int j = 0; j < 4; ++j) if (!(newHas[cur] & (1 << j))) {
			res[cur] = j;
			break;
		}
		if (res[cur] == -1) return false;
	}
	return cur == st && res[cur] == x;

}


void solve() {
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		scanf("%d", nxt + i);
		f[nxt[i]]++;
	}

	for (int i = 1; i <= n; ++i) state[i] = -1;
	for (int i = 1; i <= n; ++i) if (f[i] == 0) {
		int j = i;
		while (state[j] == -1) {
			state[j] = 1;
			j = nxt[j];
		}
		while (!ring[j]) {
			ring[j] = 1;
			j = nxt[j];
		}
		st = j;
		break;
	}

	if (st == -1) {
		st = 1;
		for (int i = 1; i <= n; ++i) ring[i] = 1;
	}

//	for (int i = 1; i <= n; ++i) if (ring[i]) cout << i << '\n';

	for (int i = 1; i <= n; ++i) {
		if (f[i] == 0) {
			int cur = 1;
			int j = i;
			while (!ring[j]) {
				cur ^= 1;
				j = nxt[j];
			}
			has[j] |= 1 << cur;
		}
	}


//	for (int i = 1; i <= n; ++i) if (ring[i]) cout << i << ' ' << has[i] << '\n';

	for (int i = 1; i <= n; ++i) state[i] = -1;
//	cout << st << '\n';
//	cout << check(1);
//	return;

	for (int i = 0; i < 4; ++i) if (check(i)) {
		puts("POSSIBLE");
		return;
	}

	puts("IMPOSSIBLE");



}

