bool nuee;

void dfs(int x){
	used[x]=1;
	for(auto y:g[x]){
		if(!used[y]) dfs(y);
	}
	vs.push_back(x);
}

void rdfs(int x, int k){
	used[x]=1;
	cmp[k].push_back(x);
	for(auto y:gr[x]){
		if(!used[y]){
			nuee=1;
			rdfs(y, k);
		}
	}
}

int scc(){
	for(int x=0; x<n; x++){
		if(!used[x]) dfs(x);
	}
	fill(used, used+n, 0);
	int k=0;
	for(int i=vs.size()-1; i>=0; i--){
		if(!used[vs[i]]) rdfs(vs[i], k++);
	}
	return k;
}

int main()
{
	cin>>n;
	for(int i=0; i<n; i++){
		int p; cin>>p; p--;
		g[p].push_back(i);
		gr[i].push_back(p);
	}

	int k=scc();
	if(!nuee){
		cout<<"POSSIBLE"<<endl;
		return 0;
	}
	int a[200000], a2[200000];
	fill(a, a+n, -1);
	fill(a2, a2+n, -1);
