            a[cmp[i][0]]=0;
            a2[cmp[i][0]]=0;
          }else{
			for(int t=0; ; t++){
				if(st.find(t)==st.end()){
					a[cmp[i][0]]=t;
					a2[cmp[i][0]]=t;
					break;
				}
			}
          }
		}else{
			set<int> st;
			for(auto y:g[cmp[i][0]]){
				st.insert(a[y]);
			}
			bool e=0;
			for(int t=0; ; t++){
				if(st.find(t)==st.end()){
					if(!e){
						e=1;
						a[cmp[i][0]]=t;
					}else{
						a2[cmp[i][0]]=t;
						break;
					}
				}
			}
			for(int j=1; j<cmp[i].size(); j++){
				set<int> st1, st2;
				for(auto y:g[cmp[i][j]]){
					st1.insert(a[y]);
