		if (num[cn] == -1) {
			vector<int>v;
			for (auto i : edge[cn])v.push_back(num[i]);
			sort(v.begin(), v.end());
			num[cn] = 0;
			for (auto i : v) {
				if (i < num[cn])continue;
				if (i > num[cn])break;
				num[cn]++;
			}
		}
		dir[rev_edge[cn]]--;
		if (!dir[rev_edge[cn]])Q.push(rev_edge[cn]);
	}
	vector<int>loop;
	for (int i = 0; i < N; i++) {
