		if (i > L)break;
		L++;
	}
	bool flag = true;
	num[loop[0]] = L;
	int nx = rev_edge[loop[0]];
	while (nx != loop[0]) {
		vector<int>w;
		for (auto i : edge[nx])w.push_back(num[i]);
		sort(w.begin(), w.end());
		num[nx] = 0;
		for (auto i : w) {
			if (i < num[nx])continue;
			if (i > num[nx])break;
			num[nx]++;
		}
		nx = rev_edge[nx];
	}
	for (int i = 0; i < N; i++) {
		for (auto j : edge[i]) {
			if (num[i] == num[j]) {
				flag = false;
			}
		}
	}
	if (flag) {
		cout << "POSSIBLE\n";
		return 0;
	}
	int box = L;
	L++;
	for (auto i : v) {
		if (i < L)continue;
		if (i > L)break;
		L++;
	}
	num[loop[0]] = L;
	nx = rev_edge[loop[0]];
	while (nx != loop[0]) {
		vector<int>w;
		for (auto i : edge[nx])w.push_back(num[i]);
		sort(w.begin(), w.end());
		num[nx] = 0;
		for (auto i : w) {
			if (i < num[nx])continue;
			if (i > num[nx])break;
			num[nx]++;
		}
		if (rev_edge[nx] == loop[0]) {
			if (num[nx] != box) {
				cout << "IMPOSSIBLE\n";
				return 0;
			}
		}
		nx = rev_edge[nx];
	}
	for (int i = 0; i < N; i++) {
