int main() {
    int n; cin >> n;
    vector<int> par(n), a(n, -1);
    vector<vector<int>> g(n);
    for (int i = 0; i < n; i++) {
        cin >> par[i], par[i]--;
        g[par[i]].emplace_back(i);
    }
    queue<int> que;
    for (int i = 0; i < n; i++) if (g[i].size() == 0) que.emplace(i);   // 葉
    while (!que.empty()) {
        int u = que.front(); que.pop();
        if (a[u] >= 0) continue;
        set<int> s;
        bool on_cycle = false;
        for (int v: g[u]) {
            if (a[v] == -1) on_cycle = true;
            s.emplace(a[v]);
        }
        if (on_cycle) continue;
        int g = 0; while (s.count(g)) g++;
        a[u] = g;
        que.emplace(par[u]);
    }
    auto check = [&](int st, int val) {
        int u = par[st];
        int prev = val;
        while (u != st) {
            set<int> s; s.insert(prev);
            for (int v: g[u]) s.insert(a[v]);
            int g = 0; while (s.count(g)) g++;
            prev = a[u] = g;
            u = par[u];
        }
        set<int> s; s.insert(prev);
        for (int v: g[u]) s.insert(a[v]);
        int g = 0; while (s.count(g)) g++;
        a[st] = g;
        return g == val;
    };
    int u;
    for (int i = 0; i < n; i++) if (a[i] == -1) u = i;
    set<int> s;
    for (int v: g[u]) s.emplace(a[v]);
    int g1 = 0;         while (s.count(g1)) g1++;
    int g2 = g1 + 1;    while (s.count(g2)) g2++;
    if (check(u, g1) || check(u, g2)) cout << "POSSIBLE" << endl;
    else cout << "IMPOSSIBLE" << endl;
    return 0;
}

