int grundy(vector<int>& vv){
    sort(all(vv));
    vv.erase(unique(all(vv)),vv.end());
    if(vv[0]>0){
        return 0;
    }
    for(int j=0;j<vv.size()-1;j++){
        if(vv[j+1]>vv[j]+1){
            return vv[j]+1;
        }
    }
    return vv.back()+1;
}
