class scc_decomposition{
public:
    int V;
    vector<vector<int>> E, rE;
    vector<int> pos, used, cmp;
    scc_decomposition() {}
    scc_decomposition(int v){
        V = v;
        E.resize(v);
        rE.resize(v);
        cmp.resize(v);
        used.resize(v, 0);
    }

    void add(int from, int to){
        E[from].push_back(to);
        rE[to].push_back(from);
    }

    void dfs(int v){
        used[v] = 1;
        rep(i, E[v].size()){
            if (!used[E[v][i]]) dfs(E[v][i]);
        }
        pos.push_back(v);
    }

    void rdfs(int v, int k){
        used[v] = 1;
        cmp[v] = k;
        rep(i, rE[v].size()){
            if (!used[rE[v][i]]) rdfs(rE[v][i], k);
        }
    }

    int scc(){
        rep(v, V){
            if (!used[v]) dfs(v);
        }
        used.assign(V, 0);
        int k = 0;
        for (int i = (int)pos.size() - 1; i >= 0; i--) {
            if (!used[pos[i]]) rdfs(pos[i], k++);
        }
        return k; // return the number of sccs
    }
};

scc_decomposition scc;

int dfs(int cur, int par = -1){
    vector<int> tmp;
    for(int a: scc.E[cur]){

        if(scc.cmp[a] != scc.cmp[cur]){
            tmp.pb(dfs(a));
        }
    }
    sort(all(tmp));
    rep(i, tmp.size()){
        if(tmp[i] != i){
            return i;
        }
    }
    return (int)tmp.size();
}

bool same(vector<int> &V){
    int a = V[0];
    rep(i, V.size()){
        if(a != V[i]) return false;
    }
    return true;
}

