int calc(vector<int> &mex) {
	sort(mex.begin(), mex.end());
	int sg = 0;
	for (int i : mex) {
		if (i == sg) ++sg;
		else if (i > sg) break;
	}
	return sg;
}

int main() {
	scanf("%d", &n);
	iter(i, n) scanf("%d", &p[i]), ++in[p[i]];

	int h = 1, t = 0;
	iter(i, n) if (!in[i]) q[++t] = i;

	while (h <= t) {
		int i = q[h++];
		sg[i] = calc(mex[i]);
		mex[p[i]].push_back(sg[i]);
		if (!--in[p[i]]) q[++t] = p[i];
	}

	iter(i, n) if (in[i]) {
		for (int x = i; ; x = p[x]) {
			ring.push_back(x);
			sg[x] = calc(mex[x]);
			if (p[x] == i) break;
		}

		reverse(ring.begin(), ring.end());

		int len = ring.size(), lst = sg[ring[0]];
		for (int i = 1; i < len; ++i) {
			if (lst == sg[ring[i]]) ++lst;
			else lst = sg[ring[i]];
		}

		if (lst != sg[ring[0]]) puts("POSSIBLE");
		else {
			lst = sg[ring[0]] + 1;
			for (int i = 1; i < len; ++i) {
				if (lst == sg[ring[i]]) ++lst;
				else lst = sg[ring[i]];
			}
			if (lst == sg[ring[0]]) puts("POSSIBLE");
			else puts("IMPOSSIBLE");
		}
		break;
	}
	return 0;
}

