vector<int> topologicalSort(const vector<vector<int> > &graph) {
    int V = (int)graph.size(), cur = 0;
    vector<int> deg(V), res(V);
    stack<int> stk;
    for (int i = 0; i < V; ++i)
        for (int v : graph[i])deg[v]++;
    for (int i = 0; i < V; ++i)if (deg[i] == 0)stk.push(i);
    while (!stk.empty()) {
        int v = stk.top(); stk.pop();
        res[cur++] = v;
        for (int w : graph[v])if (!--deg[w])stk.push(w);
    }
    return cur == V ? res : vector<int>();
}

class TarjanSCC {
public:
    TarjanSCC() {}
    TarjanSCC(const vector<vector<int> > &G)
        : V(int(G.size())), stamp(0), cnt(0), vis(V), id(V), low(V)
    {
        for (int i = 0; i<V; ++i) {
            if (!vis[i]) {
                dfs(G, i);
            }
        }
    }
    /*
    頂点uはどの強連結成分に属するか。
    0~count-1のいずれかを返す。
    */
    int get(int u) {
        return id[u];
    }
    /*
    頂点u, vは同じ強連結成分に属するか。
    */
    bool same(int u, int v) {
        return id[u] == id[v];
    }
    int count() {
        return cnt;
    }
private:
    int V, stamp, cnt;
    vector<bool> vis;
    vector<int> id, low;
    stack<int> st;
    void dfs(const vector<vector<int> > &G, int u) {
        vis[u] = true;
        low[u] = ++stamp;
        st.push(u);
        int lowest = low[u];
        for (const auto to : G[u]) {
            if (!vis[to]) {
                dfs(G, to);
            }
            lowest = min(lowest, low[to]);
        }
        if (lowest < low[u]) {
            low[u] = lowest;
            return;
        }
        int v;
        do {
            v = st.top();
            st.pop();
            id[v] = cnt;
            low[v] = INT_MAX;
        } while (u != v);
        cnt++;
    }
};

