        each(j, G[i]) {
            int v = scc.get(j);
            if (u != v)H[u].push_back(v);
            else nex[j] = i;
        }
    }

    vi vs = topologicalSort(H);
    reverse(all(vs));
    vi dp(N, -1);

    auto grundy = [&](int u) {
        set<int> S;
        each(v, G[u])S.insert(dp[v]);
        for (dp[u] = 0; S.count(dp[u]); ++dp[u]);
    };

    each(i, vs) {
        int u = rev[i];
        if (u == -1 || dp[u]!=-1)continue;
        if (nex[u]==-1) {
            grundy(u);
        } else {
            set<int> S, T;
            each(v, G[u]) 
                S.insert(dp[v]);
            for (int j = 0; sz(T) < 2; ++j)if (!S.count(j))T.insert(j);
            int ok = 0;
            each(x, T) {
                int v = nex[u];
                dp[u] = x;
                while (v != u) {
                    grundy(v);
                    v = nex[v];
                }
                grundy(u);
                if (dp[u] == x) {
                    ok = 1;
                    break;
                }
            }

            if (!ok) {
                cout << "IMPOSSIBLE" << endl;
                return 0;
            }
        }
    }

    cout << "POSSIBLE" << endl;
}

