struct edge{int x, y, next;}a[N];
int n, l, p[N], x, flag[N], cl, d[N], b[N], ss, f[N], mex[N], x1, x2;
vector<int>son[N];

inline void add(int x, int y){a[++l].x=x; a[l].y=y; a[l].next=p[x]; p[x]=l;}

inline void dfs_circle(int x){
	flag[x]=ss; d[++cl]=x;
	for(int i=p[x]; i; i=a[i].next){
		if(flag[a[i].y]&&flag[a[i].y]<ss)continue;
		if(!flag[a[i].y]){dfs_circle(a[i].y); continue;}
		l=0; int now=cl;
		while(d[now]!=a[i].y){b[++l]=d[now]; now--;}
		b[++l]=a[i].y;
	}
	cl--;
}

inline void dfs_mex(int x){
	son[x].clear();
	for(int i=p[x]; i; i=a[i].next){
		dfs_mex(a[i].y); son[x].push_back(a[i].y);
	}
	for(int i=0; i<=son[x].size(); i++)f[i]=0;
	for(int i=0; i<son[x].size(); i++)if(mex[son[x][i]]<=son[x].size())f[mex[son[x][i]]]=1;
	for(int i=0; i<=son[x].size(); i++)if(!f[i]){mex[x]=i; break;}
}

inline int check(int w){
	mex[b[1]]=w; int x, sum;
	for(int i=2; i<=l+1; i++){
		x=b[i]; sum=son[x].size()+1;
		for(int j=0; j<=sum; j++)f[j]=0;
		for(int j=p[x]; j; j=a[j].next)if(mex[a[j].y]<=sum)f[mex[a[j].y]]=1;
		for(int j=0; j<=sum; j++)if(!f[j]){mex[x]=j; break;}
	}
	return mex[b[1]]==w?1:0;
}

int main(){
	scanf("%d", &n);
	l=0; memset(p, 0, sizeof(p));
	for(int i=1; i<=n; i++){scanf("%d", &x); add(x, i);}
	memset(flag, 0, sizeof(flag)); ss=0;
	for(int i=1; i<=n; i++)if(!flag[i]){ss++; cl=0; dfs_circle(i);}
	b[l+1]=b[1];
	memset(flag, 0, sizeof(flag));
	for(int i=1; i<=l; i++)flag[b[i]]=1;
	for(int i=1; i<=l; i++){
		x=b[i]; son[x].clear();
