long long int func(int pos, int pre, int start){
	if(grundy[pos] != -1){
		return grundy[pos];
	}
	if(pos == start && pre != -1){
		return INF;
	}
	vector<long long int> ret;
	for(int i = 0; i < E[pos].size(); i++){
		long long int S = func(E[pos][i], pos, start);
		ret.push_back(S);
	}
	for(int i = 0; i < ret.size(); i++){
		if(ret[i] == INF){
			for(int j = 0; j < i; j++){
				flag[ret[j]] = false;
			}
			grundy[pos] = INF;
			return INF;
		}else{
			flag[ret[i]] = true;
		}
	}
	int val;
	for(int i = 0; i <= N; i++){
		if(!flag[i]){
			grundy[pos] = i;
			val = i;
			break;
		}
	}
	for(int i = 0; i < ret.size(); i++){
		flag[ret[i]] = false;
	}
	return val;
}

