    if(c[i]!=-1)return;
    c[i]=k;
    rdfs(p[i],k);
}
int grundy(vector<int>& vv){
    sort(all(vv));
    vv.erase(unique(all(vv)),vv.end());
    if(vv[0]>0){
        return 0;
    }
    for(int j=0;j<vv.size()-1;j++){
        if(vv[j+1]>vv[j]+1){
            return vv[j]+1;
        }
    }
    return vv.back()+1;
}
void dfs2(int i){
    if(G[i].size()==0){
        g[i]=0;
        return;
    }
    vector<int> vv;
    for(auto e:G[i]){
        dfs2(e);
        vv.push_back(g[e]);
    }
    g[i]=grundy(vv);
}
bool dfs3(int i,int k){
    if(i!=st){
        vector<int> vv;
        for(auto e:G[i]){
            vv.push_back(g[e]);
        }
        int gg=grundy(vv);
        if(p[i]==st){
            if(k==0){
                return gg>=t[1];
            }else{
                return gg==t[0];
            }
        }else{
            g[i]=gg;
        }
    }else{
        g[i]=t[k];
    }
    return dfs3(p[i],k);
}
