int mex(std::set<int>& set) {
	int pre = -1;
	for (auto& x : set) {
		if (pre + 1 != x) return pre + 1;
		pre = x;
	}
	return pre + 1;
}

std::vector<int> mex2(std::set<int>& set) {
	std::vector<int> res(2, -1);
	int pre = -1;
	for (auto& x : set) {
		if (pre + 1 != x) {
			if (res[0] == -1) {
				res[0] = pre + 1;
				++pre;
				continue;
			}
			else {
				res[1] = pre + 1;
				return res;
			}
		}
		pre = x;
	}
	if (res[0] == -1) {
		res[0] = pre + 1;
		++pre;
		res[1] = pre + 1;
	}
	else {
		res[1] = pre + 1;
	}
	return res;
}

signed main() {
	INIT;
	VAR(int, n);
	VEC(int, p, n);
	std::vector<std::vector<int>> g(n);
	REP(i, n) {
		--p[i];
		g[p[i]].emplace_back(i);
	}
	std::vector<bool> visited(n, false);
	std::vector<bool> used(n, false);
	std::function<bool(int)> dfs = [&](int v) {
		visited[v] = true;
		if (g[v].empty()) return used[v] = true;
		bool f = true;
		for (auto& to : g[v]) {
			if (visited[to]) {
				f &= used[to];
				continue;
			}
			f &= dfs(to);
		}
		return used[v] = f;
	};
	REP(i, n) dfs(i);
	std::vector<std::set<int>> G(n);
	std::function<int(int)> dfs2 = [&](int v) {
		if (g[v].empty()) return 0LL;
		for (auto& to : g[v]) {
			if (!used[to]) continue;
			G[v].insert(dfs2(to));
		}
		return mex(G[v]);
	};
	int pos;
	REP(i, n) {
		if (used[i]) continue;
		pos = i;
		dfs2(i);
	}
	std::vector<int> he(1, pos);
	int now = pos;
	while (true) {
		for (auto& to : g[now]) {
			if (used[to]) continue;
			he.emplace_back(to);
			break;
		}
		now = he.back();
		if (now == pos) {
			he.resize(he.size() - 1);
			break;
		}
	}
	std::reverse(ALL(he));
	auto v(mex2(G[he[0]]));
	REP(_, 2) {
		auto gg(G);
		gg[he[1]].insert(v[_]);
		FOR(i, 1, he.size() - 1) {
			gg[he[i + 1]].insert(mex(gg[he[i]]));
		}
		gg[he[0]].insert(mex(gg[he.back()]));
		int t = mex(gg[he[0]]);
		if (t == v[_]) {
			OUT("POSSIBLE")BR;
			return 0;
		}
	}
	OUT("IMPOSSIBLE")BR;
	return 0;
}

