void rebuild(int v) {
	fill(tmp, tmp + graph[v].size(), false);
	for (int u : graph[v]) 
		tmp[res[u]] = true;
	for (int i = 0; i < (int)graph[v].size(); i++)
		if (!tmp[i]) {
			res[v] = i;
			return;
		}
	res[v] = (int)graph[v].size();
}

