struct Graph {
    Graph(int n)
    {
        edge.resize(n);
    }
    void addEdge(int from, int to)
    {
        edge[from].push_back(to);
    }
    vector<vector<int>> edge;
};

int N;
pair<int, int> dfs(const Graph& g, int s, vector<pair<int, int>>& value, const vector<bool>& cycle)
{
    if (g.edge[s].empty()) {
        value[s] = make_pair(0, 1);
        return make_pair(0, 1);
    } else {
        set<int> st;
        for (const int p : g.edge[s]) {
            if (cycle[p]) {
                continue;
            }
            const int child = dfs(g, p, value, cycle).first;
            st.insert(child);
        }
        int first = -1;
        int second = -1;
        for (int i = 0; i <= N; i++) {
            if (st.find(i) == st.end()) {
                if (first == -1) {
                    first = i;
                } else if (second == -1) {
                    second = i;
                    break;
                }
            }
        }
        return make_pair(first, second);
    }
}

int main()
{
    cin >> N;
    Graph g(N);
    Graph rev(N);

    for (ll i = 0; i < N; i++) {
        int from;
        cin >> from;
        from--;
        g.addEdge(from, i);
        rev.addEdge(i, from);
    }

    int pos = 0;
    for (int i = 0; i < N; i++) {
        pos = rev.edge[pos][0];
    }
    vector<bool> cycle(N, false);
    vector<int> comp;
    for (int i = 0; i < N; i++) {
        if (cycle[pos]) {
            break;
        }
        comp.push_back(pos);
        cycle[pos] = true;
        pos = rev.edge[pos][0];
    }
    reverse(comp.begin(), comp.end());

    vector<pair<int, int>> pairs(N);
    const int size = comp.size();
    const auto pi = dfs(g, comp[0], pairs, cycle);
    int miss = 0;
    for (int d = 0; d < 2; d++) {
        int next = (d == 0) ? pi.first : pi.second;
        const int start = (d == 1) ? pi.first : pi.second;
        for (int i = 1; i < size; i++) {
            const int p = comp[i];
            const auto q = dfs(g, p, pairs, cycle);
            next = (q.first == next) ? q.second : (q.second == next) ? q.first : -1;
            if (next == -1) {
                miss++;
                continue;
            }
        }
        if (next != start) {
            miss++;
            continue;
        }
    }
    if (miss == 2) {
        cout << "IMPOSSIBLE" << endl;
    } else {
        cout << "POSSIBLE" << endl;
    }

    return 0;
}

