		}
	}
	cout << "POSSIBLE\n";
	return 0;
}

//題意の条件は「遷移先に含まれない最小の非負整数を書く」と言い換えらえる。木やDAGの場合は書き方が一意に定まる。
//なもりグラフの場合は、木を含むか・単なるループかによって書き方が異なる。単なるループの場合、ループ長の偶奇で判定できる。
//木を含む場合は、木の根を一つ取ってきて書く数aを決めると、書き方が一意に定まる。ここで書き方のルールを間違えると嵌るので注意。
//例えば、木の根rに直接つながる頂点に0,1,2,3,5,6,7,9,10が書かれているとき、rには4以上を書き込むのだが、5～7, 9～10は書き込めないことに注意する必要がある。
//グランディー数xの頂点が存在するためには、x*(x-1)/2辺以上が必要なので、制約より700以上の数はは絶対に書き込まないとしてよい。
//したがって、aに書き込む値を高々700通り試し、それぞれについてループ内の頂点に値を書き込み、矛盾判定をすればよい。
//実装は、グラフの辺の向きを逆にすると簡単。逆にする：i -> p_i

#include <iostream>
#include <queue>
#include <set>
#include <vector>
#define rep(i, n) for(i = 0; i < n; i++)
using namespace std;

int n;
int p[200000], inV[200000];
set<int> gset[200000];
int g[200000];
int g2[200000];
bool isTree[200000];
vector<int> et[200000];

bool check(int start, int val) {
	int i, j;
	rep(i, n) g2[i] = g[i];
	g2[start] = val;

	//ループ内の頂点について、grundy数を決める.	
	rep(i, n) gset[i].clear();
	int pos = start;
	while (true) {
		int npos = p[pos];
		if (npos == start) break;
		rep(i, et[npos].size()) gset[npos].insert(g2[et[npos][i]]);
		rep(i, n) if (gset[npos].find(i) == gset[npos].end()) break;
		g2[npos] = i;
		pos = npos;
	}

	//rep(i, n) cout << g2[i] << " ";
	//cout << endl;

	//矛盾判定(頂点startについてのみ、おこなえばよい)
	rep(i, et[start].size()) gset[start].insert(g2[et[start][i]]);
	rep(i, n) if (gset[start].find(i) == gset[start].end()) break;
	return i == val;
}

int main() {
	int i, j;
	queue<int> que;

	cin >> n;
	rep(i, n) { cin >> p[i]; p[i]--; inV[p[i]]++; }
	rep(i, n) { if (!inV[i]) que.push(i); }

	while (!que.empty()) {
		int v = que.front(); que.pop();
		rep(i, n) if (gset[v].find(i) == gset[v].end()) break;
		g[v] = i;
		gset[v].clear();
		gset[p[v]].insert(g[v]);
		inV[p[v]]--;
		if (!inV[p[v]]) que.push(p[v]);
	}

	rep(i, n) isTree[i] = (gset[i].size() > 0);
	rep(i, n) if (isTree[i]) break;
	if (i == n) { cout << ((n % 2) ? "IMPOSSIBLE" : "POSSIBLE") << endl; return 0; }

	rep(i, n) {
		if (!isTree[i]) continue;
		rep(j, n) if (gset[i].find(j) == gset[i].end()) break;
		g[i] = j;
	}

	rep(i, n) if (isTree[i]) break;
	int start = i, g0 = g[start];
	rep(i, n) et[p[i]].push_back(i);

	rep(i, 700) if (check(start, g0 + i)) { cout << "POSSIBLE" << endl; return 0; }
	cout << "IMPOSSIBLE" << endl;
	return 0;
}

