int dp[200009];
int dp2[200009];
int f[200009];
bool b[200009];
bool x[200009];

void dfs(int v) {
    for(int u : G[v])
        if(!x[u]) {
            dfs(u);
            b[dp[u]] = 1;
        }
    while(b[dp[v]])
        dp[v]++;
    if(x[v]) {
        dp2[v] = dp[v] + 1;
        while(b[dp2[v]])
            dp2[v]++;
    }
    for(int u : G[v])
        if(!x[u]) b[dp[u]] = 0;
}

int main() {
