        cin >> p[i];
        p[i]--;
        G[p[i]].push_back(i);
    }

    int s = 0;
    rep(i, n) s = p[s];
    rep(i, n) x[s = p[s]] = 1;

    rep(i, n) if(x[i]) dfs(i);

    f[s] = dp[s];
    int t = s;
    while(p[t] != s) {
        if(dp[p[t]] == f[t])
            f[p[t]] = dp2[p[t]];
        else
            f[p[t]] = dp[p[t]];
        t = p[t];
    }
    if(f[t] != f[s]) {
        cout << "POSSIBLE\n";
        return 0;
    }

    f[s] = dp2[s];
    t = s;
    while(p[t] != s) {
        if(dp[p[t]] == f[t])
            f[p[t]] = dp2[p[t]];
        else
            f[p[t]] = dp[p[t]];
        t = p[t];
    }
    if(f[t] == dp[s]) {
        cout << "POSSIBLE\n";
        return 0;
    }

    cout << "IMPOSSIBLE\n";

    return 0;
}

