void work ()
{
	// main work

	int kc = 0;
	lpi ( i, 1, n ){
		if ( !vis[i] ) findcir ( i, ++kc );

		if ( cir.size () ) break;
	}

	int size = cir.size () - 1;
	lpi ( i, 1, size ) inc[cir[i]] = true;

	lpi ( i, 1, n ) if ( la[i] == -1 ) m0[i] = true;
	lpi ( i, 1, n ){
		for ( int j = la[i]; ~j; j = edge[j].last ){
			if ( m0[edge[j].v] ){
				n0[i] = true;
				break;
			}
		}
	}
	lpi ( i, 1, n ){
		for ( int j = la[i]; ~j; j = edge[j].last ){
			if ( !n0[edge[j].v] && !inc[edge[j].v] ){
				c20[i] = true;
				break;
			}
		}
		for ( int j = la[i]; ~j; j = edge[j].last ){
			if ( !inc[edge[j].v] ){
				c21[i] = true;
				break;
			}
		}
	}

	pre[0][0] = pre[0][1] = true;
	lpi ( i, 1, size ){
		pre[i][0] = pre[i-1][0];
		pre[i][1] = pre[i-1][1];
		pre[i][i&1] &= !n0[cir[i]];
	}
	post[size+1][0] = post[size+1][1] = true;
	lpdi ( i, size, 1 ){
		post[i][0] = post[i+1][0];
		post[i][1] = post[i+1][1];
		post[i][i&1] &= !n0[cir[i]];
	}

	if ( size & 1 ){
		lpi ( i, 1, size ){
			if ( ( c20[cir[i]] && pre[i][~i&1] && post[i+1][i&1] ) || ( c21[cir[i]] && pre[i-1][i&1] && post[i][~i&1] ) ) YES ();
		}
		NO ();
	} else{
		if ( pre[size][0] || pre[size][1] ) YES ();
		else NO ();
	}
}



void findcir ( int now, int nc )
{
	if ( vis[now] == nc ){
		cir.push_back ( 0 );
		for ( int t = top; stk[t+1] ^ now; --t ){
			cir.push_back ( stk[t] );
		}
		return;
	} else if ( vis[now] ) return;

	vis[now] = true;
	stk[++top] = now;

	for ( int i = la[now]; ~i; i = edge[i].last ) findcir ( edge[i].v, nc );

	--top;
}

