const int nil = -2;
const int loop = -1;

int main() {
  int N;
  while (cin >> N) {
    vector<vector<int>> G(N);
    for (int i = 0; i < N; i++) {
      int p;
      cin >> p;
      --p;
      G[p].push_back(i);
    }
    vector<vector<int>> cand(N);
    vector<int> dp(N, nil);
    function<int(int)> dfs = [&](int v) {
      int &res = dp[v];
      if (res != nil) {
        return res;
      }
      res = loop;
      set<int> S;
      bool hasloop = false;
      for (int u : G[v]) {
        int g = dfs(u);
        if (g == loop) {
          hasloop = true;
        } else {
          S.insert(g);
        }
      }
      int g1 = 0;
      while (S.count(g1)) ++g1;
      int g2 = g1 + 1;
      while (S.count(g2)) ++g2;
      if (!hasloop) {
        return res = g1;
      }
      cand[v].push_back(g1);
      cand[v].push_back(g2);
      return res = loop;
    };
    int r = -1;
    for (int v = 0; v < N; v++) {
      dfs(v);
      if (!cand[v].empty()) {
        r = v;
      }
    }
    bool ans = true;
    if (r != -1) {
      ans = false;
      for (int x : cand[r]) {
        for (int u = 0; u < N; u++) {
          if (!cand[u].empty()) {
            dp[u] = nil;
          }
        }
        dp[r] = x;
        set<int> S;
        for (int u : G[r]) {
          S.insert(dfs(u));
        }
        int y = 0;
        while (S.count(y)) ++y;
        if (y == x) {
          ans = true;
          break;
        }
      }
    }
    cout << (ans ? "POSSIBLE" : "IMPOSSIBLE") << endl;
  }
  return 0;
}

