int mex(std::set<int>& set) {
	int pre = -1;
	for (auto& x : set) {
		if (pre + 1 != x) return pre + 1;
		pre = x;
	}
	return pre + 1;
}

std::vector<int> mex2(std::set<int>& set) {
	std::vector<int> res(2, -1);
	int pre = -1;
	for (auto& x : set) {
		if (pre + 1 != x) {
			if (res[0] == -1) {
				res[0] = pre + 1;
				++pre;
				continue;
			}
			else {
				res[1] = pre + 1;
				return res;
			}
			pre = x;
		}
	}
	if (res[0] == -1) {
		res[0] = pre + 1;
		++pre;
		res[1] = pre + 1;
	}
	else {
		res[1] = pre + 1;
	}
	return res;
}

