	std::vector<bool> used(n, false);
	std::function<bool(int)> dfs = [&](int v) {
		visited[v] = true;
		if (g[v].empty()) return used[v] = true;
		bool f = true;
		for (auto& to : g[v]) {
			if (visited[to]) {
				f &= used[to];
				continue;
			}
			f &= dfs(to);
		}
		return used[v] = f;
	};
	REP(i, n) dfs(i);
	std::vector<std::set<int>> G(n);
	std::function<int(int)> dfs2 = [&](int v) {
		if (g[v].empty()) return 0LL;
		for (auto& to : g[v]) {
			if (!used[to]) continue;
			G[v].insert(dfs2(to));
		}
		return mex(G[v]);
	};
	int pos;
