	pre[p[u]].push_back(la[u]);
	if(!--d[p[u]] && !vis[p[u]])
		dfs(p[u]);
}

bool check() {
	for(int i = 1; i <= n; ++i)
	if(la[i] == la[p[i]])
		return false;
	for(int i = 1; i <= n; ++i)
	if(la[i] != mex(pre[i]))
		return false;
	return true;
}

int main() {
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i) {
		scanf("%d", p + i);
		++d[p[i]];
	}
	for(int i = 1; i <= n; ++i)
	if(!d[i] && !vis[i])
		dfs(i);
	memcpy(fd, d, sizeof(fd));
	memcpy(fv, vis, sizeof(fv));
	memcpy(fa, la, sizeof(fa));
	for(int i = 1; i <= n; ++i)
		fp[i] = pre[i];
	int u;
	for(u = 1; u <= n; ++u)
	if(!vis[u])
		break;
	dfs(p[u]);
	if(check()) {
		puts("POSSIBLE");
		return 0;
	} else {
		memcpy(d, fd, sizeof(fd));
		memcpy(vis, fv, sizeof(fv));
		memcpy(la, fa, sizeof(fa));
		for(int i = 1; i <= n; ++i)
			pre[i] = fp[i];
		int l = mex(pre[p[u]]);
		pre[p[u]].push_back(l);
		dfs(p[u]);
		if(la[u] == l && check()) {
			puts("POSSIBLE");
			return 0;
		}
	}
	puts("IMPOSSIBLE");
	return 0;
}

