int mex(int n) {
	vector<int>v;
	for (auto nxt : G[n]) {
		if (fix[nxt])v.push_back(X[nxt]);
	}
	VSORT(v);
	v.erase(unique(all(v)), v.end());
	v.push_back(INF);
	REP(i, v.size()) {
		if (i != v[i])return i;
	}
}

int mex(vector<int>v) {
	VSORT(v);
	v.erase(unique(all(v)), v.end());
	v.push_back(INF);
	REP(i, v.size()) {
		if (i != v[i])return i;
	}
}

bool dfs(int s, int sx, int pre, int n, int prex) {
	if (n == s && pre != s) {
		vector<int>v;
		v.push_back(sx);
		for (auto nxt : G[par[n]]) {
			if (fix[nxt])v.push_back(X[nxt]);
		}
		return mex(v) == prex;
	}
	vector<int>v;
	bool found = false;
	v.push_back(prex);
	for (auto nxt : G[n]) {
		if (nxt == s) {
			found = true;
			v.push_back(sx);
		}
		if (fix[nxt])v.push_back(X[nxt]);
	}

	int m = mex(v);
	//m
	v.clear();
	v.push_back(m);
	for (auto nxt : G[par[n]]) {
		if (fix[nxt])v.push_back(X[nxt]);
	}
	if (mex(v) == prex) {
		for (auto nxt : G[n]) {
			if (!fix[nxt]) {
				if (dfs(s, sx,n, nxt, m))return true;
			}
		}
	}
	//m+1
	v.clear();
	v.push_back(m + 1);
	for (auto nxt : G[par[n]]) {
		if (fix[nxt])v.push_back(X[nxt]);
	}
	if (mex(v) == prex) {
		for (auto nxt : G[n]) {
			if (!fix[nxt]) {
				if (dfs(s, sx, n, nxt, m + 1))return true;
			}
		}
	}
	return false;
}

void solve() {
	int N; cin >> N;
	REP(i, N) {
		int u; cin >> u;
		u--;
		G[u].push_back(i);
		par[i] = u;
		deg[u]++;
	}
	REP(i, N) {
		if (deg[i] == 0) {
			bool flag = 0;
			int nxt = i;
			while (deg[nxt] <= 1) {
				int pos = nxt;
				fix[pos] = true;
				X[pos] = flag;
				flag = ~flag;
				nxt = par[pos];
			}
		}
	}
	bool ok = false;
	REP(i, N) {
		if (!fix[i]) {
			vector<int>v;
			for (auto nxt : G[i]) {
				if (fix[nxt])v.push_back(X[nxt]);
			}
			int m = mex(v);
			for (auto nxt : G[i]) {
				if (!fix[nxt]) {
					if (dfs(i, m,i, nxt, m) || dfs(i, m + 1,i, nxt, m + 1))ok = true;
				}
			}
			break;
		}
	}
	if (ok)print("POSSIBLE");
	else print("IMPOSSIBLE");
}



