void get_cycle(vector<int>&ans,const vector<vector<int>>&edges, vector<int>&used,const int color,const int now) {
	if (used[now]==color) {
		ans = vector<int>(1, now);
		return;
	}
	else if(used[now]==-1){
		used[now] = color;
		for (auto e : edges[now]) {
			get_cycle(ans, edges, used, color, e);
			if (!ans.empty()) {
				ans.emplace_back(now);
				return;
			}
		}
	}
}

vector<int> get_num(const int now,const vector<vector<int>>&edges,const int not_go,bool flag) {
	if (edges[now].empty()) {
		return vector<int>(1,0);
	}
	else {
		set<int>tos;
		for (auto e : edges[now]) {
			if (e == not_go) {
				continue;
			}
			else {
				tos.emplace(get_num(e, edges, not_go,false)[0]);
			}
		}
		if (flag) {
			vector<int>kouhos;
			for (int i = 0; i < 1000000; ++i) {
				if (tos.find(i) == tos.end()) {
					kouhos.push_back(i);
					if (kouhos.size() == 2)return kouhos;
				}
			}
		}
		else {
			for (int i = 0; i < 1000000; ++i) {
				if (tos.find(i) == tos.end()) {
					return vector<int>(1,i);
				}
			}
		}
	}
}

bool check(vector<vector<int>>&kouhos) {
	bool ok = false;
	for (int l = 0; l < 2; ++l) {
		int now = kouhos[0][l];
		for (int i = 1; i < kouhos.size(); ++i) {
			if (kouhos[i][0] == now) {
				now = kouhos[i][1];
			}
			else {
				now = kouhos[i][0];
			}
		}
		if (l == 0) {
			if (now != kouhos[0][0])ok = true;
		}
		else {
			if (now == kouhos[0][0])ok = true;
		}
	}
	return ok;
}

