    nxt[eid]=nbs[u]; dst[eid]=v; rev[eid]=0; nbs[u]=eid++;
    nxt[eid]=nbs[v]; dst[eid]=u; rev[eid]=1; nbs[v]=eid++;
    cov[u]++;
}

void flush(){
    lef=rig=0;
    for(int i=0; i<n; i++){
        if(cov[i]==0){
            que[rig++]=i;
        }
    }
    for(; lef<rig; lef++){
        int u=que[lef];
        chest.clear();
        for(int i=nbs[u]; ~i; i=nxt[i]){
            if(rev[i]==1)continue;
            int v=dst[i];
            assert(~act[v]);
            chest.insert(act[v]);
        }
        for(act[u]=0; chest.count(act[u]); )act[u]++;
        //fprintf(stderr, "act[%d]=%d\n", u, act[u]);
        for(int i=nbs[u]; ~i; i=nxt[i]){
            if(rev[i]==0)continue;
            int v=dst[i];
            cov[v]--;
            if(cov[v]==0){
                que[rig++]=v;
            }
        }
    }
}

int flush(const int pot, const int val){
    sgn[pot]=val;
    //fprintf(stderr, "*sgn[%d]=%d\n", pot, sgn[pot]);
    for(int i=0; i<n; i++)red[i]=0;
    lef=rig=0;
    for(int i=nbs[pot]; ~i; i=nxt[i]){
        if(rev[i]==0)continue;
        int v=dst[i];
        red[v]++;
        if(cov[v]==red[v]){
            que[rig++]=v;
        }
    }
    for(; lef<rig; lef++){
        int u=que[lef];
        chest.clear();
        for(int i=nbs[u]; ~i; i=nxt[i]){
            if(rev[i]==1)continue;
            int v=dst[i];
            if(!~act[v]){
                assert(~sgn[v]);
                chest.insert(sgn[v]);
                //fprintf(stderr, "chest + sgn[%d]=%d\n", v, sgn[v]);
            }else{
                chest.insert(act[v]);
                //fprintf(stderr, "chest + act[%d]=%d\n", v, act[v]);
            }
        }
        for(sgn[u]=0; chest.count(sgn[u]); )sgn[u]++;
        //fprintf(stderr, "sgn[%d]=%d (chest.size=%d)\n", u, sgn[u], SIZE(chest));
        if(u==pot){
            return sgn[u]!=val?1:0;
        }
        for(int i=nbs[u]; ~i; i=nxt[i]){
            if(rev[i]==0)continue;
            int v=dst[i];
            red[v]++;
            if(cov[v]==red[v]){
                que[rig++]=v;
            }
        }
    }
    return 0;
}

int main(){
    while(scanf("%d", &n)!=EOF){
        for(int i=0; i<n; i++)nbs[i]=-1;
        eid=0;
        for(int i=0; i<n; i++)cov[i]=0;
        for(int i=0; i<n; i++){
            int u, v=i;
            scanf("%d", &u);
            u--;
            add_edge(u, v);
        }
        for(int i=0; i<n; i++)act[i]=-1;
        flush();
        int pot=-1;
        for(int i=0; i<n; i++){
            if(!~act[i]){
                pot=i;
                break;
            }
        }
        if(~pot){
            chest.clear();
            for(int i=nbs[pot]; ~i; i=nxt[i]){
                if(rev[i]==1)continue;
                int v=dst[i];
                if(!~act[v])continue;
                chest.insert(act[v]);
            }
            int x, y;
            for(x=0; chest.count(x); )x++;
            for(y=x+1; chest.count(y); )y++;
            if(!flush(pot, x)){
                printf("POSSIBLE\n");
            }else{
                if(!flush(pot, y)){
                    printf("POSSIBLE\n");
                }else{
                    printf("IMPOSSIBLE\n");
                }
            }
        }else{
            printf("POSSIBLE\n");
        }
    }
    return 0;
}

