bool f(graph g, int val, int idx, vector<int> a, vector<int> d, vector<int> p){
  a[idx] = val;
  int cur = p[idx];
  while(a[cur] == -1){
    set<int> vec;
    rep(i, g[cur].size()){
      int nxt = g[cur][i];
      if(a[nxt] == -1) continue;
      vec.insert(a[nxt]);
    }
    if(a[p[cur]] != -1) vec.insert(a[p[cur]]);
    int num = -1;
    rep(i, 100){
      if(vec.find(i) == vec.end()){
        num = i;
        break;
      }
    }

    a[cur] = num;
    cur = p[cur];
  }

  rep(i, a.size()) cerr << a[i] << " ";
  cerr << endl;

  // validation

  rep(i, a.size()){
    set<int> st;
    cerr << i << " " << a[i] << endl;
    rep(j, g[i].size()){
      st.insert(a[g[i][j]]);
      cerr << g[i][j] << " ";
    }
    cerr << endl;
    rep(x, a[i]){
      if(st.find(x) == st.end()){
        return false;
      }
    }
  }
  return true; 
}


int main(){

  int n; cin >> n;
  graph g(n);
  vector<int> d(n, 0);
  queue<int> que;
  vector<int> p(n);
  rep(i, n){
    int in; cin >> in;
    in--;
    p[i] = in;
    g[p[i]].push_back(i);
    d[p[i]]++;
  }

  vector<int> a(n, -1);

  rep(i, n){
    if(d[i] == 0) que.push(i);
  }

  while(!que.empty()){
    int cur = que.front();
    que.pop();
    d[p[cur]]--;
    if(d[p[cur]] == 0) que.push(p[cur]);
    // 隣接頂点をなめる
    set<int> vec;
    rep(i, g[cur].size()){
      int nxt = g[cur][i];
      if(a[nxt] == -1){
        continue;
      }
      vec.insert(a[nxt]);
    }
    if(a[p[cur]] != -1) vec.insert(a[p[cur]]);
    rep(i, 100){
      if(vec.find(i) == vec.end()){
        a[cur] = i;
        break;
      }
    }
  }


  int idx = 0;
  rep(i, n){
    if(a[i] == -1){
      idx = i;
      break;
    }
  }

  set<int> st;
  rep(i, g[idx].size()){
    int nxt = g[idx][i];
    if(a[nxt] == -1) continue;
    st.insert(a[nxt]);
  }
  if(a[p[idx]] != -1) st.insert(a[p[idx]]);
  int val = -1;
  rep(i, 100){
    if(st.find(i) == st.end()){
      val = i;
      break;
    }
  }

  rep(i, a.size()) cerr << a[i] << " ";
  cerr << endl;

  // val pr val + 1
  if(f(g, val, idx, a, d, p) or f(g, val + 1, idx, a, d, p)) POSSIBLE();
  else IMPOSSIBLE();

  return 0;
}

