#include <bits/stdc++.h>

using namespace std;
using int64 = long long;

constexpr int DEBUG = 0;

struct Edge {
  const int from, to;
  Edge(int from, int to) : from(from), to(to) {}
};

// Vector
template<typename T> ostream& operator<<(ostream& s, const vector<T>& v) {
  int len = v.size();
  s << "[";
	for (int i = 0; i < len; i++) {
    if (i > 0) s << ", ";
		s << v[i];
  }
  s << "]";
  return s;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;

  vector<int> ps(n);
  vector<vector<Edge>> graph(n);
  vector<int> out_ds(n);
  for (int i = 0; i < n; i++) {
    int p;
    cin >> p;
    p--;
    ps[i] = p;
    graph[p].push_back(Edge(p, i));
    out_ds[p]++;
  }

  auto grundy_fn = [](const vector<vector<Edge>>& graph, const vector<int>& gs, int v) -> int {
    set<int> s;
    for (const auto& e : graph[v]) {
      s.insert(gs[e.to]);
    }
    int c = 0;
    while (true) {
      if (s.find(c) == s.end()) return c;
      c++;
    }
  };

  vector<int> gs(n, -1);
  deque<int> q;
  for (int v = 0; v < n; v++) {
    if (out_ds[v] == 0) {
      q.push_back(v);
    }
  }
  while (!q.empty()) {
    int v = q.front();
    q.pop_front();
    gs[v] = grundy_fn(graph, gs, v);
    out_ds[ps[v]]--;
    if (out_ds[ps[v]] == 0) {
      q.push_back(ps[v]);
    }
  }

  vector<int> cycle;
  for (int v = 0; v < n; v++) {
    if (out_ds[v] > 0) {
      cycle.push_back(v);
      int u = ps[v];
      while (true) {
        cycle.push_back(u);
        u = ps[u];
        if (u == v) break;
      }
      break;
    }
  }
  reverse(cycle.begin(), cycle.end());

  if (cycle.empty()) {
    cerr << "Unexpected: No cycle!" << endl;
    exit(1);
  }

  if (DEBUG) cout << "cycle: " << cycle << endl;

  int v1 = cycle[cycle.size() - 1];
  vector<int> g1s;
  {
    set<int> s;
    for (const auto& e : graph[v1]) {
      s.insert(gs[e.to]);
    }
    int c = 0;
    while (true) {
      if (s.find(c) == s.end()) {
        g1s.push_back(c);
        if (g1s.size() == 2) break;
      }
      c++;
    }
  }

  bool ans = false;
  for (int g1 : g1s) {
    vector<int> hs(gs.begin(), gs.end());
    hs[v1] = g1;
    for (int i = cycle.size() - 2; i >= 0; i--) {
      hs[cycle[i]] = grundy_fn(graph, hs, cycle[i]);
    }
    if (grundy_fn(graph, hs, v1) == hs[v1]) {
      if (DEBUG) {
        cout << "v1: " << v1 << " hs[v1]: " << hs[v1] << " grundy: " << grundy_fn(graph, hs, v1) << endl;
      }
      ans = true;
    }
  }

  cout << (ans ? "POSSIBLE" : "IMPOSSIBLE") << endl;
}

