        return 0;
    }
    auto saved = sg;
    for (int j = 0; j < 1; ++j) {
        {
            sg = saved;
            int x = cycle[j];
            for (int i = 0; i < cycle.size(); ++i) {
                int r = prv[x];
                for (int k : g[r]) used[sg[k]] = 1;
                sg[r] = 0;
                while (used[sg[r]]) sg[r]++;
                for (int k : g[r]) used[sg[k]] = 0;
                x = r;
