            if (Check()) {
                // printf("upd = %d\n", cycle[j]);
                puts("POSSIBLE");
                return 0;
            }
        }
        {
            sg = saved;
            sg[cycle[j]] = upd[cycle[j]];
            int x = cycle[j];
            for (int i = 0; i < cycle.size(); ++i) {
