		if (vis2[x] != y) continue;
		for (int y : G[x]) {
			if (odp[y] == odp[x] + 1) return true;
		}
	}
	return false;
}

bool algos(int n, int y) {
	int x = y;
	vis2[x] = x;
	int MIN = odp[x];
	int gdzie = x;
	while(vis2[skad[x]] == 0) {
		x = skad[x];
		vis2[x] = y;
		MIN = min(MIN, odp[x]);
		if (odp[x] == MIN) gdzie = x;
	}
// 	printf("algos\n");
// 	printf("x -- %d %d\n", x, odp[x]);
	x = gdzie;
	cyc[x] = true;
	int ile = 0;
	while(odp[skad[x]] == odp[x]) {
// 		printf("cyc %d\n", x);
		ile ++;
		if (cyc[skad[x]]) {
			if (ile == 1) return true;
			if (ile % 2 == 1) {
				return nieparz(n, y);
			}
			return true;
		}
		x = skad[x];
		cyc[x] = true;
	}
	while(cyc[skad[x]] == 0) {
		x = skad[x];
		cyc[x] = true;
	}
	return true;
}

