        ch[p[i]].pb(i);
    }
    F(i,n) assign(i, i);
    //F(i,n) cout<<ass[i]<<" \n"[i==n-1];
    int start=-1;
    F(i,n) if (ass[i]==-1) {
        start = i;
        break;
    }
    V<int> cy;
    cy.pb(start);
    int cur=p[start];
    while (cur != start) {
        cy.pb(cur);
        cur = p[cur];
    }
    //for (int u : cy) P(u);
    //P("");
    V<int> chstart;
    for (int v : ch[start]) if (ass[v] != -1)
        chstart.pb(ass[v]);
    int sse = se(chstart);
    if (!(test(cy, sse) || test(cy, sse+1)))
        cout<<"IM";
    P("POSSIBLE");
}

