using namespace std;

#define pb push_back
#define mp make_pair
#define N 400050
int outd[N];
vector<int> va[N],vb[N];
set<pair<int,int> > st;

int q[N];
int vis[N];
int ans[N],tmp[N];
int tim[N],ttp;
int rr[N],nxt[N],pls[N];
int main()
{
	int n;scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		int p2;scanf("%d",&p2);
		outd[p2]++;
		va[i].pb(p2);
		vb[p2].pb(i);
	}
	for(int i=1;i<=n;i++)
		ans[i]=-1;

	int l,r,p;l=1,r=0;
	for(int i=1;i<=n;i++)
		if(!outd[i]) q[++r]=i;
	if(r==0)
	{
		if(n&1) puts("IMPOSSIBLE");
		else puts("POSSIBLE");
		return 0;
	}
	while(l<=r)
	{
		p=q[l++];vis[p]=1;++ttp;
		for(int i=0;i<vb[p].size();i++)
		{
			int pt=ans[vb[p][i]];
			if(pt==-1) continue;
			if(tim[pt]<ttp) tim[pt]=ttp;
		}
		ans[p]=0;
		for(int i=0;tim[i]==ttp;i++)
			ans[p]++;
		for(int i=0;i<va[p].size();i++)
		{
			int pt=va[p][i];
			if(--outd[pt]==0)
				q[++r]=pt;
		}
	}

	int rnd=0,fst=0;
	for(int i=1;i<=n;i++)
		if(!vis[i])
		{
			if(fst==0) fst=i;
			++ttp;++rnd;
			for(int j=0;j<vb[i].size();j++)
			{
				int pt=ans[vb[i][j]];
				if(pt==-1){nxt[i]=vb[i][j];continue;}
				if(tim[pt]<ttp) tim[pt]=ttp;
			}
			for(int j=0;tim[j]==ttp;j++)
				tmp[i]++;
		}
	for(int i=1;i<=n;i++)
		if(!vis[i]) ans[i]=tmp[i];
	rr[1]=fst;
	for(int i=nxt[fst],j=2;i!=fst;i=nxt[i],j++)
		rr[j]=i;
	rr[0]=rr[rnd];

	int res;
	while(1)
	{
		int ifok=1,iffail=0;
		for(int i=rnd;i>=1;i--)
		{
			if(!pls[rr[i-1]] && ans[rr[i-1]]==ans[rr[i]])
			{
				ifok=0;
				ans[rr[i-1]]++;
				pls[rr[i-1]]=1;
				if(st.find(mp(rr[i-1],ans[rr[i-1]]))!=st.end())
					iffail=1;
				else st.insert(mp(rr[i-1],ans[rr[i-1]]));
			}
			if(pls[rr[i-1]] && ans[rr[i-1]]!=ans[rr[i]]+1)
			{
				ifok=0;
				ans[rr[i-1]]--;
				pls[rr[i-1]]=0;
				if(st.find(mp(rr[i-1],ans[rr[i-1]]))!=st.end())
					iffail=1;
				else st.insert(mp(rr[i-1],ans[rr[i-1]]));
			}

		}
		if(iffail || ifok) {res=ifok? 1:0;break;}
	}
	res? puts("POSSIBLE"): puts("IMPOSSIBLE");
}

