int n;
vector<int> graph[200000];
int decided[200000];
int cdecided[200000];
int visited[200000];
int searched[200000];
int circle[200000];
int asign[200000];

int loop(int p){
    if(searched[p] == 1){
        circle[p] = 1;
        return p;
    }
    visited[p] = 1;
    searched[p] = 1;
    int f = -1;
    for(int i = 0;i < graph[p].size();i++){
        int r = loop(graph[p][i]);
        if(r != -1 && r != p){
            f = r;
        }
    }
    searched[p] = 0;
    if(f > -1){
        circle[p] = 1;
        return f;
    }
    return -1;
}

void decide(int p){
    vector<int> t(graph[p].size()+1,0);
    for(int i = 0;i < graph[p].size();i++){
        if(decided[graph[p][i]] == -1) decide(graph[p][i]);
        if(decided[graph[p][i]] < t.size())
            t[decided[graph[p][i]]] = 1;
    }
    for(int i = 0;i < t.size();i++){
        if(t[i] == 0){
            decided[p] = i;
            break;
        }
    }
}

int main(){
    cin >> n;
    for(int i = 0;i < n;i++){
        int p;
        cin >> p;
        p--;
        graph[p].push_back(i);
    }
    for(int i = 0;i < n;i++){
        if(visited[i] == 0){
            loop(i);
        }
    }
    memset(decided,-1,sizeof(decided));
    memset(visited,0,sizeof(visited));
    int c,b;
    for(int i = 0;i < n;i++){
        if(circle[i] == 1){
            c = i;
            for(int j = 0;j < graph[i].size();j++){
                if(circle[graph[i][j]] == 0){
                    decide(graph[i][j]);
                    asign[decided[graph[i][j]]] = 1;
                } else {
                    b = graph[i][j];
                }
            }
            break;
        }
    }
    int small,big;
    for(int i = 0;i < n;i++){
        if(asign[i] == 0){
            small = i;
            for(int j = i+1;j < n;j++){
                if(asign[j] == 0){
                    big = j;
                    break;
                }
            }
            break;
        }
    }
    for(int i = 0;i < n;i++) cdecided[i] = decided[i];
    decided[c] = small;
    for(int i = 0;i < n;i++){
        if(decided[i] == -1) decide(i);
    }
    if(decided[b] != small){
        cout << "POSIBLE" << endl;
        return 0;
    }
    for(int i = 0;i < n;i++) decided[i] = cdecided[i];
    decided[c] = big;
    for(int i = 0;i < n;i++){
        if(decided[i] == -1) decide(i);
    }
    if(decided[b] == small){
        cout << "POSIBLE" << endl;
        return 0;
    }for(int i = 0;i < n;i++) cout << decided[i] << endl;
    cout << "IMPOSIBLE" << endl;
    return 0;
}

