void dfs(const int x,const int fa)
{
	int yn=d[x];
	for(int k=fir[x],y=a[k].y;k;k=a[k].nex,y=a[k].y) if(y!=fa&&!inc[y])
		++yn,dfs(y,x);
	for(int i=0;i<=yn+10;i++) v[i]=false;
	for(int k=fir[x],y=a[k].y;k;k=a[k].nex,y=a[k].y) if(y!=fa&&!inc[y])
