	}
}
int c[maxn],dir;
bool judge()
{
	if(dir)
	{
		for(int i=2;i<=cn;i++) c[cir[i]]=-1;
		for(int i=2;i<=cn;i++)
		{
			int x=cir[i];
			for(int j=0;j<=d[x]+10;j++) v[j]=false;
			for(int k=fir[x],y=a[k].y;k;k=a[k].nex,y=a[k].y) v[c[y]]=true;
			if(!v[s[x]]) c[x]=s[x];
			else c[x]=s2[x];
		}
		if(c[cir[1]]==c[cir[cn]]) return false;
		return true;
	}
	else
	{
		for(int i=2;i<=cn;i++) c[cir[i]]=-1;
		for(int i=cn;i>=2;i--)
		{
			int x=cir[i];
			for(int j=0;j<=d[x]+10;j++) v[j]=false;
			for(int k=fir[x],y=a[k].y;k;k=a[k].nex,y=a[k].y) v[c[y]]=true;
			if(!v[s[x]]) c[x]=s[x];
			else c[x]=s2[x];
		}
		if(c[cir[1]]==c[cir[2]]) return false;
		return true;
	}
}

