	for(int i=1;i<=n;i++)
	{
		int x; scanf("%d",&x); 
		d[x]++; ins(x,i);
	}
	for(int i=1;i<=n&&!cn;i++) if(!dfn[i]) tarjan(i);
	for(int k=fir[cir[1]],y=a[k].y;k;k=a[k].nex,y=a[k].y) if(y==cir[cn]) dir=1;
	for(int i=1;i<=cn;i++) inc[cir[i]]=true;

	for(int i=1;i<=cn;i++)
	{
		dfs(cir[i],0);
		for(int j=s[i]+1;;j++) if(!v[j])
		{
			s2[cir[i]]=j; break;
		}
	}
	for(int i=1;i<=n;i++) c[i]=s[i];
	c[cir[1]]=s[cir[1]];
	if(judge()) { puts("POSSIBLE");return 0; }
	c[cir[1]]=s2[cir[1]];
	if(judge()) { puts("POSSIBLE");return 0; }

	puts("IMPOSSIBLE");

	return 0;
}

