#define N 1000006
#define rint register int
using namespace std;

int tot = 0, fir[N], nxt[N << 1], to[N << 1];

inline void addEdge(int u, int v) {
    nxt[++tot] = fir[u], fir[u] = tot, to[tot] = v;
}

int n, vis[N], nx[N], inc[N], cntc, cir[N], val[N], use[N];

inline void dfs(int u) {
    if (vis[u]) return ;
    if (nx[u]) {
        inc[u] = 1, cir[++cntc] = u;
        for (rint i = nx[u]; i != u; i = nx[i])
            inc[i] = 1, cir[++cntc] = i;
        return ;
    }
    for (rint i = fir[u]; i; i = nxt[i])
        nx[u] = to[i], dfs(nx[u]);
    nx[u] = 0;
    vis[u] = 1;
}

void getmex(int u) {
    for (rint i = fir[u], v; i; i = nxt[i]) {
        v = to[i];
        if (inc[v]) continue;
        getmex(v);
        use[val[v]] = 1;
    }
    while (use[val[u]]) ++val[u];
    for (rint i = fir[u]; i; i = nxt[i])
        if (!inc[to[i]]) use[val[to[i]]] = 0;
}

int main() {
    cin >> n;
    for (rint i = 1, u; i <= n; ++i)
        scanf("%d", &u), addEdge(u, i);
    for (rint i = 1; i <= n; ++i) dfs(i);
    for (rint i = 1; i <= cntc; ++i) getmex(cir[i]);
    bool check = 1;
    for (rint i = 1; i < cntc; ++i)
        if (val[cir[i]] != val[cir[i + 1]]) check = 0;
    if (check && cntc % 2) puts("IMPOSSIBLE");
    else puts("POSSIBLE");
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

int mex(set<int> x)
{
    int r = 0;
    while(x.count(r))
        r++;
    return r;
}

const int maxn = 3e5;
vector<int> G[maxn], Gt[maxn];

void add_edge(int u, int z1, int v, int z2)
{
    int U = 2 * u + z1 + 1;
    int V = 2 * v + z2 + 1;
    G[U].push_back(V);
    Gt[V].push_back(U);
}

int used[maxn];

void dfs(int v, vector<int> *G, vector<int> &st)
{
    if(used[v])
        return;
    used[v] = 1;
    for(auto u: G[v])
        dfs(u, G, st);
    st.push_back(v);
}

void try2sat()
{
    vector<int> top_sort;
    dfs(0, G, top_sort);
    reverse(begin(top_sort), end(top_sort));
    memset(used, 0, sizeof(used));
    for(auto v: top_sort)
    {
        if(used[v])
            continue;
        vector<int> comp;
        dfs(v, Gt, comp);
        set<int> lol;
        for(auto u: comp)
        {
            lol.insert(u);
            if(lol.count(u ^ 1))
            {
                cout << "IMPOSSIBLE\n";
                exit(0);
            }
        }
    }
    cout << "POSSIBLE\n";
}

signed main()
{
    //freopen("input.txt", "r", stdin);
    ios::sync_with_stdio(0);
    cin.tie(0);
    int n;
    cin >> n;
    int p[n], cnt[n] = {0};
    set<pair<int, int>> vrt;
    for(int i = 0; i < n; i++)
    {
        cin >> p[i];
        p[i]--;
        vrt.erase({cnt[p[i]], p[i]});
        cnt[p[i]]++;
        vrt.insert({cnt[p[i]], p[i]});
    }
    set<int> banned[n];
    while(begin(vrt)->first == 0)
    {
        int v = begin(vrt)->second;
        vrt.erase(begin(vrt));
        vrt.erase({cnt[p[v]], p[v]});
        cnt[p[v]]--;
        vrt.insert({cnt[p[v]], p[v]});
        banned[p[v]].insert(mex(banned[v]));
    }
    int m[n][2];
    for(auto it: vrt)
    {
        int v = it.second;
        m[v][0] = mex(banned[v]);
        banned[v].insert(m[v][0]);
        m[v][1] = mex(banned[v]);
    }
    for(auto it: vrt)
    {
        int v = it.second;
        int u = p[v];
        for(int z1 = 0; z1 <= 1; z1++)
            for(int z2 = 0; z2 <= 1; z2++)
                if(m[u][z1] == m[v][z2])
                {
                    add_edge(u, z1, v, !z2);
                    add_edge(v, z2, u, !z1);
                }
        if(m[u][0] == m[v][0])
        {
            add_edge(u, 1, v, 0);
        }
        else if(m[u][0] == m[v][1])
        {
            add_edge(u, 1, v, 1);
        }
        else
        {
            add_edge(u, 1, u, 0);
        }
    }
    try2sat();
}

