bool cycle(int x, int y){
	int i = p[x];
	int pre = y;
	while(i!=x){
		set<int> s;
		s.insert(pre);
		for(int j=0;j<G[i].size();j++){
			s.insert(a[G[i][j]]);
		}
		int z = 0;
