			z++;
		}
		a[i] = z;
		pre = a[i];
		i = p[i];
	}
	set<int> st;
	st.insert(pre);
	for(int j=0;j<G[x].size();j++){
		st.insert(a[G[x][j]]);
	}
	int z = 0;
	while(st.count(z)){
		z++;
	}
	return y==z;
}

