        fr[{pr, i}] = pr;
        fr[{i, pr}] = pr;
        gr[pr].push_back(i);
        gr[i].push_back(pr);
    }

    cycle(0);

    for (int i = 0; i < n; i++) used[i] = 0;

    for (int i = 0; i < way.size(); i++) used[way[i]] = 1;

    for (int i = 0; i < way.size(); i++) {
        ll v = way[i];

        find(v);
    }

    for (int i = 0; i < n; i++) used[i] = 0;

    for (int i = 0; i < way.size(); i++) {
        ll v = way[i], u = way[(i + 1) % way.size()];
        if (c[v] == c[u] && !used[v] && !used[u]) {
            ll hr = fr[{v, u}];
            c[hr]++;
            used[v] = 1;
            used[u] = 1;
        }
    }

    for (int i = 0; i < n; i++) c2[i] = c[i];

    for (auto cur : way) s.insert(cur);

    for (int i = 0; i < 2; i++) {
        bool flag2 = true;

        ll v = way[0];

        for (int i = 0; i < n; i++) c[i] = c2[i];
        c[v] += i;

        if (fr[{way[0], way[1]}] == way[0]) {
            for (int j = 1; j < way.size(); j++) {
                ll v = way[j], pr = way[j - 1];
                if (c[pr] == c[v]) c[pr]++;
            }
            if (c[way.back()] != c[v] -1) flag2 = false;
        } else {
            for (int j = way.size() - 1; j > 0; j--) {
                ll v= way[j], pr = way[(j + 1) % n];
                if (c[v] == c[pr]) c[pr]++;
            }
            if (c[way[1]] != c[v] - 1) flag2 = false;
        }

        for (int i = 0; i < n; i++) {
            for (auto to : gr[i]) {
                if (c[i] == c[to]) flag2 = false;
            }
        }

        if (flag2) {
            cout << "POSSIBLE";
            return 0;
        } 
    }


    cout << "IMPOSSIBLE";


    return 0;    
}

