const int Size=1<<16;
char buffer[Size],*head,*tail;
inline char Getchar() {
    if(head==tail) {
        int l=fread(buffer,1,Size,stdin);
        tail=(head=buffer)+l;
    }
    if(head==tail) return -1;
    return *head++;
}
inline int read() {
    int x=0,f=1;char c=Getchar();
    for(;!isdigit(c);c=Getchar()) if(c=='-') f=-1;
    for(;isdigit(c);c=Getchar()) x=x*10+c-'0';
    return x*f;
}
typedef long long ll;
const int maxn=200010;
vector<int>G[maxn];
int n,p[maxn],vis[maxn],A[maxn],B[maxn],in[maxn],first[maxn],nxt[maxn],to[maxn],e;
void AddEdge(int u,int v) {G[v].push_back(u);in[v]++;to[++e]=v;nxt[e]=first[u];first[u]=e;}
int Q[maxn],S[maxn];
int work(int x) {
	memset(S,0,sizeof(S));
	int y=x;
	do {
		y=p[y];
		if(B[y]>=0) break;
		rep(i,0,G[y].size()-1) S[B[G[y][i]]]++;
		B[y]=0;while(S[B[y]]) B[y]++;
		rep(i,0,G[y].size()-1) S[B[G[y][i]]]--;
	}while(y!=x);
	rep(x,1,n) {
		rep(i,0,G[x].size()-1) S[B[G[x][i]]]++;
		rep(i,0,B[x]-1) if(!S[i]) return 0;
		if(S[B[x]]) return 0;
		rep(i,0,G[x].size()-1) S[B[G[x][i]]]--;
	}
//	rep(i,1,n) printf("%d%c",B[i],i==n?'\n':' ');
	return 1;
}
int solve() {
	memset(A,-1,sizeof(A));
	int l=1,r=0;
	rep(i,1,n) if(!in[i]) Q[++r]=i,A[i]=0;
	while(l<=r) {
		int x=Q[l++];vis[x]=1;
		for(int i=first[x];i;i=nxt[i]) if(!(--in[to[i]])) Q[++r]=to[i];
		rep(i,0,G[x].size()-1) S[A[G[x][i]]]++;
		A[x]=0;while(S[A[x]]) A[x]++;
		rep(i,0,G[x].size()-1) S[A[G[x][i]]]--;
	}
	rep(i,1,n) if(!vis[i]) {
		rep(j,0,G[i].size()-1) S[A[G[i][j]]]++;
		int v=0;while(S[v]) v++;
		int v2=v+1;while(S[v2]) v2++;
		rep(j,0,G[i].size()-1) S[A[G[i][j]]]--;
		rep(j,1,n) B[j]=A[j];
		B[i]=v;if(work(i)) return 1;
		rep(j,1,n) B[j]=A[j];
		B[i]=v2;if(work(i)) return 1;
		return 0;
	}
}
int main() {
	n=read();
	rep(i,1,n) AddEdge(i,p[i]=read());
	puts(solve()?"POSSIBLE":"IMPOSSIBLE");
	return 0;
}

