const int N=200005;

std:: stack <int> stack;
std:: vector <int> vec;

struct edge {int x,y,next;} e[N*2];

int used[N],dep[N],ls[N],p[N],f[N],d,wjp,edCnt=1;

bool vis[N],in[N];

int read() {
	int x=0,v=1; char ch=getchar();
	for (;ch<'0'||ch>'9';v=(ch=='-')?(-1):v,ch=getchar());
	for (;ch<='9'&&ch>='0';x=x*10+ch-'0',ch=getchar());
	return x*v;
}

void add_edge(int x,int y) {
	e[++edCnt]=(edge) {x,y,ls[x]}; ls[x]=edCnt;
}

void dfs1(int x) {
	stack.push(x);
	for (int i=ls[x];i;i=e[i].next) {
		if (!vis[e[i].y]) {
			vis[e[i].y]=1;
			dep[e[i].y]=dep[x]+1;
			dfs1(e[i].y);
		} else {
			int y=0;
			while (y!=e[i].y) {
				y=stack.top(),stack.pop();
				vec.push_back(y);
				in[y]=1;
			}
		}
	}
}

void dfs2(int x,int from) {
	for (int i=ls[x];i;i=e[i].next) {
		if (!in[e[i].y]&&e[i].y!=from) dfs2(e[i].y,x);
	}
	++wjp;
	for (int i=ls[x];i;i=e[i].next) {
		if (!in[e[i].y]&&e[i].y!=from) {
			used[f[e[i].y]]=wjp;
		}
	}
	for (f[x]=0;used[f[x]]==wjp;) f[x]++;
}

int main(void) {
	int n=read(),rec=-1;
	rep(i,1,n) p[i]=read();
	rep(i,1,n) add_edge(i,p[i]);
	dep[1]=vis[1]=1;
	dfs1(1);
	rep(i,1,n) add_edge(p[i],i);
	bool flag=false;
	for (int x:vec) {
		dfs2(x,0);
		if (rec==-1) rec=f[x];
		else if (rec!=f[x]) flag=true;
	}
	if ((vec.size()&1)&&(!flag)) puts("IMPOSSIBLE");
	else puts("POSSIBLE");
	return 0;
}

