signed main() {
	INIT;

	VAR(int, n);
	VEC(int, p, n);

	std::vector<std::vector<int>> g(n), g2(n);
	std::vector<int> in(n, 0), in2(n, 0);
	REP(i, n) {
		--p[i];
		g[p[i]].emplace_back(i);
		g2[i].emplace_back(p[i]);
		++in[i];
		++in2[p[i]];
	}

	std::vector<int> ord(n, -1);
	int LIM;
	{
		std::queue<int> que;
		REP(i, n) if (in[i] == 0) que.push(i);
		int p = 0;
		while (!que.empty()) {
			int now = que.front(); que.pop();
			ord[now] = p++;
			for (int to : g[now]) {
				if (--in[to] == 0) {
					que.push(to);
				}
			}
		}
		if (p == n) {
			OUT("POSSIBLE")BR;
			return 0;
		}
		LIM = p;
	}
	{
		std::queue<int> que;
		REP(i, n) if (in2[i] == 0) que.push(i);
		int p = n - 1;
		while (!que.empty()) {
			int now = que.front(); que.pop();
			ord[now] = p--;
			for (int to : g2[now]) {
				if (--in2[to] == 0) {
					que.push(to);
				}
			}
		}
	}

	std::set<int> cycle;
	REP(i, n) if (ord[i] == -1) cycle.insert(i);

	if (cycle.size() % 2 == 0) {
		OUT("POSSIBLE")BR;
		return 0;
	}

	std::vector<int> grundy(n, -1);
	std::vector<int> v;
	REP(i, n) if (ord[i] > LIM) v.emplace_back(i);
	std::sort(ALL(v), [&](int l, int r) { return ord[l] > ord[r]; });

	auto getGrundy = [&](int x) {
		int res = 0;
		std::set<int> set;
		for (auto& to : g[x]) set.insert(grundy[to]);
		while (set.count(res)) ++res;
		return res;
	};

	REP(i, v.size()) {
		int now = v[i];
		grundy[now] = getGrundy(now);
	}

	int base = *cycle.begin();
	{
		grundy[base] = getGrundy(base);
		int now = base;
		while (true) {
			for (auto& to : g2[now]) {
				if (cycle.count(to)) {
					now = to;
					break;
				}
			}
			if (now == base) break;
			grundy[now] = getGrundy(now);
		}
		if (grundy[base] == getGrundy(base)) {
			OUT("POSSIBLE")BR;
			return 0;
		}
	}
	for (auto& x : cycle) grundy[x] = -1;
	/////////////////////////////////////////////////////////////////////////

	{
		grundy[base] = getGrundy(base);
		int baseto = -1;
		for (auto& to : g[base]) {
			if (cycle.count(to)) {
				baseto = to;
				break;
			}
		}
		grundy[baseto] = grundy[base];
		grundy[base] = getGrundy(base);

		int now = base;
		while (true) {
			for (auto& to : g2[now]) {
				if (cycle.count(to)) {
					now = to;
					break;
				}
			}
			if (now == baseto) break;
			grundy[now] = getGrundy(now);
		}
		if (grundy[baseto] == getGrundy(baseto)) {
			OUT("POSSIBLE")BR;
			return 0;
		}
	}
	OUT("IMPOSSIBLE")BR;
	return 0;
}

