const int maxn=2e5;
int n,tot,cnt;
int pre[maxn+8],now[maxn+8],son[maxn+8];
bool vis[maxn+8],cir[maxn+8],inq[maxn+8];
int v[maxn+8],tmp[maxn+8];

int read()
{
    int x=0,f=1;char ch=getchar();
    for (;ch<'0'||ch>'9';ch=getchar()) if (ch=='-') f=-1;
    for (;ch>='0'&&ch<='9';ch=getchar()) x=x*10+ch-'0';
    return x*f;
}

void add(int u,int v)
{
    pre[++tot]=now[u];
    now[u]=tot;
    son[tot]=v;
}

bool dfs(int x)
{
    vis[x]=1;
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    cir[x]|=vis[child];
	    if (!vis[child]) cir[x]|=dfs(child);
	}
    return cir[x];
}
void get(int x)
{
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    if (cir[child]) continue;
	    get(child);
	}
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    if (cir[child]) continue;
	    inq[v[child]]=1;
	}
    while(inq[v[x]]) v[x]++;
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    if (cir[child]) continue;
	    inq[v[child]]=0;
	}
}	    

int main()
{
    n=read();
    for (int i=1;i<=n;i++)
	{
	    int x=read();
	    add(x,i);
	}
    for (int i=1;i<=n;i++)
	if (!vis[i]) dfs(i);
    for (int i=1;i<=n;i++) if (cir[i]) get(i),tmp[++cnt]=v[i];
    if (cnt&1)
	{
	    if (cnt==n) {puts("IMPOSSIBLE");return 0;}
	    for (int i=2;i<=cnt;i++)
		if (tmp[i]!=tmp[i-1])
		    {
			puts("POSSIBLE");
			return 0;
		    }
	    puts("IMPOSSIBLE");
	}
    else puts("POSSIBLE");
	    return 0;
}

