void dfs(int x){
	int y;
	for (y=fst[x]; y; y=nxt[y]) if (!bo[y]) dfs(y);
	for (y=fst[x]; y; y=nxt[y]) if (!bo[y]) tg[f[y]]=x;
	for (y=0; tg[y]==x; y++);
	f[x]=y;
	for (y++; tg[y]==x; y++);
	g[x]=y;
}
