	for(int i = 1; i <= n; ++i)
	{
		fa[i] = read<int>();
		adj[fa[i]].push_back(i);
	}
}

int cir[MAXN + 5], len = 0, is_cir[MAXN + 5];

inline void find_cir()
{
	static int vis[MAXN + 5];

	int p = 1;
	for(; !vis[p]; p = fa[p]) vis[p] = 1;
	for(; vis[p] != 2; p = fa[p]) is_cir[p] = 1, vis[cir[++len] = p] = 2;
}

int a[MAXN + 5], a0[MAXN + 5];

inline void dfs(int u)
{
	for(auto v : adj[u]) if(!is_cir[v]) dfs(v);

	static int bkt[MAXN + 5];

	for(auto v : adj[u]) if(!is_cir[v]) ++bkt[a[v]];
	for(int i = 0; i <= n; ++i) if(bkt[i] == 0) { a[u] = i; break; }
	for(int i = a[u] + 1; i <= n; ++i) if(bkt[i] == 0) { a0[u] = i; break; }
	for(auto v : adj[u]) if(!is_cir[v]) --bkt[a[v]];
}

inline void solve()
{
	find_cir();

	for(int i = 1; i <= len; ++i) dfs(cir[i]);

	static int b[MAXN + 5];

	b[1] = a[cir[1]];
	for(int i = 2; i <= len; ++i) b[i] = b[i - 1] == a[cir[i]] ? a0[cir[i]] : a[cir[i]];

	int fg = 1;
	for(int i = 1; i <= len; ++i) if(b[i % len + 1] == b[i]) { fg = 0; break; }
	if(fg) { puts("POSSIBLE"); return; }

	b[1] = a0[cir[1]];
	for(int i = 2; i <= len; ++i) b[i] = b[i - 1] == a[cir[i]] ? a0[cir[i]] : a[cir[i]];

	fg = b[len] == a[cir[1]];
	if(fg) for(int i = 1; i <= len; ++i) if(b[i % len + 1] == b[i]) { fg = 0; break; }
	if(fg) { puts("POSSIBLE"); return; }

	puts("IMPOSSIBLE");
}

