            if(!isloop[u])
                grundy[v].insert(dfs_grundy(u));

    for(int v:loop){
        int res=-1;
        while(grundyP[v].size()<2){
            if(grundy[v].count(++res)==0)
                grundyP[v].push_back(res);
        }
    }

    int root=loop[0];
    fill_n(used,N,0);
    if(dfs_solve(root,-1)!=grundyP[root][0]){
        cout<<"POSSIBLE"<<endl;
    }else{
