vector<vector<int>> g;
vector<int> a;
vector<int> b;
vector<int> used;
vector<int> circle;
bool dfs(int v) {
    used[v] = true;
    bool circ = false;
    set<int> grandi;
    for (int to : g[v]) {
        if (used[to]) {
            circ = true;
        }
        else {
            bool res = dfs(to);
            circ |= res;
            if (!res) {
                grandi.insert(a[to]);
            }
        }
    } 
    a[v] = 0;
    while (grandi.find(a[v]) != grandi.end()) {
        a[v]++;
    }
    b[v] = a[v] + 1;
    while (grandi.find(b[v]) != grandi.end()) {
        b[v]++;
    }
    if(circ) {
        circle.push_back(v);
    }
    return circ;
}


int main() {
    int N;
    cin >> N;
    g.resize(N);
    a.resize(N);
    b.resize(N);
    used.resize(N, 0);
    for (int i = 0; i < N; ++i) {
        int v;
        cin >> v;
        --v;
        g[v].push_back(i);
    }
    for (int i = 0; i < N; ++i) {
        if (!used[i]) {
            dfs(i);
        }
    }
    reverse(circle.begin(), circle.end());
    int v = a[circle[0]];
    for (int i = 1; i < circle.size(); ++i) {
        if (a[circle[i]] == v) {
            v = b[circle[i]];
        }
        else {
            v = a[circle[i]];
        }
    }
    if (v != a[circle[0]]) {
        cout << "POSSIBLE" << endl;
        exit(0);
    }
    v = b[circle[0]];
    for (int i = 1; i < circle.size(); ++i) {
        if (a[circle[i]] == v) {
            v = b[circle[i]];
        }
        else {
            v = a[circle[i]];
        }
    }
    if (v == a[circle[0]]) {
        cout << "POSSIBLE" << endl;
        exit(0);
    }
    cout << "IMPOSSIBLE" << endl;
}

