int main() {
    int n; scanf("%d", &n);
    vector<int> p(n), dg(n);
    vector<vector<int>> g(n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &p[i]);
        p[i]--;
        dg[p[i]]++;
        g[p[i]].push_back(i);
    }
    queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (dg[i] == 0) q.push(i); 
    }
    vector<int> used(n + n), sg(n);
    while (!q.empty()) {
        int x = q.front(); q.pop();
        for (int u : g[x]) used[sg[u]] = 1;
        while (used[sg[x]]) sg[x]++;
        for (int u : g[x]) used[sg[u]] = 0;
        if (--dg[p[x]] == 0) q.push(p[x]);
    }
    vector<int> nxt(n, -1), prv(n, -1), upd(n, -1);
    vector<int> cycle;
    for (int i = 0; i < n; ++i) {
        if (dg[i] != 0) {
            for (int u : g[i]) if (dg[u] == 0) used[sg[u]] = 1;
            while (used[sg[i]]) sg[i]++;
            upd[i] = sg[i] + 1;
            while (used[upd[i]]) ++upd[i];
            for (int u : g[i]) if (dg[u] == 0) used[sg[u]] = 0;
            for (int u : g[i]) if (dg[u] > 0) { 
                nxt[i] = u;
                prv[u] = i;
            }
            cycle.push_back(i);
        }
    }
    bool ok = true;
    for (int u : cycle) ok &= sg[u] != sg[nxt[u]];
    if (ok) {
        puts("POSSIBLE");
        return 0;
    }
    sg[cycle[0]] = upd[cycle[0]];
    int x = cycle[0];
    for (int i = 0; i < cycle.size(); ++i) {
        int r = prv[x];
        for (int k : g[r]) used[sg[k]] = 1;
        sg[r] = 0;
        while (used[sg[r]]) sg[r]++;
        for (int k : g[r]) used[sg[k]] = 0;
        x = r;
    }
    ok = sg[cycle[0]] == upd[cycle[0]];
    for (int v : cycle) ok &= sg[v] != sg[nxt[v]];
    if (ok) puts("POSSIBLE");
    else puts("IMPOSSIBLE");
}

