int grundy(int u)
{
    set<int> s;
    for (int v : g[u])
        s.insert(grundy(v));
    int res = 0;
    while (s.count(res))
        res++;
    return res;
}

void solve(int u)
{
    set<int> s;
    for (int v : g[u])
        if (!circle[v])
            s.insert(grundy(v));
    int res = 0;
    while (s.count(res))
        res++;
    var[u][0] = res;
    res++;
    while (s.count(res))
        res++;
    var[u][1] = res;
}

bool check(int u, int x)
{
    int v = u, val = x;
    while (true)
    {
        int w = to[v];
        if (var[w][0] != val)
            val = var[w][0];
        else
            val = var[w][1];
        v = w;
        if (v == u)
            break;
    }
    return (val == x);
}

