	for(int i = 0; i + 1 < tmp.size(); ++i){
		int x = tmp[i], y = tmp[i + 1];
		bool ok = false;
		for(int v = x + 1; v < y; ++v){
			bool flg = upd(cand1, cand2, v);
			if(flg){
				ok = flg;
				break;
			}
		}
		if(ok) break;
	}
	if(flg){
		vals[root] = cand1;
	}else{
		vals[root] = cand2;
	}
	int v = prv[root];
	while(v != root){
		vector<int> tmp;
		for(int i = 0; i < G[v].size(); ++i){
			tmp.push_back(vals[G[v][i]]);
		}
