using namespace std;

template <typename C>
int mex(C const & xs) {
    int y = 0;
    for (int x : xs) { // xs must be sorted (duplication is permitted)
        if (y <  x) break;
        if (y == x) ++ y;
    }
    return y;
}

vector<int> func(vector<int> a, int n, vector<vector<int> > const & g, vector<vector<int> > const & h) {
    vector<int> outdegree(n);
    queue<int> que;
    repeat (i, n) {
        outdegree[i] = g[i].size();
        for (int j : g[i]) {
            if (a[j] != -1) {
                outdegree[i] -= 1;
            }
        }
        if (outdegree[i] == 0 and a[i] == -1) {
            que.push(i);
        }
    }
    while (not que.empty()) {
        int i = que.front(); que.pop();
        assert (outdegree[i] == 0);
        assert (a[i] == -1);
        set<int> gs;
        for (int j : g[i]) {
            assert (a[j] != -1);
            gs.insert(a[j]);
        }
        a[i] = mex(gs);
        for (int j : h[i]) {
            assert (outdegree[j] != 0);
            outdegree[j] -= 1;
            if (outdegree[j] == 0 and a[i] == -1) {
                que.push(j);
            }
        }
    }
    return a;
}

int mex_node(int i, vector<int> const & a, int n, vector<vector<int> > const & g) {
    set<int> gs;
    for (int j : g[i]) {
        if (a[j] != -1) {
            gs.insert(a[j]);
        }
    }
    return mex(gs);
}

