        now.push_back(test_Grundy[to][index]);
    }
    sort(now.begin(), now.end());
    now.erase(unique(now.begin(), now.end()), now.end());
    for(int i = 0; i < now.size(); i++){
        if(now[i] != i) {
            test_Grundy[from][index] = i;
            break;
        }
    }
    test_visited[from][index] = true;
    test_bfs(parent[from], index);
    return;
}

