    used[v] = true;
    bool circ = false;
    set<int> grandi;
    for (int to : g[v]) {
        if (used[to]) {
            circ = true;
        }
        else {
            bool res = dfs(to);
            if (!res) {
                grandi.insert(a[to]);
            }
            else {
                circ = true;
            }
        }
    } 
    a[v] = 0;
    while (grandi.find(a[v]) != grandi.end()) {
        a[v]++;
    }
    b[v] = a[v] + 1;
    while (grandi.find(b[v]) != grandi.end()) {
        b[v]++;
    }
    if(circ) {
        circle.push_back(v);
    }
    return circ;
}


