using namespace std;

const int MAXN = 200005;

int n, naso;
int par[MAXN], bio[MAXN], cik[MAXN], mex[MAXN], val[MAXN], c[MAXN];
vector <int> v[MAXN];

void dfs (int x) {
    bio[x] = 1;
    for (auto sus : v[x]) {
        if (bio[sus] == 1) {
            if (!naso) naso = x;
        } else if (bio[sus] == 0) dfs(sus);
    }
    bio[x] = 2;
}

int calc (int x) {
    if (val[x] != -1) return val[x];
    for (int i=0; i<=v[x].size(); i++) mex[i] = 0;
    for (auto sus : v[x]) {
        if (cik[sus]) continue;
        mex[calc(sus)] = 1;
    }
    for (int i=0; i<=v[x].size(); i++) {
        if (mex[i] == 0) {
            val[x] = i;
            return i;
        }
    }
}

int f (int x) {
    for (int i=0; i<=v[x].size(); i++) mex[i] = 0;
    for (auto sus : v[x]) {
        mex[c[sus]] = 1;
    }
    for (int i=0; i<=v[x].size(); i++) if (mex[i] == 0) return i;
}

bool ok () {
    for (int i=1; i<=n; i++) {
        if (f(i) != c[i]) return 0;
    }
    return 1;
}

bool probaj (int x, int br) {
    for (int i=1; i<=n; i++) {
        c[i] = val[i];
    }
    c[x] = br;
	int curr = x;
	while (1) {
        if (curr != x) c[curr] = f(curr);
        curr = par[curr];
        if (curr == x) break;
	}
	return ok();
}

int main () {
    memset(val, -1, sizeof val);
	cin >> n;
	for (int i=1; i<=n; i++) {
		cin >> par[i];
		v[par[i]].push_back(i);
	}
	for (int i=1; i<=n; i++) {
        if (bio[i] == 0 && naso == 0) dfs(i);
	}
	int curr = naso;
	while (1) {
        cik[curr] = 1;
        curr = par[curr];
        if (curr == naso) break;
	}
	for (int i=1; i<=n; i++) {
        calc(i);
	}
	if (probaj(naso, val[par[naso]])) {
        cout << "POSSIBLE";
	} else if (probaj(par[naso], val[par[naso]])) {
        cout << "POSSIBLE";
	} else {
        cout << "IMPOSSIBLE";
	}
	return 0;
}

