namespace scc_space
{
	void dfs(int v_, vector<bool>&used_, vector<int>G_[], vector<int>&vs_)
	{
		used_[v_] = true;
		for (int nxt : G_[v_])
		{
			if (!used_[nxt])dfs(nxt, used_, G_, vs_);
		}
		vs_.push_back(v_);
	}

	void rdfs(int v_, int k_, vector<bool>&used_, vector<vector<int>>&rG_, vector<int>&top)
	{
		used_[v_] = true;
		top[v_] = k_;
		for (int nxt : rG_[v_])
		{
			if (!used_[nxt])rdfs(nxt, k_, used_, rG_, top);
		}
	}
}

//頂点数n_のグラフG_の強連結成分分解をする
//topに強連結成分のトポロジカル順序が格納される
//(top[i]==top[j]のとき、iとjは強連結である。)
//戻り値:強連結成分の個数
int scc(vector<int>G_[], int n_, vector<int>&top)
{
	using namespace scc_space;
	top.resize(n_);
	vector<vector<int>>rG_(n_);
	for (int i = 0; i < n_; ++i)
	{
		for (int to : G_[i])
		{
			rG_[to].push_back(i);
		}
	}
	vector<bool>used(n_, false);
	vector<int>vs;
	for (int v = 0; v < n_; ++v)
	{
		if (!used[v])dfs(v, used, G_, vs);
	}
	fill(used.begin(), used.end(), false);
	int k = 0;
	for (int i = vs.size() - 1; i >= 0; --i)
	{
		if (!used[vs[i]])rdfs(vs[i], k++, used, rG_, top);
	}
	return k;
}

vector<int>path[234567 * 6];//mod 6ごとに0,1,2,非0,非1,非2

vector<int>graph[234567];
int invgr[234567];
int N;

bool firstpath[234567];
int f(int v)
{
	if (firstpath[v])return v;
	firstpath[v] = true;
	return f(invgr[v]);
}

int br(int v)
{
	if (graph[v].size() == 0)return 0;
	assert(graph[v].size() == 1);
	return 1 + br(graph[v][0]);
}

int main(void)
{
	cin >> N;
	for (int i = 0; i < N; ++i)
	{
		int p;
		cin >> p;
		--p;
		graph[p].push_back(i);
		invgr[i] = p;
	}
	int v = f(0);
	vector<int>cycle;
	cycle.push_back(v);
	int now = v;
	for (;;)
	{
		now = invgr[now];
		if (now == cycle.front())break;
		cycle.push_back(now);
	}
	int period = cycle.size();
	//cycle.push_back(cycle.front());
	for (int i = 0; i < period; ++i)
	{
		//cycle[i] <- cycle[i+1]
		int S = i;
		int T = (i + 1) % period;
		int lef = cycle[S];
		int now = cycle[T];
		if (graph[now].size() == 1)
		{
			//0->1
			//1->0
			//2->0
			path[S * 6 + 0].push_back(T * 6 + 0 + 3);
			path[S * 6 + 0].push_back(T * 6 + 1 + 0);
			path[S * 6 + 0].push_back(T * 6 + 2 + 3);
			path[S * 6 + 1].push_back(T * 6 + 0 + 0);
			path[S * 6 + 1].push_back(T * 6 + 1 + 3);
			path[S * 6 + 1].push_back(T * 6 + 2 + 3);
			path[S * 6 + 2].push_back(T * 6 + 0 + 0);
			path[S * 6 + 2].push_back(T * 6 + 1 + 3);
			path[S * 6 + 2].push_back(T * 6 + 2 + 3);
		}
		else
		{
			//assert(graph[now].size() == 2);
			int down = -1;
			if (graph[now][0] != lef)
			{
				down = graph[now][0];
			}
			else if (graph[now][1] != lef)
			{
				down = graph[now][1];
			}
			else assert(false); 
			int dnum = br(down) % 2;
			if (dnum == 0)
			{
				//0->1
				//1->2
				//2->1
				path[S * 6 + 0].push_back(T * 6 + 0 + 3);
				path[S * 6 + 0].push_back(T * 6 + 1 + 0);
				path[S * 6 + 0].push_back(T * 6 + 2 + 3);
				path[S * 6 + 1].push_back(T * 6 + 0 + 3);
				path[S * 6 + 1].push_back(T * 6 + 1 + 3);
				path[S * 6 + 1].push_back(T * 6 + 2 + 0);
				path[S * 6 + 2].push_back(T * 6 + 0 + 3);
				path[S * 6 + 2].push_back(T * 6 + 1 + 0);
				path[S * 6 + 2].push_back(T * 6 + 2 + 3);
			}
			else
			{
				//0->2
				//1->0
				//2->0
				path[S * 6 + 0].push_back(T * 6 + 0 + 3);
				path[S * 6 + 0].push_back(T * 6 + 1 + 3);
				path[S * 6 + 0].push_back(T * 6 + 2 + 0);
				path[S * 6 + 1].push_back(T * 6 + 0 + 0);
				path[S * 6 + 1].push_back(T * 6 + 1 + 3);
				path[S * 6 + 1].push_back(T * 6 + 2 + 3);
				path[S * 6 + 2].push_back(T * 6 + 0 + 0);
				path[S * 6 + 2].push_back(T * 6 + 1 + 3);
				path[S * 6 + 2].push_back(T * 6 + 2 + 3);
			}
		}
	}
	vector<int>top;
	scc(path, period * 6, top);
	for (int i = 0; i < period; ++i)
	{
		for (int d = 0; d < 3; ++d)
		{
			if (top[i * 6 + d] == top[i * 6 + d + 3])
			{
				//i = 非i
				cout << "IMPOSSIBLE\n";
				return 0;
			}
			if (top[i * 6 + d] == top[i * 6 + (d + 1) % 3])
			{
				//i = (i+1)
				cout << "IMPOSSIBLE\n";
				return 0;
			}
		}
		int not0 = top[i * 6 + 3];
		int not1 = top[i * 6 + 4];
		int not2 = top[i * 6 + 5];
		if (not0 == not1 && not1 == not2)
		{
			cout << "IMPOSSIBLE\n";
			return 0;
		}
	}
	cout << "POSSIBLE\n";
	return 0;
}

