    for(int i = 1;i <= n;i++){
        if(cycle[i] == 0){
            start = i;
        }
    }
    memset(vis, 0, sizeof(vis));
    vector<int> candidate;
    for(auto v : G[start]){
        vis[sg[v]] = true; 
    }
    for(int i = 0;i < maxn;i++){
        if(!vis[i]){
            candidate.push_back(i);
        } 
        if(candidate.size() == 2){
            break;
        }
    } 
    for(auto x : candidate){
        memset(vis, 0, sizeof(vis));
        sg[start] = x;
        int now = p[start];
        while(now != start){
            for(auto v : G[now]){
                vis[sg[v]] = true;
