int mex(vector<int>v) {
	VSORT(v);
	v.erase(unique(all(v)), v.end());
	//print_space(v);
	v.push_back(INF);
	REP(i, v.size()) {
		if (i != v[i]) {
			//DEBUG(i);
			return i;
		}
	}
	//return 1;
}


bool dfs(int s, int sx, int pre, int n, int prex) {
	if (n == s && pre != s) {
		vector<int>v;
		v.push_back(prex);
		for (auto nxt : G[n]) {
			if (fix[nxt])v.push_back(X[nxt]);
		}
		int m = mex(v);
		if (m == sx && m != prex)return true;
		else return false;
	}
	vector<int>v;
	v.push_back(prex);
	for (auto nxt : G[n]) {
		if (fix[nxt])v.push_back(X[nxt]);
	}
	int m = mex(v);
	return dfs(s, sx, n, par[n], m);
}

void solve() {
	int N; cin >> N;
	REP(i, N) {
		int u; cin >> u;
		u--;
		G[u].push_back(i);
		par[i] = u;
		deg[u]++;
	}
	queue<int>que;
	REP(i, N) {
		if (deg[i] == 0) {
			que.push(i);
		}
	}
	while (!que.empty()) {
		int pos = que.front(); que.pop();
		vector<int>v;
		for (auto nxt : G[pos]) {
			if (fix[nxt])v.push_back(X[nxt]);
		}
		fix[pos] = true;
		X[pos] = mex(v);
		deg[par[pos]]--;
		if (deg[par[pos]] == 0)que.push(par[pos]);
	}
	bool ok = false;
	REP(i, N) {
		if (!fix[i]) {
			vector<int>v;
			for (auto nxt : G[i]) {
				if (fix[nxt])v.push_back(X[nxt]);
			}
			int m = mex(v);
			if (dfs(i, m, i, par[i], m) || dfs(i, m + 1, i, par[i], m + 1))ok = true;
			break;
		}
	}
	if (ok)print("POSSIBLE");
	else print("IMPOSSIBLE");
}



