void Dfs (int x) {
	vis[x] = is[x] = 1;
	for (auto v : V[x]) {
		if (vis[v]) { if (is[v]) in[h[t = 1] = o = v] = 1; } else Dfs(v);
		if (o) break;
	}
	if (o) {
