	for (auto v : V[x]) if (!in[v]) Dfs2(v);
	++cnt; for (auto v : V[x]) if (!in[v]) la[f[v]] = cnt;
	while (la[f[x]] == cnt) ++f[x];
	if (in[x]) { f2[x] = f[x] + 1; while (la[f2[x]] == cnt) ++f2[x]; }
}

