static const double EPS = 1e-14;
static const long long INF = 1e18;
static const long long mo = 1e9+7;
#define ldout fixed << setprecision(40) 

vvll g, gr;

vll order;
ll order_counter = 0;
void scc_for(ll v) {
    if (order[v] >= 0) return;
    order[v] = INF;
    for (auto u : g[v]) {
        scc_for(u);
    }
    order[v] = order_counter++;
}
vvll scc_set;
vector<bool> flag;
void scc_rev(ll i, ll v) {
    if (flag[v]) return;
    flag[v] = 1;
    scc_set[i].pb(v);
    for (auto u : gr[v]) {
        scc_rev(i, u);
    }
}
vvll getSCC(void) {
    ll n = g.size();

    order.resize(n, -1);
    order_counter = 0;
    scc_set.clear();
    flag.resize(n);

    rep(v, g.size()) {
        scc_for(v);
    }
    vll order_rev(n);
    rep(i, n) {
        order_rev[n-1-order[i]] = i;
    }
    rep(i, g.size()) {
        ll v = order_rev[i];
        if (!flag[v]) {
            scc_set.pb({});
            scc_rev(scc_set.size()-1, v);
        }
    }
    return scc_set;
}
unordered_set<ll> cycle;
vll grundy;
ll grundy_dfs(ll v) {
    if (cycle.count(v)) {
        return -1;
    }
    if (grundy[v] >= 0) {
        return grundy[v];
    }
    if (g[v].size() == 0) {
        return grundy[v] = 0;
    }

    unordered_set<ll> memo;
    for (auto&& u : g[v]) {
        memo.insert(grundy_dfs(u));
    }
    rep(i, INF) {
        if (!memo.count(i)) {
            return grundy[v] = i;
        }
    }
    assert(0);
    return -1;
}


int main(void) {
    ll n; cin >> n;
    vll a(n); cin >> a;
    g.resize(n), gr.resize(n);
    rep(i, n) {
        g [a[i]-1].pb(i);
        gr[i].pb(a[i]-1);
    }

    vvll scc = getSCC();
//    cout << scc << endl;

    for (auto&& vv : scc) {
        if (vv.size() > 1) {
            for (auto&& v : vv) {
                cycle.insert(v);
            }
        }
    }
    if (cycle.empty()) {
        cout << "POSSIBLE" << endl;
        return 0;
    }

    grundy = vll(n, -1);
    rep(i, n) if (!cycle.count(i)) {
        grundy_dfs(i);
    }
//    cout << grundy << endl;

    ll v = *cycle.begin();
    unordered_set<ll> memo;
    for (auto u : g[v]) {
        memo.insert(grundy[u]);
    }
    cycle = {};
    ll counter = 2;
    rep(i, INF) {
        if (!counter) break;
        if (!memo.count(i)) {
//            cout << i << "#CAND" << endl;
            auto backup = grundy;
            grundy[v] = i;
            rep(i, n) {
                grundy_dfs(i);
            }
//            cout << grundy << endl;
            rep(i, n) {
//                cout << i <<"###########"<< endl;
                assert(grundy[i] != -1);
                unordered_set<ll> memo;
                for (auto&& u : g[i]) {
//                    cout << u << " : "<< grundy[u]<< endl;
                    memo.insert(grundy[u]);
                }
                ll grundy_i = -1;
                rep(i, INF) {
                    if (!memo.count(i)) {
                        grundy_i = i;
                        break;
                    }
                }
                if (grundy[i] != grundy_i) {
//                    cout << i << " " << grundy[i] << " : " << memo << endl;
                    goto SKIP;
                }
            }
            cout << "POSSIBLE" << endl;
            return 0;
            SKIP:;
            grundy = backup;
            counter--;
        }
    }
    cout << "IMPOSSIBLE" << endl;

    return 0;
}

