		int m = mex(v);
		if (m == sx && m != prex)return true;
		else return false;
	}
	vector<int>v;
	v.push_back(prex);
	for (auto nxt : G[n]) {
		if (fix[nxt])v.push_back(X[nxt]);
	}
	int m = mex(v);
	return dfs(s, sx, n, par[n], m);
}

void solve() {
	int N; cin >> N;
	REP(i, N) {
		int u; cin >> u;
		u--;
		G[u].push_back(i);
		par[i] = u;
		deg[u]++;
	}
	REP(i, N) {
		if (deg[i] == 0) {
			bool flag = 0;
			int nxt = i;
			while (deg[nxt] <= 1) {
				int pos = nxt;
				fix[pos] = true;
				X[pos] = flag;
				flag = ~flag;
				nxt = par[pos];
			}
		}
	}
	bool ok = false;
	REP(i, N) {
		if (!fix[i]) {
			vector<int>v;
			for (auto nxt : G[i]) {
				if (fix[nxt])v.push_back(X[nxt]);
			}
			int m = mex(v);
			if (dfs(i, m, i, par[i], m) || dfs(i, m + 1, i, par[i], m + 1))ok = true;
			break;
		}
	}
	if (ok)print("POSSIBLE");
	else print("IMPOSSIBLE");
}



