const int MAX = 200000;

vector<int> e[MAX], re[MAX];
bool cycle[MAX], used[MAX];
int ans[MAX], degout[MAX];

int dfs(int u) {
    int ret = u;
    used[u] = true;
    for (auto v: re[u]) {
        if (used[v]) {
            if (cycle[v]) return v;
            cycle[v] = true;
        }
        ret = dfs(v);
    }
    return ret;
}

int main(void) {
    int i, n;
    scanf("%d",&n);
    set<int> leaves;
    REP (i,n) leaves.insert(i);
    REP (i,n) {
        int p;
        scanf("%d",&p);
        p--;
        e[p].push_back(i);
        re[i].push_back(p);
        leaves.erase(p);
        degout[p]++;
    }
    int start = dfs(0);
    queue<int> q;
    for (auto x: leaves) q.push(x);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        set<int> st;
        for (auto v: e[u]) {
            st.insert(ans[v]);
        }
        REP (i,0,e[u].size()) if (!st.count(i)) {
            ans[u] = i;
            break;
        }
        for (auto v: re[u]) if (!cycle[v]) {
            if (--degout[v] == 0) q.push(v);
        }
    }
    set<int> st;
    for (auto v: e[start]) if (!cycle[v]) {
        st.insert(ans[v]);
    }
    vector<int> cand;
    REP (i,0,e[start].size()+1) if (cand.size() < 2 && !st.count(i)) {
        cand.push_back(i);
    }
    for (auto x: cand) {
        ans[start] = x;
        queue<int> q;
        q.push(start);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto v: re[u]) {
                set<int> st;
                for (auto w: e[v]) st.insert(ans[w]);
                int tmp;
                REP (i,0,e[v].size()) if (!st.count(i)) {
                    tmp = i;
                    break;
                }
                if (v == start) {
                    if (ans[v] == tmp) {
                        puts("POSSIBLE");
                        return 0;
                    }
                    break;
                }
                ans[v] = tmp;
                q.push(v);
            }
        }
    }
    puts("IMPOSSIBLE");
    return 0;
}

