        dfs2(v);
        mex[val[v]] = 1;
    }
    val[u] = 0;
    while (mex[val[u]]) ++val[u];
    for (rint i = fir[u]; i; i = nxt[i])
        mex[val[to[i]]] = 0;
}

inline bool bfs() {
    for (rint i = 1; i <= cntc; ++i)
        dfs2(cir[i]);
    memcpy(val2, val, sizeof val);
    val2[cntc]++;
    for (rint i = cntc - 1; i >= 1; --i) {
        if (val[i + 1] == val[i]) ++val[i];
        if (val2[i + 1] == val2[i]) ++val2[i];
    }
    return (val[1] != val[cntc]) || (val2[1] == val2[cntc] - 1);
}

