void find_cycle(const V<V<i64>> &edges, V<i64> &path) {
    if (path.size() > 1 && path.front() == path.back()) {
        return ;
    }

    FORE (n, edges[path.back()]) {
        path.push_back(n);
        find_cycle(edges, path);
        if (path.size() > 1 && path.front() == path.back()) {
            return ;
        }
        path.pop_back();
    }
}


int body(int &argc, char **argv) {
    using namespace debug;
    auto N = read<i64>();
    auto ps = read<i64>(N);
    FORE (p, ps) {
        p -= 1;
    }

    auto edges = V<V<i64>>(N, V<i64>());
    auto edges2 = V<i64>(N);
    REP (i, N) {
        // ps[i] -> i
        auto n1 = ps[i];
        i64 n2 = i;
        edges[n1].push_back(n2);
        edges2[n2] = n1;
    }

    // Find cycle
    V<i64> cycle;
    auto s = stack<V<i64>>();
    REP (i, N) {
        cycle = {i};
        find_cycle(edges, cycle);

        if (cycle.size() > 1 && cycle.front() == cycle.back()) {
            break ;
        }
    }
    /*
    REP (i, N) {
        s.push({i});
    }

    while (!s.empty()) {
        auto p = s.top();
        s.pop();

        if (p.size() > 1 && p.back() == p.front()) {
            cycle = p;
            break ;
        }

        FORE(n, edges[p.back()]) {
            auto p2 = p;
            p2.push_back(n);
            s.push(p2);
        }
    }
     */

    V<i64> values(N, -1);
    auto fill_value = [&](i64 n, auto f) -> i64 {
        if (values[n] != -1) {
            return values[n];
        }

        unordered_set<i64> xs;
        FORE (n2, edges[n]) {
            xs.insert(f(n2, f));
        }

        REP(i, xs.size() + 1) {
            if (xs.find(i) == xs.end()) {
                values[n] = i;
                return i;
            }
        }
    };

    REP (i, N) {
        if (find(cycle.begin(), cycle.end(), i) != cycle.end()) {
            continue;
        }

        fill_value(i, fill_value);
    }

    bool possible = false;
    auto start = cycle.back();
    REP (x, edges[start].size() + 1) {
        auto vs = values;
        vs[start] = x;
        FORR (i, 1, cycle.size() - 1) {
            auto n = cycle[i];
            unordered_set<i64> xs;
            FORE (n2, edges[n]) {
                xs.insert(vs[n2]);
            }

            REP(j, xs.size() + 1) {
                if (xs.find(j) == xs.end()) {
                    vs[n] = j;
                    break ;
                }
            }
        }

        auto n = cycle[0];
        auto v = vs[n];
        V<bool> exists(v);
        bool ok = true;
        FORE (n2, edges[n]) {
            auto v2 = vs[n2];
            if (v2 == v) {
                ok = false;
                break;
            }
            if (v2 < v) {
                exists[v2] = true;
            }
        }
        REP (i, v) {
            auto f = exists[i];
            if (!f) {
                ok = false;
                break;
            }
        }

        if (ok) {
            possible = true;
            break;
        }
    }

    cout << (possible ? "POSSIBLE": "IMPOSSIBLE") << endl;

    return 0;
}

