void dfs( int v ){
    mex[v] = 0;
    vector < int > val;
    for ( int j = 0; j < size(g[v]); j++ ){
        int u = g[v][j];
        if ( !inCycle[u] && u != parent[v] ){
            parent[u] = v;
            dfs(u);
            val.pb( mex[u] );
        }
    }
    sort( val.begin(), val.end() );
    cval[st] = val;
    for( int j = 0; j < size(val); j++ ){
        if ( val[j] == mex[v] ){
            mex[v]++;
        }
    }
}

void check( int s, int mexx ){
    int prv, res = 1;
    cmex[s] = mexx;
    vector < int > val;
    val.pb(mexx);
    for ( int i = 1; i <= size(cycle) - 1; i++ ){
        prv = s;
        s = to[s];
        if ( cmex[prv] == mex[s] ){
            cmex[s] = nxtMex[s];
        }
        else{
            cmex[s] = mex[s];
        }
        val.pb( cmex[s] );
    }
    for ( int i = 1; i < size(val); i++ ){
        if ( val[i] == val[i-1] ){
            res = 0;
        }
    }
    if ( val[0] == val.back() ){
        res = 0;
    }
    if ( res ){
        ans = 1;
    }
}

