#include <bits/stdc++.h>
using namespace std;
const int MAXN = 200005;

int n, in[MAXN], deg[MAXN], val[MAXN];
vector <int> mex[MAXN]; queue <int> q;

int calc(vector <int> &cal){
	int ret;
	for(ret = 0; ret < int(cal.size()) && cal[ret]; ++ ret) ;
	return ret;
}
bool check(int p, int v){
	int i; val[p] = v;
	for(i = p; in[i] != p; i = in[i]){
		if(int(mex[in[i]].size()) <= val[i])
			mex[in[i]].resize(val[i] + 1);
		++ mex[in[i]][val[i]];
		val[in[i]] = calc(mex[in[i]]);
	}
	if(int(mex[in[i]].size()) <= val[i])
		mex[in[i]].resize(val[i] + 1);
	++ mex[in[i]][val[i]];
	bool ret = calc(mex[in[i]]) == val[in[i]];
	for(i = p; in[i] != p; i = in[i])
		-- mex[in[i]][val[i]];
	-- mex[in[i]][val[i]];
	return ret;
}
int main(){
	int i;
	scanf("%d", &n);
	for(i = 1; i <= n; ++ i){
		scanf("%d", &in[i]);
		++ deg[in[i]];
	}
	memset(val, -1, sizeof(val));
	for(i = 1; i <= n; ++ i)
		if(!deg[i]) q.push(i);
	while(!q.empty()){
		i = q.front(); q.pop();
		val[i] = calc(mex[i]);
		if(int(mex[in[i]].size()) <= val[i])
			mex[in[i]].resize(val[i] + 1);
		++ mex[in[i]][val[i]];
		if(!(-- deg[in[i]])) q.push(in[i]);
	}
	for(i = 1; i <= n; ++ i)
		if(val[i] == -1) break;
	int tmp = calc(mex[i]);
	bool res = check(i, tmp);
	if(int(mex[i].size()) <= tmp)
		mex[i].resize(tmp + 1);
	++ mex[i][tmp];
	int tmp2 = calc(mex[i]);
	-- mex[i][tmp];
	res = res || check(i, tmp2);
	printf("%s\n", res ? "POSSIBLE" : "IMPOSSIBLE");
	return 0;
}

