int grundy[200010];
int st = -1;
const int CYCLE = 42;

int dfs(int x) {
	cycle[x] = 1;
	for(int i : out[x]) {
		if(cycle[i] == 1) {
			st = i;
			cycle[x] = CYCLE;
			return CYCLE;
		}
		else if(cycle[i] == 0) {
			if(dfs(i) == CYCLE) {
				cycle[x] = CYCLE;
				if(x == st) return 0;
				else return CYCLE;
			}
		}
	}
	cycle[x] = 2;
	return 0;
}

int getgrundy(int x) {
	set<int> s;
	for(int i : out[x])
		if(cycle[i] != CYCLE)
			s.insert(getgrundy(i));
	int ans = 0;
	auto it = s.begin();
	while(it != s.end()) {
		if(*it == ans) {
			++ans;
			++it;
		}
		else return grundy[x] = ans;
	}
	return grundy[x] = ans;
}

bool chk(int x, int val, int res) {
	if(x == st) return res == val;
	int nxt = -1;
	for(int i : out[x]) {
		if(cycle[i] == CYCLE) {
			nxt = i;
		}
	}
	return chk(nxt, grundy[nxt] + (grundy[nxt] == val), res);
}

