void cycle(int v) {
    used[v] = 1;
    for (auto to : gr[v]) {
        if (!used[to]) {
            par[to] = v;
            cycle(to);
        } else if (to != par[v]) {
            if (!flag) {
                ll u = v;
                while (u != to) {
                    way.push_back(u);
                    u = par[u];
                }              
                way.push_back(to);
                flag = true;      
            }
        }
    }
}

void find(int v) {
    used[v] = 1;

    vector<ll> curVl;
    for (auto to : gr[v]) {
        if (!used[to]) {
            find(to);
            if (fr[{v, to}] == v) curVl.push_back(c[to]);
        }
    }

    ll pr = -1;
    curVl.push_back(INF);
    sort(curVl.begin(), curVl.end());

    ll mx = -1;
    for (auto cur : curVl) {
        if (cur == pr) continue;

        if (pr + 1 < cur) {
            mx = pr + 1;
            break;
        }
        pr = cur;
    }

    c[v] = mx;
}

void ch(int v) {
    used[v] = 1;

    for (auto to : graph[v]) {
        if (!used[to] && s.find(to) != s.end()) {
            ch(to);
        }
        if (c[v] == c[to]) {
            c[v]++;
        }
    }
}

