int g(int now) {
	vector<int> c(li[now].size() + 1,0);
	int i;
	if (now == s) {
		if (flag)
			flag--;
		else {
			for (auto &e : li[now]) {
				if (e!=nex)
					c[g(e)] = 1;
			}
			int first = -1, second;
			for (i = 0; i < li[now].size() + 1; i++) {
				if (!c[i]) {
					if (first < 0)
						first = i;
					else {
						second = i;
						break;
					}
				}
			}
			if (mode) {
				memo = first;
				return first;
			}
			else {
				memo = second;
				return second;
			}
		}
	}
	for (auto &e : li[now])
		c[g(e)] = 1;
	int ans;
	for (i = 0; i < li[now].size() + 1; i++) {
		if (!c[i]) {
			ans = i;
			break;
		}
	}
	if (now == s) {
		if (memo == ans)
			return 1;
		else
			return 0;
	}
	return ans;
}

