inline void addedge(int from, int to) {
  e[++tot] = (Edges){to, head[from]};
  head[from] = to;
}

void Dfs(int now) {
  if (vis[now]) {
    while (stk[top] != now) a[++cnt] = stk[top--];
    a[++cnt] = stk[top--];
    return;
  }
  stk[++top] = now;
  vis[now] = 1;
  for (RI i = head[now]; i; i = e[i].next)
    Dfs(e[i].to);
  --top;
}

void Work(int now) {
  for (RI i = head[now]; i; i = e[i].next)
    if (!Ring[e[i].to])
      Work(e[i].to), ok[now][b[e[i].to]] = 1;
  for (RI i = 0; i < 20; ++i)
    if (!ok[now][i])
      return b[now] = i, void();
}

