const int N = 2e5 + 10;
vector<int> a[N];
vector<int> C;
bool circle[N];
int pre[N];
int dp[N];
bool instack[N];

void DFS1(int u) {
  instack[u] = true;
  for (auto& v : a[u]) {
    if (pre[v] < 0) {
      pre[v] = u;
      DFS1(v);
    } else {
      if (instack[v]) {
        assert(C.empty());
        int w = u;
        while (w != v) {
          circle[w] = true;
          C.push_back(w);
          w = pre[w];
        }
        circle[v] = true;
        C.push_back(v);
      }
    }
  }
  instack[u] = false;
}

void DFS(int u) {
  vector<int> A;
  for (auto& v : a[u]) {
    if (circle[v]) continue;
    DFS(v);
    A.push_back(dp[v]);
  }
  if (!A.empty()) {
    sort(A.begin(), A.end());
    for (int i = 1; i < A.size(); ++i) {
      if (A[i] > A[i - 1] + 1) {
        dp[u] = A[i - 1] + 1;
        break;
      }
    }
    if (dp[u] == 0) dp[u] = A[A.size() - 1] + 1;
  }
}

