int visit[212345];
int cycle_find(const vector<vint>& G,int v,int c){
  if(visit[v]==c){
    return v;
  }else if(visit[v]>=0){
    return -1;
  }
  visit[v]=c;
  for(int u:G[v]){
    int find=cycle_find(G,u,c);
    if(find>=0) return find;
  }
  return -1;
}
int a[212345];
void dfs(const vector<vint>& G,int v){
  if(visit[v]) return;
  visit[v]=true;
  set<int> st;
  for(int u:G[v]){
    dfs(G,u);
    st.insert(a[u]);
  }
  a[v]=0;
  while(st.count(a[v]++));
  a[v]--;
}

