const ll MOD=1e9+7;

int N;
int state[214514];
int nxt[214514];
vector<int> cycle;
vector<int> es[214514];
vector<multiset<int>> mex;

int DecomposeNamori(int v) {
  if (state[v] == 2) {
    return 0;
  }

  if (state[v] == 1) {
    state[v] = 2;
    return 1;
  }

  assert(state[v] == 0);
  state[v] = 1;
  int res = DecomposeNamori(nxt[v]);
  if (res == 1) {
    cycle.eb(v);
    if (state[v] == 2) return 0;
    state[v] = 2;
    return 1;
  }
  assert(res == 0);
  es[nxt[v]].eb(v);
  return 0;
}

int CalcGrundy(int v) {
  vector<char> num(es[v].size());
  int ret = es[v].size();
  for (int u : es[v]) {
    int t = CalcGrundy(u);
    if (t >= num.size()) continue;
    num[t] = 1;
  }

  rep(t, ret) {
    if (!num[t]) return t;
  }
  return ret;
}

multiset<int> CalcMex(int v) {
  multiset<int> ret;
  for (int u : es[v]) {
    ret.insert(CalcGrundy(u));
  }
  return ret;
}

int Mex(multiset<int> &ms) {
  int ret = ms.size();
  rep(t, ret) {
    if (!ms.count(t)) return t;
  }
  return ret;
}

int main() {
  cin >> N;
  rep(v, N) {
    cin >> nxt[v];
    nxt[v]--;
  }

  rep(v, N) {
    if (state[v] == 2) continue;
    assert(state[v] == 0);
    DecomposeNamori(v);
  }

  reverse(all(cycle));
  for (int v : cycle) {
    mex.eb(CalcMex(v));
  }

  assert(mex.size() >= 2);
  vector<int> grundy(mex.size());
  int M = mex.size();
  rep(i, 2) {
    grundy[0] = Mex(mex[0])+i;
    reps(idx, 1, mex.size()) {
      int p = (idx-1)%M;
      mex[idx].insert(grundy[p]);
      grundy[idx] = Mex(mex[idx]);
      mex[idx].erase(mex[idx].find(grundy[p]));
    }

    mex[0].insert(grundy[M-1]);
    if (grundy[0] == Mex(mex[0])) {
      puts("POSSIBLE");
      return 0;
    }
    mex[0].erase(mex[0].find(grundy[M-1]));
  }
  puts("IMPOSSIBLE");
}

