using ulint = unsigned long long int;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;
template<class T, class U> void assign(V<T>& v, int n, const U& a) { v.assign(n, a); }
template<class T, class... Args> void assign(V<T>& v, int n, const Args&... args) { v.resize(n); for (auto&& e : v) assign(e, args...); }


int scc(const VV<>& g, V<>& comp) {
  int n = g.size();
  VV<> rg(n);
  for (int v = 0; v < n; v++) {
    for (int w : g[v]) {
      rg[w].push_back(v);
    }
  }
  V<> vs;
  V<bool> vis(n);
  comp.resize(n);

  auto dfs = [&](const auto& dfs, int v) -> void {
    vis[v] = true;
    for (int w : g[v]) if (!vis[w]) {
      dfs(dfs, w);
    }
    vs.push_back(v);
  };

  auto rdfs = [&](const auto& rdfs, int v, int k) -> void {
    vis[v] = true;
    comp[v] = k;
    for (int w: rg[v]) if (!vis[w]) {
      rdfs(rdfs, w, k);
    }
  };

  for (int v = 0; v < n; v++) if (!vis[v]) {
    dfs(dfs, v);
  }
  vis.assign(n, false);
  int k = 0;
  reverse(vs.begin(), vs.end());
  for (int v : vs) if (!vis[v]) {
    rdfs(rdfs, v, k++);
  }
  return k;
}

int main() {
  cin.tie(nullptr); ios_base::sync_with_stdio(false);
  int n; cin >> n;
  VV<> g(n);
  for (int i = 0; i < n; ++i) {
    int p; cin >> p, --p;
    g[p].push_back(i);
  }
  V<> comp;
  int k = scc(g, comp);
  if (k == n) return cout << "POSSIBLE" << '\n', 0;
  VV<> h(n);
  bool first = true;
  int u0, v0;
  map<int, int> mp;
  for (int v = 0; v < n; ++v) {
    for (int w : g[v]) {
      if (comp[v] == comp[w]) {
        if (first) {
          u0 = v, v0 = w;
          first = false;
        }
        mp[w] = v;
        continue;
      }
      h[v].push_back(w);
    }
  }
  scc(h, comp);
  V<> vs(n);
  iota(begin(vs), end(vs), 0);
  sort(begin(vs), end(vs), [&](int u, int v) { return comp[u] > comp[v]; });
  V<> a(n);
  for (int v : vs) {
    set<int> se;
    for (int w : h[v]) {
      se.insert(a[w]);
    }
    int i = 0;
    while (se.count(i)) ++i;
    a[v] = i;
  }
  if (a[u0] != a[v0]) return cout << "POSSIBLE" << '\n', 0;
  assert(false);
  while (u0 != v0) {
    set<int> se;
    for (int w : g[u0]) {
      se.insert(a[w]);
    }
    int i = 0;
    while (se.count(i)) ++i;
    a[u0] = i;
    u0 = mp[u0];
  }
  for (int w : g[v0]) {
    if (a[w] == a[v0]) return cout << "IMPOSSIBLE" << '\n', 0;
  }
  cout << "POSSIBLE" << '\n';
}

