int findCycle(int n){
    for(int i = 1; i <= n; i++) p[i] = i;
    int x = -1, y = -1;
    for(int u = 1; u <= n; u++){
        if(x!=-1) break;
        for(int v: g[u]){
            if(find(u)!=find(v)) merge(u,v);
            else{
                x = u, y = v;
                break;
            }
        }
    }
    if(x==-1) return 0;
    else{
        parent[y] = -1;
        dfs(y);
        if(parent[x]==0) return 0;
        int size = 0;
        int cur = x;
        while(cur!=-1){
            cycle[++size] = cur;
            cur = parent[cur];
        }
        for(int i = 1; i <= size; i++){
            int j = size-i+1;
            if(i>=j) break;
            else{
                int t = cycle[i];
                cycle[i] = cycle[j];
                cycle[j] = t;
            }
        }
        return size;
    }
}

int getMex(vector<int>& set,int n){
    std::sort(set.begin(),set.end());
    int p = 0;
    for(int i = 0; i <= n+1; i++){
        while(p<(int)set.size() && set[p]<i) p++;
        if(p>=(int)set.size() || set[p]!=i) return i;
    }
    return -1;
}

void topo(int n){
    int h = 1, t = 0;
    for(int i = 1; i <= n; i++){
        if(in[i]==0){
            queue[++t] = i;
        }
    }
    while(h<=t){
        int u = queue[h++];
        value[u] = getMex(son[u],n);
        for(int v: rg[u]){
            in[v]--;
            son[v].push_back(value[u]);
            if(in[v]==0){
                queue[++t] = v;
            }
        }
    }
}

void preWork(int n,int size){
    for(int i = 1; i <= size; i++){
        int u = cycle[i];
        offer[u][0] = getMex(son[u],n);
        son[u].push_back(offer[u][0]);
        offer[u][1] = getMex(son[u],n);
    }
}

