int getval ( int now )
{
	for ( int i = la[now]; ~i; i = edge[i].last ) hv[dp[edge[i].v]] = true;
	int ans = -1;
	lp ( i, 0, MAXN ){
		if ( !hv[i] ){
			ans = i;
			break;
		}
	}
	for ( int i = la[now]; ~i; i = edge[i].last ) hv[dp[edge[i].v]] = false;
	return ans;
}

