void work ()
{
	// main work

	INIT ( la, -1 );
	lpi ( i, 1, n ){
		edge[ke].setd ( p[i], i, la[p[i]] );
		la[p[i]] = ke++;
	}

	int now = 1;
	while ( 1 ){
		if ( ins[now] ){
			while ( stk[top] ^ now ) cyc[++kc] = stk[--top];
			break;
		}
		ins[now] = true;
		stk[top++] = now;
		now = p[now];
	}

	reverse ( cyc+1, cyc+1+kc );
//	lpi ( i, 1, kc ) cerr << cyc[i] << " "; cerr << endl;
	lpi ( i, 1, kc ) inc[cyc[i]] = true;
	lpi ( i, 1, kc ) dfs ( cyc[i] );

	dp[cyc[kc]] = MAXN-1;
	dp[cyc[1]] = getval ( cyc[1] );
	lpi ( i, 2, kc ) dp[cyc[i]] = getval ( cyc[i] );
	if ( dp[cyc[1]] == getval ( cyc[1] ) ){
		cout << "POSSIBLE" << endl;
		return;
	}
	dp[cyc[kc]] = dp[cyc[1]];
	dp[cyc[1]] = getval ( cyc[1] );
	lpi ( i, 2, kc ) dp[cyc[i]] = getval ( cyc[i] );
	cout << ( ( dp[cyc[1]] == getval ( cyc[1] ) ) ? "POSSIBLE" : "IMPOSSIBLE" ) << endl;
}

