void add_edge(int x,int y) {
	e[++edCnt]=(edge) {x,y,ls[x]}; ls[x]=edCnt;
}

void dfs1(int x) {
	stack.push(x);
	for (int i=ls[x];i;i=e[i].next) {
		if (!vis[e[i].y]) {
			vis[e[i].y]=1;
			dep[e[i].y]=dep[x]+1;
			dfs1(e[i].y);
		} else {
			cir=dep[x]-dep[e[i].y]+1;
			int y=0;
			while (y!=e[i].y) {
				y=stack.top(),stack.pop();
				vec.push_back(y);
				in[y]=1;
			}
		}
	}
}

void dfs2(int x) {
	d++;
	for (int i=ls[x];i;i=e[i].next) {
		if (!in[e[i].y]) dfs2(e[i].y);
	}
}

