inline int mex(set<int> & s){
	for(int i = 0; ;i++) if(!s.count(i)) return i;
}
const int N = 2e5 + 10;
int deg[N], p[N], bad[N];
vector< set<int> > adj, adj2;
vector<pair<int, int> > edges;
int vis[N];
vector<int> cycle;
int color[N];
bool error = 0;
void toposort(int n){
	queue<int> q;
	for(int i = 1; i <= n; i++) if(deg[i] == 0 && !bad[i]) q.push(i);
	while(!q.empty()){
		int u = q.front(); q.pop();
		set<int> s;
		for(int v : adj[u]){
			s.insert(color[v]);
		}
		color[u] = mex(s);
		if(!bad[p[u]]){
			deg[p[u]]--;
			if(deg[p[u]] == 0) q.push(p[u]);
		}
	}
}
