int main(){
	memset(color, -1, sizeof color);
	int n;
	sd(n);
	adj.resize(n + 1);
	for(int i = 1; i <= n; i++) sd(p[i]), adj[p[i]].insert(i), deg[p[i]]++, edges.pb({p[i], i});
	adj2 = adj;
	// find a cycle
	bool found;
	for(int i = 1; i <= n; i++){
		if(vis[i]) continue;
		set<int> vec = {i};
		vis[i] = 1;
		int v = p[i];
		while(!vis[v]){
			vec.insert(v);
			vis[v] = 1;
			v = p[v];
		}
		if(vec.count(v)){
			found = 1;
			cycle.push_back(v); bad[v] = 1;
			int u = p[v];
			while(u != v){
				cycle.push_back(u);
				bad[u] = 1;
				u = p[u];
			}
			break;
		}
	}
	// print(cycle);
	if(cycle.empty()){
		printf("POSSIBLE"); return 0;
	}
	// Remove cycle and color
	for(auto it : edges){
		if(bad[it.S]){
			adj[it.F].erase(it.S);
			deg[it.F]--;
		}
	}
	toposort(n);
	int ind = 0, mn = 1e9;
	for(int c : cycle) if(adj[c].size() < mn){mn = adj[c].size(); ind = c;}
	for(int i = 0; i <= mn + 2; i++){
		for(int j : cycle) color[j] = -1;
		color[ind] = i;
		int v = p[ind];
		error = 0;
		while(v != ind){
			set<int> s;
			for(int x : adj2[v]) s.insert(color[x]);
			color[v] = mex(s);
			v = p[v];
		}
		for(int j : cycle) if(color[j] == color[p[j]]) error = 1;
		set<int> s;
		for(int x : adj2[ind]) s.insert(color[x]);
		if(mex(s) != i) error = 1;
		if(!error){
			/*for(int j = 1; j <= n; j++) cerr << color[j] << " ";
			cerr << endl;*/
			printf("POSSIBLE");
			return 0;
		}
	}
	printf("IMPOSSIBLE");
	return 0;
}

