    b[s] = c1;
    queue<int> q;
    q.push(rev[s]);

    int last = bfs(q,b,cc);
// dbg(b);
    if(b[last]!=b[s] && b[last] == mex(last, b) && b[s]==mex(s,b)) return true;

    swap(c1,c2);
  }

  return false;
}

