#define N 200005
vi adj[N];
bitset<N> inCycle;
int n;
bitset<N> vis;
int grund[N];
set<int> SET;
int nexCyc[N], preCyc[N];

bool dfs(int u, int par) {
	if (vis.test(u)) {
		inCycle.set(u, 1);
		preCyc[u] = par;
		nexCyc[par] = u;
		return 1;
	}
	vis.set(u, 1);
	for (const auto& v : adj[u]) {
		if (dfs(v, u)) {
			inCycle.set(u, 1);
			preCyc[v] = u;
			nexCyc[u] = v;
		}
	}

	if (!inCycle.test(u)) {
		SET.clear();
		for (const auto& v : adj[u]) {
			SET.insert(v);
		}
		int& res = grund[u];
		res = 0;
		while (SET.find(res) != SET.end()) {
			++res;
		}
	}
	return inCycle.test(u);
}

int grundTmp[N];

bool coba(int su, int val) {
	FOR (i, 0, n) grundTmp[i] = grund[i];

	grund[su] = val;
	int u = preCyc[u];
	while (u != su) {
		int& res = grund[u];
		SET.clear();
		for (const auto& v : adj[u]) {
			SET.insert(grund[v]);
		}
		res = 0;
		while (SET.find(res) != SET.end()) ++res;
		u = preCyc[u];
	}

	bool ok = 1;

	FOR (u, 0, n) {
		if (ok && inCycle.test(u)) {
			int tmp = 0;
			SET.clear();
			for (const auto& v : adj[u]) {
				SET.insert(grund[v]);
			}
			while (SET.find(tmp) != SET.end()) ++tmp;

			ok = ok && tmp == grund[u];
		}
	}

	FOR (i, 0, n) grund[i] = grundTmp[i];

	return ok;
}

int main(int argc, char** argv) {
	__INIT_CC__
	cin >> n;
	FOR (i, 0, n) {
		int a;
		cin >> a;
		--a;
		adj[a].pb(i);
	}

	RESET(grund, -1);
	RESET(preCyc, -1);
	RESET(nexCyc, -1);
	FOR (i, 0, n) {
		if (vis.test(i));
		else {
			dfs(i, -1);
		}
	}

	int root = -1;
	FOR (i, 0, n) {
		if (inCycle.test(i)) {
			root = i;
			break ;
		}
	}

	SET.clear();
	for (const auto& v : adj[root]) {
		if (grund[v] != -1) {
			SET.insert(grund[v]);
		}
	}
	FOR (u, 0, n) {
		if (grund[u] == -1) {
			inCycle.set(u, 1);
		}
	}

	FOR (u, 0, n) {
		if (grund[u] == -1) {
			inCycle.set(u, 1);
		}
		if (inCycle.test(u)) {
			for (const auto& v : adj[u]) {
				if (inCycle.test(v)) {
					nexCyc[u] = v;
					preCyc[v] = u;
				}
			}
		}
	}

	set<int> possible_values;
	possible_values.clear();
	int z = 0;
	while (SET.find(z) != SET.end()) ++z;
	possible_values.insert(z);
	++z;
	while (SET.find(z) != SET.end()) ++z;
	possible_values.insert(z);

	bool ok = 0;
	ok = ok || coba(root, *possible_values.begin());
	possible_values.erase(possible_values.begin());
	ok = ok || coba(root, *possible_values.begin());
	if (ok) {
		cout << "POSSIBLE\n";
	} else {
		cout << "IMPOSSIBLE\n";
	}
}

