void scc()
{
	memset(used,0,sizeof(used));
	vector<int> po;
	FOR(i,0,N * 2) if(used [i] == false){
		dfs(i,po);
	}
	memset(used,0,sizeof(used));
	for(int i = int(po.size()) - 1;i >= 0;i--) if(used [po [i]] == false){
		rdfs(po [i],k++);
	}
}

