	FOR(i,0,N) if(outdeg [i] == 0){
		q.push(i);
	}
	memset(grundy,-1,sizeof(grundy));
	while(q.empty() == false){
		int curr = q.front(); q.pop();
		set<int> st;
		for(const auto& it : to [curr]){
			st.insert(grundy [it]);
		}
		grundy [curr] = 0;
		while(st.count(grundy [curr])) grundy [curr]++;
		if(--outdeg [from [curr]] == 0) q.push(from [curr]);
	}

	FOR(i,0,N) if(grundy [i] == -1){
		bool haveZero = false;
		for(const auto& it : to [i]) if(grundy [it] == 0){
			G [i].push_back(i + N);
			rG [i + N].push_back(i);
			haveZero = true;
		}
		for(const auto& it : to [i]) if(grundy [it] == -1){
			G [i].push_back(it + N);
			G [it].push_back(i + N);
			rG [it + N].push_back(i);
			rG [i + N].push_back(it);
