				G [i + N].push_back(it);
				rG [it].push_back(i + N);
			}
		}
	}
	scc();

	bool ans1 = true,ans2 = false;
	FOR(i,0,N) if(grundy [i] == -1){
		ans1 &= cmp [i] != cmp [i + N];
		ans2 |= cmp [i + N] < cmp [i];
	}
