vb seen, finished;

vector<pii> grundy;

void predfs(Graph<int> &g, int v) {
  hist.push(v);
  seen[v] = true;

  for (auto &nv : g[v]) {
    if (finished[nv]) continue;

    if (seen[nv]) {
      cycle.emplace_back(nv);

      while (hist.top() != nv) {
        cycle.emplace_back(hist.top());
        hist.pop();
      }

      return;
    }

    predfs(g, nv);

    if (!cycle.empty()) return;
  }

  hist.pop();
  finished[v] = true;
}

int dfs(Graph<int> &g, int v, int p = -1) {
  int sz = g[v].size();
  vb det(sz + 1, false);

  for (auto &nv : g[v]) {
    if (nv != p) {
      int ret = dfs(g, nv);
      if (ret < sz) det[ret] = true;
    }
  }

  int tmp = -1;

  repeq(i,sz) {
    if (!det[i]) {
      if (p == -1) return i;

      if (tmp == -1) {
        tmp = i;
        continue;
      }

      grundy.emplace_back(tmp, i);
      return 0;
    }
  }
}

int confirm(int idx, int next) {
  if (idx == grundy.size()) return next;

  int prev = grundy[idx].first == next ? grundy[idx].second : grundy[idx].first;
  return confirm(idx + 1, prev);
}

void solve() {
  int n; cin >> n;

  Graph<int> g(n);
  rep(i,n) {
    int v; cin >> v; --v;
    g[v].emplace_back(i);
  }

  seen.assign(n, false);
  finished.assign(n, false);

  rep(i,n) {
    if (!seen[i]) predfs(g, i);
    if (!cycle.empty()) break;
  }

  const int sz = cycle.size();
  grundy.reserve(sz);

  int prev = cycle.back();

  for (auto &v : cycle) {
    dfs(g, v, prev);
    prev = v;
  }

  bool p = grundy.back().first == confirm(0, grundy.back().first);
  if (!p) p = grundy.back().second == confirm(0, grundy.back().second);

  CoutYN(p, "POSSIBLE", "IMPOSSIBLE");
}


