bool check(std::vector<int>& redge, std::vector<std::set<int>>const& imp, int start, int now, int prev)
{
	if (now == start)
	{
		return !imp[now].count(j) && prev == j;
	}
	int j = 0;
	for (; j < 3; ++j)
	{
		if (!imp[now].count(j) && prev != j)
		{
			break;
		}
	}
	return check(redge, imp, start, redge[now], j);
}

