			{
				int j = i;
				do
				{
					j = reverse_edge[j];
					start = j;
					imp[j].emplace(1 - *(imp[edge[j].second].begin()));
				} while (edge[j].first < 2);
			}
		}
		int j = 0;
		for (; j < 3; ++j)
