vector<int> li[222222];
vector<int> li2[222222];
int check[222222], flag = 0, s, mode, p[222222], memo, nex, flag2;
void dfs(int now, int par) {
	if (check[now]) {
		flag++;
		flag2 = 1;
		s = now;
	}
	else {
		check[now]++;
		for (auto &e : li2[now]) {
			if (e != par) {
				dfs(e, now);
				if (flag) {
					if (p[now] == s && flag2)
						nex = now;
					if (now == s)
						flag2--;
					break;
				}
			}
		}
	}
}

int g(int now) {
	vector<int> c(li[now].size() + 1, 0);
	int i;
	if (now == s) {
		if (flag)
			flag--;
		else {
			for (auto &e : li[now]) {
				if (e != nex) {
					int a = g(e);
					if(a < li[now].size() + 1)
					c[a] = 1;
				}
			}
			int first = -1, second;
			for (i = 0; i < li[now].size() + 1; i++) {
				if (!c[i]) {
					if (first < 0)
						first = i;
					else {
						second = i;
						break;
					}
				}
			}
			if (mode) {
				memo = first;
				return first;
			}
			else {
				memo = second;
				return second;
			}
		}
	}
	for (auto &e : li[now]) {
		int a = g(e);
		if (a < li[now].size() + 1)
			c[a] = 1;
	}
	int ans;
	for (i = 0; i < li[now].size() + 1; i++) {
		if (!c[i]) {
			ans = i;
			break;
		}
	}
	if (now == s) {
		if (memo == ans)
			return 1;
		else
			return 0;
	}
	return ans;
}

