const int N = 2e5 + 5;

std::vector <int> e[N];
int vis[N];
std::pair <int, int> val[N];

int get_mex(std::set<int>& mex) {
    int p = 0;
    for (auto i : mex) {
        if (p != i)
            break;
        ++p;
    }
    return p;
}

void dfs(int u, int p = 0) {
    std::set <int> mex1;
    std::set <int> mex2;
    vis[u] = 1;
    bool is_cycle = false;
    for (int v : e[u]) {
        if (v != p) {
            if (vis[v] == 1) {
                is_cycle = true;
                continue;
            }
            if (vis[v] == 0)
                dfs(v, u);
            mex1.insert(val[v].first);
            mex2.insert(val[v].second);
        }
    }
    val[u].first = get_mex(mex1);
    if (is_cycle)
        mex2.insert(val[u].first);
    val[u].second = get_mex(mex2);

    vis[u] = 2;
}

bool check1(int u) {
    std::set<int> mex;
    for (int v : e[u])
        mex.insert(val[v].first);
    return (mex.count(val[u].first));
}

bool check2(int u) {
    std::set<int> mex;
    for (int v : e[u])
        mex.insert(val[v].second);
    return (mex.count(val[u].second));
}

bool solve() {
    int n, u;
    std::cin >> n;
    for (int i = 1; i <= n; ++i) {
        scanf("%d", &u);
        e[u].push_back(i);
    }

    for (int i = 1; i <= n; ++i) {
        if (!vis[i])
            dfs(i);
    }
    for (int i = 1; i <= n; ++i) {
        if (check1(i))
            goto next;
    }
    std::cout << "POSSIBLE" << std::endl;
    return 0;
next:
    for (int i = 1; i <= n; ++i) {
        if (check2(i)) {
            std::cout << "IMPOSSIBLE" << std::endl;
            return 0;
        }
    }
    std::cout << "POSSIBLE" << std::endl;

    return 0;
}

int main() {
#ifdef LOCALHOST
    freopen("input", "r", stdin);
#endif
    while (solve());

    return 0;
}

