void dfs(int s,int par){
    if (ans[s]!=-1) return;
    vector<int> list;
    rep(i,G[s].size()){
        int t=G[s][i];
        if (inCycle[t] || t==par) continue;
        dfs(t,s);
        list.push_back(ans[t]);
    }
    sort(list.begin(),list.end());
    int k=-1;
    rep(i,list.size()){
        if (list[i]==k+1) k+=1;
        else if (list[i]>k+1) {
            ans[s]=k+1;
            return;
        }
    }
    ans[s]=k+1;
}

