    while(!visited[s]){
        //cout << s << endl;
        visited[s]=true;
        cycle.push_back(s);
        s=p[s];
    }
    rep(i,cycle.size()){
        if (cycle[0]==s) break;
        cycle.pop_front();
    }
    rep(i,cycle.size()){
        inCycle[cycle[i]]=true;
        //cout << cycle[i] << " ";
    }
    rep(i,cycle.size()){
        dfs(cycle[i],-1);
    }
    //cout << "" << endl;
    //rep(i,n){
        //cout << ans[i] << " ";
    //}
    //cout << "" << endl;
    vector<int> num(cycle.size(),-1);
    num[0]=ans[cycle[0]];
    Rep(i,1,cycle.size()){
        if (num[i-1]==ans[cycle[i]]) num[i]=ans[cycle[i]]+1;
        else num[i]=ans[cycle[i]];
        //cout << num[i] << endl;
    }
    //rep(i,cycle.size()){
    //    cout << num[i] << " ";
    //}
    //cout << "" << endl;
    if (num[0]!=num.back()) {
        cout << "POSSIBLE" << endl;
        return;
    }

    num.resize(cycle.size(),-1);
    num[0]=ans[cycle[0]]+1;
    Rep(i,1,cycle.size()){
