        if(!deg[p[x]])qq.push(p[x]);
    }
    REPP(j,1,n+1){
        if(a[j]!=-1)continue;
        int it=0;
        REP(i,SIZE){
            if(!front[j].count(i)){
                base[j][it++]=i;
                if(it==2)break;
            }
        }
    }
    int st=-1;
    REPP(i,1,n+1){
        if(a[i]==-1){
            st=i;
            break;
        }
    }
    int now=st;
    REP(i,2){
        int v=base[now][i];
        do{
            now=p[now];
            if(base[now][0]==v)v=base[now][1];
            else v=base[now][0];
        }while(now!=st);
        if(v==base[now][i])return 0*puts("POSSIBLE");
    }
    return 0*puts("IMPOSSIBLE");
}

