	if (p[u]!=u)p[u]=Find(p[u]);
	return p[u];
}

void Union(int u,int v){
	p[Find(u)]=Find(v);
}

void dfs(int u){
	if (u==forb)return;
	if (!sz(P[u]))return;
	for (auto it:P[u])dfs(it);
	for (auto it:P[u])O[grundy[it]]=true;
	for (int i=0;i<=n+2;i++) if (!O[i]){grundy[u]=i;break;}
	for (auto it:P[u])O[grundy[it]]=false;
}

