//    if(mem[i]!=-1)return mem[i];
    forg(gi, g[i])if(clo[t]==0)ss[i] += ds(i, t);
    rep(v, inf) {
        if (ss[i].count(v) == 0) {
            if (clo[i] == 0)gv[i] = v;
            return v;
        }
    }
    return 0;
}

digraph<> rg(0);
vi r(k5 * 2);
bool ds2(int p, int i, int nex) {
    int v;
    rep(j, inf) {
        if (ss[i].count(j) == 0 && nex != j) {
            v = j;
            break;
        }
    }

    if (gv[i] != -1) {
        bool ok = v == gv[i];
        if (ok)outv(gv);
        return ok;
    } else {
        gv[i] = v;
        return ds2(r[p], p, v);
    }
}

void solve() {
    in(n);
    rep(i, n) {
        g.add(in() - 1, i);
    }
    clo = get_close1(g);
    deg = outdegree(g);
    rep(i, n) {
        if (clo[i])ds(-1, i);
    }
    rg = rev(g);
    rep(i, n)forg(gi, rg[i]) {
            if (clo[t])r[i] = t;
        }

    rep(i, n) {
        if (clo[i]) {
            int m = 2;
            int pgv = 0;
            rep(v, inf) {
                if (m == 0)break;
                if (ss[i].count(v) == 0) {
                    rep(i, n) if (clo[i])gv[i] = -1;
                    if (m == 2) {
                        gv[i] = v;
                        if (ds2(r[r[i]], r[i], v)) {
                            POSSIBLE(1);
                        }
                        pgv = v;
                    } else {
                        int to = 0;
                        forg(gi, g[i])if (clo[t])to = t;
                        gv[to] = pgv;
                        gv[i] = v;
                        POSSIBLE(ds2(r[r[i]], r[i], v));
                    }
                    m--;
                }
            }
        }
    }
    POSSIBLE(0);
}
