int N,p[MAXN],deg[MAXN],val[MAXN];
int id[MAXN][2],tot,cir;
vector<int> t[MAXN],to[MAXN * 2];
vector<int> son[MAXN];
queue<int> q;
int dfn[MAXN * 2],low[MAXN * 2],sta[MAXN * 2],instack[MAXN * 2],idx,top;
bool flag = 0;
void Tarjan(int u) {
    dfn[u] = low[u] = ++idx;
    sta[++top] = u;instack[u] = 1;
    for(auto v : to[u]) {
	if(!dfn[v]) {Tarjan(v);low[u] = min(low[v],low[u]);}
	else if(instack[u] == 1){
	    low[u] = min(low[u],dfn[v]);
	}
    }
    if(low[u] == dfn[u]) {
	int k = 0;
	while(1) {
	    int x = sta[top--];
	    ++k;
	    instack[x] = 2;
	    if(x == u) break;
	}
	if(k == cir) flag = 1;
    }
}
void Solve() {
    read(N);
    for(int i = 1 ; i <= N ; ++i) {
	read(p[i]);
	deg[p[i]]++;
    }
    for(int i = 1 ; i <= N ; ++i) {
	if(!deg[i]) q.push(i);
    }
    while(!q.empty()) {
	int u = q.front();q.pop();
	sort(son[u].begin(),son[u].end());
	son[u].erase(unique(son[u].begin(),son[u].end()),son[u].end());
	int m = 0;
	while(m < son[u].size()) {
	    if(son[u][m] != m) break;
	    ++m;
	}
	son[p[u]].pb(m);
	if(!--deg[p[u]]) {
	    q.push(p[u]);
	}
    }
    for(int i = 1 ; i <= N ; ++i) {
	if(deg[i]) {
	    sort(son[i].begin(),son[i].end());
	    son[i].erase(unique(son[i].begin(),son[i].end()),son[i].end());
	    int m = 0,pos = 0;

	    while(1) {
		if(pos >= son[i].size() || son[i][pos] != m) {
		    t[i].pb(m);
		    if(t[i].size() < 2) {++m;}
		    else break;
		}
		else {pos++;++m;}
	    }
	    id[i][0] = ++tot;id[i][1] = ++tot;
	    ++cir;
	}
    }
    for(int i = 1 ; i <= N ; ++i) {
	if(deg[i]) {
	    int f = p[i];
	    to[id[f][0]].pb(id[i][t[f][0] == t[i][0]]);
	    to[id[f][1]].pb(id[i][t[f][1] == t[i][0]]);
	}
    }
    for(int i = 1 ; i <= tot ; ++i) {
	if(!dfn[i]) Tarjan(i);
    }
    if(flag) puts("POSSIBLE");
    else puts("IMPOSSIBLE");
}
