const int MAXN = 2e5 + 5;

struct Edge
{
	int next,to;
}e[MAXN];
int head[MAXN],etot=0;
inline void add(int u,int v)
{
	e[++etot]=(Edge){ head[u],v};
	head[u]=etot;
}

int pre[MAXN];

vector<int> cir;
bool vis[MAXN], ins[MAXN];
int dfs_cir(int u)
{
	vis[u] = 1; ins[u] = 1;
	for(int i=head[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(ins[v]){ cir.push_back(u); ins[u]=0; return v;}

		int res = dfs_cir(v);
		if(res){ cir.push_back(u); ins[u]=0; return res==u? 0: res;}
	}
	ins[u] = 0;
	return 0;
}

bool incir[MAXN];

inline int get_mex(vector<int> &vec,int need)
{
	for(int i=0; i<(int)vec.size(); ++i)
	{
		if(vec[i] > need) return need;
		if(vec[i] == need) ++need;
 	}
 	return need;
}

int val[MAXN];
vector<int> nxt[MAXN];
void get_val(int u)
{
	for(int i=head[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(incir[v]) continue;
		get_val(v);

		nxt[u].push_back(val[v]);
	}

	sort(nxt[u].begin(),nxt[u].end());

	val[u] = get_mex(nxt[u], 0);
}

bool check(int val_lst)
{
	int lst = val_lst;

	for(int k=0; k<(int)cir.size(); ++k)
	{
		int u = cir[k];
		if(val[u] == lst) lst = get_mex(nxt[u], val[u]+1);
		else lst = val[u];
	}
	return lst == val_lst;
}

int main(void)
{
	int n;
	scanf("%d",&n);
	for(int i=1; i<=n; ++i) scanf("%d",&pre[i]);

	for(int i=1; i<=n; ++i) add(pre[i], i);

	for(int i=1; i<=n; ++i)
		if(!vis[i]) dfs_cir(i);
	for(int i=0; i<(int)cir.size(); ++i)
		incir[cir[i]] = 1;

	if((int)cir.size() <= 1) return printf("IMPOSSIBLE"), 0;

	for(int i=0; i<(int)cir.size(); ++i)
		get_val(cir[i]);

	int u = cir.back();
	if(check(val[u]))
		printf("POSSIBLE");
	else if(check(get_mex(nxt[u], val[u]+1)))
		printf("POSSIBLE");
	else
		printf("IMPOSSIBLE");
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int MAX_N=2e5+10;

int N,pos=-1;
vector<int> G[MAX_N];
bool seen[MAX_N],finished[MAX_N];
stack<int> hist;
set<int> cycle;
int par[MAX_N],grundy[MAX_N][2];

void dfs1(int v){
    seen[v]=true; hist.emplace(v);
    for (int u:G[v]){
        if (finished[u]) continue;
        if (seen[u]&&!finished[u]){
            pos=u; return;
        }
        dfs1(u);
        if (~pos) return;
    }
    finished[v]=true; hist.pop();
}

void dfs2(int v,int p){
    set<int> mex;
    for (int u:G[v]){
        if (u==p) continue;
        if (p<0&&cycle.count(u)) continue;
        dfs2(u,v);
        mex.emplace(grundy[u][0]);
    }
    if (~p){
        for (int i=0;;++i){
            if (!mex.count(i)){
                grundy[v][0]=i;
                break;
            }
        }
    } else {
        int ok=0;
        for (int i=0;;++i){
            if (!mex.count(i)){
                if (ok){grundy[v][1]=i; break;}
                else {grundy[v][0]=i; ok=1;}
            }
        }
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N; cin >> N;
    for (int i=0;i<N;++i){
        cin >> par[i];
        G[--par[i]].emplace_back(i);
    }
    for (int i=0;i<N;++i){
        if (!seen[i]) dfs1(i);
    }
    while(!hist.empty()){
        cycle.emplace(hist.top());
        hist.pop();
    }
    for (int v:cycle) dfs2(v,-1);
    int s=*cycle.begin();
    for (int i=0;i<2;++i){
        vector<int> G(N);
        int now=s; G[s]=grundy[s][i];
        while(par[now]!=s){
            int p=par[now];
            G[p]=(G[now]==grundy[p][0]?grundy[p][1]:grundy[p][0]);
            now=p;
        }
        if ((G[now]==grundy[s][0])==i){
            cout << "POSSIBLE" << '\n';
            return 0;
        }
    }
    cout << "IMPOSSIBLE" << '\n';
}

