bitset<200010> cyc;

bool dfs(int u) {
	vis[u] = 1;
	for(int v: ed[u]) {
		if (!vis[v]) {
			if (dfs(v)) {
				vec.pb(u);
				cyc[u] = 1;
				return 1;
			}
		} else if (vis[u] == 1) {
			cyc[u] = 1;
			vec.pb(u);
			return 1;
		}
	}
	vis[u] = 2;
	return 0;
}

void dfs2(int u) {
	for(int v: ed[u]) {
		if (!cyc[v]) dfs2(v);
	}
	for(int v: ed[u]) if (!cyc[v]) arr[lo[v]]++;
	int ans = 0;
	while (arr[ans]) ans++;
	lo[u] = ans++;
	while (arr[ans]) ans++;
	hi[u] = ans;
	for(int v: ed[u]) if (!cyc[v]) arr[lo[v]]--;
}

int bt(int st, int n, int cur) {
	if (cur == fin - 1) {
		if (n == 0 && st == 0) return lo[vec[0]] != lo[vec[cur]]; 
		if (n == 1 && st == 0) return lo[vec[0]] != hi[vec[cur]]; 
		if (n == 0 && st == 1) return hi[vec[0]] != lo[vec[cur]]; 
		if (n == 1 && st == 1) return hi[vec[0]] != hi[vec[cur]]; 
	}
	if (dp[st][n][cur] != -1) return dp[st][n][cur];
	if (n == 0) {
		if (lo[vec[cur]] != lo[vec[cur + 1]] && bt(st,0,cur + 1)) return dp[st][n][cur] = 1;
		if (lo[vec[cur]] != hi[vec[cur + 1]] && bt(st,1,cur + 1)) return dp[st][n][cur] = 1;
	} else {
		if (hi[vec[cur]] != lo[vec[cur + 1]] && bt(st,0,cur + 1)) return dp[st][n][cur] = 1;
		if (hi[vec[cur]] != hi[vec[cur + 1]] && bt(st,1,cur + 1)) return dp[st][n][cur] = 1; 
	}
	return dp[st][n][cur] = 0;
}


int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);
	//freopen("test.txt", "r", stdin);
    cin >> n;
    int x;
    FOR(i,0,n) {
    	cin >> x;
    	x--;
    	ed[x].pb(i);
    }
    FOR(i,0,n) {
    	if (!vis[i]) dfs(i);
    }
    for(int c: vec) dfs2(c);
    fin = vec.size();
    memset(dp,-1,sizeof dp);
    if (bt(0,0,0) || bt(1,1,0)) cout << "POSSIBLE";
    else cout << "IMPOSSIBLE";
}

