int one(int s){
	EACH(j,rev[s])return *j;
	return -1;
}

bool canDo(){
	int start = -1;
	REP(i,n){
		if(ectn[i]==0){
			EACH(j,rev[i])val[*j]=1;
		}else{
			if(start==-1)start=i;
		}
	}
	int now = start;
	if(!val[now])return true;
	now=one(now);
	while(now!=start){
		if(!val[now])return true;
		now=one(now);
	}
	return false;
}

