using namespace std;
int n;
vector<int> p;
vector<vector<int>> adj;
vector<bool> in_cyc;
vector<bool> vis;
vector<int> ass;
int cyc_root;

int mex(vector<int>& v){
  if(v.empty())
    return 0;
  sort(v.begin(), v.end());
  if(v[0] != 0)
    return 0;
  for(int i = 1;i < v.size();i++){
    if(v[i] > v[i - 1] + 1)
      return v[i - 1] + 1;
  }
  return v.back() + 1;
}
int next_mex(vector<int>& v, int x){
  unordered_set<int> ss;
  for(auto el : v)
    ss.insert(el);
  x++;
  while(ss.find(x) != ss.end())
    x++;
  return x;
}
void detect_cycle(){
  vector<bool> v(n);
  int x = 0;
  v[0] = 1;
  while(!v[p[x]]){
    x = p[x];
    v[x] = 1;
  }

  cyc_root = x;
  in_cyc[x] = 1;
  x = p[x];
  while(x != cyc_root){
    in_cyc[x] = 1;
    x = p[x];
  }
//  cout << cyc_root << endl;
}

void dfs(int u){
  vis[u] = 1;
  vector<int> chs;
  for(auto el : adj[u]){
    assert(!in_cyc[el]);
    if(!vis[el])
      dfs(el);
    chs.push_back(ass[el]);
  }
  ass[u] = mex(chs);
}

