	vis[k]=D;s[++top]=k;
	for(int i=home[k];~i;i=e[i].next){
		if(!vis[e[i].k]) dfs(e[i].k);
		else if(vis[e[i].k]==D){
			tot=top;
			for(int p=1;p<=top;p++) h[s[p]]=s[p==1?top:p-1],nxt[s[p]]=s[p==top?1:p+1],a[p]=s[p];
		}
	}
	top--;
}
