	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F){
		dfs(e[i].k,k);
	}
	for(int i=home[k];~i;i=e[i].next) if(e[i].k!=F){
		sum[f[e[i].k]]=k;
	}
	for(int i=0;i<=20;i++) if(sum[i]!=k){
		f[k]=i;break;
	}
}
