	for(int i=f[a[1]],o=f[a[1]]+1;i<=o;i++){
		memset(sum,0,sizeof(sum));
		bool t=1;
		f[a[1]]=i;
		for(int p=home[a[1]];~p;p=e[p].next) if(e[p].k!=nxt[a[1]]) if(f[e[p].k]==i){
			t=0;break;
		}
		if(!t) continue;
		for(int p=tot;p;p--){
			for(int j=home[a[p]];~j;j=e[j].next) sum[f[e[j].k]]=p;
			for(int j=0;j<=20;j++) if(sum[j]!=p){
				f[a[p]]=j;break;
			}
		}
		if(f[a[1]]!=i) t=0;
		if(t) return 1;
	}
	return 0;
}
