        int k = 0;
        for(int i:forb[x]){
            if(i != k) break;
            ++k;
        }
        ans[x] = k;
        forb[p[x]].insert(k);
        forbCP[p[x]].insert(k);
        if(--deg[p[x]] == 0) q.push(p[x]);
    }

    if(forbCP[st].count(bad)){
        //cerr<<"2"<<endl;
