//サイクルを一周して最後に矛盾がないかどうか
bool cycle(int x, int y){
	int i = p[x];
	int pre = y;
	while(i!=x){
		set<int> s;
		s.insert(pre);
		for(int j:G[i]){
			s.insert(a[j]);
		}
		int z = 0;
		while(s.count(z)){
			z++;
		}
		a[i] = z;
		pre = a[i];
		i = p[i];
	}

	set<int> st;
	st.insert(pre);
	for(int j=0;j<G[x].size();j++){
		st.insert(a[j]);
	}
	int z = 0;
	while(st.count(z)){
		z++;
	}
	return y==z;
}

