		cin >> p[i];
		p[i]--;
		G[p[i]].push_back(i);
	}

	for(i=0;i<n;i++){
		if(G[i].size()==0){
			que.push(i);
		}
		a[i]  = -1;
	}

	while(!que.empty()){
		set<int> s;
		int x = que.front();
		que.pop();
		if(a[x]>=0) continue;
		for(j=0;j<G[x].size();j++){
			if(a[G[x][j]]<0){
				z = 1;
			}
			s.insert(a[G[x][j]]);
		}
		if(z){
			z = 0;
			continue;
		}
		int y = 0;
		while(s.count(y)){
			y++;
		}
		a[x] = y;
		que.push(p[i]);
	}

	for(i=0;i<n;i++){
		if(a[i]<0){
			z = i;
			break;
		}
	}

	set<int> st;
	for(i=0;i<G[z].size();i++){
		st.insert(a[i]);
	}
	j = 0;
	while(st.count(j)){
		j++;
	}
	int k = j;
	j++;
	while(st.count(j)){
		j++;
	}
	int l = j;
	if(cycle(z,k) || cycle(z,j)){
		cout << "POSSIBLE" << endl;
		return 0;
	}
	cout << "IMPOSSIBLE" << endl;
}

