std::vector <int> e[N];
int vis[N];
std::pair <int, int> val[N];

int get_mex(std::set<int>& mex) {
    int p = 0;
    for (auto i : mex) {
        if (p != i)
            break;
        ++p;
    }
    return p;
}

void dfs(int u, int p = 0) {
    std::set <int> mex1;
    std::set <int> mex2;
    vis[u] = 1;
    bool is_cycle = false;
    for (int v : e[u]) {
        if (v != p) {
            if (vis[v] == 1) {
                is_cycle = true;
                continue;
            }
            if (vis[v] == 0)
                dfs(v, u);
            mex1.insert(val[v].first);
            mex2.insert(val[v].second);
        }
    }
    val[u].first = get_mex(mex1);
    if (is_cycle)
        mex2.insert(val[u].first);
    val[u].second = get_mex(mex2);

    vis[u] = 2;
}

bool check(int u) {
    for (int v : e[u]) {
        if (val[v].first == val[u].first && val[v].second == val[u].second)
            return false;
    }
    return true;
}

