void dfs1 (int v) {
    used[v] = true;
    for (size_t i=0; i<g[v].size(); ++i)
        if (!used[ g[v][i] ])
            dfs1 (g[v][i]);
    order.push_back (v);
}

void dfs2 (int v) {
    used[v] = true;
    component.push_back (v);
    for (size_t i=0; i<gr[v].size(); ++i)
        if (!used[ gr[v][i] ])
            dfs2 (gr[v][i]);
}

void go_tree(int v) {
    www[v] = 1;
    vector<int> was;
    for(auto u: gg[v]) {
        if(v == u) continue;
        go_tree(u);
        was.push_back(mex[u]);
    }
    sort(was.begin(), was.end());
    int cur = 0;
    int l = 0;
    while(l < (int)was.size()) {
        while(l < (int)was.size() && was[l] < cur)
            l++;
        if(l == (int)was.size() || was[l] > cur) {
            mex[v] = cur;
           return;
        }
        while(l < (int)was.size() && was[l] == cur) l++;
        cur++;
    }
    mex[v] = cur;
}

