    for (int i=0; i<n; ++i)
        if (!used[i])
            dfs1 (i);
    used.assign (n, false);
    for (int i=0; i<n; ++i) {
        int v = order[n-1-i];
        if (!used[v]) {
            dfs2 (v);
            for(auto v: component)
                colors[v] = cur;
            cur++;
            cmps.push_back(component);
            component.clear();
        }
    }
    for(auto x: e) {
        gg[colors[x.first]].push_back(colors[x.second]);
    }
    for(int i = 1; i < cur; i++) {
        if(!www[i]) {
            go_tree(i);
        }
    }
    int now = 0;
    for(auto x: cmps) {
        now++;
        if((x.size() & 1) && mex[now] + 1 <= 1 && x.size() > mex[now] + 1) {
