int get_next_val(int u, int to_add){
    int val = 0;
    if(val == to_add) val++;
    sort(a[u].begin(), a[u].end());
    for(int i = 0; i < a[u].size(); i++){
            if(a[u][i] == val || val == to_add) val++;
    }
    if(val == to_add) val++;
    return val;
}

