    for(int i = 0; i < n; i++){
        if(e[i] == 0) leafs.push_back(i);
    }
    int cnt = n;
    while(leafs.begin() != leafs.end()){
        int u = leafs.front();
        leafs.pop_front();
        int val = get_next_val(u, -1);
        a[ pr[u] ].push_back(val);
        e[pr[u]]--;
        if(e[ pr[u] ] == 0) leafs.push_back(pr[u]);
        cnt--;
    }
