    int root = 0;
    while(e[root] == 0) root++;
    int prev_root_res = -1;

    for(int i = 0; i < 2; i++){
        int root_res = get_next_val(root, prev_root_res);
        int u = pr[root];
        int to_add = root_res;
        while(pr[u] != root){
            u = pr[u];
            to_add = get_next_val(u, to_add);
        }
        int fin_val = get_next_val(u, to_add);
        bool ok = fin_val != root_res;
        if(prev_root_res != -1 && prev_root_res != fin_val) ok = false;
        if(ok){cout << "POSSIBLE" << endl; return 0;}
        prev_root_res = root_res;
    }
    cout << "IMPOSSIBLE" << endl;
    return 0;
}

