typedef long long lint;

vector<vector<int>> adj;
vector<bool> mark, in_cycle;

vector<int> stack, cycle;
vector<bool> in_stack;

bool find_cycle(int v) {
  mark[v] = true;
  stack.push_back(v);
  in_stack[v] = true;
  for (int u : adj[v]) {
    if (in_stack[u]) {
      while (stack.back() != u) {
        cycle.push_back(stack.back());
        in_cycle[stack.back()] = true;
        stack.pop_back();
      }
      cycle.push_back(u);
      in_cycle[u] = true;
      stack.pop_back();
      reverse(cycle.begin(), cycle.end());
      return true;
    } else if (!mark[u] && find_cycle(u)) {
      return true;
    }
  }
  in_stack[v] = false;
  stack.pop_back();
  return false;
}

int get_gap(vector<int> &values) {
  sort(values.begin(), values.end());
  if (values.empty() || values[0] > 0)
    return 0;
  for (int i = 0; i + 1 < (int)values.size(); ++i)
    if (values[i] + 1 < values[i + 1])
      return values[i] + 1;
  return values.back() + 1;
}

vector<int> value;

int get_value(int v) {
  vector<int> adj_values;
  if (value[v] != -1)
    return value[v];
  for (int u : adj[v])
    adj_values.push_back(get_value(u));
  return get_gap(adj_values);
}

int main() {
  int n;
  scanf("%d", &n);
  adj.resize(n);
  for (int i = 0; i < n; ++i) {
    int p;
    scanf("%d", &p), --p;
    adj[p].push_back(i);
  }
  mark.resize(n, false);
  in_cycle.resize(n, false);
  in_stack.resize(n, false);
  for (int i = 0; i < n; ++i)
    if (!mark[i]) {
      if (find_cycle(i))
        break;
    }

  for (int i = 0; i < (int)cycle.size(); ++i) {
    int ci = cycle[i], cip1 = cycle[(i + 1) % cycle.size()];
    bool ok = false;
    for (int u : adj[ci])
      if (u == cip1) {
        ok = true;
        break;
      }
    assert(ok);
  }

  value.resize(n, -1);
  for (int v = 0; v < n; ++v)
    if (in_cycle[v])
      for (int u : adj[v])
        if (!in_cycle[u])
          value[u] = get_value(u);

  const int c0 = cycle[0];
  vector<int> c0values;
  for (int u : adj[c0])
    if (!in_cycle[u])
      c0values.push_back(value[u]);
  vector<int> cands;
  cands.push_back(get_gap(c0values));
  c0values.push_back(cands[0]);
  cands.push_back(get_gap(c0values));
  bool possible = false;
  for (int cand : cands) {
    value[c0] = cand;
    for (int i = (int)cycle.size() - 1; i > 0; --i) {
      int ci = cycle[i];
      value[ci] = -1;
      value[ci] = get_value(ci);
    }
    value[c0] = -1;
    if (get_value(c0) == cand) {
      possible = true;
      break;
    }
  }
  if (possible) printf("POSSIBLE\n");
  else printf("IMPOSSIBLE\n");
  return 0;
}

