		--x;
		out[x].push_back(i);
		in[i] = x;
	}
	for(int i = 0; i < n; ++i) if(cycle[i] == 0) dfs(i, -1);
	for(int i = 0; i < n; ++i) {
		if(cycle[i] == CYCLE) getgrundy(i);
	}
	int nxt;
	for(int i : out[st]) {
		if(cycle[i] == CYCLE) {
			nxt = i;
		}
	}
	return cout << "POSSIBLE" << endl;
	if(chk(nxt, grundy[nxt] + (grundy[st] == grundy[nxt]), grundy[st])) cout << "POSSIBLE" << endl;
