vi al[200000];
int n;
bool act[200000],vis[200000];
int mex[200000];
vi cyc;

vi seen;

int mx(int i,int o=-1) {
	if (mex[i]!=-1) return mex[i];
	seen.clear();
	for (int j:al[i]) if (j!=o) seen.push_back(mex[j]);
	sort(seen.begin(),seen.end());
	seen.resize(unique(seen.begin(),seen.end())-seen.begin());
	for (int c=0;c<seen.size();c++) if (seen[c]!=c) {
		return mex[i]=c;
	}
	return mex[i]=seen.size();
}

bool tmx(int i) {
	int v=mex[i];
	mex[i]=-1;
	bool res=mx(i)==v;
	mex[i]=v;
	return res;
}

bool consist() {
	for (int i:cyc) if (!tmx(i)) return 0;
	return 1;
}


bool dfs(int i) {
	if (vis[i]) return 0;
	if (act[i]) return 1;
	act[i]=1;
	bool incyc=0;
	for (int j:al[i]) {
		incyc=dfs(j)||incyc;
	}
	vis[i]=1;
	if (incyc) {
		cyc.push_back(i);
		return 1;
	}

	mx(i);
	return 0;
}

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n;
	for (int i=0;i<n;i++) {
		int u;cin >> u;u--;
		al[u].push_back(i);
	}

	fill(mex,mex+n,-1);

	for (int i=0;i<n;i++) if (!vis[i]) {
		dfs(i);
		if (cyc.size()) {
			//if (cyc.size()%2) cout << "IMPOSSIBLE\n";
			//else cout << "POSSIBLE\n";
			//return 0;
			mex[cyc[0]]=-1;
			int mx0=mx(cyc[0],cyc.back());
			for (int j=1;j<cyc.size();j++) mex[cyc[j]]=-1,mx(cyc[j]);
			if (!consist()) {
				mex[cyc.back()]=mx0;
				for (int j=0;j+1<cyc.size();j++) {
					mex[cyc[j]]=-1;
					mx(cyc[j]);
				}
				if (!consist()) {
					cout << "IMPOSSIBLE\n";
					return 0;
				}
			}
			cyc.clear();
		}
	}

	cout << "POSSIBLE\n";

}

#include <stdio.h>
