using namespace std;

set<int> S[200200],T[200200];
int N,G[200200],D[200200],M[200200];

int main()
{
	scanf ("%d",&N);
	for (int i=1;i<=N;i++){
		scanf ("%d",&G[i]);
		D[G[i]]++;
	}

	queue<int> Q;
	for (int i=1;i<=N;i++) if (D[i] == 0){
		Q.push(i);
	}

	while (!Q.empty()){
		int x = Q.front(); Q.pop();
		for (auto &m : S[x]){
			if (m == M[x]) M[x]++;
			else break;
		}
		S[G[x]].insert(M[x]);
		if (--D[G[x]] == 0) Q.push(G[x]);
	}

	for (int x=1;x<=N;x++) if (D[x] != 0){
		for (auto &m : S[x]){
			if (m == M[x]) M[x]++;
			else break;
		}

		for (int i=1;i<=N;i++) if (D[i] != 2) T[i] = S[i];
		int t = x;
		while (G[t] != x){
			T[G[t]].insert(M[t]);
			t = G[t];
			for (auto &m : T[t]){
				if (m == M[t]) M[t]++;
				else break;
			}
		}

		if (M[x] != M[t]){
			puts("POSSIBLE");
			return 0;
		}

		x = t;
		for (int i=1;i<=N;i++) if (D[i] != 2) T[i] = S[i];
		int o = M[t];
		while (true){
			T[G[t]].insert(M[t]);
			t = G[t];
			M[t] = 0;
			for (auto &m : T[t]){
				if (m == M[t]) M[t]++;
				else break;
			}
			if (t == x) break;
		}

		if (o == M[t]){
			puts("POSSIBLE");
			return 0;
		}
		break;
	}
	puts("IMPOSSIBLE");
	return 0;
}

