std::unordered_set<int128_t> loop_set;
Directed_Graph dg(MAX_N);
std::vector<int128_t> gr;

int128_t cal_gr(const std::unordered_set<int128_t>& st) {
    rep (i, 0, N) {
        if (!st.count(i)) {
            return i;
        }
    }
    assert(false);
}

void dfs(int128_t node) {
    std::unordered_set<int128_t> st;
    for (auto e : dg.G[node]) {
        if (!loop_set.count(e.to)) {
            dfs(e.to);
            st.insert(gr[e.to]);
        }
    }
    if (!loop_set.count(node)) {
        gr[node] = cal_gr(st);
    }
}

bool check(int128_t node, int128_t g) {
    int128_t tmp = node;
    auto gcp = gr;
    gcp[node] = g;
    while (p[tmp] != node) {
        tmp = p[tmp];
        std::unordered_set<int128_t> st;
        for (auto e : dg.G[tmp]) {
            st.insert(gcp[e.to]);
        }
        gcp[tmp] = cal_gr(st);
    }

    std::unordered_set<int128_t> st2;
    for (auto e : dg.G[node]) {
        st2.insert(gcp[e.to]);
    }
    return cal_gr(st2) == g;
}

