    int128_t tmp = 1;
    st.insert(tmp);

    while (st.count(p[tmp]) == 0) {
        tmp = p[tmp];
        st.insert(tmp);
    }

    while (loop_set.count(p[tmp]) == 0) {
        tmp = p[tmp];
        loop_set.insert(tmp);
    }

    rep (i, 1, N) {
        if (loop_set.count(i)) {
            dfs(i);
        }
    }

    std::unordered_set<int128_t> st2;
    for (auto e : dg.G[tmp]) {
        if (!loop_set.count(e.to)) {
            st2.insert(gr[e.to]);
        }
    }

    int128_t cnt = 0;
    rep (i, 0, N + 1) {
        if (!st2.count(i)) {
            if (check(tmp, i)) {
