    }

    for (int i = 0; i < vc.size(); ++i)
        cycle[vc[i]] = vc[(i + vc.size() - 1) % vc.size()];

    for (int i = 1; i <= n; ++i)
        grundy[i] = -1;
    for (int i = 1; i <= n; ++i)
        dfs_grundy(i);

