void dfs(int v)
{
  used[v] = true;
  for (int i = 0; i < G[v].size(); i++) {
    if(!used[G[v][i]]) dfs(G[v][i]);
  }
  vs.push_back(v);
}

void rdfs(int v, int k)
{
  used[v] = true;
  cmp[v] = k; GG[k].push_back(v);
  for (int i = 0; i < rG[v].size(); i++) {
    if(!used[rG[v][i]]) rdfs(rG[v][i], k);
  }
}

int scc()
{
  memset(used, 0, sizeof(used));
  vs.clear();
  for (int v = 0; v < V; v++) {
    if(!used[v]) dfs(v);
  }

  memset(used, 0, sizeof(used));
  int k = 0;
  for (int i = vs.size()-1; 0 <= i; i--) {
    if(!used[vs[i]]){
      GG.push_back(vector<int>());
      rdfs(vs[i], k++);
    }
  }

  return k;
}

bool LOOP[MAX_N];

int dist[MAX_N];
int grundy[MAX_N];

void check(int pos)
{
  if(used[pos]){
    return;
  }

  used[pos] = true;

  for (int i = 0; i < G[pos].size(); i++) {
    if(LOOP[G[pos][i]]){
      check(G[pos][i]);
      break;
    }
  }

  priority_queue<int, vector<int>, greater<int>> Set;

  for (int i = 0; i < G[pos].size(); i++) {
    Set.push(grundy[G[pos][i]]);
  }

  int g = 0;
  while(Set.size()){
    int p = Set.top();
    Set.pop();
    if(p == g){
      g++;
    }
    else{
      break;
    }
  }

  grundy[pos] = g;

  return;
}

