    int w = rg[v][0];
    if (a[w] != -1) {
        if (a[w] == 2 && a[v] != 1) r = false;
        if (a[w] == 1 && a[v] == 1) r = false;
        if (a[w] == 0 && a[v] == 0) r = false;
