typedef long long ll;

ll N;
vector<ll> Parent;
vector<vector<ll>> Kids;
ll Root;
vector<ll> A;

void find_root() {
  vector<bool> Seen;
  Seen.resize(N);
  ll v;
  for (v = 0; !Seen[v]; v = Parent[v]) Seen[v] = true;
  Root = v;
}
ll dfs(ll v, ll mode) {
  unordered_set<ll> kids_as;
  for (ll w : Kids[v])
    if (w != Root) kids_as.insert(dfs(w, mode));
  vector<ll> a_candidates;
  for (ll x = 0; a_candidates.size() < 2; ++x)
    if (!kids_as.count(x)) a_candidates.push_back(x);
  return A[v] = v == Parent[Root] ? a_candidates[mode] : a_candidates[0];
}
bool check() {
  ll v = Parent[Root];
  unordered_set<ll> needed;
  for (ll x = 0; x < A[v]; ++x) needed.insert(x);
  for (ll w : Kids[v]) {
    if (A[v] == A[w]) return false;
    needed.erase(A[w]);
  }
  return needed.empty();
}
bool solve() {
  find_root();
  for (ll mode : {0, 1}) {
    A.resize(N, -1);
    dfs(Root, mode);
    if (check()) return true;
  }
  return false;
}
int main() {
  cin >> N;
  Parent.resize(N);
  Kids.resize(N);
  for (ll v = 0; v < N; ++v) {
    ll p;
    cin >> p;
    --p;
    Parent[v] = p;
    Kids[p].push_back(v);
  }
  cout << (solve() ? "POSSIBLE" : "IMPOSSIBLE") << endl;
  return 0;
}

