	rep (i, 1, n) if (deg[i] == 0) q[++t] = i;
	while (h != t) {
		int x = q[++h], y = bac[x];
		if (--deg[y] == 0) q[++t] = y;
	}
	rep (i, 1, n) if (deg[i]) {
