	sort(q+1, q+tq+1);
	tq = unique(q+1, q+tq+1) - (q+1);

	for (int cur = 0, i = 1; ; ++ cur) {
		if (i <= tq && q[i] == cur) {++ i; continue;}
		if (val[x][0] == -1) val[x][0] = cur;
