ll find_aval(const set<ll> &nexts)
{
    rep (aval, 10000000000LL) {
        if (nexts.find(aval) == nexts.end()) {
            return aval;
        }
    }

    assert(false);
}

ll find_aval2(const set<ll> &nexts)
{
    ll cnt = 0LL;

    rep (aval, 10000000000LL) {
        if (nexts.find(aval) == nexts.end()) {
            cnt++;
            if (cnt == 2) return aval;
        }
    }

    assert(false);
}

ll find_aval_n(const set<ll> &nexts, ll nval)
{
    rep (aval, 10000000000LL) {
        if (nexts.find(aval) == nexts.end() && aval != nval) {
            return aval;
