vector<int> children[252521];

int cycle[252521];
int m = 0;
bool cycled[252521];

int calcorder[252521];
int calcorderhead = 0;
int calcordertail = 0;

int it = 0;

#define MAX_DEG 19
int val[252521];
bool deg[MAX_DEG+2];

void calc(int x){
    REP(i,children[x].size()){
        int v = val[children[x][i]];
        deg[v]=true;
    }
    REP(d,MAX_DEG+1)if(!deg[d]){
        val[x] = d;
        break;
    }
    REP(i,MAX_DEG+2)deg[i]=false;
}

int main(void){
    scanf("%d",&n);
    REP(i,n){
        scanf("%d",p+i);
        p[i]--;
        children[p[i]].push_back(i);
    }
    REP(i,n)it = p[it];
    do{
        cycle[m++] = it;
        cycled[it] = true;
        it = p[it];
    }while(cycle[0]!=it);
    REP(i,m){
        int x = cycle[i];
        REP(j,children[x].size()){
            int y = children[x][j];
            if(cycled[y])continue;
            calcorder[calcordertail++] = y;
        }
    }
    while(calcorderhead != calcordertail){
        int x = calcorder[calcorderhead++];
        REP(j,children[x].size()){
            calcorder[calcordertail++] = children[x][j];
        }
    }
    REP(i,n)val[i] = MAX_DEG+1;
    while(calcordertail--){
        int x = calcorder[calcordertail];
        calc(x);
    }
    // first challenge
    REP(i,m)calc(cycle[i]);
    int tst = val[cycle[0]];
    calc(cycle[0]);
    if(tst == val[cycle[0]]){
        puts(possible);
        return 0;
    }
    REP(i,m-1)calc(cycle[i+1]);
    tst = val[cycle[0]];
    calc(cycle[0]);
    if(tst == val[cycle[0]]){
        puts(possible);
    }else{
        puts(impossible);
    }
    return 0;
}

