int body(int &argc, char **argv) {
    using namespace debug;
    auto N = read<i64>();
    auto ps = read<i64>(N);
    FORE (p, ps) {
        p -= 1;
    }

    auto edges = V<V<i64>>(N, V<i64>());
    auto edges2 = V<i64>(N);
    REP (i, N) {
        // ps[i] -> i
        auto n1 = ps[i];
        i64 n2 = i;
        edges[n1].push_back(n2);
        edges2[n2] = n1;
    }

    // Find cycle
    auto s = stack<V<i64>>();
    V<i64> cycle;
    REP (i, N) {
        s.push({i});
    }

    while (!s.empty()) {
        auto p = s.top();
        s.pop();

        if (p.size() > 1 && p.back() == p.front()) {
            cycle = p;
            break ;
        }

        FORE(n, edges[p.back()]) {
            auto p2 = p;
            p2.push_back(n);
            s.push(p2);
        }
    }

    V<i64> values(N, -1);
    auto fill_value = [&](i64 n, auto f) -> i64 {
        if (values[n] != -1) {
            return values[n];
        }

        unordered_set<i64> xs;
        FORE (n2, edges[n]) {
            xs.insert(f(n2, f));
        }

        REP(i, xs.size() + 1) {
            if (xs.find(i) == xs.end()) {
                values[n] = i;
                return i;
            }
        }
    };

    REP (i, N) {
        if (find(cycle.begin(), cycle.end(), i) != cycle.end()) {
            continue;
        }

        fill_value(i, fill_value);
    }

    bool possible = false;
    V<i64> used;
    while (true) {
        FORR(i, 0, cycle.size() - 1) {
            auto n = cycle[i];

            unordered_set<i64> xs;
            FORE (n2, edges[n]) {
                xs.insert(values[n2]);
            }

            REP(j, xs.size() + 1) {
                if (xs.find(j) == xs.end()) {
                    if (i == 0) {
                        if (values[n] == j) {
                            possible = true;
                            goto ANS;
                        }

                        if (find(used.begin(), used.end(), j) != used.end()) {
                            possible = false;
                            goto ANS;
                        }
                        used.push_back(j);
                    }

                    values[n] = j;
                    break ;
                }
            }
        }
    }
    ANS:

    cout << (possible ? "POSSIBLE": "IMPOSSIBLE") << endl;

    return 0;
}

