string solve() {
  int N;
  cin >> N;
  vector<vector<int>> G(N);
  for(auto i=0; i<N; ++i) {
    int p;
    cin >> p;
    G[p-1].emplace_back(i);
  }

  vector<int> Grundy(N, -1);

  function<int(int, int)> dfs = [&](auto u, auto d) {
    if(Grundy[u]!=-1) return Grundy[u];
    Grundy[u] = N;
    set<int> S;
    for(auto v: G[u]) S.emplace(dfs(v, d));
    for(auto i=0; i<N; ++i) if(!S.count(i)) if(!S.count(N) || d--==0) return Grundy[u] = i;
    assert(false);
  };

  auto check = [&]() {
    for(auto u=0; u<N; ++u) {
      set<int> S;
      for(auto v: G[u]) {
        if(Grundy[u]==Grundy[v]) return false;
        S.emplace(Grundy[v]);
      }
      for(auto i=0; i<Grundy[u]; ++i) if(!S.count(i)) return false;
    }
    return true;
  };

  for(auto d: {0, 1}) {
    Grundy.assign(N, -1);
    for(auto v=0; v<N; ++v) dfs(v, d);
    if(check()) return "POSSIBLE";
  }
  return "IMPOSSIBLE";
}

