bool circle[N];
int pre[N];
int dp[N];
bool instack[N];

void DFS1(int u) {
  instack[u] = true;
  for (auto& v : a[u]) {
    if (pre[v] < 0) {
      pre[v] = u;
      DFS1(v);
    } else {
      if (instack[v]) {
        assert(C.empty());
        while (u != v) {
          circle[u] = true;
          C.push_back(u);
          u = pre[u];
        }
        circle[v] = true;
        C.push_back(v);
      }
    }
  }
  instack[u] = false;
}

void DFS(int u) {
  dp[u] = -1;
  for (auto& v : a[u]) {
    if (circle[v]) continue;
    DFS(v);
    dp[u] = max(dp[u], dp[v]);
  }
  dp[u] += 1;
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    int x;
    scanf("%d", &x);
    --x;
    a[x].push_back(i);
  }
  fill(pre, pre + n, -1);
  for (int i = 0; i < n; ++i) {
    if (pre[i] >= 0) continue;
    pre[i] = i;
    DFS1(i);
  }
  for (auto& u : C) {
    DFS(u);
  }
  bool found = false;
  for (int i = 0; i < C.size(); ++i) {
    if (dp[i]) found = true;
  }
  if (!found) {
    puts(C.size() % 2 == 0 ? "POSSIBLE" : "IMPOSSIBLE");
    return 0;
  }
  C.push_back(C[0]);
  found = false;
  for (int i = 0; i < C.size() - 1; ++i) {
    if (dp[C[i]] && dp[C[i + 1]] && dp[C[i]] == dp[C[i + 1]]) {
      found = true;
    }
  }
  puts(!found ? "POSSIBLE" : "IMPOSSIBLE");
  return 0;
}

