bool dfs_findloop(int v){
    used[v]=true;
    bool res=false;
    for(int u:G[v]){
        if(!used[u]){
            if(dfs_findloop(u))res=true;
        }else res=true;
    }
    if(res)loop.push_back(v);
    return res;
}

void add_G(int from,int to){
    G[from].push_back(to);
    rG[to].push_back(from);
