class Namori{
public:
    int V;
    vector<vector<int> > G, rG, graph;
    vector<int> deg, loop;
    vector<bool> flag, inloop;
	vector<set<int> > st;
    Namori(int node_size) : V(node_size), G(V), rG(V), deg(V, 0), flag(V, false), inloop(V, false), st(V){}
    void add_edge(int u, int v){
        G[u].push_back(v), rG[v].push_back(u);
        deg[u]++, deg[v]++;
    }
    void dfs(int u){
        loop.push_back(u);
		inloop[u] = true;
        for(int v : G[u]){
            if(flag[v]) continue;
            flag[v] = true;
            dfs(v);
        }
    }
    void build(){
        graph.resize(V);
        queue<int> que;
        for(int i = 0; i < V; i++){
            if(deg[i] == 1){
                que.push(i);
                flag[i] = true;
            }
        }
        while(!que.empty()){
            int p = que.front();
            que.pop();
            for(int v : rG[p]){
                if(flag[v]) continue;
                deg[v]--;
                //サイクルから端
                graph[v].push_back(p);
                //端からサイクル
                graph[p].push_back(v);
                if(deg[v] > 1) continue;
                que.push(v);
                flag[v] = true;
            }
        }
        for(int i = 0; i < V; i++){
            if(flag[i]) continue;
            flag[i] = true;
            dfs(i);
            break;
        }
    }
	int dfs2(int u){
		set<int> hoge;
		each(v, G[u]){
			hoge.insert(dfs2(v));
		}
		int s = 0;
		auto it = hoge.begin();
		while(it != hoge.end()){
			if(*it != s) break;
			it++, s++;
		}
		return s;
	}
	bool alloc(int num){
		vi al(V);
		al[loop[0]] = num;
		auto nst = st;
		rrep(i, len(loop)){
			nst[loop[i]].insert(al[loop[(i+1)%len(loop)]]);
			auto it = nst[loop[i]].begin();
			int s = 0;
			while(it != nst[loop[i]].end()){
				if(*it != s) break;
				it++, s++;
			}
			al[loop[i]] = s;
		}
		return (al[loop[0]] == num);
	}
	bool solve(){
		rep(i,V){
			each(v, graph[i]){
				if(!inloop[v]){
					st[i].insert(dfs2(v));
				}
			}
		}
		int s = loop[0];
		int nw = 0;
		int emp = -1;
		auto it = st[s].begin();
		while(true){
			if(it == st[s].end()){
				if(emp >= 0) break;
				emp = nw++;
				continue;
			}
			if(*it != nw){
				if(emp >= 0){
					break;
				}
				emp = nw++;
				continue;
			}
			it++, nw++;
		}
		if(alloc(emp)){
			return true;
		}else{
			return alloc(nw);
		}
	}
};

