void tree(int v) {
    vector<ll> mex;
    for (auto to : gr[v]) {
        if (s.find(to) == s.end()) {
            tree(to);
            mex.push_back(vals[to]);
        }
    }

    mex.push_back(SIZE);
    sort(mex.begin(), mex.end());

    ll pr = -1;
    for (int i = 0; i < mex.size(); i++) {
        if (pr + 1 < mex[i]) {
            vals[v] = pr + 1;
            break;
        }
        pr = mex[i];
    }
