    for (int i = 0; i < gr.size(); i++) {
        set<ll> s;
        for (auto to : gr[i]) {
            s.insert(vals[to]);
        }
        for (int j = 0; j < vals[i]; j++) {
            if (s.find(j) == s.end()) flag = false;
        }
        if (s.find(vals[i]) != s.end()) flag = false;
    }

    return flag;
}

