            ll u = way[j], pr = way[j - 1];
            if (vals[u] == vals[pr]) vals[u]++;
        }

        if (check()) flag = true;
    }

    if (flag) {
        cout << "POSSIBLE";
    }
    else {
        cout << "IMPOSSIBLE";
    }
}


