int head[MAXN],etot=0;
inline void add(int u,int v)
{
	e[++etot]=(Edge){ head[u],v};
	head[u]=etot;
}

int pre[MAXN];

vector<int> cir;
bool vis[MAXN];
int dfs_cir(int u)
{
	vis[u] = 1;
	for(int i=head[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(vis[v]){ cir.push_back(u); return v;}

		int res = dfs_cir(v);
		if(res){ cir.push_back(u); return res==u? 0: res;}
	}
	return 0;
}

bool incir[MAXN];

inline int get_mex(vector<int> &vec,int need)
{
	for(int i=0; i<(int)vec.size(); ++i)
	{
		if(vec[i] > need) return need;
		if(vec[i] == need) ++need;
 	}
 	return need;
}

int val[MAXN];
vector<int> nxt[MAXN];
void get_val(int u)
{
	for(int i=head[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(incir[v]) continue;
		get_val(v);

		nxt[u].push_back(val[v]);
	}

	sort(nxt[u].begin(),nxt[u].end());

	val[u] = get_mex(nxt[u], 0);
}

bool check(int val_lst)
{
	int lst = val_lst;

	for(int k=0; k<(int)cir.size(); ++k)
	{
		int u = cir[k];
		if(val[u] == lst) lst = get_mex(nxt[u], val[u]+1);
		else lst = val[u];
	}
	return lst == val_lst;
}

