	scanf("%d",&n);
	for(int i=1; i<=n; ++i) scanf("%d",&pre[i]);

	for(int i=1; i<=n; ++i) add(pre[i], i);

	for(int i=1; i<=n; ++i)
		if(!vis[i]) dfs_cir(i);
	for(int i=0; i<(int)cir.size(); ++i)
		incir[cir[i]] = 1;

	if((int)cir.size() <= 1) return printf("POSSIBLE"), 0;

	for(int i=0; i<(int)cir.size(); ++i)
		get_val(cir[i]);

	int u = cir.back();
	if(check(val[u]))
		printf("POSSIBLE");
	else if(check(get_mex(nxt[u], val[u]+1)))
		printf("POSSIBLE");
	else
		printf("IMPOSSIBLE");
	return 0;
}

