int GroupNo[MAX_V];//属する強連結成分のトポロジカル順序

void add_edge__(int from,int to){
	G[from].push_back(to);
	rG[to].push_back(from);
}

void dfs(int v){
	visit[v] = true;
	for(int i=0;i<(int)G[v].size();++i){
		if(!visit[G[v][i]]){
			dfs(G[v][i]);
		}
	}
	vs.push_back(v);
}

void rdfs(int v,int k){
	visit[v] = true;
	GroupNo[v] = k;
	for(int i=0;i<(int)rG[v].size();++i){
		if(!visit[rG[v][i]]){
			rdfs(rG[v][i],k);
		}
	}
}

int scc(){
	visit.assign(V,false);
	vs.clear();
	for(int v=0;v<V;++v){
		if(!visit[v]){
			dfs(v);
		}
	}
	visit.assign(V,false);
	int k=0;
	for(int i=vs.size()-1;i>=0;i--){
		if(!visit[vs[i]]){
			rdfs(vs[i],k++);
		}
	}
	return k;
}
