vector<int> loop,mem;
bool visit[200020] = {0};
bool ele_loop[200020] = {0};
int num[200020] = {0};
int can[200020];

void construct(int v)
{
    if(sum[v] != 0)return;
    int res = 0;
    for(int i = 0; i < to[v].size(); i++)
    {
        can[num[to[v][i]]] = v;
    }
    for(int i = 0; i < N; i++)
    {
        if(can[res] == v)res++;
        else break;
    }
    sum[from[v][0]]--;
    num[v] = res;
    construct(from[v][0]);
    return;
}

bool search_loop(int v)
{
    if(visit[v])
    {
        for(int i = mem.size() - 1; i >= 0; i--)
        {
            loop.push_back(mem[i]);
            if(mem[i] == v)return true;
        }
    }
    visit[v] = true;
    mem.push_back(v);
    for(int i = 0; i < from[v].size(); i++)
    {
        if(search_loop(from[v][i]))return true;
    }
    mem.pop_back();
    return false;
}

