    {
        if(sum[i])
        {
            search_loop(i);
            break;
        }
    }
    for(int i = 0; i < loop.size(); i++)ele_loop[loop[i]] = true;
    reverse(loop.begin(),loop.end());
    for(int i = 1; i <= N; i++)
    {
