void dfs(int cur){
    lab[cur] = -1;
    set<int> st;
    for(auto &v:g[cur]){
        if(lab[v] == -1){
            e = {cur, v};
            continue;
        }
        if(lab[v] == -2) dfs(v);
        st.insert(lab[v]);
    }
    int ind = 0;
    for(auto &v:st){
        if(v != ind){
            lab[cur] = ind;
            return;
        }
        ind++;
    }
    lab[cur] = ind;
}

void dfs2(int cur){
    set<int> st;
    for(auto &v:g[cur]){
        if(lab[v] < 0) dfs(cur);
        st.insert(lab[v]);
    }
    int ind = 0;
    for(auto &v:st){
        if(v != ind){
            lab[cur] = ind;
            return;
        }
        ind++;
    }
    lab[cur] = ind;
}

bool check(int cur){
    set<int> st;
    for(auto &v:g[cur]) st.insert(lab[v]);
    int ind = 0;
    for(auto &v:st){
        if(v != ind) break;
        ind++;
    }
    return lab[cur] == ind;
}

