int n;
int p[252521];
vi ch[252521];
int val[252521];
bool cycled[252521];

pii calc(int x){
  set<int> S;
  for(int to : ch[x]){
    S.insert(val[to]);
  }
  int a=-1, b=-1;
  REP(i,1000){
    if(S.count(i)==0){
      if(a==-1)a=i;
      else{
        b=i;break;
      }
    }
  }
  return pii(a,b);
}

bool solve(){
  REP(i,n)val[i]=-1;
  REP(i,n)cycled[i]=false;

  int it = 0;
  REP(i,n)it = p[it];
  vi cycle;
  while(true){
    cycle.push_back(it);
    cycled[it] = true;
    it = p[it];
    if(cycle.front() == it)break;
  }
  int m = cycle.size();
  vi order;
  REP(i,m){
    for(int to : ch[cycle[i]])if(!cycled[to]){
      stack<int> S;
      S.push(to);
      while(S.size()){
        int x = S.top(); S.pop();
        for(int to : ch[x])if(!cycled[to]){
          S.push(to);
        }
        order.push_back(x);
      }
    }
  }
  reverse(ALL(order));
  REP(i,n)val[i]=-1;
  for(int x : order){
    val[x] = calc(x).first;
  }
  pii cand = calc(cycle.front());
  vi CCC;
  CCC.push_back(cand.first);
  CCC.push_back(cand.second);
  for(int c : CCC){
    val[cycle[0]] = c;
    for(int p : cycle){
      if(p==cycle[0])continue;
      val[p] = calc(p).first;
    }
    int ooo = calc(cycle[0]).first;
    if(c==ooo){
      return true;
    }
  }
  return false;
}

