int N, p[200020], deg[200020];
int A[200020];
set <int> S[200020];
pii C[200020];

int get(set <int> &X) {
	for(int i=0;;i++) if(X.find(i) == X.end()) return i;
	return -1;
}

pii get2(set <int> &X) {
	pii res = pii(-1, -1);
	for(int i=0;;i++) if(X.find(i) == X.end()) {
		if(res.Fi == -1) res.Fi = i;
		else if(res.Se == -1) res.Se = i;
		else return res;
	}
}

int chk[200020];
void dfs2(int x,vector<int> &c){
	c.pb(x); chk[x] = 1;
	int e = p[x];
	if(deg[e] > 0 && chk[e] == 0) dfs2(e, c);
}

void solve(){
	scanf("%d", &N);
	for(int i=1;i<=N;i++) scanf("%d", p+i), deg[p[i]]++;
	queue <int> que;
	for(int i=1;i<=N;i++) {
		if(deg[i] == 0) que.push(i);
	}
	while(!que.empty()) {
		int t = que.front(); que.pop();
		A[t] = get(S[t]);
		S[p[t]].insert(A[t]);
		--deg[p[t]];
		if(deg[p[t]] == 0) {
			que.push(p[t]);
		}
	}
	vector <int> cyc;
	for(int i=1;i<=N;i++) if(deg[i] > 0) {
		dfs2(i, cyc);
		break;
	}
	for(int e : cyc) C[e] = get2(S[e]);
	A[cyc[0]] = C[cyc[0]].Fi;
	for(int i=1;i<sz(cyc);i++) {
		int a = A[cyc[i-1]];
		if(a == C[cyc[i]].Fi) A[cyc[i]] = C[cyc[i]].Se;
		else A[cyc[i]] = C[cyc[i]].Fi;
	}
	if(A[cyc[sz(cyc)-1]] != A[cyc[0]]) {
		puts("POSSIBLE");
		return;
	}
	A[cyc[0]] = C[cyc[0]].Se;
	for(int i=1;i<sz(cyc);i++) {
		int a = A[cyc[i-1]];
		if(a == C[cyc[i]].Fi) A[cyc[i]] = C[cyc[i]].Se;
		else A[cyc[i]] = C[cyc[i]].Fi;
	}
	if(A[cyc[sz(cyc)-1]] == C[cyc[0]].Fi) {
		puts("POSSIBLE");
		return;
	}
	puts("IMPOSSIBLE");
}

int main(){
	int Tc = 1; //scanf("%d\n", &Tc);
	for(int tc=1;tc<=Tc;tc++){
		// printf("Case #%d: ", tc);
		solve();
	}
	return 0;
}

