int n;
int nxt[N];
int state[N];
int f[N];
bool ring[N];
int has[N];
int newHas[N];
bool visited[N];
int res[N];

int st = -1;

bool check(int x) {
	for (int i = 1; i <= n; ++i) {
		newHas[i] = has[i];
		visited[i] = false;
		res[i] = -1;
	}
	int cur = st;
	res[cur] = x;

	while (!visited[cur]) {
		if ((1 << res[cur]) & newHas[cur]) return false;
		visited[cur] = true;
		newHas[nxt[cur]] |= 1 << res[cur];
		cur = nxt[cur];
		for (int j = 0; j < 5; ++j) if (!(newHas[cur] & (1 << j))) {
			res[cur] = j;
			break;
		}
		if (res[cur] == -1) return false;
	}
	if (cur != st || res[cur] != x) return false;

	for (int j = 0; j < res[cur]; ++j) if (!(newHas[cur] & (1 << j))) return false;
	if ((1 << res[cur]) & newHas[cur]) return false;
	return true;

}

int q[N];
int top = 0;


void solve() {
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		scanf("%d", nxt + i);
		f[nxt[i]]++;
	}

	for (int i = 1; i <= n; ++i) state[i] = -1;
	for (int i = 1; i <= n; ++i) if (f[i] == 0) {
		int j = i;
		while (state[j] == -1) {
			state[j] = 1;
			j = nxt[j];
		}
		while (!ring[j]) {
			ring[j] = 1;
			j = nxt[j];
		}
		st = j;
		break;
	}

	if (st == -1) {
		st = 1;
		for (int i = 1; i <= n; ++i) ring[i] = 1;
//		if (n & 1) puts("NO");
//		else puts("YES");
//		return;
	}

	for (int i = 1; i <= n; ++i) state[i] = -1;

	for (int i = 1; i <= n; ++i) if (f[i] == 0) {
		state[i] = 0;
		q[top++] = i;
	}

	for (int j = 0; j < top; ++j) {
		int u = q[j];
		if (state[u] == -1) {
			for (int j = 0; j < 10; ++j) if (!(has[u] & (1 << j))) {
				state[u] = j;
				break;
			}
		}
		has[nxt[u]] |= 1 << state[u];
		f[nxt[u]]--;
		if (f[nxt[u]] == 0) q[top++] = nxt[u];
	}

	for (int i = 0; i < 10; ++i) if (check(i)) {
		puts("POSSIBLE");
		return;
	}

	puts("IMPOSSIBLE");



}

