	while(q.empty() == false){
		int curr = q.front(); q.pop();
		set<int> st;
		for(const auto& it : to [curr]){
			st.insert(grundy [it] [0]);
		}
		grundy [curr] [0] = 0;
		while(st.count(grundy [curr] [0])) grundy [curr] [0]++;
		if(--outdeg [from [curr]] == 0) q.push(from [curr]);
	}

	FOR(i,0,N) if(grundy [i] [0] == -1){
		set<int> st;
		for(const auto& it : to [i]) if(grundy [it] [1] == -1){
			st.insert(grundy [it] [0]);
		}
		grundy [i] [0] = 0;
		while(st.count(grundy [i] [0])) grundy [i] [0]++;
		grundy [i] [1] = grundy [i] [0] + 1;
		while(st.count(grundy [i] [1])) grundy [i] [1]++;
	}

