        mini_dp[v] = 0;
        return;
    }
    vector<int> cnt(graph[v].size() + 1);
    for (auto u : graph[v])
    {
        dp_call(u);
        if (mini_dp[u] < cnt.size()) cnt[mini_dp[u]] = 1;
    }
    for (int x = 0; x < cnt.size(); x++)
    {
