    if (value[adj[a][i]]) { one = true; } else { zero = true; }
  }
  if (not zero) return -1;
  if (one) return 2;
  return 1;
}

bool find_assignment(vvl& adj, vvl& back, vl outgoing, vl value, l check) {
  queue<l> q;
  l n = adj.size();
  F(i, 0, n) if (value[i] == -1 and outgoing[i] == 0) q.emplace(i);
  while (not q.empty()) {
    l a = q.front(); q.pop();
    if (value[a] == -1) {
      value[a] = calc(a, adj, value);
      if (value[a] == -1) return false;
    } else {
      if (value[a] != calc(a, adj, value)) return false;
    }
    for (auto b : back[a]) {
      outgoing[b]--;
      if (outgoing[b] == 0) q.emplace(b);
    }
  }
  if (check != -1) return L(value[check] == calc(check, adj, value), value);
  F(i, 0, n) {
    if (value[i] != -1) continue;
    for (auto b : back[i]) outgoing[b]--;
