int main() {
	int n;
	std::cin >> n;

	std::vector<std::vector<int>> g(n);
	std::vector<std::vector<int>> h(n);
	std::vector<int> deg(n);
	for (int i = 0; i < n; i++) {
		int p;
		std::cin >> p;
		p--;
		g[p].push_back(i);
		h[i].push_back(p);
		deg[p]++;
	}

	std::queue<int> q;

	for (int i = 0; i < n; i++) {
		if (deg[i] == 0) {
			q.push(i);
		}
	}

	std::vector<int> ord(n, -1);
	std::vector<int> topo;
	int now = 0;
	while (!q.empty()) {
		int u = q.front();
		q.pop();
		ord[u] = now++;
		topo.push_back(u);

		for (int v : h[u]) {
			if (--deg[v] == 0) {
				q.push(v);
			}
		}
	}

	std::vector<int> dp(n);
	for (int u : topo) {
		std::set<int> mex;
		for (int v : g[u]) if (ord[v] != -1) {
			mex.insert(dp[v]);
		}
		while (mex.count(dp[u])) {
			dp[u]++;
		}
	}

	std::vector<int> cycle;
	for (int i = 0; i < n; i++) {
		if (ord[i] == -1) {
			int j = i;
			while (j != i || cycle.empty()) {
				cycle.push_back(j);
				for (int k : g[j]) if (ord[k] == -1) {
					j = k;
					break;
				}
			}
			break;
		}
	}

	if (cycle.empty()) {
		puts("POSSIBLE");
		return 0;
	}

	int f = cycle[0];
	std::vector<int> cand;
	std::set<int> st;
	for (int u : g[f]) {
		if (ord[u] != -1) {
			st.insert(dp[u]);
		}
	}

	int mex = 0;
	while (st.count(mex)) mex++;

	cand.push_back(mex);
	mex++;
	while (st.count(mex)) mex++;
	cand.push_back(mex);

	for (int c : cand) {
		dp[f] = c;

		for (int i = cycle.size() - 1; i >= 0; i--) {
			int u = cycle[i];
			std::set<int> st;
			for (int v : g[u]) {
				st.insert(dp[v]);
			}
			dp[u] = 0;
			while (st.count(dp[u])) dp[u]++;
		}
		if (dp[f] == c) {
			puts("POSSIBLE");
			return 0;
		}
	}
	puts("IMPOSSIBLE");
}

