		for(int i=0;i<g[v].size();i++){
			int u=g[v][i];
			if(!used[u]) DFS(u,time);
		}
		scc[v]=time;
	}
	void Order(int v){
		used[v]=1;
		for(int i=0;i<g[v].size();i++){
			int u=g[v][i];
			if(!used[u]) Order(u);
		}
		Vec.push_back(v);
	}
	Graph Rev(){
		Graph G(V);
		for(int i=0;i<V;i++){
			for(int j=0;j<g[i].size();j++){
				int v=g[i][j];
				G.g[v].push_back(i);
			}
		}
		return G; 
	}
	void SCC(){
		scc=vi(V);
		used=vb(V,0);
		for(int i=0;i<V;i++) if(!used[i]) Order(i);
		Graph RG=Rev();
		RG.used=vb(V,0);
		RG.scc=vi(V);
		int time=0;
		while(!Vec.empty()){
			time++;
			int v=Vec.back();
			Vec.pop_back();
			if(!RG.used[v]) RG.DFS(v,time);
		}
		scc=RG.scc;
	}
	int Grundy(vi a){
		a.push_back(inf);
		sort(a.begin(),a.end());
		int S=a.size(),res;
		for(int i=0;i<S;i++) if(a[i]!=i){
			res=i;
			break;
		}
		return res;
	}
	int dfs(int v){
		int res=0;
		used[v]=1;
		vi a;
		for(int i=0;i<g[v].size();i++){
			int u=g[v][i];
			if(!used[v]&&scc[u]!=roop) a.push_back(dfs(u));
		}
		return Grundy(a);
	}
	bool Judge(int v,int I,vi& p,vi& q){
		int u=v,J=I;
		do{
			int w=g[u][0],va=(J==0?p[u]:q[u]);
			if(p[w]==va) J=1;
			else J=0;
			u=w;
		}while(v!=u);
		return I==J;
	}
	public:
	Graph(int v){
		V=v;
		g=vvi(v);
	}
	void add_edge(int s,int t){
		g[s].push_back(t);
	}
	void solve(){
		SCC();
		vi tmp(V+1);
		for(int i=0;i<V;i++){
			if(tmp[scc[i]]){
				roop=scc[i];
				break;
			}
			tmp[scc[i]]++;
		}
		used=vb(V,0);
		vvi a(V);
		for(int i=0;i<V;i++) if(scc[i]==roop){
			for(int j=0;j<g[i].size();j++){
				int v=g[i][j];
				if(scc[v]!=roop){
					a[i].push_back(dfs(v));
				}
			}
		}
		vi p(V),q(V);
		int u;
		for(int i=0;i<V;i++) if(scc[i]==roop){
			u=i;
			p[i]=Grundy(a[i]);
			a[i].push_back(p[i]);
			q[i]=Grundy(a[i]);
		}
		Graph G=Rev();
		if(G.Judge(u,0,p,q)||G.Judge(u,1,p,q)) cout<<"POSSIBLE"<<endl;
		else cout<<"IMPOSSIBLE"<<endl;
	}
};

