int deg[N];
vector<int> G[N];

int skad[N];
int odp[N];

int odw[N];

bool vis[N];
bool cyc[N];

bool nieparz(int n) {
// 	printf("nieparz\n");
	for (int x = 1; x <= n; x ++) {
		if (vis[x]) continue;
		for (int y : G[x]) {
			if (odp[y] == odp[x] + 1) return true;
		}
	}
	return false;
}

bool algos(int n, int x) {
// 	printf("algos\n");
// 	printf("x -- %d %d\n", x, odp[x]);
	cyc[x] = true;
	int ile = 0;
	while(odp[skad[x]] == odp[x]) {
// 		printf("cyc %d\n", x);
		ile ++;
		if (cyc[skad[x]]) {
			if (ile % 2 == 1) {
				return nieparz(n);
			}
			return true;
		}
		x = skad[x];
		cyc[x] = true;
	}
	return true;
}

int main()
{
	int n;
	scanf("%d", &n);
	for (int i = 1; i <= n; i ++) {
		int a;
		scanf("%d", &a);
		skad[i] = a;
		G[a].push_back(i);
		deg[a] ++;
	}
	queue<int> kol;
	for (int i = 1; i <= n; i ++) {
		if (deg[i] == 0) kol.push(i);
	}
	while(!kol.empty()) {
		int x = kol.front();
		kol.pop();
		for (int y: G[x]) {
			odw[odp[y]] = x;
		}
		int i = 0;
		for (i = 0; odw[i] == x; i ++);
		odp[x] = i;
		deg[skad[x]] --;
		if (deg[skad[x]] == 0) {
			kol.push(skad[x]);
		}
		vis[x] = true;
	}
	int MIN = n + 1;
	for (int x = 1; x <= n; x ++) {
		if (vis[x]) continue;
		for (int y: G[x]) {
			if (vis[y])
			odw[odp[y]] = x;
		}
		int i = 0;
		for (i = 0; odw[i] == x; i ++);
		odp[x] = i;
		MIN = min(MIN, i);
	}
	bool ans = true;
	for (int x = 1; x <= n; x ++) {
		if (vis[x]) continue;
		if (odp[x] == MIN) {
			ans = algos(n, x);
			break;
		}
	}
	printf("%sPOSSIBLE\n", not ans? "IM" : "");
}

