        for (i = 0; z[x].size() < 2; i++) {
            if (!s[x].count(i)) z[x].push_back(i);
        }

        return -1;
    } else {
        for (i = 0; ; i++) {
            if (!s[x].count(i)) return g[x] = i;
        }
    }
}

