    {
        scanf("%d", &p[i]);
        a[i] = -1;
        V[p[i]].push_back(i);
    }
    findCycle();
    for (int i = 1; i <= n; ++ i)
        if (!vis[i] && onCycle[p[i]] && !onCycle[i])
            dfs(i);

    a[head] = Mex(head, 2);
    if (OkCycle())
        printf("POSSIBLE\n");
    else
    {
        a[V[head][0]] = a[head];
        a[head] = Mex(head, 1);
        for (int i = 1; i <= n; ++ i)
            if (i != head && i != V[head][0] && onCycle[i])
                a[i] = -1;
        if (OkCycle())
            printf("POSSIBLE\n");
        else
            printf("IMPOSSIBLE\n");
    }
    return 0;
}

