vector<long long> loopvec;
set<long long> loopset;
long long loopvisit[200005];

long long paint[200005];
long long work[200005];

bool dfsloop(long long cur, long long col){
	//cout << "cur = " << cur << endl;
	if(loopvisit[cur] == col){
		return true;
	}
	if(loopvisit[cur] != 0){
		return false;
	}
	loopvisit[cur] = col;

	for(long long i = 0; i < tree[cur].size(); i++){
		if(dfsloop(tree[cur][i], col)){
			loopvec.push_back(cur);
			loopset.insert(cur);
			return true;
		}
	}
	return false;
}

void markloop(){
	long long col = 1;
	for(long long i = 0; i < N; i++){
		if(loopvisit[i] != 0){
			continue;
		}
		dfsloop(i, col);
		col++;
	}
}

bool isloop(long long node){
	return (loopset.count(node) != 0);
}

long long paintunloopdfs(long long node){
	if(tree[node].size() == 0){
		paint[node] = 0;
		return 0;
	}
	vector<long long> vec;
	for(long long i = 0; i < tree[node].size(); i++){
		vec.push_back(paintunloopdfs(tree[node][i]));
	}
	sort(vec.begin(), vec.end());
	long long cur = 0;
	for(long long i = 0; i < vec.size(); i++){
		if(vec[i] == cur){
			cur++;
		}
	}
	paint[node] = cur;
	return cur;
}

void paintunloop(){
	for(long long i = 0; i < loopvec.size(); i++){
		long long start = loopvec[i];
		for(long long j = 0; j < tree[start].size(); j++){
			if(!isloop(tree[start][j])){
				paintunloopdfs(tree[start][j]);
			}
		}
	}
}

bool paintloop(long long cur){
	vector<long long> chs;
	for(long long i = 0; i < tree[cur].size(); i++){
		if(work[tree[cur][i]] == -1){
			paintloop(tree[cur][i]);
		}
		chs.push_back(work[tree[cur][i]]);
	}
	sort(chs.begin(), chs.end());

	long long col = 0;
	for(long long i = 0; i < chs.size(); i++){
		if(chs[i] == col){
			col++;
		}
	}
	if(work[cur] != -1 && work[cur] != col){
		return false;
	}else{
		work[cur] = col;
	}
	return true;
}

