	G[u].push_back(v);
}

bool vis[N];
vector<int>cir;

bool dfs(int u,int an){
	vis[u]=1;
	for(int i=0;i<G[u].size();i++){
		int v=G[u][i];
		if(vis[v]){
			if(v==an){
				cir.push_back(an);
				return 1;
			}
		}
		else if(dfs(v,an)){
			cir.push_back(v);
			return 1;
		}
	}
	return 0;
}

int dp[N],nex[N];
bool visit[N];
void DP(int u){
	vector<int>dat;
	for(int i=0;i<G[u].size();i++){
		int v=G[u][i];
		if(vis[v]) continue;
		DP(v);
		dat.push_back(dp[v]);
		visit[dp[v]]=1;
	}
	for(int i=0;;i++){
		if(!visit[i]) {dp[u]=i;break;}
	}
	for(int i=dp[u]+1;;i++){
		if(!visit[i]) {nex[u]=i;break;}
	}

	for(int i=0;i<G[u].size();i++){
		int v=G[u][i];
		if(vis[v]) continue;
		visit[dp[v]]=0;
	}
}

