  while (leaf.size()) {
    ll now = leaf.front(); leaf.pop();
    for (auto x: radj[now]) { tos[x]--; if (tos[x]==0) leaf.push(x); }
    set<ll> used; for (auto x: adj[now]) used.insert(grundy[x]); 
    grundy[now] = 0; while (used.count(grundy[now])) grundy[now]++;
  }

  vector<ll> f(N), s(N);
  rep(i,N) {
    if (grundy[i]==-1) {
      set<ll> used; for (auto x: adj[i]) used.insert(grundy[x]);
      f[i] = 0;      while (used.count(f[i])) f[i]++;
