#include <bits/stdc++.h>

struct Node
{
	std::list<int> edges, rev_edges;
	bool visited{};
	int num{-1};
};

std::vector<Node> graph;
std::vector<int> topology;
std::vector<std::vector<int>> sorted;

bool solve();
void back_track(int);
void sort(int, std::vector<int> &);
bool sc_success(std::vector<int> &, bool);

int main()
{
	if (solve())
		printf("POSSIBLE\n");
	else
		printf("IMPOSSIBLE\n");

	return 0;
}

bool solve()
{
	int n;
	scanf("%d", &n);
	graph.resize(n);
	for (int i{}; i < n; i++)
	{
		int p;
		scanf("%d", &p);
		p--;
		graph[p].edges.push_back(i);
		graph[i].rev_edges.push_back(p);
	}

	for (int i{}; i < n; i++)
		back_track(i);
	for (int i{}; i < n; i++)
		graph[i].visited = false;
	for (int i{n - 1}; i >= 0; i--)
	{
		if (graph[topology[i]].visited)
			continue;
		sorted.push_back({});
		sort(topology[i], sorted.back());
	}
	for (auto scv{sorted.rbegin()}; scv != sorted.rend(); scv++)
	{
		if (scv->size() == 1)
		{
			int &index{scv->front()};
			if (graph[index].edges.size() == 0)
				graph[index].num = 0;
			else
			{
				std::vector<int> to;
				for (auto &e : graph[index].edges)
					to.push_back(graph[e].num);
				std::sort(to.begin(), to.end());
				to.push_back(1 << 30);
				int num{};
				for (auto &e : to)
				{
					if (e > num)
						break;
					if (e == num)
						num++;
				}
				graph[index].num = num;
			}
		}
		else
		{
			if (sc_success(*scv, false))
				return true;
			for (auto &e : *scv)
				graph[e].num = -1;
			if (sc_success(*scv, true))
				return true;
			return false;
		}
	}
	return true;
}

void back_track(int index)
{
	if (graph[index].visited)
		return;
	graph[index].visited = true;
	for (auto &e : graph[index].edges)
		back_track(e);
	topology.push_back(index);
	return;
}

void sort(int index, std::vector<int> &scv)
{
	if (graph[index].visited)
		return;
	graph[index].visited = true;
	scv.push_back(index);
	for (auto &e : graph[index].rev_edges)
		sort(e, scv);
	return;
}

bool sc_success(std::vector<int> &scv, bool plus)
{
	std::vector<int> to;
	for (auto &e : graph[scv.front()].edges)
		to.push_back(graph[e].num);
	std::sort(to.begin(), to.end());
	int num{};
	unsigned i{};
	for (; i < to.size(); i++)
	{
		if (num < to[i])
			break;
		if (num == to[i])
			num++;
	}
	if (plus)
		num++;
	for (; i < to.size(); i++)
	{
		if (num < to[i]) break;
		if (num == to[i]) num++;
	}
	graph[scv.front()].num = num;
	for (unsigned int i{1}; i < scv.size(); i++)
	{
		to.clear();
		num = 0;
		for (auto &e : graph[scv[i]].edges)
			to.push_back(graph[e].num);
		std::sort(to.begin(), to.end());
		for (auto &e : to)
		{
			if (num < e)
				break;
			if (num == e)
				num++;
		}
		graph[scv[i]].num = num;
	}
	if (!plus && graph[scv.front()].num != graph[scv.back()].num)
		return true;
	if (plus && graph[scv.front()].num == graph[scv.back()].num + 1)
		return true;
	return false;
}

