typedef pair<long long int, long long int> P;

long long int INF = 1e18;
long long int MOD = 1e9 + 7;

int N;
vector<int> E[210000];
bool flag[210000] = {};
long long int grundy[210000], grundy_[210000];

long long int func(int pos, int pre, int start){
	if(grundy[pos] != -1){
		return grundy[pos];
	}
	if(pos == start && pre != -1){
		return INF;
	}
	vector<long long int> ret;
	for(int i = 0; i < E[pos].size(); i++){
		long long int S = func(E[pos][i], pos, start);
		ret.push_back(S);
	}
	for(int i = 0; i < ret.size(); i++){
		if(ret[i] == INF){
			grundy[pos] = INF;
			return INF;
		}else{
			flag[ret[i]] = true;
		}
	}
	int val;
	for(int i = 0; i <= N; i++){
		if(!flag[i]){
			grundy[pos] = i;
			val = i;
			break;
		}
	}
	for(int i = 0; i < ret.size(); i++){
		flag[ret[i]] = false;
	}
	return val;
}

long long int func2(int pos){
	if(grundy_[pos] != -1 && grundy_[pos] != INF){
		return grundy_[pos];
	}
	vector<long long int> ret;
	for(int i = 0; i < E[pos].size(); i++){
		long long int S = func2(E[pos][i]);
		ret.push_back(S);
	}
	for(int i = 0; i < ret.size(); i++){
		flag[ret[i]] = true;
	}
	int val;
	for(int i = 0; i <= N; i++){
		if(!flag[i]){
			grundy_[pos] = i;
			val = i;
			break;
		}
	}
	for(int i = 0; i < ret.size(); i++){
		flag[ret[i]] = false;
	}
	return val;
}

int main(){

	cin >> N;

	for(int i = 1; i <= N; i++){
		int p;
		cin >> p;
		E[p].push_back(i);
	}

	for(int i = 0; i <= N; i++){
		grundy[i] = -1;
	}

	long long int pos, nex;
	for(int i = 0; i <= N; i++){
		if(grundy[i] == -1){
			long long int ret = func(i, -1, i);
			if(ret == INF){
				pos = i;
				break;
			}
		}
	}


	bool ff[210000] = {};
	for(int i = 0; i < E[pos].size(); i++){
		if(grundy[E[pos][i]] == INF){
			nex = E[pos][i];
		}else{
			ff[grundy[E[pos][i]]] = true;
		}
	}
	int cnt = 0, pre;
	for(int i = 0; i <= N; i++){
		if(!ff[i]){
			for(int j = 0; j <= N; j++){
				grundy_[j] = grundy[j];
			}
			grundy_[pos] = i;
			func2(nex);
			if(cnt == 0){
				pre = grundy_[pos];
				if(grundy_[pos] != grundy_[nex]){
					cout << "POSSIBLE" << endl;
					return 0;
				}
			}else{
				if(grundy_[nex] == pre){
					cout << "POSSIBLE" << endl;
				}else{
					cout << "IMPOSSIBLE" << endl;
				}
				return 0;
			}
			cnt += 1;
		}
	}
	return 0;
}

