typedef long long LL; using namespace std;

int N;

const int MAXN = 204000;

vector<int> g[MAXN];
vector<int> gb[MAXN];

int rrun = 0;
int visited[MAXN];
bool stop_dfs;
bool circle[MAXN];
bool collect;
int start_from;

void dfs(int v) {
	visited[v] = rrun;
	if (stop_dfs)
		return;
	FOR (i, g[v].sz) {
		int w = g[v][i];
		if (visited[w] == rrun) {
			stop_dfs = true;
			start_from = w;
			collect = true;
		}
		else if (visited[w])
			continue;
		else
			dfs(w);
		if (collect)
			circle[v] = true;
		if (v == start_from)
			collect = false;
		if (stop_dfs)
			break;
	}
}

int number[MAXN];

int computeNumber(int v) {
	vector<int> vals;
	FOR (i, g[v].sz) {
		int w = g[v][i];
		if (circle[w])
			continue;
		vals.pb(computeNumber(w));
	}
	sort(all(vals));
	int val = 0, next = 0;
	int i = 0;
	while (i < vals.sz) {
		while (i < vals.sz && vals[i] == next)
			i++;
		if (i && vals[i - 1] == next) {
			next++;
			val++;
		}
		else
			break;
	}
	number[v] = val;
	return val;
}

int value;

bool possible(int v, int prev_val) {
	int myval = number[v];
	if (prev_val == myval)
		myval++;
	if (v == start_from)
		return myval == value;

	FOR (i, gb[v].sz) {
		int w = gb[v][i];
		if (circle[w])
			return possible(w, myval);
	}
}

int main() {
	cin >> N;
	FOR (i, MAXN) {
		g[i].clear();
		gb[i].clear();
	}
	int a;
	FOR (i, N) {
		cin >> a;
		a--;
		g[a].pb(i);
		gb[i].pb(a);
	}

	SET(visited, 0);
	SET(circle, 0);
	stop_dfs = false;
	collect = false;

	FOR (i, N)
		if (!visited[i]) {
			rrun++;
			dfs(i);
		}
	FOR (i, N)
		if (circle[i])
			computeNumber(i);

	int ww;
	FOR (i, gb[start_from].sz) {
		ww = gb[start_from][i];
		if (circle[ww])
			break;
	}

	value = number[start_from];
	if (possible(ww, number[start_from])) {
		cout << "POSSIBLE" << endl;
		return 0;
	}
	value = number[start_from] + 1;
	if (possible(ww, number[start_from] + 1)) {
		cout << "POSSIBLE" << endl;
		return 0;
	}
	cout << "IMPOSSIBLE" << endl;
	return 0;
}

