int ds(int u) {
	if(dp[u] != -1) return dp[u];
	for(int i=0;i<g[u].size();i++) {
		int v = g[u][i];
		if(sc[u] && sc[v]) {continue;}
		ee.set(ds(g[u][i]));
	}
	int res = 0;
	while(ee[res]) {res++;}
	for(int i=0;i<g[u].size();i++) {
		int v = g[u][i];
		if(sc[u] && sc[v]) {continue;}
		ee.reset(ds(g[u][i]));
	}
	return dp[u] = res;
}
void cyc(int u) {
	st.push_back(u);
	sv.set(u);
	vs.set(u);
	for(int i=0;i<g[u].size();i++) {
		int v = g[u][i];
