				sc.set(st.back());
				if(st.back() == v) break;
				st.pop_back();
			}
			return;
		} else {
			if(!vs[v]) {
			cyc(v);
			}
		}
	}
	if(found) return;
	sv.reset(u);
	st.pop_back();
}
