    int q = que.front(); que.pop();
    if(a[q] >= 0) continue;

    set<int> s;
    bool ng = false;
    for(int i: g[q]) {
      if(a[i] < 0) ng = true;
      s.insert(a[i]);
    }
    if(ng) continue;

    int g = 0;
    while(s.count(g)) g++;

    a[q] = g;
    que.push(p[q]);
  }
  // REP(i, n) cout << a[i] << " "; cout << endl;

  //サイクル上の適当な頂点を一点選ぶ
  int x;
  REP(i, n) if(a[i] == -1) x = i;

  set<int> s;
  for(int i: g[x]) s.insert(a[i]);
  int fir = 0;
  while(s.count(fir)) ++fir;
  int sec = fir + 1;
  while(s.count(sec)) ++sec;

  if(func(x, fir)) cout << "POSSIBLE" << endl;
  else if(func(x, sec)) cout << "POSSIBLE" << endl;
  else cout << "IMPOSSIBLE" << endl;

  // REP(i, n) cout << a[i] << " "; cout << endl;

  return 0;
}

