void adde(int a,int b)
{
	to[++cnt]=b;nxt[cnt]=fir[a];fir[a]=cnt;
	to[++cnt]=a;nxt[cnt]=fir[b];fir[b]=cnt;
}
int fa[N],cir[N],clen,dep[N];bool onc[N];
void findcir(int u,int ff)
{
	fa[u]=ff;
	dep[u]=dep[ff]+1;
	for(int v,p=fir[u];p;p=nxt[p]){
		if((v=to[p])!=ff){
			if(!dep[v])findcir(v,u);
