namespace graph {

using Node = ll;
using Weight = ll;
using Edge = std::pair<Node, Weight>;

template <bool Directed>
struct Graph : public vvec<Edge> {
    using vvec<Edge>::vvec;

    void add_edge(Node f, Node t, Weight w = 1) {
        (*this)[f].emplace_back(t, w);
        if (!Directed) (*this)[t].emplace_back(f, w);
    }

    Graph<Directed> build_inv() const {
        Graph<Directed> ret(this->size());
        for (Node i = 0; i < this->size(); i++) {
            for (const Edge &e : (*this)[i]) {
                Node j;
                Weight w;
                std::tie(j, w) = e;
                if (!Directed && j < i) continue;
                ret.add_edge(j, i, w);
            }
        }

        return ret;
    }
};

}

vec<bool> get_loop(const graph::Graph<true> &g, ll start) {
    vec<bool> ret(g.size());
    vec<bool> used(g.size());
    std::stack<ll> stk;
    stk.push(start);
    while (true) {
        ll cur = stk.top();
        if (used[cur]) {
            stk.pop();
            while (true) {
                ll n = stk.top();
                stk.pop();
                ret[n] = true;
                if (n == cur) break;
            }
            break;
        }
        used[cur] = true;
        stk.push(g[cur][0].first);
    }

    return ret;
}

bool solve() {
    ll n;
    std::cin >> n;
    graph::Graph<true> g(n);
    for (ll i = 0; i < n; i++) {
        ll p;
        std::cin >> p;
        g.add_edge(p - 1, i);
    }
    auto ig = g.build_inv();

    std::queue<ll> que;
    vec<bool> is_leaf(n);
    for (ll i = 0; i < n; i++) if (g[i].size() == 0) {
        que.push(i);
        is_leaf[i] = true;
    }

    if (que.empty()) return n % 2 == 0;

    auto loop = get_loop(ig, que.front());
    vec<ll> ans(n, -1);

    auto get_ch_num = [&](ll i) {
        std::set<ll> ch;
        for (auto &&e : g[i]) {
            ll c = e.first;
            ch.insert(ans[c]);
        }
        return ch;
    };

    auto calc_a = [&](ll i, ll ng = -1) {
        auto ch = get_ch_num(i);
        ch.insert(ng);
        ll ret = 0;
        for (;; ret++) if (ch.find(ret) == ch.end()) return ret;
    };

    while (que.size()) {
        ll cur = que.front();
        que.pop();
        ans[cur] = calc_a(cur);
        for (auto &&e : ig[cur]) {
            ll nxt = e.first;
            if (loop[nxt]) continue;
            que.push(nxt);
        }
    }

    auto check = [&](const vec<ll> &av) {
        for (ll i = 0; i < n; i++) {
            ll j = ig[i][0].first;
            if (av[i] == av[j]) return false;
        }
        for (ll i = 0; i < n; i++) {
            std::set<ll> st;
            for (auto &&e : g[i]) {
                ll nxt = e.first;
                if (av[nxt] < av[i]) st.insert(av[nxt]);
            }
            if (st.size() < av[i]) return false;
        }
        return true;
    };

    if (check(ans)) return true;

    auto nxt_n = [&](ll i) {
        return ig[i][0].first;
    };

    auto modify = [&](vec<ll> av, ll start) {
        ll cur = start;
        ll nxt = nxt_n(cur);
        while (start != nxt) {
            av[nxt] = calc_a(nxt, av[cur]);
            cur = nxt;
            nxt = nxt_n(nxt);
        }
        return check(av);
    };

    ll start = [&] {
        ll i;
        for (i = 0; i < n; i++) if (loop[i]) break;
        return i;
    }();
    auto st = get_ch_num(start);
    for (ll i = 0, cnt = 0; cnt < 2; i++) {
        if (st.find(i) != st.end()) continue;
        ans[start] = i;
        if (modify(ans, start)) return true;
        cnt++;
    }

    return false;
}

int main() {
    if (!solve()) std::cout << "IM";
    std::cout << "POSSIBLE\n";
    return 0;
}

