template<class T> void turn_on(T &x, int pos) {x = x | ((T)1<<(pos-1));}
template<class T> void turn_off(T &x, int pos) {x = x & ~((T)1<<(pos-1));}
template<class T> T sqr(T a) {return a*a;}

int n, d[maxn], p[maxn], grundy[maxn], tmp[maxn];
vector<int> a[maxn], q;
priority_queue<ii, vector<ii>, greater<ii> > pq;

ii MEX(int u) {
    q.clear();
    REP(i, a[u].sz()) {
        if (grundy[a[u][i]]!=-1)
            q.push_back(grundy[a[u][i]]);
    }
    ii res;
    q.push_back(inf);
    sort(q.begin(), q.end());
    REP(i, q.sz()) {
        if (i==0 && q[i]>0) {
            res.fi = 0;
            break;
        }
        if (i!=0 && q[i]!=q[i-1]+1) {
            res.fi = q[i-1]+1;
            break;
        }
    }
    REP(i, q.sz()) {
        if (i==0 && q[i]>1) {
            res.se = 1;
            break;
        }
        if (i!=0 && q[i]!=q[i-1]+1 && q[i-1]+1!=res.fi) {
            res.se = q[i-1]+1;
            break;
        }
        if (i!=0 && q[i]>q[i-1]+2) {
            res.se = q[i-1]+2;
            break;
        }
    }
    return res;
}

void fuck(int u, int x) {
    if (x==0) grundy[u] = MEX(u).fi;
    else grundy[u] = MEX(u).se;
    int t = p[u];
    if (grundy[t]!=-1) return;
    if (grundy[u]==MEX(t).fi) fuck(t, 1);
    else fuck(t, 0);
}

