using namespace std;
typedef long long ll;
typedef pair<int,int> pii;
const int MAXN = 2e5 + 5;

struct Edge
{
	int next,to;
}e[MAXN];
int head[MAXN],etot=0;
inline void add(int u,int v)
{
	e[++etot]=(Edge){ head[u],v};
	head[u]=etot;
}

int pre[MAXN];

vector<int> cir;
bool vis[MAXN];
int dfs_cir(int u)
{
	vis[u] = 1;
	for(int i=head[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(vis[v]){ cir.push_back(u); return v;}

		int res = dfs_cir(v);
		if(res){ cir.push_back(u); return res==u? 0: res;}
	}
	return 0;
}

bool incir[MAXN];

int val[MAXN];
vector<int> nxt[MAXN];
void get_val(int u)
{
	for(int i=head[u]; i; i=e[i].next)
	{
		int v = e[i].to;
		if(incir[v]) continue;
		get_val(v);

		nxt[u].push_back(val[v]);
	}

	sort(nxt[u].begin(),nxt[u].end());

	int need = 0;
	for(int i=0; i<(int)nxt[u].size(); ++i)
	{
		if(nxt[u][i] > need){ val[u] = need; return;}
		if(nxt[u][i] == need) ++need;
	}
	val[u] = need;
}

bool check(int val_lst)
{
	int lst = val_lst;

	for(int k=0; k<(int)cir.size(); ++k)
	{
		int u = cir[k];
		if(val[u] == lst)
		{
			int need = lst + 1;
			bool flag = 0;
			for(int i=0; i<(int)nxt[u].size(); ++i)
			{
				if(nxt[u][i] > need){ lst = need; flag=1; break;}
				if(nxt[u][i] == need) ++need;
			}
			if(!flag) lst = need;
		}
		else lst = val[u];
	}
	return lst == val_lst;
}

int main(void)
{
	int n;
	scanf("%d",&n);
	for(int i=1; i<=n; ++i) scanf("%d",&pre[i]);

	for(int i=1; i<=n; ++i) add(pre[i], i);

	for(int i=1; i<=n; ++i)
		if(!vis[i]) dfs_cir(i);
	for(int i=0; i<(int)cir.size(); ++i)
		incir[cir[i]] = 1;

	if(cir.size() <= 1) return printf("POSSIBLE"), 0;

	for(int i=0; i<(int)cir.size(); ++i)
		get_val(cir[i]);

	int u = cir.back();
	if(check(val[u])) return printf("POSSIBLE"), 0;

	int need = val[u] + 1, val_lst = -1;
	for(int i=0; i<(int)nxt[u].size(); ++i)
	{
		if(nxt[u][i] > need){ val_lst = need; break;}
		if(nxt[u][i] == need) ++need;
	}
	if(val_lst == -1) val_lst = need;

	if(check(val_lst)) printf("POSSIBLE");
	else printf("IMPOSSIBLE");
	return 0;
}

