void getnxt(int u) {
	if (nxt[u]) return;
	for(int p=s(u);p;p=n(p)) if (ind[t(p)]) {
		getnxt(nxt[u]=t(p)); break;
	}
}

bool check(int u,int U,int af,int aU) {
	int szorg, sznow, au, ret = true;
	szorg = S[u].size();
	S[u].insert(af);
	sznow = S[u].size();
	auto it = S[u].end(); it -- ;
	if (*it != S[u].size()-1) {
		if (*S[u].begin() == 0) ret = false;
		else au = 0;
	} else au = S[u].size();
	if (u==U && au!=aU) ret = false;
	if (ret==false || u==U) {
		if (sznow > szorg) S[u].erase(af);
		return ret;
	}
	ret = check(nxt[u],U,au,aU);
	if (sznow > szorg) S[u].erase(af);
	return ret;
}

