    while (top) {
        u = s[top--];
        if (S[u].empty()) a[u] = 0;
        else {
            auto it = S[u].end(); it -- ;
            if (*it >= S[u].size()) {
            	if (*S[u].begin() == 0) { puts("IMPOSSIBLE"); goto END; }
            	a[u] = 0;
