const int MAXN = 234567;
vector<int> G[MAXN];
int color[MAXN]; // 0 non visit 1 = visiting 2 = finish
int oncycle[MAXN], mex[MAXN], par[MAXN];
int tmpmex[MAXN];
bool mexnum[MAXN];

void dfs(int cur) {
    color[cur] = 1;
    for (int i : G[cur]) {
        if (color[i] == 1) {
            oncycle[cur] = 1;
            continue;
        }
        dfs(i);
        if (oncycle[i] == 1)
            oncycle[cur] = 1;
    }
    for (int i = 0; i <= (int)G[cur].size(); i++)
        mexnum[i] = false;
    for (int i : G[cur]) {
        if (oncycle[i]) continue;
        mexnum[mex[i]] = 1;
    }
    for (int i = 0; ; i++)
        if (!mexnum[i]) {
            mex[cur] = i;
            break;
        }
    color[cur] = 2;
}

bool check(int tg, int ans) {
    tmpmex[tg] = ans;
    int cur = par[tg];
    while (cur != tg) {
        for (int i = 0; i <= (int)G[cur].size(); i++)
            mexnum[i] = false;
        for (int i : G[cur])
            mexnum[tmpmex[i]] = 1;
        for (int i = 0; ; i++)
            if (!mexnum[i]) {
                tmpmex[cur] = i;
                break;
            }
        cur = par[cur];
    }
    memset(mexnum, 0, sizeof(mexnum));
    for (int i : G[tg])
        mexnum[tmpmex[i]] = 1;
    int ansmex = 0;
    while (mexnum[ansmex])
        ansmex++;
    return tmpmex[tg] == ansmex;
}

bool solve(int tg, int N) {
    for (int i = 0; i < N; i++)
        tmpmex[i] = mex[i];
    if (check(tg, tmpmex[tg])) return true;
    for (int i = 0; i < N; i++)
        tmpmex[i] = mex[i];
    int ans = 0;
    for (int i : G[tg]) {
        if (oncycle[i]) continue;
        ans = max(ans, tmpmex[i]);
    }
    if (check(tg, ans + 1)) return true;
    return false;
}

int main() {
    int N;
    scanf("%d", &N);
    for (int i = 0; i < N; i++) {
        scanf("%d", &par[i]);
        par[i]--;
        G[par[i]].push_back(i);
    }
    for (int i = 0; i < N; i++)
        if (!color[i])
            dfs(i);
    int tg;
    for (int i = 0; i < N; i++)
        if (oncycle[i])
            tg = i;
    if (solve(tg, N)) puts("POSSIBLE");
    else puts("IMPOSSIBLE");
    return 0;
}

