				int len = cycle.size();
				int lst = opt;
				for(int j = 0; j < len; j++){
					int v = 0, who = cycle[(j + 1) % len];
					while(has[who].count(v) || v == lst) v++;
					lst = v;
				}
				return lst == opt;
			};
			if(check(cand[0]) || check(cand[1])) cout << "POSSIBLE" << endl;
			else cout << "IMPOSSIBLE" << endl;
			return 0;
		}
	}
	return 0;
}

