#include <bits/stdc++.h>

using namespace std;

#define ll 			long long
#define up(i,j,n)		for (int i = j; i <= n; i++)
#define down(i,j,n)	for (int i = j; i >= n; i--)
#define cmax(a,b)		a = max (a, b)
#define cmin(a,b)		a = min (a, b)
#define Auto(i,node)	for (int i = LINK[node]; i; i = e[i].next)

const int MAXN = 2e5 + 5;
const int oo = 0x3f3f3f3f;

int N, a[MAXN];
bool mark[MAXN], vaild[MAXN];

namespace Graph{
	struct edge {
		int y, next, c;
	}e[MAXN << 1];
	int LINK[MAXN], len = 0, deg[MAXN];
	deque<int> q;
	inline void ins(int x, int y, int c) {
		e[++len].next = LINK[x]; LINK[x] = len;
		e[len].y = y; e[len].c = c;
	}
	inline void Ins(int x, int y){
		ins(x, y, 1);
		ins(y, x, 0);
		deg[x]++;
	}
	bool chk(int st){
		q.push_back(st);
		while (!q.empty()) {
			int node = q.front(); q.pop_front();
			if (node != st) {
				Auto (i, node) if (e[i].c == 1) mark[a[e[i].y]] = 1;
				int cur = 0;
				while (mark[cur]) cur++;
				a[node] = cur;
				Auto (i, node) if (e[i].c == 1) mark[a[e[i].y]] = 0;
			} 
			Auto (i, node) if (e[i].c == 0 && vaild[e[i].y] && e[i].y != st) 
				q.push_back(e[i].y);
		}
		int cur = 0;
		Auto (i, st) if (e[i].c == 1) mark[a[e[i].y]] = 1;
		while (mark[cur]) cur++;
		Auto (i, st) if (e[i].c == 1) mark[a[e[i].y]] = 0;
		return cur == a[st];
	}
}using namespace Graph;

namespace solution{
	void Prepare(){
		scanf("%d", &N);
		up (i, 1, N) {
			int x, y = i;
			scanf("%d", &x);
			Ins(x, y);
		}
	}
	void Solve(){
		up (i, 1, N) if (!deg[i])	
			q.push_back(i);
		up (i, 1, N) vaild[i] = 1;
		while (!q.empty()) {
			int node = q.front(); q.pop_front();
			vaild[node] = 0;
			Auto (i, node) if (e[i].c == 1) 
				mark[a[e[i].y]] = 1;
			int cur = 0;
			while (mark[cur]) cur++;
			a[node] = cur;
			Auto (i, node) if (e[i].c == 0) {
				if (!--deg[e[i].y]) q.push_back(e[i].y);
			}
			Auto (i, node) if (e[i].c == 1) 
				mark[a[e[i].y]] = 0;
		}
		up (i, 1, N) if (vaild[i]) {
			int cur = 0;
			Auto (j, i) if (e[j].c == 1 && !vaild[e[j].y])
				mark[a[e[j].y]] = 1;
			while (mark[cur]) cur++;
			a[i] = cur;
			Auto (j, i) if (e[j].c == 1 && !vaild[e[j].y])
				mark[a[e[j].y]] = 0;
			if (chk(i)) break;
			Auto (j, i) if (e[j].c == 1 && !vaild[e[j].y])
				mark[a[e[j].y]] = 1;
			mark[a[i]] = 1; 
			cur = 0;
			while (mark[cur]) cur++;
			mark[a[i]] = 0;
			a[i] = cur;
			Auto (j, i) if (e[j].c == 1 && !vaild[e[j].y]) 
				mark[a[e[j].y]] = 0;
			if (chk(i)) break;
			puts("IMPOSSIBLE");
			return;
		}
		puts("POSSIBLE");
	}
}

int main(){
	using namespace solution;
	Prepare();
	Solve();
	return 0;
}

