using Graph=vector<vector<int>>;
int main(){
    int n; cin>>n;
    Graph g(n),rg(n);
    for(int i=0;i<n;i++){
        int p; cin>>p; p--;
        g[p].push_back(i);
        rg[i].push_back(p);
    }
    vector<int> a(n,-1);
    auto grundy=[&](int v){
        set<int> s;
        for(auto to:g[v]){
            if(a[to]!=-1) s.insert(a[to]);
        }
        for(int i=0;;i++){
            if(!s.count(i)){
                return i;
            }
        }
        assert(false);
    };
    auto greedy=[&](){
        vector<int> d(n);
        queue<int> que;
        for(int i=0;i<n;i++){
            d[i]=g[i].size();
            if(d[i]==0){
                que.push(i);
            }
        }
        while(!que.empty()){
            int v=que.front(); que.pop();
            a[v]=grundy(v);
            for(auto to:rg[v]){
                d[to]--;
                if(d[to]==0) que.push(to);
            }
        }
    };
    function<bool(int,int)> dfs=[&](int v,int val){
        assert(a[v]==-1);
        for(auto to:g[v]){
            if(a[to]==val) return false;
        }
        for(auto to:rg[v]){
            if(a[to]==val) return false;
        }
        a[v]=val;
        for(auto pre:rg[v]){
            if(a[pre]==-1){
                bool ret=dfs(pre,grundy(pre));
                a[v]=-1;
                return ret;
            }
        }
        return true;
    };
    auto solve=[&](int v){
        int val=grundy(v);
        if(dfs(v,val)) return true;
        for(auto to:g[v]){
            if(a[to]==-1){
                if(dfs(to,val)) return true;
                else return false;
            }
        }
        assert(false);
    };

    greedy();
    int id=find(a.begin(),a.end(),-1)-a.begin();
    cout<<(solve(id) ? "POSSIBLE" : "IMPOSSIBLE")<<endl;

    return 0;
}

