bool test(int x){
	q[size=1]=x;
	for (int i=1;i<=size;i++){
		int v=q[i];
		C++;
		for (int j=0;j<e[v].size();j++) vis[ans[e[v][j]]]=C;
		while (vis[ans[v]]==C) ans[v]++;
		if (!--deg[pre[v]]) q[++size]=pre[v];
	}
	for (int i=1;i<=n;i++){
		C++;
		for (int j=0;j<e[i].size();j++) vis[ans[e[i][j]]]=C;
		int Ans=0;
		while (vis[Ans]==C) Ans++;
		if (Ans!=ans[i]) return 0;
	}
	return 1;
}
int circle;
void find_cir(int x){
	static int vis[N],C;C++;
	while (!vis[x]) vis[x]=C,x=pre[x];
	if (vis[x]==C) circle=x;
}
void work(){
	for (int i=1;i<=n;i++) find_cir(i);
	int x=circle;deg[pre[x]]--;
	C++;
	for (int i=0;i<e[x].size();i++) vis[ans[e[x][i]]]=C;
	while (vis[ans[x]]==C) ans[x]++;
	if (test(pre[x])) return;
	C++;
	for (int i=0;i<e[x].size();i++) vis[ans[e[x][i]]]=C;
	for (ans[x]++;vis[ans[x]]==C;ans[x]++);
	if (!test(pre[x])) puts("IMPOSSIBLE"),exit(0);
}
