	for (int i=1;i<=n;i++) deg[i]=e[i].size();
	for (int i=1;i<=n;i++) if (!deg[i]) q[++size]=i;
	for (int i=1;i<=size;i++){
		int v=q[i];
		C++;
		for (int j=0;j<e[v].size();j++) vis[ans[e[v][j]]]=C;
		while (vis[ans[v]]==C) ans[v]++;
		if (!--deg[pre[v]]) q[++size]=pre[v];
	}
