vector<vector<int>> g;
vector<int> a;
vector<int> b;
vector<int> used;
vector<int> circle;
bool dfs(int v) {
    used[v] = 1;
    bool circ = false;
    set<int> grandi;
    for (int to : g[v]) {
        if (used[to] == 1) {
            circ = true;
        }
        else if (used[to] == 2) {
            grandi.insert(a[to]);
        }
        else {
            bool res = dfs(to);
            if (!res) {
                grandi.insert(a[to]);
            }
            else {
                circ = true;
            }
        }
    } 
    a[v] = 0;
    while (grandi.find(a[v]) != grandi.end()) {
        a[v]++;
    }
    b[v] = a[v] + 1;
    while (grandi.find(b[v]) != grandi.end()) {
        b[v]++;
    }
    if(circ) {
        circle.push_back(v);
    }
    used[v] = 2;
    return circ;
}


