        cin >> v;
        --v;
        g[v].push_back(i);
    }
    for (int i = 0; i < N; ++i) {
        if (!used[i]) {
            dfs(i);
        }
    }
    reverse(circle.begin(), circle.end());
    int v = a[circle[0]];
    for (int i = 1; i < circle.size(); ++i) {
        if (a[circle[i]] == v) {
            v = b[circle[i]];
        }
        else {
            v = a[circle[i]];
        }
    }
    if (v != a[circle[0]]) {
