#include <bits/stdc++.h>

using namespace std;

const int INF = 1e9;

vector< vector<int> > g;

bool dfs(int cur, vector<int>& used, vector<int>& cycle) {
	if (used[cur] == 1) {
		cycle[cur] = true;
		return true;
	}
	used[cur] = 1;
	for (int nex : g[cur]) {
		if (dfs(nex, used, cycle)) {
			cycle[cur] = true;
			return true;
		}
	}
	used[cur] = 2;
	return false;
}

int solve(int cur, vector<int>& cycle, vector<int>& grundy) {
	if (grundy[cur] != INF) return grundy[cur];
	int res = 0;
	for (int nex : g[cur]) {
		if (cycle[nex]) continue;
		int x = solve(nex, cycle, grundy);
		if (res == x) res++;
	}
	return grundy[cur] = res;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;
	cin >> n;
	g.resize(n);
	for (int i = 0; i < n; i++) {
		int p;
		cin >> p;
		p--;
		g[p].push_back(i);
	}
	vector<int> used(n, 0), cycle(n, false);
	for (int i = 0; i < n; i++) {
		if (used[i]) continue;
		dfs(i, used, cycle);
	}
	int x = -1, cnt = 0;
	bool ans = true;
	vector<int> grundy(n, INF);
	for (int i = 0; i < n; i++) {
		if (cycle[i]) {
			cnt++;
			int y = solve(i, cycle, grundy);
			if (x == -1) {
				x = y;
				ans = false;
			} else if (x != y) {
				ans = true;
				break;
			}
		}
	}
	assert(ans);
	if (!ans) ans = (cnt % 2 == 0);
	cout << (ans ? "POSSIBLE" : "IMPOSSIBLE") << endl;
	return 0;
}

