int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	vector<vector<int>>edge(N);
	vector<int>rev_edge(N);
	for (int i = 0; i < N; i++) {
		cin >> M;
		M--;
		edge[M].push_back(i);
		rev_edge[i] = M;
	}
	queue<int>Q;
	vector<int>num(N,-1);
	vector<int>dir(N);
	for (int i = 0; i < N; i++) {
		if (edge[i].empty()) {
			Q.push(i);
			num[i] = 0;
		}
		else {
			dir[i] = edge[i].size();
		}
	}
	if (Q.empty()) {
		if (N % 2) {
			cout << "IMPOSSIBLE\n";
		}
		else {
			cout << "POSSIBLE\n";
		}
		return 0;
	}
	while (!Q.empty()) {
		int cn = Q.front();
		Q.pop();
		if (num[cn] == -1) {
			vector<int>v;
			for (auto i : edge[cn])v.push_back(num[i]);
			sort(v.begin(), v.end());
			num[cn] = 0;
			for (auto i : v) {
				if (i < num[cn])continue;
				if (i > num[cn])break;
				num[cn]++;
			}
		}
		dir[rev_edge[cn]]--;
		if (!dir[rev_edge[cn]])Q.push(rev_edge[cn]);
	}
	vector<int>loop;
	for (int i = 0; i < N; i++) {
		if (num[i] == -1) {
			loop.push_back(i);
		}
	}
	vector<int>v;
	for (auto i : edge[loop[0]])v.push_back(num[i]);
	sort(v.begin(), v.end());
	for (auto i : v) {
		if (i < L)continue;
		if (i > L)break;
		L++;
	}
	bool flag = true;
	num[loop[0]] = L;
	int nx = rev_edge[loop[0]];
	while (nx != loop[0]) {
		vector<int>w;
		for (auto i : edge[nx])w.push_back(num[i]);
		sort(w.begin(), w.end());
		num[nx] = 0;
		for (auto i : w) {
			if (i < num[nx])continue;
			if (i > num[nx])break;
			num[nx]++;
		}
		nx = rev_edge[nx];
	}
	for (int i = 0; i < N; i++) {
		for (auto j : edge[i]) {
			if (num[i] == num[j]) {
				flag = false;
			}
		}
	}
	if (flag) {
		cout << "POSSIBLE\n";
		return 0;
	}
	for (auto i : loop)num[i] = -1;
	num[loop[0]] = L + 1;
	nx = rev_edge[loop[0]];
	while (nx != loop[0]) {
		vector<int>w;
		for (auto i : edge[nx])w.push_back(num[i]);
		sort(w.begin(), w.end());
		num[nx] = 0;
		for (auto i : w) {
			if (i < num[nx])continue;
			if (i > num[nx])break;
			num[nx]++;
		}
		if (rev_edge[nx] == loop[0]) {
			if (num[nx] != L) {
				cout << "IMPOSSIBLE\n";
				return 0;
			}
		}
		nx = rev_edge[nx];
	}
	for (int i = 0; i < N; i++) {
		for (auto j : edge[i]) {
			if (num[i] == num[j]) {
				cout << "IMPOSSIBLE\n";
				return 0;
			}
		}
	}
	cout << "POSSIBLE\n";
	return 0;

}

