int dfs(int v, int p=-1) {
  if (used[v] == ui) return v;
  if (used[v]) return -1;
  used[v] = ui;
  rep(i,sz(to[v])) {
    int u = to[v][i];
    if (u == p) continue;
    int r = dfs(u,v);
    if (r == -1) continue;
    vs.pb(v);
    if (v == r) return -1;
    return r;
  }
  return -1;
}

int gfs(int v, int p=-1) {
  set<int> s;
  rep(i,sz(to[v])) {
    int u = to[v][i];
    if (u == p || t[u]) continue;
    int r = gfs(u,v);
    s.insert(r);
  }
  for (int i = 0;; ++i) {
    if (s.count(i)) continue;
    return i;
  }
}

