using namespace std;

const int Maxn = 200005;
const int Maxm = 200;

bool has[Maxn][Maxm];
int res[Maxn];
bool tk[Maxn];
int root, rootval;
int n;
vector <int> neigh[Maxn];
int P[Maxn];

void Solve(int v)
{
	for (int i = 0; i < neigh[v].size(); i++) {
		int u = neigh[v][i];
		if (u == root) has[v][rootval] = true;
		else { Solve(u); has[v][res[u]] = true; }
	}
	res[v] = 0;
	while (has[v][res[v]]) res[v]++;
	for (int i = 0; i < neigh[v].size(); i++) {
		int u = neigh[v][i];
		if (u == root) has[v][rootval] = false;
		else has[v][res[u]] = false;
	}
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		scanf("%d", &P[i]); 
		neigh[P[i]].push_back(i);
	}
	root = 1;
	while (!tk[root]) {
		tk[root] = true; root = P[root];
	}
	for (rootval = 0; rootval < Maxm; rootval++) {
		res[root] = rootval;
		for (int j = 0; j < neigh[root].size(); j++) {
			int u = neigh[root][j]; Solve(u);
			has[root][res[u]] = true;
		}
		int my = 0;
		while (has[root][my]) my++;
		if (res[root] == my) { printf("POSSIBLE\n"); return 0; }
		for (int j = 0; j < neigh[root].size(); j++) {
			int u = neigh[root][j];
			has[root][res[u]] = false;
		}
	}
	printf("IMPOSSIBLE\n");
	return 0;
}

