using namespace std;

template<typename T>
void read(T& n){
	char ch; int sign = 1;
	while (!isdigit(ch = getchar())) if (ch == '-') sign = -1;
	n = ch - '0';
	while (isdigit(ch = getchar())) n = n * 10 + ch - '0';
	n *= sign;
}
typedef long long ll;
const int INF = 1e9 + 7;
const int N = 211111;
int n, x, mark(0);
int vis[N], mex[N];
struct edge{int to, nxt;} g[N];
int ghead[N], gtail(0);
vector<int> cir;
pr candidates[N];

void add(int l, int r){g[++gtail] = (edge){r, ghead[l]}, ghead[l] = gtail;}
void dfs(int x){
	vis[x] = mark;
	for (int p = ghead[x]; p; p = g[p].nxt){
		int v = g[p].to;
		if (vis[v] == mark){cir.pb(v), cir.pb(x); return ;}
		else if (!vis[v]){
			dfs(v);
			if (!cir.size()) continue;
			if (*cir.begin() == x) return;
			if (*(cir.end() - 1) == v){cir.pb(x); return;}
		}
	}
}
void grundy(int x, bool isrt, int nxt){
	for (int p = ghead[x]; p; p = g[p].nxt){
		int v = g[p].to; if (v == nxt) continue;
		grundy(v, 0, nxt);
	}
	mark++;
	for (int p = ghead[x]; p; p = g[p].nxt){
		int v = g[p].to; if (v == nxt) continue;
		vis[mex[v]] = mark;
	}
	int pos = 0;
	for (; vis[pos] == mark; pos++); mex[x] = pos;
	if (isrt){
		candidates[x].x = pos; 
		for (++pos; vis[pos] == mark; ++pos); 
		candidates[x].y = pos;
	}
}
bool verify(){
	for (int i = 0; i < (int)cir.size() - 1; ++i){
		int u = cir[i]; mark++;
		for (int p = ghead[u]; p; p = g[p].nxt)
			vis[mex[g[p].to]] = mark;
		int pos = 0; for (; vis[pos] == mark; pos++); mex[u] = pos;
	}
	int u = *(cir.end() - 1); mark++;
	for (int p = ghead[u]; p; p = g[p].nxt)
		vis[mex[g[p].to]] = mark;
	int pos = 0; for (; vis[pos] == mark; pos++); return pos == mex[u];
}

int main(){
	read(n);
	rep(i, 1, n) read(x), add(x, i);
	rep(i, 1, n) if (!vis[i]) mark++, dfs(i);
	if (!cir.size()) return 0 * puts("POSSIBLE");
	for (int i = 0; i < cir.size(); ++i)
		grundy(cir[i], 1, cir[(i+cir.size()-1)%cir.size()]);
	mex[*(cir.end() - 1)] = candidates[*(cir.end() - 1)].x;
	if (verify()) return 0 * puts("POSSIBLE");
	mex[*(cir.end() - 1)] = candidates[*(cir.end() - 1)].y;
	if (verify()) return 0 * puts("POSSIBLE");
	puts("IMPOSSIBLE");
	return 0;
}

#include <bits/stdc++.h>
#define REP(i, a, b) for (int i = a; i <= b; ++i)
#define PER(i, a, b) for (int i = a; i >= b; --i)
#define RVC(i, S) for (int i = 0; i < S.size(); ++i)
#define mp make_pair
#define pb push_back
#define debug(...) fprintf(stderr, __VA_ARGS__)
#define fi first
#define se second
using namespace std;

typedef long long LL;
typedef pair<int, int> pii;
typedef vector<int> VI;

const int N = 200005;
int pi[N], n, out[N], on_tree[N], Q[N], sg[N], vis[N], va[N];
VI to[N];

void tok(int x){
	memset(va, 0, sizeof va);
	for (int i = pi[x]; i != x; i = pi[i]){
		RVC(j, to[i]) va[sg[to[i][j]]] = i;
		for (sg[i] = 0; va[sg[i]] == i || vis[sg[i]] == i; ++sg[i]);
	}
	RVC(j, to[x]) va[sg[to[x][j]]] = x;
	int tmp = 0;
	for (; va[tmp] == x || vis[tmp] == x; ++tmp);
	if (tmp == sg[x]){
		puts("POSSIBLE");
		exit(0);
	}
}

int main(){
	scanf("%d", &n);
	REP(i, 1, n){
		scanf("%d", &pi[i]);
		to[pi[i]].pb(i);
		++out[pi[i]];
	}
	int hd = 1, tl = 0;
	REP(i, 1, n) if (!out[i]) Q[++tl] = i;
	while (hd <= tl){
		int x = Q[hd++];
		on_tree[x] = 1;
		--out[pi[x]];
		if (!out[pi[x]]) Q[++tl] = pi[x];
	}
	REP(i, 1, tl){
		int x = Q[i];
		RVC(j, to[x]) vis[sg[to[x][j]]] = x;
		for (sg[x] = 0; vis[sg[x]] == x; ++sg[x]);
	}
	REP(i, 1, n) if (!on_tree[i]){
		RVC(j, to[i]) vis[sg[to[i][j]]] = i;
		for (sg[i] = 0; vis[sg[i]] == i; ++sg[i]);
		tok(i);
		for (++sg[i]; vis[sg[i]] == i; ++sg[i]);
		tok(i);
		return puts("IMPOSSIBLE"), 0;
	}
	return 0;
}

