int n=ini;
Lowlink lowlink(n);
VI onCircuit(n, 0);
VI used(n, 0);
VVI orig(n);
VI rev(n);
VI num(n, 0);

void dfs(int i) {
  if(onCircuit[i]) return;
  if(used[i]) return;
  used[i] = 1;
  set<int> st;
  for(int j : orig[i]) {
    assert(onCircuit[j] == false);
    dfs(j);
    st.insert(num[j]);
  }
  int t=0;
  while(st.count(t)) t++;
  num[i] = t;
}

bool solve(int now) {
  int last = now;
  now = rev[now];
  while(1) {
    set<int> st;
    for(int j:orig[now]) {
      st.insert(num[j]);
    }
    int nnum = 0;
    while(st.count(nnum)) nnum++;
    if(num[now] <= nnum) {
      if(num[now] == nnum) {
        if(last == now) {
          return 1;
        }
      } else {
        num[now] = nnum;
        last = now;
      }
    } else {
      return 0;
    }
    now = rev[now];
  }
}

int main() {
  REP(i, n) {
    int p = ini-1;
    // p -> i
    lowlink.addEdge(p, i);
    orig[p].PB(i);
    rev[i] = p;
  }
  lowlink.calc();

  REP(i, n) {
    for(auto edge : lowlink.g[i]) {
      int j = edge.to, idx = edge.idx;
      if(!lowlink.isBridge[idx]) {
        onCircuit[i] = 1;
      }
    }
  }

  REP(i, n) dfs(i);

  int now=-1;
  REP(i, n) {
    if(onCircuit[i]) {
      now = i;
    }
  }
  assert(now != -1);
  if(solve(now)) {
    cout << "POSSIBLE" << endl;
    return 0;
  }
  REP(i, n) {
    if(onCircuit[i]) {
      num[i] = 0;
    }
  }
  if(solve(rev[now])) {
    cout << "POSSIBLE" << endl;
    return 0;
  }
  cout << "IMPOSSIBLE" << endl;
}

