void dfs_cycle(int v, int pr = -1) {
    if (clr[v] == 2 || found)
        return;
    p[v] = pr;
    if (clr[v] == 1) {
        int cur = v;
        do
            vc.push_back(cur), cur = p[cur];
        while (cur != v);
        found = true;
        return;
    }
    clr[v] = 1;
    for (int to : g[v])
        dfs_cycle(to, v);
    clr[v] = 2;
}

int dfs_grundy(int v) {
    if (grundy[v] == -1) {
        vector<int> vec;
        for (int to : g[v]) {
            if (to != cycle[v])
                vec.push_back(dfs_grundy(to));
        }
        sort(vec.begin(), vec.end());
        vec.resize(unique(vec.begin(), vec.end()) - vec.begin());
        int f = -1, f2 = -1;
        if (vec.size() == 0) {
            f = 0;
            f2 = 1;
        } else {
            if (vec[0] > 0) {
                f = 0;
                if (vec[0] > 1) {
                    f2 = 1;
                }
            }
            for (int i = 0; i + 1 < vec.size(); ++i) {
                if (vec[i] + 2 < vec[i + 1]) {
                    if (f == -1)
                        f = vec[i] + 1, f2 = vec[i] + 2;
                    else if (f2 == -1)
                        f2 = vec[i] + 1;
                } else if (vec[i] + 1 < vec[i + 1]) {
                    if (f == -1)
                        f = vec[i] + 1;
                    else if (f2 == -1)
                        f2 = vec[i] + 1;
                }
            }
            if (f == -1)
                f = vec.back() + 1, f2 = f + 1;
            else
                f2 = vec.back() + 1;
        }
        grundy[v] = f;
        grundy2[v] = f2;
    }
    return grundy[v];
}

