struct DSU{
    int n;
    vi par;

    DSU(int _n){
        n = _n;
        par.resize(n);
        for(int i=0; i<n; i++)
            par[i] = i;
    }

    int find(int i){
        if(i == par[i]) return i;
        return par[i] = find(par[i]);
    }

    bool same(int i, int j){
        return find(i) == find(j);
    }

    void join(int i, int j){
        i = find(i), j = find(j);
        par[j] = i;
    }
};
