int mex(vi &v){
    sort(all(v));
    v.resize( unique(all(v)) - v.begin() );
    int sz = v.size();
    int ret = 0;
    while(ret < sz && v[ret] == ret) ret++;
    return ret;
}
void DFS(int u){

    vi vec;
    for(int i=0; i<G[u].size(); i++)
    {
        int v = G[u][i];
        if(v == save) continue;

        if(num[v] == -1)
            DFS(v);

        vec.PB( num[v] );
    }

    num[u] = mex(vec);
}
void go(int u){

