    vis[u] = 1;

    vi vec;
    for(int i=0; i<G[u].size(); i++)
    {
        int v = G[u][i];
        vec.PB(num[v]);
    }

    int nw = mex(vec);
    if(nw == num[u]) return;

    num[u] = nw;
    go(P[u]);
}
