		cin >> P[i];
		di[P[i]].PB(i);
		tw[P[i]].PB(i);
		re[i].PB(P[i]);
		tw[i].PB(P[i]);
		val[i]=-1;
	}
	queue<int> qu;
	FOR(i,1,N+1){
		if(di[i].empty()){
			qu.push(i);
		}
	}
	while(!qu.empty()){
		int now=qu.front();
		qu.pop();
		sort(ALL(nums[now]));
		if(nums[now].empty() or nums[now][0]!=0) val[now]=0;
		else{
			int nowp=0;
			REP(i,nums[now].size()){
				if(nowp<nums[now][i]) return false;
				else if(nowp==nums[now][i]) nowp++;
			}
		}
		REP(i,re[now].size()){
			int next=re[now][i];
			nums[next].PB(val[now]);
			reached[next]++;
			if(di[next].size()==reached[next]){
