using namespace std;

int n;
const int maxn = 2e5 + 5;
int p[maxn];
int deg[maxn];
vector<int> G[maxn];
int sg[maxn];
bool vis[maxn];
bool cycle[maxn];

bool check(){
    memset(vis, 0, sizeof(vis));
    for(int i = 1;i <= n;i++){
        for(auto v : G[i]){
            if(sg[v] == sg[i])
                return false;
            vis[sg[v]] = true;
        }
        for(int j = 0;j < sg[i];j++){
            if(!vis[j])
                return false;
        }
        for(auto v : G[i]){
            vis[sg[v]] = false;
        }
    }
    return true;
}

bool solve(){
    int start = 0;
    for(int i = 1;i <= n;i++){
        if(cycle[i] == 0){
            start = i;
        }
    }
    memset(vis, 0, sizeof(vis));
    vector<int> candidate;
    for(auto v : G[start]){
        if(cycle[v]){
            vis[sg[v]] = true;
        }
    }
    for(int i = 0;i < maxn;i++){
        if(!vis[i]){
            candidate.push_back(i);
        } 
        if(candidate.size() == 2){
            break;
        }
    } 
    for(auto x : candidate){
        memset(vis, 0, sizeof(vis));
        sg[start] = x;
        int now = p[start];
        while(now != start){
            for(auto v : G[now]){
                vis[sg[v]] = true;
            }
            for(int i = 0;i < maxn;i++){
                if(!vis[i]){
                    sg[now] = i;
                    break;
                }
            }
            for(auto v : G[now]){
                vis[sg[v]] = false;
            }
            now = p[now];
        }
        if(check())
            return true;
    }
    return false;
} 

int main(){
    while(cin >> n){
        for(int i = 1;i <= n;i++){
            G[i].clear();
        }
        for(int i = 1;i <= n;i++){
            scanf("%d", &p[i]);
            deg[p[i]]++;
            G[p[i]].push_back(i);
        }
        queue<int> q;
        for(int i = 1;i <= n;i++){
            if(deg[i] == 0){
                q.push(i);
            }
        }
        memset(vis, 0, sizeof(vis));
        memset(cycle, 0, sizeof(cycle));
        while(!q.empty()){
            int Q = q.front();q.pop();
            deg[p[Q]]--;
            cycle[Q] = true;
            if(deg[p[Q]] == 0){
                q.push(p[Q]);
            }
            for(auto v : G[Q]){
                vis[sg[v]] = true;
            }
            for(int i = 0;i < maxn;i++){
                if(vis[i] == false){
                    sg[Q] = i;
                    break;
                }
            }
            for(auto v : G[Q]){
                vis[sg[v]] = false;
            }
        }
        if(solve()){
            cout << "POSSIBLE" << endl;
        }else{
            cout << "IMPOSSIBLE" << endl;
        }
    }
    return 0;
}

