ll dfs(ll v) {
	go[v] = 1;
	for (ll w : g[v]) {

		if (go[w] == 0) {
			ll u = dfs(w);
			if (u!=0) { return u; }
		}

		if (go[w] == 1 && back[w] == 0) {return v;}
	}
	back[v] = 1;
	return 0;

}

vector<ll> gr;

ll rt, X;

ll grundy(ll v, bool b) {
	set<ll> st;

	for (ll w : g[v]) {
		if (w != rt) { st.insert(grundy(w, b)); }
	}

	ll ret = 0;
	while (1) {
		if (!st.count(ret)) {
			if (v == X && b == 1) { ret++; }
			gr[v] = ret;
			return ret; }
		ret++;
	}
}


