    int i = 0, p = 0;
    for (; list[p] == i; ++i, ++p) { }
    min[u] = i++;
    for (; list[p] == i; ++i, ++p) { }
    sec[u] = i;
    return min[u];
}

int cnt;

void solve()
{
    for (int i = 1; i <= N; ++i) {
        if (vis[i])
            continue;
        ++visclock;
        int j = i;
        for (; !vis[j]; j = P[j]) {
            vis[j] = visclock;
        }
        if (vis[j] == visclock) {
            for (; !oncycle[j]; j = P[j]) {
                oncycle[j] = true;
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
