    // }

    std::fill(vis + 1, vis + N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        if (vis[i] || !oncycle[i])
            continue;
        ++cnt;
        int last = min[i];
        vis[i] = true;
        for (int j = P[i]; j != i; j = P[j]) {
