void dfs(const int nd, const vector< vector<int> > &adj,
         vector<int> &dp, vector<int> &state)
{
  state[nd] = 1;

  // Leaf
  if (adj[nd].size() == 0) {
    dp[nd] = 0;
    state[nd] = 2;
    return;
  }

  // Calculating Child Nodes
  for (int ind = 0; ind < (int)adj[nd].size(); ++ind) {
    int child_nd = adj[nd][ind];
    if (state[child_nd] == 2) continue;
    if (state[child_nd] == 1) continue; // XXX
    dfs(child_nd, adj, dp, state);
  }

  // Determining Value of "nd"
  set<int> child_values;
  for (int ind = 0; ind < (int)adj[nd].size(); ++ind) {
    int child_nd = adj[nd][ind];
    if (dp[child_nd] == -1) {
      state[nd] = 2;
      return;
    }
    child_values.insert(dp[child_nd]);
  }
  int v = 0;
  while (true) {
    if (!child_values.count(v)) break;
    ++v;
  }
  dp[nd] = v;

  state[nd] = 2;
}

