void work ()
{
	// main work

	int kc = 0;
	lpi ( i, 1, n ){
		if ( !vis[i] ) findcir ( i, ++kc );

		if ( cir.size () ) break;
	}

	int size = cir.size () - 1;
	lpi ( i, 1, size ) inc[cir[i]] = true;

	lpi ( i, 1, size ) dfs ( i );

	int nn = cir[1], pe = -1, pre = -1;
	lp ( i, 0, no[nn].size () ){
		while ( no[nn][i] - pre > 1 ){
			++pre;

			if ( pe == -1 ){
				a[nn] = pre;
				lpi ( j, 2, size ){
					a[cir[j]] = getv ( cir[j] );
				}
				if ( a[cir[size]] ^ pre ) YES ();
				pe = pre;
			} else{
				a[nn] = pre;
				lpi ( j, 2, size ) a[cir[j]] = getv ( cir[j] );
				if ( a[cir[size]] == pe ) YES ();
				else NO ();
			}
		}
	}
}



void findcir ( int now, int nc )
{
	if ( vis[now] == nc ){
		cir.push_back ( 0 );
		for ( int t = top; stk[t+1] ^ now; --t ){
			cir.push_back ( stk[t] );
		}
		return;
	} else if ( vis[now] ) return;

	vis[now] = true;
	stk[++top] = now;

	for ( int i = la[now]; ~i; i = edge[i].last ) findcir ( edge[i].v, nc );

	--top;
}

void dfs ( int now )
{
	for ( int i = la[now]; ~i; i = edge[i].last ){
		if ( !inc[edge[i].v] ){
			dfs ( edge[i].v );
			no[now].push_back ( a[edge[i].v] );
		}
	}

	sort ( no[now].begin (), no[now].end () );
	no[now].erase ( unique ( no[now].begin (), no[now].end () ), no[now].end () );
	no[now].push_back ( INF );

	int pre = -1;
	lp ( i, 0, no[now].size () ){
		if ( no[now][i] - pre > 1 ){
			a[now] = pre + 1;
			break;
		}
		pre = no[now][i];
	}
}

int getv ( int now )
{
	AR( int ) tn;
	for ( int i = la[now]; ~i; i = edge[i].last ){
		tn.push_back ( a[edge[i].v] );
	}

	sort ( tn.begin (), tn.end () );
	tn.erase ( unique ( tn.begin (), tn.end () ), tn.end () );
	tn.push_back ( INF );

	int pre = -1;
	lp ( i, 0, tn.size () ){
		if ( tn[i] - pre > 1 ){
			return pre + 1;
		}
		pre = tn[i];
	}
}

