int mex(vi a)
{
	sort(all(a));
	if(a.empty()||a[0]>0)
		return 0;
	rep(i,a.size()-1)
		if(a[i]+1<a[i+1])
			return a[i]+1;
	return a.back()+1;
}

int calc(const vvi& g,int u,vi& grundy)
{
	if(grundy[u]!=-1)
		return grundy[u];
	vi a;
	for(int v:g[u])
		a.push_back(calc(g,v,grundy));
	return grundy[u]=mex(a);
}

bool check(const vvi& g,const vi& grundy)
{
	rep(u,g.size()){
		vi a;
		for(int v:g[u]){
			if(grundy[u]==grundy[v])
				return false;
			a.push_back(grundy[v]);
		}
		if(mex(a)!=grundy[u])
			return false;
	}
	return true;
}

