			on_cycle[v]=1;

		vi grundy(n,-1);
		rep(i,n) if(on_cycle[i])
			for(int v:g[i]) if(!on_cycle[v])
				calc(g,v,grundy);

		bool ok=false;
		{
			int next=-1;
			for(int v:g[root]) if(on_cycle[v])
				next=v;

			vi a;
			for(int v:g[root]) if(!on_cycle[v])
				a.push_back(grundy[v]);
			int x=mex(a);
			grundy[root]=x;
			calc(g,next,grundy);
			ok|=check(g,grundy);

			a.push_back(x);
			int y=mex(a);
			grundy[root]=y;
			for(int v=p[root];v!=root;v=p[v])
				grundy[v]=-1;
			calc(g,next,grundy);
			ok|=check(g,grundy);
		}
