void find_cycle(const V<V<i64>> &edges, V<bool> &is_visited, V<i64> &path) {
    is_visited[path.back()] = true;

    FORE (n, edges[path.back()]) {
        path.push_back(n);
        if (path.front() == path.back()) {
            return ;
        }
        if (is_visited[path.back()]) continue ;
        find_cycle(edges, is_visited, path);
        if (path.size() > 1 && path.front() == path.back()) {
            return ;
        }
        path.pop_back();
    }
}


int body(int &argc, char **argv) {
    using namespace debug;
    auto N = read<i64>();
    auto ps = read<i64>(N);
    FORE (p, ps) {
        p -= 1;
    }

    auto edges = V<V<i64>>(N, V<i64>());
    auto edges2 = V<i64>(N);
    REP (i, N) {
        // ps[i] -> i
        auto n1 = ps[i];
        i64 n2 = i;
        edges[n1].push_back(n2);
        edges2[n2] = n1;
    }

    // Find cycle
    V<i64> cycle;
    auto s = stack<V<i64>>();
    V<bool> is_visited(N);
    REP (i, N) {
        if (is_visited[i]) continue ;
        cycle = {i};
        find_cycle(edges, is_visited, cycle);

        if (cycle.size() > 1 && cycle.front() == cycle.back()) {
            break ;
        }
    }

    V<i64> values(N, -1);
    auto fill_value = [&](i64 n, auto f) -> i64 {
        if (values[n] != -1) {
            return values[n];
        }

        unordered_set<i64> xs;
        FORE (n2, edges[n]) {
            xs.insert(f(n2, f));
        }

        REP(i, xs.size() + 1) {
            if (xs.find(i) == xs.end()) {
                values[n] = i;
                return i;
            }
        }
    };

    unordered_set<i64> in_cycles(cycle.begin(), cycle.end());
    REP (i, N) {
        if (in_cycles.find(i) != in_cycles.end()) {
            continue;
        }

        fill_value(i, fill_value);
    }

    bool possible = false;
    auto start = cycle.back();
    unordered_set<i64> start_edges;
    i64 v1 = 0;
    i64 cnt = 0;
    FORE(e, edges[start]) {
        if (values[e] == -1) {
            cnt += 1;
        }
        v1 = max(v1, values[e]);
        start_edges.insert(values[e]);
    }
    auto max_candidate = v1 + 2 + cnt;
    REP (x, max_candidate) {
        if (start_edges.find(x) != start_edges.end()) {
            continue ;
        }

        auto vs = values;
        vs[start] = x;
        FORR (i, 1, cycle.size() - 1) {
            auto n = cycle[i];
            unordered_set<i64> xs;
            FORE (n2, edges[n]) {
                xs.insert(vs[n2]);
            }

            REP(j, xs.size() + 1) {
                if (xs.find(j) == xs.end()) {
                    vs[n] = j;
                    break ;
                }
            }
        }

        auto n = cycle[0];
        auto v = vs[n];
        V<bool> exists(v);
        bool ok = true;
        FORE (n2, edges[n]) {
            auto v2 = vs[n2];
            if (v2 == v) {
                ok = false;
                break;
            }
            if (v2 < v) {
                exists[v2] = true;
            }
        }
        REP (i, v) {
            auto f = exists[i];
            if (!f) {
                ok = false;
                break;
            }
        }

        if (ok) {
            possible = true;
            break;
        }
    }

    cout << (possible ? "POSSIBLE": "IMPOSSIBLE") << endl;

    return 0;
}

