int mex(std::vector<int> &v) {
	if(v.empty() || v.front() > 0)
		return 0;
	for(int i = 0; i + 1 < v.size(); ++i)
	if(v[i + 1] - v[i] > 1)
		return v[i] + 1;
	return v.back() + 1;
}

bool dfs(int u) {
	vis[u] = 1;
	std::sort(pre[u].begin(), pre[u].end());
	la[u] = mex(pre[u]);
	if(vis[p[u]])
		return la[u] != la[p[u]];
	pre[p[u]].push_back(la[u]);
	if(!--d[p[u]])
		return dfs(p[u]);
	return true;
}

