struct Node{
    vector<Node*> dests;
    void add(Node* n){
        dests.push_back(n);
    }
    bool dfs(vector<Node*>& cand, unordered_set<Node*>& visited, Node* start, Node* from = nullptr){
        if(this == start && from){
            return true;
        }
        cand.push_back(this);
        for(Node* d : dests){
            if(d == from){ continue; }
            if(d -> dfs(cand, visited, start, this)){
                return true;
            }
        }
        cand.pop_back();
        return false;
    }
    int dfs2(Node* from){
        int ret = 1;
        for(Node* d : dests){
            if(d == from){ continue; }
            ret += d->dfs2(this);
        }
        return ret;
    }
};

