pair<int, int> grundy(vector<int> &a){
    int mx = *max_element(a.begin(), a.end());
    vector<bool> flag(mx+1, false);
    for(int x : a) {
        if(x == -1) continue;
        flag[x] = true;
    }
    pair<int, int> ret = pair<int, int>(-1, -1);
    for(int i=0; i<=mx; i++){
        if(!flag[i]){
            if(ret.first == -1) ret.first = i;
            else{
                ret.second = i;
                break;
            }
        }
    }
    if(ret.first == -1) ret.first = mx+1;
    if(ret.second == -1) ret.second = mx+1;
    if(ret.second == ret.first) ret.second++;
    return ret;
}

void setOutside(int s){
    if(ans[s] != -1) return;
    if(G[s].empty()){
        ans[s] = 0;
        return;
    }

    vector<int> nums;
    for(int t : G[s]){
        setOutside(t);
        nums.push_back(ans[t]);
    }
    pair<int, int> gr = grundy(nums);
    ans[s] = gr.first;
}


