	if(!vec.size()) return a[v] = -1;
	sort(all(vec));
	vec.erase(unique(all(vec)),vec.end());
	int prev = -1;
	if(vec[0] != 0) return a[v] = 0;
	for(int i = 0;i < vec.size();i++){
		if(prev + 1 != vec[i]) return a[v] = prev;
		prev++;
	}
	return a[v] = prev + 1;
}

