bool color(std::vector<int>& a, std::vector<unsigned> &p, unsigned k) {
  if (a[k] == -1) {
    a[k] = 0;
  }
  if (a[p[k]] == a[k]) {
    return false;
  } else {
    a[p[k]] = (a[k] == 0 ? 1 : 0);
    return color(a, p, p[k]);
  }
}

