        q.push_back(s[i]);
        if(s[i]==s[s.size()-1]) break;
    }
    m=q.size();
    for(int i=0;i<m;i++){
        for(int j : g[q[i]]){
            if((i!=m-1 && j!=q[i+1]) || (i==m-1 && j!=q[0])){
                t=Find(j);
                t++; t%=2;
                if(t) y[i+1]=1;
                else x[i+1]=1;
            }
        }
    }
    for(int k=0;k<4;k++){
        for(int i=1;i<=m+1;i++){
            dp[i][0]=dp[i][1]=dp[i][2]=dp[i][3]=0;
        }
        dp[m+1][k]=1;
        for(int i=m;i;i--){
            if(!x[i]){
                dp[i][0]=max(dp[i+1][1],max(dp[i+1][2],dp[i+1][3]));
            }
            if(!y[i]){
                if(x[i]) dp[i][1]=max(dp[i+1][0],max(dp[i+1][2],dp[i+1][3]));
                else dp[i][1]=dp[i+1][0];
            }
            if(x[i])
                dp[i][2]=max(dp[i][2],dp[i+1][1]);
            if(y[i])
                dp[i][2]=max(dp[i][2],dp[i+1][0]);
            if(x[i] && y[i])
                dp[i][2]=max(dp[i][2],dp[i+1][3]),dp[i][3]=dp[i+1][2];
        }
        if(dp[1][k]){
            cout << "POSSIBLE";
            return 0;
        }
    }
    cout << "IMPOSSIBLE";
}

