	memset(va, 0, sizeof va);
	for (int i = pi[x]; i != x; i = pi[i]){
		RVC(j, to[i]) va[sg[to[i][j]]] = i;
		for (sg[i] = 0; va[sg[i]] == i || vis[sg[i]] == i; ++sg[i]);
	}
