const int MAX_N = 2e5 + 5;

int root [MAX_N];

int find (int u) {
  if (root[u] != u) {
    root[u] = find(root[u]);
  }
  return root[u];
}

void merge (int u, int v) {
  u = find(u);
  v = find(v);

  root[u] = v;
}

pair<int, int> mmex (const vector<int> &v) {
  set<int> unseen;
  for (int i = 0; i < (int) v.size() + 3; i++) {
    unseen.insert(i);
  }

  for (int u : v) {
    unseen.erase(u);
  }

  pair<int, int> ans;
  ans.first = *unseen.begin();
  unseen.erase(ans.first);
  ans.second = *unseen.begin();
  return ans;
}

int pre [MAX_N];
int nxt [MAX_N];
vector<int> adj [MAX_N];

pair<int, int> vals [MAX_N];
void dfs (int u) {
  for (int v : adj[u]) {
    dfs(v);
  }

  vector<int> chv;
  for (int v : adj[u]) {
    chv.push_back(vals[v].first);
  }

  vals[u] = mmex(chv);
}

