    }
    sort(c[v].begin(), c[v].end());
    if (cycle[v]) return;
    mark[v] = -1;
    int pr = -1;
    for (auto i: c[v]){
        if (pr + 1 != i && i > pr){
            mark[v] = pr + 1;
            return;
        }
        pr = i;
    }
    if (mark[v] == -1) mark[v] = pr + 1;
