}
int main() {
	iostream::sync_with_stdio(false);
	cin.tie(0);
	int n;
	cin >> n;
	REP(i, n) {
		int a;
		cin >> a;
		a--;
		edges.push_back(make_pair(i, a));
		vertexs[a].push_back(i);
		gyaku_cnt[a]++;
		gyaku[i] = a;
	}
	REP(i, n) {
		ans[i] = -1;
	}
	queue<int> next;
	REP(i, n) {
		if (gyaku_cnt[i] == 0) {
			next.push(i);
		}
	}
	while (next.empty() == false) {
		int now = next.front();
		next.pop();
		set<int> neko;
		REP(q, vertexs[now].size()) {
			neko.insert(ans[vertexs[now][q]]);
		}
		for (int i = 0;; ++i) {
			if (neko.find(i) == neko.end()) {
				ans[now] = i;
				break;
			}
		}
		gyaku_cnt[gyaku[now]]--;
		if (gyaku_cnt[gyaku[now]] == 0) {
			next.push(gyaku[now]);
		}
	}
	for (int i = 0; i < n; ++i) {
		if (ans[i] != -1) continue;
		set<int> geko;
		for (int q = 0; q < vertexs[i].size(); ++q) {
			geko.insert(ans[vertexs[i][q]]);
		}
		int cnt = 0;
		for (int q = 0;cnt < 2; ++q) {
			if (geko.find(q) == geko.end()) {
				REP(j, n) {
					memo[j] = ans[j];
				}
				ans[i] = q;
				int now = gyaku[i];
				while (ans[now] == -1) {
					set<int> neko;
					REP(q, vertexs[now].size()) {
						neko.insert(ans[vertexs[now][q]]);
					}
					for (int i = 0;; ++i) {
						if (neko.find(i) == neko.end()) {
							ans[now] = i;
							break;
						}
					}
					now = gyaku[now];
				}
				if (verify() == true) {
					cout << "POSSIBLE" << endl;
					return 0;
				}
				else {
					REP(j, n) {
						ans[j] = memo[j];
					}
				}
				cnt++;
			}
		}
		break;
	}
	cout << "IMPOSSIBLE" << endl;

	return 0;
}

