int rec(int v, bool up = false) {
  seen[v] = true;

  bool iscy = false;
  for (auto nv : G[v]) {
		if (grundy[nv] != -1) continue;
		if (seen[nv]) {
		 iscy = true;
		 continue;
		}
		rec(nv, up);
  }

  set<int> se;
  for (auto nv : G[v]) {
		if (grundy[nv] == -1 && seen[nv]) continue;
		se.insert(grundy[nv]);
  }
  int res = 0;
  for (res = 0;; ++res) {
		if (!se.count(res)) break;
  }

	if (iscy && up) {
		for (;; ++res) {
			if (!se.count(res)) break;
		}
	}

	if (iscy) {
		thev = v;
		thenum = res;
	}

	//cout << v << ": " << res << endl;

