		int val = mex(U[q]);
		//cerr << "Using q " << q << ' ' << val << endl;

		auto CC = C;
		auto UU = U;
		CC[P[q]]--;
		UU[P[q]].push_back(val);
		run(UU, CC);
		if (A[q] == val) {
		//	cerr << "A " << A;
			cout << "POSSIBLE\n" << endl;
			return;
		}

		auto UUU = U[q];
		UUU.push_back(val);
		val = mex(UUU);
		UU = U;
		CC = C;
		CC[P[q]]--;
		UU[P[q]].push_back(val);
		run(UU, CC);
		if (A[q] == val) {
		//	cerr << "B " << A;
			cout << "POSSIBLE\n" << endl;
			return;
		}

		cout << "IMPOSSIBLE\n";
    }
};


