#include <bits/stdc++.h>
using namespace std;

const int N = 200005;

int n;
vector<int> G[N], R[N];
int deg[N];
bool incycle[N];
vector<int> cyc; int sz;
vector<int> ch[N];
int a[N];

void impossible() { printf("IMPOSSIBLE\n"); exit(0); }
void possible() { printf("POSSIBLE\n"); exit(0); }

int find_mex(vector<int> &vec) {
	sort(vec.begin(), vec.end());
	vec.erase(unique(vec.begin(), vec.end()), vec.end());
	int lst = 0;
	for (int i = 0; i < vec.size(); ++i) {
		if (vec[i] != lst) return lst;
		++lst;
	}
	return lst;
}

void find_cycle(int u) {
	incycle[u] = true;
	cyc.push_back(u);
	for (int v : G[u]) if (deg[v] && incycle[v] == 0) {
		find_cycle(v);
	}
}

bool recheck() {
	// build
	for (int i = sz - 1; i >= 1; --i) {
		int u = cyc[i];
		ch[u].clear();

		for (int v : G[u]) {
			ch[u].push_back(a[v]);
		}

		a[u] = find_mex(ch[u]);
	}

	// recheck
	for (int i = 1; i <= n; ++i) {
		ch[i].clear();
		for (int j : G[i]) ch[i].push_back(a[j]);
		if (a[i] != find_mex(ch[i])) return false;
	}
	return true;
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i <= n; ++i) {
		int p; scanf("%d", &p);
		R[i].push_back(p);
		G[p].push_back(i);
		deg[p]++;
	}

	queue <int> que;
	for (int i = 1; i <= n; ++i) if (!deg[i]) que.push(i), a[i] = 0;

	while(!que.empty()) {
		int u = que.front(); que.pop();

		for (int v : R[u]) {
			if (!deg[v]) continue;
			if (--deg[v] == 0) {
				que.push(v);
				vector<int> vec;
				for (int w : G[v]) {
					vec.push_back(a[w]);
				}
				a[v] = find_mex(vec);
			}
		}
	}

	memset(incycle, 0, sizeof incycle);
	for (int i = 1; i <= n; ++i) if (deg[i]) { // in cycle
		find_cycle(i);
		break;
	}

	/*************************************************************/
	// solve inside the cycle
	sz = cyc.size();
	int u = cyc[0];
	vector<int> vec;
	for (int v : G[u]) if (!deg[v]) {
		vec.push_back(a[v]);
	}
	// first case: a[u] = mex
	a[u] = find_mex(vec);

	if (recheck()) possible();

	// second case: a[u] = mex'
	vec.push_back(a[u]);
	a[u] = find_mex(vec);

	if (recheck()) possible();

	impossible();
}

