using namespace std;

int calc_g(int i, vector<int> &g, vector<int> *adj) {
    vector<int> gs;
    for (int j : adj[i]) {
        if (g[j] >= 0) gs.push_back(g[j]);
    }
    sort(gs.begin(), gs.end());
    if (gs.empty() || gs[0] > 0)
        return 0;
    else {
        for (int i = 0; i < gs.size() - 1; i++) {
            if (gs[i] + 1 < gs[i+1]) {
                return gs[i] + 1;
            }
        }
        return gs.back() + 1;
    }
}

void dfs(int i, vector<int> &g, vector<int> *adj, vector<bool> &visited) {
    visited[i] = true;
    bool ok = true;
    for (int j : adj[i]) {
        if (!visited[j]) dfs(j, g, adj, visited);
        if (ok && g[j] == -1) ok = false;
    }
    if (ok) {
        g[i] = calc_g(i, g, adj);
    }
}

int main() {
    int n; cin >> n;
    vector<int> adj[n];
    int p[n];
    for (int i = 0; i < n; i++) {
        cin >> p[i], p[i]--;
        adj[p[i]].push_back(i);
    }
    vector<int> g(n, -1);
    vector<bool> visited(n, false);

    for (int i = 0; i < n; i++) if (!visited[i]) dfs(i, g, adj, visited);
    vector<int> cycle;
    for (int i = 0; i < n; i++) {
        if (g[i] == -1) {
            for (int j = i;;) {
                for (int k : adj[j]) {
                    if (g[k] == -1) {
                        cycle.push_back(k);
                        j = k;
                        break;
                    }
                }
                if (j == i) break;
            }
            break;
        }
    }
    const int x = calc_g(cycle.back(), g, adj);

    g[cycle.back()] = x;
    for (int i = cycle.size() - 2; i >= 0; i--)
        g[cycle[i]] = calc_g(cycle[i], g, adj);
    if (x == calc_g(cycle.back(), g, adj)) {
        cout << "POSSIBLE\n";
        return 0;
    }

    g[cycle.front()] = x;
    for (int i = cycle.size() - 1; i > 0; i--)
        g[cycle[i]] = calc_g(cycle[i], g, adj);
    if (x == calc_g(cycle.front(), g, adj)) {
        cout << "POSSIBLE\n";
        return 0;
    }

    cout << "IMPOSSIBLE\n";
}

