using namespace std;

vector<vector<int>> edge;
int visited[200010];
bool cycle[200010];
int grundy[200010];
vector<int> cyc;

bool dfs(int i) {
	visited[i] = 1;
	for (int u: edge[i]) {
		if (visited[u] == 0) cycle[i] |= dfs(u);
		else if (visited[u] == 1) cycle[i] = 1;
	}
	visited[i] = 2;
	if (cycle[i]) cyc.push_back(i);
	return cycle[i];
}

int find_grundy(int i) {
	if (grundy[i] != -1) return grundy[i];
	int mask = 0;
	for (int u: edge[i]) {
		mask |= (1 << find_grundy(u));
	}
	return grundy[i] = __builtin_ctz(~mask);
}

int grundy_single_init(int i) {
	int mask = 0;
	for (int u: edge[i]) {
		if (!cycle[u]) mask |= (1 << grundy[u]);
	}
	return mask;
}

int grundy_single(int i) {
	int mask = 0;
	for (int u: edge[i]) {
		mask |= (1 << grundy[u]);
	}
	return __builtin_ctz(~mask);
}

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);

	int n, t;
	cin >> n;

	edge.resize(n);
	memset(grundy, -1, sizeof(grundy));
	for (int i = 0; i < n; ++i) {
		cin >> t;
		t--;
		edge[t].push_back(i);
	}

	for (int i = 0; i < n; ++i) {
		if (!visited[i]) dfs(i);
	}

	for (int i = 0; i < n; ++i) {
		if (!cycle[i] && grundy[i] == -1) find_grundy(i);
	}

	int start = grundy_single_init(cyc[0]);
	int low = __builtin_ctz(~start);
	grundy[cyc[0]] = low;
	start |= (1 << low);
	for (int i = 1; i < cyc.size(); ++i) {
		grundy[cyc[i]] = grundy_single(cyc[i]);
	}
	if (grundy_single(cyc[0]) == grundy[cyc[0]]) {
		cout << "POSSIBLE";
		return 0;
	}

	grundy[cyc[0]] = __builtin_ctz(~start);
	for (int i = 1; i < cyc.size(); ++i) {
		grundy[cyc[i]] = grundy_single(cyc[i]);
	}
	if (grundy_single(cyc[0]) == grundy[cyc[0]]) {
		cout << "POSSIBLE";
	}
	else cout << "IMPOSSIBLE";
}

