#include <cstring>
#include <algorithm>
#include <cstdio>

using namespace std;
const int MAXN = 200010;
int nowarn;

int n, in[MAXN];

namespace Graph {
	int head[MAXN], nxt[MAXN], to[MAXN], eidx = 0;
	void init() {
		memset( head, -1, sizeof(head) );
	}
	void adde( int u, int v ) {
		to[eidx] = v, nxt[eidx] = head[u], head[u] = eidx++;
	}
}

int loop[MAXN], lpidx = 0;
int onloop[MAXN] = {0};
void find_loop() {
	int u = 1;
	for( int i = 1; !onloop[u]; ++i )
		onloop[u] = i, loop[i] = u, u = in[u];
	for( int i = onloop[u]; loop[i]; ++i )
		loop[i-onloop[u]] = loop[i], lpidx = i+1-onloop[u];
	memset( onloop, 0, sizeof(onloop) );
	for( int i = 0; i < lpidx; ++i ) onloop[loop[i]] = 1;
}

int mex[MAXN], vis[MAXN] = {0};
void dfs( int u ) {
	using namespace Graph;
	if( mex[u] != -1 ) return;
	if( head[u] == -1 ) {
		mex[u] = 0;
		return;
	}
	for( int i = head[u]; ~i; i = nxt[i] )
		dfs( to[i] );
	for( int i = head[u]; ~i; i = nxt[i] )
		vis[mex[to[i]]] = u;
	for( int i = 0; ; ++i )
		if( vis[i] != u ) {
			mex[u] = i;
			break;
		}
}
void solve1() {
	memset( mex, -1, sizeof(mex) );
	for( int i = 1; i <= n; ++i ) {
		if( !onloop[i] )
			dfs(i);
		// printf( "mex[%d] = %d\n", i, mex[i] );
	}
}

bool check( int x ) {
	using namespace Graph;
	mex[loop[0]] = x;
	memset( vis, 0, sizeof(vis) );
	for( int i = 1; i < lpidx; ++i ) {
		int u = loop[i];
		for( int j = head[u]; ~j; j = nxt[j] ) {
			int v = to[j];
			vis[mex[v]] = u;
		}
		for( int j = 0; ; ++j )
			if( vis[j] != u ) {
				mex[u] = j;
				break;
			}
	}
	int u = loop[0];
	for( int i = head[u]; ~i; i = nxt[i] ) {
		int v = to[i];
		vis[mex[v]] = u;
	}
	for( int i = 0; ; ++i )
		if( vis[i] != u )
			return mex[u] == i;
}
void solve2() {
	using namespace Graph;
	int u = loop[0], mex2;
	for( int i = head[u]; ~i; i = nxt[i] ) {
		int v = to[i];
		if( onloop[v] ) continue;
		vis[mex[v]] = u;
	}
	for( int i = 0; ; ++i )
		if( vis[i] != u ) {
			mex[u] = i;
			break;
		}
	vis[mex[u]] = u;
	for( int i = 0; ; ++i )
		if( vis[i] != u ) {
			mex2 = i;
			break;
		}
	// printf( "mex2 = %d\n", mex2 );
	if( check(mex[u]) || check(mex2) ) puts("POSSIBLE");
	else puts("IMPOSSIBLE");
}

int main() {
	nowarn = scanf( "%d", &n );
	Graph::init();
	for( int i = 1; i <= n; ++i ) {
		nowarn = scanf( "%d", in+i );
		Graph::adde( in[i], i );
	}
