int loop(int v, int ng) {
	set<int> S;
	int res = 0;
	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(n == ng) continue;
		S.insert(loop(n, -1));
	}
	for(int s : S) {
		if(s == res) res++;
		else return res;
	}
	return res;
}

void solve() {
	cin >> N;
	rep(i, 0, N) {
		int a; cin >> a; a--;
		G[a].pb(i);
		rG[i].pb(a);
		cnt[a]++;
	}
	queue<int> que;
	rep(i, 0, N) {
		if(cnt[i] == 0) que.push(i);
	}
	while(!que.empty()) {
		int v = que.front(); que.pop();
		used[v] = true;
		rep(i, 0, sz(rG[v])) {
			int n = rG[v][i];
			cnt[n]--;
			if(cnt[n] == 0) {
				que.push(n);
			}
		}
	}
	rep(i, 0, N) if(!used[i]) vec.pb(i);
	M = sz(vec);
	int v = vec[0];
	rep(i, 0, M) {
		int tnex = -1;
		rep(i, 0, sz(G[v])) {
			int n = G[v][i];
			int tat = lower_bound(all(vec), n) - vec.begin();
			if(tat != M && vec[tat] == n) {
				tnex = n;
			}
		}
		grundy[i] = loop(v, tnex);
		v = tnex;
	}

	rep(q, 0, 2) {
		memset(dp, 0, sizeof(dp));
		dp[0][q]= true;
		rep(i, 0, M) {
			rep(j, 0, 2) {
				if(!dp[i][j]) continue;
				int nid = (i + 1) % M;
				if(j == 0) {
					if(grundy[nid] != grundy[i]) {
						dp[i + 1][0] = true;
					}
					if(grundy[nid] + 1 != grundy[i]) {
						dp[i + 1][1] = true;
					}
				}
				else {
					if(grundy[nid] == (grundy[i] + 1) - 1) {
						dp[i + 1][0] = true;
					}
					if(grundy[nid] + 1 == (grundy[i] + 1) - 1) {
						dp[i + 1][1] = true;
					}
				}
			}
		}
		if(dp[M][q]) {
			cout << "POSSIBLE\n";
			return;
		}
	}
	cout << "IMPOSSIBLE\n";
}

