int Q[maxn],S[maxn];
int work(int x) {
	memset(S,0,sizeof(S));
	int y=x;
	do {
		y=p[y];
		if(B[y]>=0) break;
		rep(i,0,G[y].size()-1) {
			S[B[G[y][i]]]++;
		}
		rep(i,0,3) if(!S[i]) {B[y]=i;break;}
		rep(i,0,3) S[i]=0;
	}while(y!=x);
	rep(x,1,n) {
		rep(i,0,G[x].size()-1) S[B[G[x][i]]]++;
		rep(i,0,B[x]-1) if(!S[i]) return 0;
		if(S[B[x]]) return 0;
		rep(i,0,3) S[i]=0;
	}
