	return 1;
}
int solve() {
	memset(A,-1,sizeof(A));
	int l=1,r=0;
	rep(i,1,n) if(!in[i]) Q[++r]=i,A[i]=0;
	while(l<=r) {
		int x=Q[l++];vis[x]=1;
		for(int i=first[x];i;i=nxt[i]) if(!(--in[to[i]])) Q[++r]=to[i];
		rep(i,0,G[x].size()-1) S[A[G[x][i]]]++;
		A[x]=0;while(S[A[x]]) A[x]++;
		rep(i,0,G[x].size()-1) S[A[G[x][i]]]--;
	}
	rep(i,1,n) if(!vis[i]) {
		rep(j,0,G[i].size()-1) S[A[G[i][j]]]++;
		int v=0;while(S[v]) v++;
		int v2=v;while(S[v2]) v2++;
		rep(j,0,G[i].size()-1) S[A[G[i][j]]]--;
		rep(j,1,n) B[j]=A[j];
		B[i]=v;if(work(i)) return 1;
		rep(j,1,n) B[j]=A[j];
		B[i]=v2;if(work(i)) return 1;
		return 0;
	}
}
