void dfs2(int u) {
	for(int v: ed[u]) {
		if (!cyc[v]) dfs2(v);
	}
	for(int v: ed[u]) if (!cyc[v]) arr[lo[v]] = 1;
	int ans = 0;
	while (arr[ans]) ans++;
	lo[u] = ans++;
	while (arr[ans]) ans++;
	hi[u] = ans;
	for(int v: ed[u]) if (!cyc[v]) arr[lo[v]] = 0;
}

int bt(int st, int n, int cur) {
	if (cur == fin - 1) {
		if (n == 0 && st == 0) return lo[vec[0]] != lo[vec[cur]]; 
		if (n == 1 && st == 0) return lo[vec[0]] == lo[vec[cur]]; 
		if (n == 0 && st == 1) return hi[vec[0]] != lo[vec[cur]]; 
		if (n == 1 && st == 1) return hi[vec[0]] == lo[vec[cur]];
	}
	//if (dp[st][n][cur] != -1) return dp[st][n][cur];
	if (n == 0) {
		if (lo[vec[cur]] != lo[vec[cur + 1]] && bt(st,0,cur + 1)) return dp[st][n][cur] = 1;
		if (lo[vec[cur]] != hi[vec[cur + 1]] && bt(st,1,cur + 1)) return dp[st][n][cur] = 1;
	} else {
		if (lo[vec[cur]] == lo[vec[cur + 1]] && bt(st,0,cur + 1)) return dp[st][n][cur] = 1;
		if (lo[vec[cur]] == hi[vec[cur + 1]] && bt(st,1,cur + 1)) return dp[st][n][cur] = 1; 
	}
	return dp[st][n][cur] = 0;
}


