vector<vector<int>> G;
vector<vector<int>> rG;
vector<bool> visited;
vector<int> vs;
vector<int> cmp;

void dfs(int v) {
    visited[v] = true;
    for(int i=0;i<G[v].size();i++){
        if(!visited[G[v][i]]) dfs(G[v][i]);
    }
    vs.push_back(v); // 帰りがけにvを記録。グラフの末端に近いものから並ぶ
}

void rdfs(int v, int k) {
    visited[v] = true;
    cmp[v] = k;

    for(int i=0;i<rG[v].size();i++){
        if(!visited[rG[v][i]]) rdfs(rG[v][i], k);
    }
}

int scc(int n) { // 強連結成分分解
  vs.clear();

  visited.assign(n, false);
  for(int i=0;i<n;i++){
    if(!visited[i]) dfs(i);
  }

  cmp.assign(n, -1);
  visited.assign(n, false);
  int k=0;
  for(int i=vs.size()-1;i>=0;i--){
    if(!visited[vs[i]]) rdfs(vs[i], k++);
  }
  return k;
}

int scc_start;
vector<int> a;
int N;

int get_min_a(set<int>& s){
    int min_a = 0;
    for(int a : s){
        if(a != min_a){
            return min_a;
        }
        min_a++;
    }
    return min_a;
}

int set_a(int v){
    if(a[v] != -1) return a[v];
    set<int> s;
    for(int to : G[v]){
        if(cmp[to] != cmp[scc_start]){
            s.insert(set_a(to));
        }
    }
    a[v] = get_min_a(s);
    return a[v];
}

void set_a_in_scc(int v){
    if(v != scc_start){
        set<int> s;
        for(int to : G[v]){
            s.insert(a[to]);
        }
        a[v] = get_min_a(s);
    }
    for(int from : rG[v]){
        if(cmp[from] == cmp[scc_start] && from != scc_start){
            set_a_in_scc(from);
        }
    }
}

bool solve(){
    cin >> N;

    G.assign(N, {});
    rG.assign(N, {});
    for(int i=0;i<N;i++){
        int p;
        cin >> p;
        p--;
        G[p].push_back(i);
        rG[i].push_back(p);
    }

    scc(N);
    set<int> ks;
    for(int i=0;i<N;i++){
        if(ks.count(cmp[i]) == 1){
            scc_start = i;
        }
        ks.insert(cmp[i]);
    }

    a.assign(N, -1);
    for(int i=0;i<N;i++){
        if(cmp[i] != cmp[scc_start]){
            set_a(i);
        }
    }

    set<int> s;
    for(int to : G[scc_start]){
        if(cmp[to] != cmp[scc_start]){
            s.insert(a[to]);
        }
    }

    a[scc_start] = get_min_a(s);
    set_a_in_scc(scc_start);

    {
        set<int> s_all;
        for(int to : G[scc_start]){
            s_all.insert(a[to]);
        }
        if(a[scc_start] == get_min_a(s_all)) return true;
    }

    s.insert(a[scc_start]);
    a[scc_start] = get_min_a(s);
    set_a_in_scc(scc_start);

    {
        set<int> s_all;
        for(int to : G[scc_start]){
            s_all.insert(a[to]);
        }
        if(a[scc_start] == get_min_a(s_all)) return true;
    }

    return false;
}

int main(){
    if(solve()) cout << "POSSIBLE" << endl;
    else cout << "IMPOSSIBLE" << endl;
    return 0;
}

