using namespace std;
const int MAXN = 200010;
struct edge{int t,w,next;}edges[MAXN<<1];
int head[MAXN],top = 1;
void add(int f,int t,int w = 0){
	edges[++top].next = head[f];
	edges[top].t = t;
	edges[top].w = w;
	head[f] = top;
}
bool vis[MAXN],inloop[MAXN],flag[MAXN<<1];
int loop[MAXN],cnt,pa[MAXN];
bool getloop(int x){
	vis[x] = true;
	for(int i = head[x];i;i = edges[i].next){
		int t = edges[i].t;
		if(flag[i]||flag[i^1])continue;
		flag[i] = flag[i^1] = true;
		if(vis[t]){
			loop[++cnt] = t;
			inloop[t] = true;
			for(int p = x;p!=t;p = pa[p]){
				loop[++cnt] = p;
				inloop[p] = true;
			}
			return true;
		}
		pa[t] = x;
		if(getloop(t))return true;
	} 
	return false;
}
int mark[MAXN];
int dp[MAXN],dfn;
void dfs(int x){
	vis[x] = true;
	for(int i = head[x];i;i = edges[i].next){
		int t = edges[i].t;
		if(inloop[t]||vis[t])continue;
		dfs(t);
	}
	dfn++;
	for(int i = head[x];i;i = edges[i].next){
		int t = edges[i].t;
		if(inloop[t])continue;
		mark[dp[t]] = dfn;
	}
	dp[x] = 0;
	while(mark[dp[x]]==dfn)dp[x]++;
}
int main(){
	int n;scanf("%d",&n);
	int t;
	for(int i = 1;i<=n;i++){
		scanf("%d",&t);
		add(t,i);
	}
	getloop(1);
	memset(vis,0,sizeof(vis));
	for(int i = 1;i<=cnt;i++)dfs(loop[i]);
	int mn = n+1,mx = -1;
	for(int i = 1;i<=cnt;i++){
		mn = min(mn,dp[loop[i]]);
		mx = max(mx,dp[loop[i]]);
	}
	if(mn==mx&&(cnt%2==1))printf("IMPOSSIBLE");
	else printf("POSSIBLE");
	return 0;
}

#include <bits/stdc++.h>

const int N = 200054;

int n;
int p[N], fc[N], nc[N];
int cnt = 0, cyc[N];
int f[N], mark[N];
bool used[N];

inline void link(int x, int px) {nc[x] = fc[px], fc[px] = x;}

int dfs(int x) {
	int y, &g = f[x];
	for (y = fc[x]; y; y = nc[y]) dfs(y);
	for (y = fc[x]; y; y = nc[y]) mark[f[y]] = x;
	for (; mark[g] == x; ++g); return g;
}

int main() {
	int i, C, _;
	scanf("%d", &n);
	for (i = 1; i <= n; ++i) scanf("%d", p + i);
	for (C = 1; !used[C]; C = p[C]) used[C] = true;
	i = C;
	do cyc[cnt++] = i, _ = p[i], p[i] = 0, i = _; while (i != C);
	if (!(cnt & 1)) return puts("POSSIBLE"), 0;
	for (i = 1; i <= n; ++i) if (p[i]) link(i, p[i]);
	dfs(*cyc);
	for (i = 1; i < cnt; ++i)
		if (dfs(cyc[i]) != dfs(*cyc)) return puts("POSSIBLE"), 0;
	return puts("IMPOSSIBLE"), 0;
}

