using namespace std;

int find_cycle(
	vector<int>& out, vector<bool>& passed,
	int u, const vector<vector<int>>& conn)
{
	passed[u] = true;
	for(const int v : conn[u]){
		if(passed[v]){
			out.push_back(u);
			return v;
		}
		const int t = find_cycle(out, passed, v, conn);
		if(t >= 0){
			out.push_back(u);
			return (t == u ? -2 : u);
		}else if(t == -2){
			return -2;
		}
	}
	return -1;
}

int main(){
	ios_base::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<vector<int>> conn(n), rconn(n);
	for(int i = 0; i < n; ++i){
		int x;
		cin >> x;
		conn[x - 1].push_back(i);
		rconn[i].push_back(x - 1);
	}
	vector<int> out_deg(n);
	for(int i = 0; i < n; ++i){ out_deg[i] = conn[i].size(); }
	queue<int> q;
	for(int i = 0; i < n; ++i){
		if(out_deg[i] == 0){ q.push(i); }
	}
	vector<int> g(n, -1);
	while(!q.empty()){
		const int u = q.front();
		q.pop();
		for(const auto v : rconn[u]){
			if(--out_deg[v] == 0){ q.push(v); }
		}
		set<int> s;
		for(const auto v : conn[u]){ s.insert(g[v]); }
		g[u] = 0;
		for(const int x : s){
			if(x != g[u]){ break; }
			++g[u];
		}
	}
	vector<int> cycle;
	for(int i = 0; i < n; ++i){
		if(out_deg[i] == 1){
			vector<bool> passed(n, false);
			find_cycle(cycle, passed, i, conn);
			break;
		}
	}
	vector<array<int, 2>> candidates;
	for(const int u : cycle){
		set<int> s;
		for(const int v : conn[u]){
			if(out_deg[v] != 0){ continue; }
			s.insert(g[v]);
		}
		array<int, 2> t = { 0, 0 };
		auto it = s.begin();
		while(it != s.end()){
			if(*it != t[0]){ break; }
			++t[0];
		}
		t[1] = t[0] + 1;
		while(it != s.end()){
			if(*it != t[1]){ break; }
			++t[1];
		}
		candidates.push_back(t);
	}
	bool found = false;
	for(const int gc : candidates[0]){
		g[cycle[0]] = gc;
		for(const int u : cycle){
			if(u == cycle[0]){ continue; }
			set<int> s;
			for(const int v : conn[u]){ s.insert(g[v]); }
			g[u] = 0;
			for(const int x : s){
				if(x != g[u]){ break; }
				++g[u];
			}
		}
		set<int> s;
		for(const int v : conn[cycle[0]]){ s.insert(g[v]); }
		int t = 0;
		for(const int x : s){
			if(x != t){ break; }
			++t;
		}
		if(t == gc){ found = true; }
	}
	cout << (found ? "POSSIBLE" : "IMPOSSIBLE") << endl;
	return 0;
}

