  for (int i = 0; i < n; i++) {
    ++deg[p[i]];
  }
  vector<int> que;
  for (int i = 0; i < n; i++) {
    if (deg[i] == 0) {
      que.push_back(i);
    }
  }
  vector<set<int>> ban(n);
  vector<int> g(n, -1);
  for (int b = 0; b < (int) que.size(); b++) {
    int i = que[b];
    g[i] = 0;
    while (ban[i].find(g[i]) != ban[i].end()) {
      ++g[i];
    }
    ban[p[i]].insert(g[i]);
    --deg[p[i]];
    if (deg[p[i]] == 0) {
      que.push_back(p[i]);
    }
  }
  for (int st = 0; st < n; st++) {
    if (g[st] != -1) {
      continue;
    }
    vector<int> cycle;
    int pp = st;
    while (g[pp] == -1) {
      g[pp] = -2;
      cycle.push_back(pp);
      pp = p[pp];
    }
    int len = (int) cycle.size();
    vector<vector<int>> val(len, vector<int>(2));
    for (int i = 0; i < len; i++) {
      int x = 0;
      while (ban[cycle[i]].find(x) != ban[cycle[i]].end()) ++x;
      val[i][0] = x;
      ++x;
      while (ban[cycle[i]].find(x) != ban[cycle[i]].end()) ++x;
      val[i][1] = x;
    }
    bool found = false;
    for (int z = 0; z < 2; z++) {
      vector<vector<bool>> dp(len + 1, vector<bool>(2));
      dp[0][z] = true;
      for (int i = 1; i < len + 1; i++) {
        for (int k = 0; k < 2; k++) {
          if (dp[i - 1][k]) {
            int nj = 0;
            if (val[i % len][nj] == val[i - 1][k]) ++nj;
            dp[i][nj] = true;
          }
        }
      }
      if (dp[len][z]) {
        found = true;
        break;
      }
    }
    if (!found) {
      cout << "IMPOSSIBLE" << '\n';
      return 0;
    }
  }
  cout << "POSSIBLE" << '\n';
  return 0;
}

