bool solve(){
  int n;
  cin>>n;
  vector<vector<int>> tree(n);
  vector<int> rev(n), cnt(n), a(n, -1);

  rep(i,n){
    int p; cin>>p; p--;
    tree[p].pb(i);
    rev[i] = p;
  }
  rep(i,n) cnt[i] = tree[i].size();

  auto bfs = [&](queue<int> &q, vector<int> &num, vector<int> &c){
    int last = -1;
    while(!q.empty()){
      int v = q.front(); q.pop();
      vector<int> vv;
      for(auto d : tree[v]) vv.pb(num[d]);
      uniq(vv);
      int x = 0;
      while(x < vv.size() && vv[x]==x) x++;
      num[v] = x;//dbg(v,x);
      c[rev[v]]--;
      if(c[rev[v]]==0 && num[rev[v]]==-1) q.push(rev[v]);
      last = v;
    }
    return last;
  };

  {
    queue<int> q;
    rep(i,n) if(tree[i].size()==0) q.push(i);
    bfs(q,a,cnt);
  }

  int s = -1;
  rep(i,n) if(a[i]==-1) s=i;

  if(s==-1) return true;

  vector<int> vv;
  for(auto d : tree[s]) if(a[d]!=-1) vv.pb(a[d]);
  uniq(vv);
  int c1=0;
  while(c1 < vv.size() && vv[c1]==c1) c1++;
  int c2 = c1+1;
  while(c2-1 < vv.size() && vv[c2-1]==c2) c2++;

  // dbg(s,c1,c2,vv,a);

  rep(_,2){
    // try c1
    vector<int> b(a);
    vector<int> cc(cnt);
    cc[s] = 0;
    b[s] = c1;
    queue<int> q;
    q.push(rev[s]);

    int last = bfs(q,b,cc);

    if(b[last] != b[s]) return true;

    swap(c1,c2);
  }

  return false;
}

