	}

	for (int i = 1; i <= n; ++i) state[i] = -1;
	for (int i = 1; i <= n; ++i) if (f[i] == 0) {
		int j = i;
		while (state[j] == -1) {
			state[j] = 1;
			j = nxt[j];
		}
		while (!ring[j]) {
			ring[j] = 1;
			j = nxt[j];
		}
		st = j;
		break;
	}

	if (st == -1) {
		st = 1;
	}

	for (int i = 1; i <= n; ++i) state[i] = -1;

	for (int i = 1; i <= n; ++i) if (f[i] == 0) {
		state[i] = 0;
		q[top++] = i;
	}

	for (int j = 0; j < top; ++j) {
