template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;
template<class T, class U> void assign(V<T>& v, int n, const U& a) { v.assign(n, a); }
template<class T, class... Args> void assign(V<T>& v, int n, const Args&... args) { v.resize(n); for (auto&& e : v) assign(e, args...); }


int scc(const VV<>& g, V<>& comp) {
  int n = g.size();
  VV<> rg(n);
  for (int v = 0; v < n; v++) {
    for (int w : g[v]) {
      rg[w].push_back(v);
    }
  }
  V<> vs;
  V<bool> vis(n);
  comp.resize(n);

  auto dfs = [&](const auto& dfs, int v) -> void {
    vis[v] = true;
    for (int w : g[v]) if (!vis[w]) {
      dfs(dfs, w);
    }
    vs.push_back(v);
  };

  auto rdfs = [&](const auto& rdfs, int v, int k) -> void {
    vis[v] = true;
    comp[v] = k;
    for (int w: rg[v]) if (!vis[w]) {
      rdfs(rdfs, w, k);
    }
  };

  for (int v = 0; v < n; v++) if (!vis[v]) {
    dfs(dfs, v);
  }
  vis.assign(n, false);
  int k = 0;
  reverse(vs.begin(), vs.end());
  for (int v : vs) if (!vis[v]) {
    rdfs(rdfs, v, k++);
  }
  return k;
}

int main() {
  cin.tie(nullptr); ios_base::sync_with_stdio(false);
  int n; cin >> n;
  VV<> g(n);
  for (int i = 0; i < n; ++i) {
    int p; cin >> p, --p;
    g[p].push_back(i);
  }
  V<> comp;
  int k = scc(g, comp);
  if (k == n) return cout << "POSSIBLE" << '\n', 0;
  VV<> h(n);
  bool first = true;
  int u0, v0;
  map<int, int> mp;
  for (int v = 0; v < n; ++v) {
    for (int w : g[v]) {
      if (comp[v] == comp[w]) {
        if (first) {
          u0 = v, v0 = w;
          first = false;
        }
        mp[w] = v;
        continue;
      }
      h[v].push_back(w);
    }
  }
  scc(h, comp);
  V<> vs(n);
  iota(begin(vs), end(vs), 0);
  sort(begin(vs), end(vs), [&](int u, int v) { return comp[u] > comp[v]; });
  V<> a(n);
  for (int v : vs) {
    set<int> se;
    for (int w : h[v]) {
      se.insert(a[w]);
    }
    int i = 0;
    while (se.count(i)) ++i;
    a[v] = i;
  }
  if (a[u0] != a[v0]) return cout << "POSSIBLE" << '\n', 0;
  while (u0 != v0) {
    set<int> se;
    for (int w : g[u0]) {
      se.insert(a[w]);
    }
    int i = 0;
    while (se.count(i)) ++i;
    a[u0] = i;
    u0 = mp[u0];
  }
  for (int w : g[v0]) {
    if (a[w] == a[v0]) return cout << "IMPOSSIBLE" << '\n', 0;
  }
  cout << "POSSIBLE" << '\n';
}

#include <bits/stdc++.h>

using namespace std;

int const N = 1234567;

int was[N], g[N], ng[N], p[N], cycle[N];

vector<int> edges[N];

int dfs(int v, int bad) {
  if (g[v] >= 0) return g[v];
  for (int to : edges[v]) {
    if (to == bad) continue;
    dfs(to, bad);
  }
  int children = (int) edges[v].size();
  for (int i = 0; i <= children; i++) was[i] = false;
  for (int to : edges[v]) {
    if (to == bad) continue;
    int got = dfs(to, bad);
    if (got <= children) was[got] = true;
  }
  int i = 0;
  while (was[i]) ++i;
  g[v] = i;
  return i;
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", p + i);
    --p[i];
    edges[p[i]].push_back(i);
    g[i] = -1;
  }
  int v = 0;
  for (int i = 0; i < n; i++) v = p[v];
  int cc = 0;
  int start = v;
  while (true) {
    cycle[cc++] = v;
    v = p[v];
    if (start == v) break;
  }
  dfs(cycle[0], cycle[cc - 1]);
  int gv = g[cycle[0]];
  for (int i = 0; i < n; i++) ng[i] = g[i];
  for (int value = gv; value <= gv + 1; value++) {
    for (int i = 0; i < n; i++) g[i] = ng[i];
    g[cycle[0]] = value;
    for (int i = 0; i < cc; i++) {
      int v = cycle[i];
      if (g[v] < 0) dfs(v, -1);
    }
    int last = cycle[cc - 1];
    if (value == gv && g[last] == gv) {
      continue;
    }
    if (value == gv + 1 && g[last] != gv) continue;
    puts("POSSIBLE");
    return 0;
  }
  puts("IMPOSSIBLE");
}

