int rec(int v){
	vector<int> s;
	for(int i=0;i<G[v].size();i++){
		if(cmp[G[v][i]]==loop_idx)continue;
		s.pb(rec(G[v][i]));
		if(s.back()==-1)return -1;
	}
	sort(all(s));
	s.erase(unique(all(s)),s.end());
	for(int i=0;i<s.size();i++){
		if(s[i]!=i)return -1;
	}
	return (int)s.size();
}
