int s;

bool check(){
	int now=p[s];
	for(;now!=s;now=p[now]){
		eF(i,now) k[a[to[i]]]=1;
		for(int i=0;;++i) if(!k[i]) {a[now]=i; break;}
		eF(i,now) k[a[to[i]]]=0;
	}
	bool ok=1;
	eF(i,s) k[a[to[i]]]=1;
	for(int i=0;;++i) if(!k[i]) {if(a[s]!=i) ok=0; break;}
	eF(i,s) k[a[to[i]]]=0;
	return ok;
}

