	F(i,1,n) a[i]=-1;
	while(l<=r){
		int u=que[l++];
		eF(i,u) k[a[to[i]]]=1;
		for(int i=0;;++i) if(!k[i]) {a[u]=i; break;}
		eF(i,u) k[a[to[i]]]=0;
		if((--out[p[u]])==0) que[++r]=p[u];
	}
