int n, lo[200010], hi[200010], arr[200010], dp[2][2][200010], fin;
vi ed[200010], vec;
bitset<200010> vis, cyc;

bool dfs(int u) {
	vis[u] = 1;
	for(int v: ed[u]) {
		if (!vis[v]) {
			if (dfs(v)) {
				vec.pb(u);
				cyc[u] = 1;
				return 1;
			}
		} else {
			cyc[u] = 1;
			vec.pb(u);
			return 1;
		}
	}
	return 0;
}

void dfs2(int u, int p) {
	for(int v: ed[u]) {
		if (!cyc[v]) {
			dfs2(v,p);
			arr[lo[v]]++;
		}
	}
	int ans = 0;
	while (arr[ans]) ans++;
	lo[u] = ans;
	ans++;
	while (arr[ans]) ans++;
	hi[p] = ans;
	for(int v: ed[u]) if (!cyc[v]) arr[lo[v]]--;
}

int bt(int st, int n, int cur) {
	if (cur == fin - 1) {
		if (n == 0 && st == 0) return lo[vec[0]] != lo[vec[cur - 1]]; 
		if (n == 1 && st == 0) return lo[vec[0]] != hi[vec[cur - 1]]; 
		if (n == 0 && st == 1) return hi[vec[0]] != lo[vec[cur - 1]]; 
		if (n == 1 && st == 1) return hi[vec[0]] != hi[vec[cur - 1]]; 
	}
	if (dp[st][n][cur] != -1) return dp[st][n][cur];
	if (n == 0) {
		if (lo[vec[cur]] != lo[vec[cur + 1]] && bt(st,0,cur + 1)) return dp[st][n][cur] = 1;
		if (lo[vec[cur]] != hi[vec[cur + 1]] && bt(st,1,cur + 1)) return dp[st][n][cur] = 1;
	} else {
		if (hi[vec[cur]] != lo[vec[cur + 1]] && bt(st,0,cur + 1)) return dp[st][n][cur] = 1;
		if (hi[vec[cur]] != hi[vec[cur + 1]] && bt(st,1,cur + 1)) return dp[st][n][cur] = 1; 
	}
	return dp[st][n][cur] = 0;
}

