{
    vis[x]=1;
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    cir[x]|=vis[child];
	    if (!vis[child]) cir[x]|=dfs(child);
	}
    return cir[x];
}
void get(int x)
{
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    if (cir[child]) continue;
	    get(child);
	}
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    if (cir[child]) continue;
	    inq[v[child]]=1;
	}
