int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<int> p(n);
    for (int i = 0; i < n; i++)
    {
        cin >> p[i];
        p[i]--;
    }

    int root = 0;
    vector<int> v;
    for (int i = 0; i < 3 * n; i++)
    {
        v.push_back(root);
        root = p[root];
    }
    reverse(all(v));

    vector<char> repeated(n, false);
    vector<int> loop;
    for (int i = 0; i < n; i++)
    {
        if (repeated[v[i]])
            break;

        loop.push_back(v[i]);
        repeated[v[i]] = true;
    }
    assert(loop.size() > 1);

    vector<vector<int>> e(n);
    vector<int> out_deg(n, 0);
    for (int i = 0; i < n; i++)
    {
        out_deg[p[i]]++;
        e[p[i]].push_back(i);
    }

    vector<char> used = repeated;

    vector<int> mark(n, -1);
    for (int i = 0; i < n; i++)
    {
        if (!used[i] && out_deg[i] == 0)
        {
            int now = i;
            int cur = 0;
            while (!used[now])
            {
                used[now] = true;
                mark[now] = cur;
                cur = 1 - cur;
                now = p[now];
            }
        }
    }

    for (int i = 0; i < n; i++)
    {
        assert(used[i]);
        assert(repeated[i] || mark[i] != -1);
    }

    const int MAX_MEX = 20;

    bool good = false;
    for (int first = 0; first < MAX_MEX; first++)
    {
        auto old_mark = mark;
        bool fail = false;

        mark[loop[0]] = first;
        for (int i = (int)loop.size() - 1; i >= 0; i--)
        {
            vector<char> used(MAX_MEX, false);
            for (int x: e[loop[i]])
            {
                assert(mark[x] != -1);
                used[mark[x]] = true;
            }

            int mex = -1;
            for (int k = 0; k < MAX_MEX; k++)
                if (!used[k])
                {
                    mex = k;
                    break;
                }

            assert(mex != -1);
            if (mark[loop[i]] == -1 || mark[loop[i]] == mex)
            {
                mark[loop[i]] = mex;
            }
            else
            {
                fail = true;
                break;
            }
        }

        if (!fail)
        {
            good = true;
            break;
        }

        mark = old_mark;
    }

    cout << (good ? "POSSIBLE" : "IMPOSSIBLE") << endl;

    if (good)
    {
        for (int i = 0; i < n; i++)
        {
            vector<char> used(MAX_MEX, false);

            for (int x: e[i])
                used[mark[x]] = true;

            int mex = 0;
            while (mex < MAX_MEX && used[mex]) mex++;
            assert(mex != MAX_MEX);

            if (mark[i] != mex) while(true);
        }
    }

#if 0
    if (good)
    {
        for (int i = 0; i < n; i++)
            cout << mark[i] << " ";
        cout << endl;
    }
#endif

    return 0;
}

