void dfs0(int u,int ff){
	vis[u] = 1;
	sta[++tp] = u;
	for(int i=info[u],v;i;i=Prev[i]) if(i^ff){
		v=to[i];
		if(!vis[v]) dfs0(v,(i^1));
		else if(!onc[v]){
			for(int t=-1;t!=v;){
				t = sta[tp--];
				ar[++ar[0]] = t;
				onc[t] = 1;
			}
			per(i,ar[0],1) sta[++tp] = ar[i];
		}
	}
	if(sta[tp] == u) tp--;
}

void dfs1(int u,int ff){
	static int vis[maxn],tim;
	for(int i=info[u],v;i;i=Prev[i]) if((v=to[i]) ^ ff && !onc[v])
		dfs1(v,u);
	++tim;
	for(int i=info[u],v;i;i=Prev[i]) if((v=to[i]) ^ ff && !onc[v])
		vis[a[v]] = tim;
	a[u] = 0;
	for(;vis[a[u]] == tim; a[u]++);
}

