#include <bits/stdc++.h>
using namespace std;
const int MAX_N=2e5+10;

int N;
vector<int> G[MAX_N];
bool seen[MAX_N],finished[MAX_N];
stack<int> hist;
set<int> cycle;
int par[MAX_N],grundy[MAX_N][2];

struct CycleDetection{
    vector<vector<int>> G;
    vector<int> seen,finished;
    stack<int> hist;
    int pos;
    CycleDetection(int n):G(n),seen(n,0),finished(n,0),pos(-1){}
    void add_edge(int u,int v){
        G[u].emplace_back(v);
    }
    void dfs(int v){
        seen[v]=1; hist.push(v);
        for (int u:G[v]){
            if (finished[u]) continue;
            if (seen[u]&&!finished[u]){pos=u; return;}
            dfs(u);
            if (pos!=-1) return;
        }
        finished[v]=1; hist.pop();
    }
    set<int> build(int &cycle){
        for (int v=0;v<G.size();++v){
            if (!seen[v]) dfs(v);
        }
        cycle=(pos!=-1);
        set<int> res;
        while(!hist.empty()){
            int t=hist.top(); hist.pop();
            res.emplace(t);
            if (t==pos) break;
        }
        return res;
    }
};

void dfs2(int v,int p){
    set<int> mex;
    for (int u:G[v]){
        if (u==p) continue;
        if (p<0&&cycle.count(u)) continue;
        dfs2(u,v);
        mex.emplace(grundy[u][0]);
    }
