        if (g[p] > h[p]) return false;
        //printf("Node #%d: %d | [%d, %d]\n", cyc[p], f[cyc[p]], g[p], h[p]);
    }
    for (int i = g[(pos + 1) % n]; i <= h[(pos + 1) % n]; ++i)
        if (h[pos] != i) return true;
    return false;
}

