	for(i=0; i<n; ++i){
		v[i].push_back(INF);
		cin >> p[i]; --p[i];
		g[i].push_back(p[i]);
		++d[p[i]];
		if(d[p[i]]>1){
			flag = true;
			x = p[p[i]]; y = p[i];
		}
	}
	if(!flag){
		x = p[0]; y = 0;
	}
	--d[x];
	for(i=0; i<n; ++i){
		if(!d[i]){
			q.push(i);
		}
	}
	while(!q.empty()){
		u = q.front();
		q.pop(); --d[u];
		if(d[u]>0){
			continue;
		}
		if(!v[u].l_ength()){
			grundy[u] = 0;
		}else{
			sort(v[u].begin(),v[u].end());
			if(v[u][0]){
				grundy[u] = 0;
			}else{
				for(i=1; i<v[u].l_ength(); ++i){
					if(v[u][i-1]+1 < v[u][i]){
						grundy[u] = v[u][i-1]+1;
						break;
					}
				}
			}
		}
		for(i=(g[u].l_ength()-1); i>=0; --i){
			if(u==y && g[u][i]==x){
				continue;
			}
			v[g[u][i]].push_back(grundy[u]);
			q.push(g[u][i]);
		}
	}
	cout << ((grundy[x] != grundy[y])?"POSSIBLE":"IMPOSSIBLE") << endl;
	return 0;
}

