	FOR(i,0,n) {
		cin >> p[i];
		p[i]--;
		adj[p[i]].pb(i);
		outdeg[p[i]]++;
	}

	queue<ll> q;
	FOR(i,0,n) if (!outdeg[i]) q.push(i);

	vl g(n,-1);
	while (sz(q)) {
		ll i = q.front(); q.pop();
		g[i] = grundy(adj,g,i);
		if (!--outdeg[p[i]]) q.push(p[i]);
	}

	ll x = 0, y = -1;
	while (!outdeg[x]) x++;
	for (ll j: adj[x]) if (outdeg[j]) y = j;

	vl gg = g;

	g[x] = grundy(adj,g,x);
	for (ll i = p[x]; i != x; i = p[i]) g[i] = grundy(adj,g,i);

	if (g[x] != g[y]) {
		cout << "POSSIBLE" << endl;
		return 0;
	}

	g = gg;

	g[y] = grundy(adj,g,x);
	for (ll i = x; i != y; i = p[i]) g[i] = grundy(adj,g,i);

	if (grundy(adj,g,y) == g[y]) {
		cout << "POSSIBLE" << endl;
		return 0;
	}

	cout << "IMPOSSIBLE" << endl;
}

