    FOR(i, 1, n) {
        scanf("%d", &p[i]);
        a[p[i]].push_back(i);
    }
    memset(grundy, -1, sizeof(grundy));
    FOR(i, 1, n) pq.push(ii(d[i]=a[i].sz(), i));
    while (pq.sz()) {
        int u = pq.top().se, du = pq.top().fi;
        pq.pop();
        if (du!=d[u] || du!=0) continue;
        d[p[u]]--;
        pq.push(ii(d[p[u]], p[u]));
        grundy[u] = MEX(u).fi;
    }
    //Debug(MEX(1).se);
    FOR(i, 1, n) {
        if (grundy[i]==-1) {
            FOR(j, 1, n) tmp[j] = grundy[j];
            fuck(i, MEX(i).fi);
            bool ok = true;
            FOR(j, 1, n) {
                if (grundy[j]!=MEX(j).fi)
                    ok = false;
            }
            if (ok) {cout << "POSSIBLE"; return 0;}
            ok = true;
            FOR(j, 1, n) grundy[j] = tmp[j];
            fuck(i, MEX(i).se);
            FOR(j, 1, n) {
                if (grundy[j]!=MEX(j).fi) ok = false;
            }
            if (ok) {cout << "POSSIBLE"; return 0;}
            cout << "IMPOSSIBLE";
            return 0;
        }
    }
    cout << "POSSIBLE";
}

