#include<bits/stdc++.h>
using namespace std;

int n;
vector<int> out[200010];
int in[200010];
int cycle[200010];
int grundy[200010];
int st = -1;
const int CYCLE = 42;

int dfs(int x, int p) {
	cycle[x] = 1;
	for(int i : out[x]) {
		if(i != p) {
			if(cycle[i] == 1) {
				st = i;
				cycle[x] = CYCLE;
				return CYCLE;
			}
			else if(cycle[i] == 0) {
				if(dfs(i, x) == CYCLE) {
					cycle[x] = CYCLE;
					if(x == st) return 0;
					else return CYCLE;
				}
			}
		}
	}
	cycle[x] = 2;
	return 0;
}

int getgrundy(int x) {
	set<int> s;
	for(int i : out[x])
		if(cycle[i] != CYCLE)
			s.insert(getgrundy(i));
	int ans = 0;
	auto it = s.begin();
	while(it != s.end()) {
		if(*it == ans) {
			++ans;
			++it;
		}
		else return grundy[x] = ans;
	}
	return grundy[x] = ans;
}

bool chk(int x, int val, int res) {
	if(x == st) return res == val;
	int nxt = -1;
	for(int i : out[x]) {
		if(cycle[i] == CYCLE) {
			nxt = i;
		}
	}
	if(nxt == -1) return false;
	return chk(nxt, grundy[nxt] + (grundy[nxt] == val), res);
}

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0);
	cin >> n;
	memset(cycle, 0, sizeof cycle);
	for(int i = 0; i < n; ++i){
		int x;
		cin >> x;
		--x;
		out[x].push_back(i);
		in[i] = x;
		if(x < i and in[x] == i) {
			st = i;
			cycle[x] = cycle[i] = CYCLE;
		}
	}
	for(int i = 0; st == -1 and i < n; ++i) if(cycle[i] == 0) dfs(i, -1);
	for(int i = 0; i < n; ++i) {
		if(cycle[i] == CYCLE) getgrundy(i);
	}
	int nxt;
	for(int i : out[st]) {
		if(cycle[i] == CYCLE) {
			nxt = i;
		}
	}
	if(st == nxt or chk(nxt, grundy[nxt] + (grundy[st] == grundy[nxt]), grundy[st])) cout << "POSSIBLE" << endl;
	else if (chk(nxt, grundy[nxt] + ((grundy[st] + 1) == grundy[nxt]), grundy[st] + 1)) cout << "POSSIBLE" << endl;
	else cout << "IMPOSSIBLE" << endl;

}

//題意の条件は「遷移先に含まれない最小の非負整数を書く」と言い換えらえる。木やDAGの場合は書き方が一意に定まる。
//なもりグラフの場合は、木を含むか・単なるループかによって書き方が異なる。単なるループの場合、ループ長の偶奇で判定できる。
//木を含む場合は、木の根を一つ取ってきて書く数aを決めると、書き方が一意に定まる。aは2通り程度試せばよい…と思う。最後に矛盾判定をすればよい。
//実装は、グラフの辺の向きを逆にすると簡単。逆にする：i -> p_i

#include <iostream>
#include <queue>
#include <set>
#include <vector>
#define rep(i, n) for(i = 0; i < n; i++)
using namespace std;

int n;
int p[200000], inV[200000];
set<int> gset[200000];
int g[200000];
int g2[200000];
bool isTree[200000];
vector<int> et[200000];

bool check(int start, int val) {
	int i, j;
	rep(i, n) g2[i] = g[i];
	g2[start] = val;

	//ループ内の頂点について、grundy数を決める.	
	int pos = start;
	while (true) {
		int npos = p[pos];
		if (npos == start) break;
		g2[npos] += (g2[pos] == g2[npos]);
		pos = npos;
	}

	//rep(i, n) cout << g2[i] << " ";
	//cout << endl;

	//矛盾判定 (元のグラフで考える)
	rep(i, n) gset[i].clear();
	rep(i, n) et[p[i]].push_back(i);
	rep(i, n) {
		rep(j, et[i].size()) gset[i].insert(g2[et[i][j]]);
		rep(j, n) if (gset[i].find(j) == gset[i].end()) break;
		if (j != g2[i]) { return false; }
	}
	return true;
}

int main() {
	int i, j;
	queue<int> que;

	cin >> n;
	rep(i, n) { cin >> p[i]; p[i]--; inV[p[i]]++; }
	rep(i, n) { if (!inV[i]) que.push(i); }

	while (!que.empty()) {
		int v = que.front(); que.pop();
		rep(i, n) if (gset[v].find(i) == gset[v].end()) break;
		g[v] = i;
		gset[v].clear();
		gset[p[v]].insert(g[v]);
		inV[p[v]]--;
		if (!inV[p[v]]) que.push(p[v]);
	}

	rep(i, n) isTree[i] = (gset[i].size() > 0);
	rep(i, n) if (isTree[i]) break;
	if (i == n) { cout << ((n % 2) ? "IMPOSSIBLE" : "POSSIBLE") << endl; return 0; }

	rep(i, n) {
		if (!isTree[i]) continue;
		rep(j, n) if (gset[i].find(j) == gset[i].end()) break;
		g[i] = j;
	}

	rep(i, n) if (isTree[i]) break;
	int start = i, g0 = g[start];

	rep(i, 100) if (check(start, g0 + i)) { cout << "POSSIBLE" << endl; return 0; }
	cout << "IMPOSSIBLE" << endl;
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

int mex(set<int> x)
{
    int r = 0;
    while(x.count(r))
        r++;
    return r;
}

const int maxn = 6e5;
vector<int> G[maxn], Gt[maxn];

void add_edge(int u, int z1, int v, int z2)
{
    int U = u + maxn / 2 * z1;
    int V = v + maxn / 2 * z2;
    G[U].push_back(V);
    Gt[V].push_back(U);
}

int used[maxn];

void dfs(int v, vector<int> *G, vector<int> &st)
{
    if(used[v])
        return;
    used[v] = 1;
    for(auto u: G[v])
        dfs(u, G, st);
    st.push_back(v);
}

void try2sat()
{
    vector<int> top_sort;
    dfs(0, G, top_sort);
    reverse(begin(top_sort), end(top_sort));
    memset(used, 0, sizeof(used));
    for(auto v: top_sort)
    {
        if(used[v])
            continue;
        vector<int> comp;
        dfs(v, Gt, comp);
        set<int> lol;
        for(auto u: comp)
        {
            lol.insert(u);
            if(lol.count(u ^ 1))
            {
                cout << "IMPOSSIBLE\n";
                exit(0);
            }
        }
    }
    cout << "POSSIBLE\n";
}

signed main()
{
    //freopen("input.txt", "r", stdin);
    ios::sync_with_stdio(0);
    cin.tie(0);
    int n;
    cin >> n;
    int p[n], cnt[n] = {0};
    set<pair<int, int>> vrt;
    for(int i = 0; i < n; i++)
    {
        cin >> p[i];
        p[i]--;
        vrt.erase({cnt[p[i]], p[i]});
        cnt[p[i]]++;
        vrt.insert({cnt[p[i]], p[i]});
    }
    set<int> banned[n];
    while(begin(vrt)->first == 0)
    {
        int v = begin(vrt)->second;
        vrt.erase(begin(vrt));
        vrt.erase({cnt[p[v]], p[v]});
        cnt[p[v]]--;
        vrt.insert({cnt[p[v]], p[v]});
        banned[p[v]].insert(mex(banned[v]));
    }
    int m[n][2];
    for(auto it: vrt)
    {
        int v = it.second;
        m[v][0] = mex(banned[v]);
        banned[v].insert(m[v][0]);
        m[v][1] = mex(banned[v]);
        cout << v << ' ' << m[v][0] << ' ' << m[v][1] << endl;
    }
    for(auto it: vrt)
    {
        int v = it.second;
        int u = p[v];
        for(int z1 = 0; z1 <= 1; z1++)
            for(int z2 = 0; z2 <= 1; z2++)
                if(m[u][z1] == m[v][z2])
                {
                    add_edge(u, z1, v, !z2);
                    add_edge(v, z2, u, !z1);
                }
        if(m[u][0] == m[v][0])
        {
            add_edge(u, 1, v, 0);
        }
        else if(m[u][0] == m[v][1])
        {
            add_edge(u, 1, v, 1);
        }
        else
        {
            add_edge(u, 1, u, 0);
        }
    }
    try2sat();
}

