int n, v[200000], g[200000];
vector<vi> e;

void rec(int c, vi &stk, vi &loop){
	//dbg(c);
	v[c] = 1;
	stk.pb(c);
	for(int i : e[c]) if(v[i] != 2){
		if(v[i] == 1){
			for(int j = stk.size() - 1; ; j--){
				assert(j >= 0);
				loop.pb(stk[j]);
				if(stk[j] == i) break;
			}
			return;
		}
		else rec(i, stk, loop);
		if(loop.size()) return;
	}
	v[c] = 2;
	stk.pop_back();
}
int grundy(int c){
	if(g[c] >= 0) return g[c];
	set<int> s;
	for(int i : e[c]) s.insert(grundy(i));
	for(int i = 0; ; i++) if(!s.count(i)) return g[c] = i;
}
