		set<int> s;
		for(int i : e[v]) s.insert(g[i]);
		for(int i = 0; b < 0; i++) if(!s.count(i)){
			if(a < 0) a = i;
			else b = i;
		}
		g[v] = it ? a : b;
		for(int i : loop) grundy(i);
