void run(int v) {
    was[v] = 1;
    st.push_back(v);
    int u = go[v];
    if (was[u]) {
        for (int i = 0; i < st.size(); ++i)
            if (st[i] == u) {
                for (int j = i; j < st.size(); ++j)
                    vv.push_back(st[j]);
                break;
            }
        return;
    }
    else {
        run(u);
    }
}

