    vector<int> vv;
    for (int u: eds[v]) {
        vv.push_back(dfs1(u));
    }
    sort(vv.begin(), vv.end());
    vv.resize(unique(vv.begin(), vv.end()) - vv.begin());
    a[v] = vv.size();
    for (int i = 0; i < vv.size(); ++i)
        if (vv[i] != i) {
            a[v] = i;
            break;
        }
    return a[v];
}

int get(int v) {
    vector<int> vv;
    for (int u: eds[v]) {
        vv.push_back(a[u]);
    }
    sort(vv.begin(), vv.end());
    vv.resize(unique(vv.begin(), vv.end()) - vv.begin());
    for (int i = 0; i < vv.size(); ++i)
        if (vv[i] != i) {
            return i;
        }
    return vv.size();
}

