int IN(){
	int c,f,x;
	while (!isdigit(c=getchar())&&c!='-');c=='-'?(f=1,x=0):(f=0,x=c-'0');
	while (isdigit(c=getchar())) x=(x<<1)+(x<<3)+c-'0';return !f?x:-x;
}

const int N=200000+19;

struct Edge{
	int y,nxt;
} E[N*2];
int las[N],fa[N],vis[N],onc[N],A[N],tmp[N],T[N],val[N];
int n,cnt,Time,pre,u,v,x,y;

void Add_Edge(int x,int y){
	E[cnt]=(Edge){y,las[x]};las[x]=cnt++;
}
void dfs(int x){
	vis[x]=1;
	for (int i=las[x],y;~i;i=E[i].nxt){
		y=E[i].y;
		if (!vis[y]){
			fa[y]=x;
			dfs(y);
		} else{
			u=x,v=y;
		}
	}
}
void calc(int x){
	for (int i=las[x];~i;i=E[i].nxt) calc(E[i].y);
	Time++;
	for (int i=las[x];~i;i=E[i].nxt) T[val[E[i].y]]=Time;
	val[x]=0;
	while (T[val[x]]==Time) val[x]++;
}
void Work(){
	For(s,2,*A+1){
		int x=A[s];
		for (int i=las[x],y;~i;i=E[i].nxt) if (!onc[y=E[i].y]) calc(y);
		Time++;
		for (int i=las[x],y;~i;i=E[i].nxt) if (!onc[y=E[i].y]) T[val[y]]=Time;
		T[val[A[s-1]]]=Time;
		val[x]=0;
		while (T[val[x]]==Time) val[x]++;
	}
}

int main(){
	memset(las,-1,sizeof(las));
	n=IN();
	For(i,1,n+1){
		x=IN(),y=i;
		Add_Edge(x,y);
	}
	dfs(1);
	for (int w=u;w!=v;w=fa[w]){
		onc[w]=1;
		A[++*A]=w;
	}
	onc[v]=1;
	A[++*A]=v;
	for (int i=las[u],y;~i;i=E[i].nxt)
		if ((y=E[i].y)!=v){
			calc(y);
			tmp[val[y]]=1;
		}
	val[u]=0;
	while (tmp[val[u]]) val[u]++;
	Work();
	if (val[A[*A]]!=val[u]){
		puts("POSSIBLE");
		return 0;
	}
	pre=val[u];
	val[u]++;
	while (tmp[val[u]]) val[u]++;
	Work();
	if (val[A[*A]]==pre){
		puts("POSSIBLE");
		return 0;
	}
	puts("IMPOSSIBLE");
}

