bool nieparz(int n) {
	for (int x = 1; x <= n; x ++) {
		if (vis[x]) continue;
		for (int y : G[x]) {
			if (odp[y] == odp[x] + 1) return true;
		}
	}
	return false;
}

bool algos(int n, int x) {
// 	printf("algos\n");
// 	printf("x -- %d %d\n", x, odp[x]);

	cyc[x] = true;
	int ile = 0;
	while(odp[skad[x]] == odp[x]) {
// 		printf("cyc %d\n", x);
		ile ++;
		if (cyc[skad[x]]) {
			if (ile % 2 == 1) {
				return nieparz(n);
			}
			return true;
		}
		x = skad[x];
		cyc[x] = true;
	}
	while(cyc[skad[x]] == 0) {
		x = skad[x];
		cyc[x] = true;
	}
	return true;
}

int tle(int x, int y) {
	if (x == 0) {
		return y + 1;
	}
	return tle(x + 1, tle(x, y + 1)); 
}

