		for (j=1;j<=cnt;j++)
			if (sig!=a[j]) break;
		else sig++;
		dp[k]=sig;
		u=p[k]; d[u]--;
		if (!d[u]){
			vis[u]=1; q.push(u);
		}
	}
}

void solve(){
	int k,u,j,st;
	st=b[1]; k=p[b[1]];
	while (k!=st){
