void dfs(int u, vector<int> &ans, vector<vector<int>> &from, vector<vector<int>> &to) {

    FOE(v, to[u]) {
        if (ans[v] == -1) {
            unordered_set<int> s;
            bool ok = true;
            FOE(x, from[v]) {
                s.insert(x);
                if (ans[x] == -1) {
                    ok = false;
                }
            }

            if (ok) {
                FOR(i, 0, s.size() + 2) {
                    if (s.find(i) == s.end()) {
                        ans[v] = i;
                        dfs(v, ans, from, to);
                        break;
                    }
                }
            }
        }
    }
}

bool func(int u, vector<int> &ans, vector<vector<int>> &from, vector<vector<int>> &to) {
    int v = to[u][0];
    while (true) {
        unordered_set<int> s;
        FOE(x, from[v]) {
            s.insert(ans[x]);
        }

        FOR(i, 0, s.size() + 2) {
            if (s.find(i) == s.end()) {
                if (ans[v] != -1) {
                    return ans[v] == i;
                }
                ans[v] = i;
                break;
            }
        }

        v = to[v][0];
    }
}

bool check(vector<int> &ans, vector<vector<int>> &from) {
    FOR(i, 0, ans.size()) {
        unordered_set<int> s;
        FOE(x, from[i]) {
            if (ans[x] == -1) {
                return false;
            }
            s.insert(ans[x]);
        }

        FOR(j, 0, s.size() + 1) {
            if (s.find(j) == s.end()) {
                if (j != ans[i]) {
                    return false;
                }
                break;
            }
        }
    }
    return true;
}

