int read()
{
    int x=0,f=1;char ch=getchar();
    for (;ch<'0'||ch>'9';ch=getchar()) if (ch=='-') f=-1;
    for (;ch>='0'&&ch<='9';ch=getchar()) x=x*10+ch-'0';
    return x*f;
}

void add(int u,int v)
{
    pre[++tot]=now[u];
    now[u]=tot;
    son[tot]=v;
}

bool dfs(int x)
{
    vis[x]=1;
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    cir[x]|=vis[child];
	    if (!vis[child]) cir[x]|=dfs(child);
	}
    return cir[x];
}
void get(int x)
{
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    if (cir[child]) continue;
	    get(child);
	}
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    if (cir[child]) continue;
	    inq[v[child]]=1;
	}
    while(inq[v[x]]) v[x]++;
    for (int p=now[x];p;p=pre[p])
	{
	    int child=son[p];
	    if (cir[child]) continue;
	    inq[v[child]]=0;
	}
    if (cir[x]) tmp[++cnt]=v[x];
}	    

