{
    n=read();
    for (int i=1;i<=n;i++)
	{
	    int x=read();
	    add(x,i);
	}
    for (int i=1;i<=n;i++)
	if (!vis[i]) cir[i]=dfs(i);
    for (int i=1;i<=n;i++) if (cir[i]) get(i);
    if ((cnt&1)^1) {puts("POSSIBLE");return 0;}
    for (int i=2;i<=cnt;i++)
	if (tmp[i]!=tmp[i-1])
	    {
		puts("POSSIBLE");
		return 0;
	    }
    puts("IMPOSSIBLE");
    return 0;
}

#include <cstdio>
const int N=200005;
int fst[N],nxt[N],p[N],q[N],deg[N],f[N];
bool u[N];
void addedge(int x,int y){
	nxt[y]=fst[x];fst[x]=y;
}
int calc(int x){
	for (int i=fst[x];i;i=nxt[i]) if (!deg[i]) u[f[i]]=1;
	int y=0;
	for (;u[y];y++);
	for (int i=fst[x];i;i=nxt[i]) u[f[i]]=0;
	return y;
}
bool check(int st,int v){
	for (int i=st;!deg[i];i=p[i]) deg[i]=1;
	--deg[st];f[st]=calc(st)+v;
	for (int i=p[st];i!=st;i=p[i]){
		deg[i]=0;
		f[i]=calc(i);
	}
	return calc(st)==f[st];
}
int main(){
	int n;
	scanf("%d\n",&n);
	for (int i=1;i<=n;i++){
		scanf("%d",&p[i]);
		addedge(p[i],i);
		deg[p[i]]++;
	}
	int head=1,tail=0;
	for (int i=1;i<=n;i++)
		if (!deg[i]) q[++tail]=i;
	for (;head<=tail;){
		int x=q[head++];
		if (!--deg[p[x]]) q[++tail]=p[x];
		f[x]=calc(x);
	}
	int st=0;
	for (int i=1;i<=n;i++)
		if (deg[i]) st=i;
	if (check(st,0) || check(st,1)) printf("POSSIBLE\n");
		else printf("IMPOSSIBLE\n");
}

