#define N 200005

using namespace std;

struct edge{
	int to, nxt;
}e[N << 1];

int n, cnt, num, tot;
int a[N], p[N], fir[N], dfn[N], low[N], co[N];

stack < int > st;
vector < int > G[N];

void add(int ,int);
void Tarjan(int);
void dfs(int ,int);

int main(){
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i)
		scanf("%d",p + i), add(p[i], i);
	for(int i = 1; i <= n; ++i)
		if(!dfn[i]) Tarjan(i);
	bool flag = true;
	for(int i = 1; i <= tot; ++i){
		int sz = G[i].size();
		if(sz == 1 || sz % 2 == 0) continue;
		for(int j = 0; j < sz; ++j)
			dfs(G[i][j], co[G[i][j]]);
		bool book = true;
		for(int j = 1; j < sz; ++j)
			if(a[G[i][j]] != a[G[i][j - 1]]){
				book = false;break;
			}
		if(book) flag = false;
	}
	if(flag) puts("POSSIBLE");
	else puts("IMPOSSIBLE");
	return 0;
}

void add(int u,int v){
	e[++cnt].to = v;e[cnt].nxt = fir[u];fir[u] = cnt;
	return ;
}

void Tarjan(int u){
	dfn[u] = low[u] = ++num;
	st.push(u);
	for(int i = fir[u]; i; i = e[i].nxt){
		int v = e[i].to;
		if(!dfn[v]) Tarjan(v), low[u] = min(low[u], low[v]);
		else if(!co[v]) low[u] = min(low[u], dfn[v]);
	}
	if(low[u] == dfn[u]){
		co[u] = ++tot;G[tot].push_back(u);
		while(st.top() != u){
			co[st.top()] = tot;
			G[tot].push_back(st.top());
			st.pop();
		}
		st.pop();
	}
	return ;
}

void dfs(int u,int x){
	bool vis[100];memset(vis, false, sizeof vis);
	for(int i = fir[u]; i; i = e[i].nxt){
		int v = e[i].to;
		if(co[v] == x) continue;
		dfs(v, x);vis[a[v]] = true;
	}
	int pos = 0;
	while(vis[pos]) ++pos;
	a[u] = pos;
	return ;
}

