using namespace std;

typedef long long ll;
typedef long double ld;
#define fastInp cin.tie(0); cout.tie(0); ios_base::sync_with_stdio(0);

const ll SIZE = 1e6 + 100, INF = 1e9;
vector<vector<ll>> graph, gr;
map<pair<ll, ll>, ll> fr;

bool flag = false;
ll c[SIZE], par[SIZE];
bool used[SIZE];
vector<ll> way;
set<ll> s;

void cycle(int v) {
    used[v] = 1;
    for (auto to : gr[v]) {
        if (!used[to]) {
            par[to] = v;
            cycle(to);
        } else if (to != par[v]) {
            if (!flag) {
                ll u = v;
                while (u != to) {
                    way.push_back(u);
                    u = par[u];
                }              
                way.push_back(to);
                flag = true;      
            }
        }
    }
}

void find(int v) {
    used[v] = 1;

    vector<ll> curVl;
    for (auto to : gr[v]) {
        if (!used[to]) {
            find(to);
            if (fr[{v, to}] == v) curVl.push_back(c[to]);
        }
    }

    ll pr = -1;
    curVl.push_back(INF);
    sort(curVl.begin(), curVl.end());

    ll mx = -1;
    for (auto cur : curVl) {
        if (cur == pr) continue;

        if (pr + 1 < cur) {
            mx = pr + 1;
            break;
        }
        pr = cur;
    }

    c[v] = mx;
}

void ch(int v) {
    used[v] = 1;

    for (auto to : graph[v]) {
        if (!used[to] && s.find(to) != s.end()) {
            ch(to);
        }
        if (c[v] == c[to]) {
            c[v]++;
        }
    }
}

int main()
{
    fastInp;

    ll n;
    cin >> n;

    graph.resize(n);
    gr.resize(n);
    for (int i = 0; i < n; i++) {
        ll pr;
        cin >> pr;
        pr--;
        graph[pr].push_back(i);
        fr[{pr, i}] = pr;
        fr[{i, pr}] = pr;
        gr[pr].push_back(i);
        gr[i].push_back(pr);
    }

    cycle(0);

    for (int i = 0; i < n; i++) used[i] = 0;

    for (int i = 0; i < way.size(); i++) used[way[i]] = 1;

    for (int i = 0; i < way.size(); i++) {
        ll v = way[i];

        find(v);
    }

    for (int i = 0; i < n; i++) used[i] = 0;

    for (int i = 0; i < way.size(); i++) {
        ll v = way[i], u = way[(i + 1) % way.size()];
        if (c[v] == c[u] && !used[v] && !used[u]) {
            ll hr = fr[{v, u}];
            c[hr]++;
            used[v] = 1;
            used[u] = 1;
        }
    }

    bool flag = true;

    for (auto cur : way) s.insert(cur);

    for (auto cur : way) {
        if (!used[cur]) ch(cur);
    }
    for (int i = 0; i < way.size(); i++) {
        ll v = way[i], u = way[(i + 1) % way.size()];
        if (c[u] == c[v]) flag = false;
    }

    if (flag) {
        cout << "POSSIBLE";
    } else {
        cout << "IMPOSSIBLE";
    }
    return 0;    
}

