vector<int> cir, E[maxn], G;
int top, e, cnt;
vector<int> ed[maxn];
int dfn[maxn], low[maxn], sta[maxn], belong[maxn], id[maxn][2];
inline void cmin(int& u, int& v)
{
	u = u > v ? v : u;
}
void tarjan(int u)
{
	dfn[u] = low[u] = ++e;
	sta[++top] = u;
	for(int i = 0; i < ed[u].size(); ++i)
	{
		int v = ed[u][i];
		if(!dfn[v])
			tarjan(v), cmin(low[u], low[v]);
		else if(!belong[v])
			cmin(low[u], dfn[v]);
	}
	if(low[u] == dfn[u])
		for(++cnt; sta[top + 1] ^ u; --top)
			belong[sta[top]] = cnt;
}
bool solve()
{
	int nn = cir.size() << 1 | 1;
	for(int i = 2; i <= nn; ++i)
		if(!dfn[i])
			tarjan(i);
	for(int i = 1; i <= cir.size(); ++i)
		if(belong[i << 1] == belong[i << 1 | 1])
			return 0;
	return 1;
}
void getsg(int x)
{
	G.clear();
	for(auto v : E[x])
		if(!incir[v])
			 G.push_back(sg[v]);
	fill(insg, insg + G.size() + 1, 0);
	for(auto v : G) insg[v] = 1;
	for(int i = 0; i <= G.size(); ++i)
		if(!insg[i])
		{
			sg[x] = i;
			break;
		}
}
void dfs(int x)
{
	vis[x] = 1;
	for(auto v : E[x])
	{
		if(!vis[v])
			dfs(v);
		if(incir[v])
		{
			incir[x] = 1;
			cir.push_back(x);
		}
	}
	getsg(x);
}
int main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i)
	{
		scanf("%d", &p[i]);
		E[p[i]].push_back(i);
		fa[i] = p[i];
	}
	int rt = 1;
	for(int i = 1; i <= n; ++i) rt = fa[rt];
	incir[rt] = 1;
	dfs(rt);
	for(int i = 0; i < cir.size(); ++i) id[cir[i]][0] = (i + 1) << 1, id[cir[i]][1] = (i + 1) << 1 | 1;
	for(int i = 1; i <= cir.size(); ++i)
	{
		int u = cir[i - 1], v = cir[i == cir.size() ? 0 : i];
		if(sg[u] == sg[v])
		{
			ed[id[u][0]].push_back(id[v][1]);
			ed[id[u][1]].push_back(id[v][0]); 
			ed[id[v][0]].push_back(id[u][1]);
			ed[id[v][1]].push_back(id[u][0]); 
		}
		else if(sg[u] == sg[v] - 1)
		{
			ed[id[u][0]].push_back(id[v][0]);
			ed[id[u][1]].push_back(id[v][1]); 
			ed[id[v][0]].push_back(id[u][0]);
			ed[id[v][1]].push_back(id[u][1]); 
		}
		else
		{
			ed[id[v][1]].push_back(id[v][0]);
		}
	}
