//サイクルを一周して最後に矛盾がないかどうか
bool cycle(int x, int y){
	int i = p[x];
	int pre = y;
	while(i!=x){
		set<int> s;
		s.insert(pre);
		for(int j=0;j<G[i].size();j++){
			s.insert(a[G[i][j]]);
		}
		int z = 0;
		while(s.count(z)){
			z++;
		}
		a[i] = z;
		pre = a[i];
		i = p[i];
	}
	set<int> st;
	st.insert(pre);
	for(int j=0;j<G[x].size();j++){
		st.insert(a[G[x][j]]);
	}
	int z = 0;
	while(st.count(z)){
		z++;
	}
	return y==z;
}

int main(){
	int i,j,z;
	cin >> n;
	for(i=0;i<n;i++){
		cin >> p[i];
		p[i]--;
		G[p[i]].push_back(i);
	}

	for(i=0;i<n;i++){
		if(G[i].size()==0){
			que.push(i);
		}
		a[i]  = -1;
	}

	while(!que.empty()){
		set<int> s;
		int x = que.front();
		que.pop();
		if(a[x]>=0) continue;
		for(j=0;j<G[x].size();j++){
			if(a[G[x][j]]<0){
				z = 1;
			}
			s.insert(a[G[x][j]]);
		}
		if(z){
			z = 0;
			continue;
		}
		int y = 0;
		while(s.count(y)){
			y++;
		}
		a[x] = y;
		que.push(p[x]);
	}

	for(i=0;i<n;i++){
		if(a[i]<0){
			z = i;
			break;
		}
	}

	set<int> st;
	for(i=0;i<G[z].size();i++){
		st.insert(a[G[z][i]]);
	}
	j = 0;
	while(st.count(j)){
		j++;
	}
	int k = j;
	j++;
	while(st.count(j)){
		j++;
	}
	int l = j;
	if(cycle(z,k)||cycle(z,l)){
		cout << "POSSIBLE" << endl;
		return 0;
	}
	cout << "IMPOSSIBLE" << endl;
}

