    }
};
template <typename TEdge, bool Index> vector<int> toposort(graph<1, TEdge, Index>& g) {
    vector<int> indeg(g.adj.size());
    for(int u = Index; u < g.adj.size(); u++) {
        for(int e : g[u]) {
            indeg[g(e).v]++;
        }
    }
    queue<int> q;
    for(int u = Index; u < g.adj.size(); u++) {
        if(indeg[u] == 0) {
            q.push(u);
        }
    }
    vector<int> ans;
    while(not q.empty()) {
        int u = q.front(); q.pop();
        ans.push_back(u);
        for(int e : g[u]) {
            if(--indeg[g(e).v] == 0) {
                q.push(g(e).v);
            }
        }
    }
    return ans;
}
auto mex1 = [](set<int>& s) {
    for(int i = 0; ; i++) {
        if(not s.count(i)) {
            return i;
        }
    }
    return -1;
};
auto mex2 = [](set<int>& s) {
    int m1 = mex1(s);
    s.insert(m1);
    int ans = mex1(s);
    s.erase(m1);
    return ans;
};
auto mex = [](graph<1, edge, 1>& g, vector<int>& nimber, int u, const function<int(set<int>&)>& mex_f) {
    set<int> s;
    for(int e : g[u]) {
        s.insert(nimber[g(e).v]);
    }
    return mex_f(s);
};
bool can(graph<1, edge, 1>& g, vector<int>& tp, const function<int(set<int>&)>& mex_s) {
    vector<int> nimber(g.adj.size(), -1);
    for(int v : tp) {
        nimber[v] = mex(g, nimber, v, mex1);
    }
    set<int> cycle;
    for(int v = 1; v <= g.size(); v++) {
        if(nimber[v] == -1) {
            cycle.insert(v);
        }
    }
    if(not cycle.empty()) {
        vector<int> pre(g.adj.size());
        for(int u : cycle) {
            for(int e : g[u]) {
                if(cycle.count(g(e).v)) {
                    pre[g(e).v] = u;
                }
            }
        }
        int s = *cycle.begin();
        nimber[s] = mex(g, nimber, s, mex_s);
        for(int k = pre[s]; k != s; k = pre[k]) {
            nimber[k] = mex(g, nimber, k, mex1);
        }
    }
    return all_of(g.edges.begin(), g.edges.end(), [&](auto& e) {
        return nimber[e.u] != nimber[e.v];
    }) and (cycle.empty() or mex(g, nimber, *cycle.begin(), mex1) == nimber[*cycle.begin()]);
}
