bool vis[maxn];
bool cycle[maxn];

bool check(){
    memset(vis, 0, sizeof(vis));
    for(int i = 1;i <= n;i++){
        for(auto v : G[i]){
            if(sg[v] == sg[i])
                return false;
            vis[sg[v]] = true;
        }
        for(int j = 0;j < sg[i];j++){
            if(!vis[j])
                return false;
        }
        for(auto v : G[i]){
            vis[sg[v]] = false;
        }
    }
    return true;
}

bool solve(){
    int start = 0;
    for(int i = 1;i <= n;i++){
        if(cycle[i] == 0){
            start = i;
        }
    }
    memset(vis, 0, sizeof(vis));
    vector<int> candidate;
    for(auto v : G[start]){
        if(cycle[v]){
            vis[sg[v]] = true;
        }
    }
    for(int i = 0;i < maxn;i++){
        if(!vis[i]){
            candidate.push_back(i);
        } 
        if(candidate.size() == 2){
            break;
        }
    } 
    for(auto x : candidate){
        memset(vis, 0, sizeof(vis));
        sg[start] = x;
        int now = p[start];
        while(now != start){
            for(auto v : G[now]){
                vis[sg[v]] = true;
            }
            for(int i = 0;i < maxn;i++){
                if(!vis[i]){
                    sg[now] = i;
                    break;
                }
            }
            for(auto v : G[now]){
                vis[sg[v]] = false;
            }
            now = p[now];
        }
        if(check())
            return true;
    }
    return false;
} 

