void input()
{
	int f;
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		scanf("%d",&f);
		v[i]=f;
		rud[f]++;
	}
}

int mex(int y)
{
	sort(son[y].begin(),son[y].end());
	if(!son[y].size())return 0;
	else if(son[y][0]!=0)return 0;
	else
	{
		int p=1;
		while(p<son[y].size()&&son[y][p]-son[y][p-1]<=1)p++;
		return son[y][p-1]+1;
	}
}

int stk[MX],top;
void topo()
{
	int x,y;
	for(int i=1;i<=n;i++)if(!rud[i])stk[++top]=i;
	while(top)
	{
		x=stk[top--];
		y=v[x];
		rud[y]--;
		son[y].push_back(num[x]);
		if(!rud[y])
		{
			num[y]=mex(y);
			stk[++top]=y;
		}
	}
}

int work()
{
	int x=0,siz=0,num;
	for(int i=1;i<=n;i++)
	{
		if(rud[i])
		{
			x=i,siz++;
			//for(int j=0;j<son[i].size();j++)cout<<son[i][j]<<" ";cout<<endl;
			//cout<<"fuck:";
			may[i][0]=mex(i);//cout<<endl;
			son[i].push_back(may[i][0]);
			//for(int j=0;j<son[i].size();j++)cout<<son[i][j]<<" ";cout<<endl;
			may[i][1]=mex(i);
			//cout<<i<<" : "<<may[i][0]<<" "<<may[i][1]<<endl;
		}
	}
	num=may[x][0];
	for(int i=1;i<=siz;i++)
	{
		x=v[x];
		if(num==may[x][0])num=may[x][1];
		else num=may[x][0];
	}
	if(num==may[x][0])return 1;
	num=may[x][1];
	for(int i=1;i<=siz;i++)
	{
		x=v[x];
		if(num==may[x][0])num=may[x][1];
		else num=may[x][0];
	}
	if(num==may[x][1])return 1;
	return 0;
}

int main()
{
