int main() {
    int n;
    cin>>n;

    VI p(n,0);
    VVI q(n,VI{});
    for(ll i:R(n)){
        int j;
        cin >> j;
        p.at(i)=j-1;
        q.at(p.at(i)).push_back(i);
    }
    queue<int> que;
    VI a(n,-1);
    for(ll i:R(n)){
        if(q.at(i).size()==0){
            a.at(i)=0;
            que.push(p.at(i));
        }
    }

    while(que.size()){
        int i = que.front();
        que.pop();
        if(a.at(i)>=0) continue;
        set<int> s;
        bool ng=false;
        for(int j:q.at(i)){
            if(a.at(j)<0) ng=true;
            s.insert(a.at(j));
        }
        if(ng) continue;
        int g=0;
        while(s.count(g)) g++;
        a.at(i)=g;
        que.push(p.at(i));
    }

    int loop_start;
    for(ll i:R(n)){
        if(a.at(i)==-1) {
            loop_start=i;
            break;
        }
    }
    int a_loop_start_1,a_loop_start_2;
    {
        set<int> s;
        for(ll i:q.at(loop_start)){
            s.insert(a.at(i));
        }
        a_loop_start_1=0;
        while(s.count(a_loop_start_1)) a_loop_start_1++;
        a_loop_start_2 = a_loop_start_1+1;
        while(s.count(a_loop_start_2)) a_loop_start_2++;
    }


    auto func = [&](int a_loop_start){
        a.at(loop_start)=a_loop_start;
        int next=p.at(loop_start);
        while(next!=loop_start){
            set<int> s;
            for(ll i:q.at(next)){
                s.insert(a.at(i));
            }
            int g=0;
            while(s.count(g)) g++;
            a.at(next)=g;
            next=p.at(next);
        }
        set<int> s;
        for(ll i:q.at(loop_start)){
            s.insert(a.at(i));
        }
        int g=0;
        while(s.count(g)) g++;
        return g==a.at(loop_start);
    };


    if(func(a_loop_start_1)) cout<<"POSSIBLE"<<endl;
    else if(func(a_loop_start_2)) cout<<"POSSIBLE"<<endl;
    else cout<<"IMPOSSIBLE"<<endl;

    return 0;
}

