int n,cnt,last[N],p[N],sg[N],p1,p2,deg[N];
bool vis[N],arr[N];
struct edge{int to,next;bool del;}e[N];

int read()
{
	int x=0,f=1;char ch=getchar();
	while (ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
	while (ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
	return x*f;
}

void addedge(int u,int v)
{
	e[++cnt].to=v;e[cnt].next=last[u];last[u]=cnt;
}

int get_mex(int x)
{
	int ans;
	for (int i=last[x];i;i=e[i].next) if (!e[i].del) vis[sg[e[i].to]]=1;
	for (int i=0;;i++) if (!vis[i]) {ans=i;break;}
	for (int i=last[x];i;i=e[i].next) if (!e[i].del) vis[sg[e[i].to]]=0;
	return ans;
}

void dfs(int x)
{
	arr[x]=1;
	for (int i=last[x];i;i=e[i].next)
		if (!arr[e[i].to]) dfs(e[i].to);
		else if (deg[e[i].to]) p1=x,p2=e[i].to,e[i].del=1;
	sg[x]=get_mex(x);
}

int main()
{
	n=read();
	for (int i=1;i<=n;i++) p[i]=read(),addedge(p[i],i),deg[p[i]]++;
	for (int i=1;i<=n;i++) if (!arr[i]) dfs(i);
	int s1=get_mex(p1);
	vis[s1]=1;
	int s2=get_mex(p1);
	vis[s1]=0;
	if (sg[p2]!=s1) {puts("POSSIBLE");return 0;}
	sg[p[1]]=s2;
	int x=p1;
	while (x!=p2) x=p[x],sg[x]=get_mex(x);
	if (sg[1]==s1) puts("POSSIBLE");
	else puts("IMPOSSIBLE");
	return 0;
}

