    rep(i, N) if(!used[i]) dfs(i);
    fill(used, used+N, false);
    int k = 0;
    rep3(i, vs.size()-1, 0){
        int e = vs[i];
        if(!used[e]) rdfs(e, k++);
    }
}


//vに含まれない最小の非負整数
int calc(vector<int> v){
    int n = v.size();
    bool Used[n];
    fill(Used, Used+n, false);
    for(auto &e: v) if(e < n) Used[e] = true;
    rep(i, n) if(!Used[i]) return i;
    return n;
}

//有向木におけるgrundy数を求める
int grundy(int now){
    vector<int> v;
    for(auto &e: es[now]) if(topo[e]) v.pb(grundy(e));
    return calc(v);
}

