    cin >> n;
    for (int i = 1; i <= n; i++){
        int u, v;
        cin >> u;
        v = i;
        g[v].pb(u);
        g[u].pb(v);
        G[u].pb(v);
        if (ff[{v, u}]){
            cycle[v] = 1;
            cycle[u] = 1;
        }
        ff[{u, v}] = 1;
        in[v].pb(u);
        deg[u]++;
    }
    dfs1(1);
    for (int i = 1; i <= n; i++) if (cycle[i]) dfs2(i);
    for (int i = 1; i <= n; i++){
        if (cycle[i]){
            vector < int > cand;
            for (auto j: c[i]) b[j] = 1;
            for (int j = 0; j <= n + 5; j++) if (b[j] == 0) cand.pb(j);
            tr(i, cand[0]);
            tr(i, cand[1]);
