void dfs(const vector<vint>& G,int v){
  if(visit[v]) return;
  visit[v]=true;
  set<int> st;
  for(int u:G[v]){
    dfs(G,u);
    st.insert(a[u]);
  }
  a[v]=0;
  while(st.count(a[v]++));
  a[v]--;
}

