struct Node{
    vector<Node*> dests;
    void add(Node* n){
        dests.push_back(n);
    }
    bool dfs(vector<Node*>& cand, unordered_set<Node*>& visited, Node* start, Node* from = nullptr){
        if(this == start && from){
            return true;
        }
        cand.push_back(this);
        for(Node* d : dests){
            if(d == from){ continue; }
            if(d -> dfs(cand, visited, start, this)){
                return true;
            }
        }
        cand.pop_back();
        return false;
    }
    int dfs2(Node* from, Node* start){
        int ret = 1;
        if(this == start){ return 0; }
        for(Node* d : dests){
            if(d == from){ continue; }
            ret += d->dfs2(this, start);
        }
        return ret;
    }
};

int main(){
    int n; cin >> n;
    // vector<int> ps(n);
    vector<Node> nodes(n);
    for(int i = 0; i < n; i++){
        // cin >> ps[i];
        int p; cin >> p;
        p--;
        nodes[p].add(&nodes[i]);
    }
    unordered_set<Node*> visited;
    vector<Node*> cand;
    for(int i = 0; i < n; i++){
        cand.clear();
        if(nodes[i].dfs(cand, visited, &nodes[i])){
            break;
        }
        visited.insert(&nodes[i]);
    }
    if(cand.size() % 2 == 1){
        bool ok = false;
        for(int i = 0; i < cand.size(); i++){
            if(cand[i]->dests.size() == 0){ return 1; }
            if(cand[i]->dests.size() == 1 && cand[(i + 1) % cand.size()]->dests.size() >= 2){
                ok = true;
                break;
            }
            if(cand[(i + 1) % cand.size()]->dests.size() >= 2){
                if(cand[i]->dests.size() == 1){
                    ok = true;
                    break;
                }else{
                    bool ok2 = true;
                    for(Node* dest : cand[i]->dests){
                        ok2 &= dest->dfs2(cand[i], cand[i]) % 2 == 0;
                    }
                    if(ok2){
                        ok = true;
                        break;
                    }
                }
            }
        }
        if(!ok){
            cout << "IMPOSSIBLE" << '\n';
            return 0;
        }
    }
    cout << "POSSIBLE" << '\n';
    return 0;
}

