/// --- Lowlink Library {{{ ///

// undirected graph
// count edges
// construct : (int size)
// do : calc()
struct Lowlink {
  struct Edge {
    int to, idx;
    Edge(int to, int idx): to(to), idx(idx) {}
  };
  int size;
  int edgeSize = 0;
  vector< vector< Edge > > g;
  VI ord, low;

  VI used;
  VI isBridge, isArticulation;
  Lowlink(int n): size(n), g(n), ord(n), low(n) {}

  void addEdge(int a, int b) {
    g[a].emplace_back(b, edgeSize);
    g[b].emplace_back(a, edgeSize);
    edgeSize++;
  }

  void calc() {
    used.assign(size, 0);
    isBridge.assign(edgeSize, 0);
    isArticulation.assign(size, 0);

    int k = 0;
    dfs(0, -1, k);
  }

  // p just means "just before"
  private :
  void dfs(int i, int p, int &k) {
    used[i] = 1;
    ord[i]=low[i]=k++;
    isArticulation[i] = 0;
    int DFSTreeDegree = 0;
    for(Edge edge : g[i]) {
      int j = edge.to;
      int idx = edge.idx;
      if(used[j]) {
        if(j != p) {
          // back edge
          smin(low[i], ord[j]);
        }
      } else {
        // on dfs-tree
        DFSTreeDegree++;
        dfs(j, i, k);
        smin(low[i], low[j]);
        isBridge[idx] = ord[i] < low[j];
        if(p != -1 && ord[i] <= low[j]) {
          isArticulation[i] = 1;
        }
      }
    }
    if(p == -1 && DFSTreeDegree > 1) {
      isArticulation[i] = 1;
    }
  }
};

/// }}}--- ///

int n=ini;
Lowlink lowlink(n);
VI onCircuit(n, 0);
VI used(n, 0);
VVI orig(n);
VI rev(n);
VI num(n, 0);

void dfs(int i) {
  if(onCircuit[i]) return;
  if(used[i]) return;
  used[i] = 1;
  set<int> st;
  for(int j : orig[i]) {
    assert(onCircuit[j] == false);
    dfs(j);
    st.insert(num[j]);
  }
  int t=0;
  while(st.count(t)) t++;
  num[i] = t;
}

bool solve(int now) {
  int last = now;
  now = rev[now];
  while(1) {
    set<int> st;
    for(int j:orig[now]) {
      st.insert(num[j]);
    }
    int nnum = 0;
    while(st.count(nnum)) nnum++;
    if(num[now] <= nnum) {
      if(num[now] == nnum) {
        if(last == now) {
          return 1;
        }
      } else {
        num[now] = nnum;
        last = now;
      }
    } else {
      return 0;
    }
    now = rev[now];
  }
}

int main() {
  REP(i, n) {
    int p = ini-1;
    // p -> i
    lowlink.addEdge(p, i);
    orig[p].PB(i);
    rev[i] = p;
  }
  lowlink.calc();

  REP(i, n) {
    for(auto edge : lowlink.g[i]) {
      int j = edge.to, idx = edge.idx;
      if(!lowlink.isBridge[idx]) {
        onCircuit[i] = 1;
      }
    }
  }

  REP(i, n) dfs(i);

  int now=-1;
  REP(i, n) {
    if(onCircuit[i]) {
      now = i;
    }
  }
  assert(now != -1);
  if(solve(now)) cout << "POSSIBLE" << endl;
  REP(i, n) {
    if(onCircuit[i]) {
    }
  }
  if(solve(rev[now])) cout << "POSSIBLE" << endl;
  cout << "IMPOSSIBLE" << endl;
}

