const int maxN = 2e5 + 7;

template<class T> inline T rd() {
	bool f = 1; char c = getchar(); for (; !isdigit(c); c = getchar()) if (c == '-') f = 0;
	T x = 0; for (; isdigit(c); c = getchar()) x = x * 10 + c - 48; return f ? x : -x;
}

inline void NIE() {puts("IMPOSSIBLE"); exit(0);}
inline void TAK() {puts("POSSIBLE"); exit(0);}

int n;
int bac[maxN], deg[maxN];
int val[maxN][2];
int lop[maxN], tl, vis[maxN];
bool f[maxN][2];

struct vec {
	static const int maxE = maxN;
	int g[maxN], te;
	struct edge {int y, nxt;} e[maxE << 1];
	inline void push(int x, int y) {e[++te] = (edge){y, g[x]}; g[x] = te;}
	inline void link(int x, int y) {push(x, y), push(y, x);}
	inline int& operator () (int x) {return g[x];}
	inline edge& operator [] (int x) {return e[x];}
}e;

void topu() {
	static int q[maxN]; int h = 0, t = 0;
	rep (i, 1, n) if (deg[i] == 0) q[++t] = i;
	while (h != t) {
		int x = q[++h], y = bac[x];
		if (--deg[y] == 0) q[++t] = y;
	}
	rep (i, 1, n) if (deg[i]) {
		lop[tl = 1] = i;
		for (int x = bac[i]; x != i; x = bac[x]) lop[++tl] = x;
		rep (i, 1, tl) vis[lop[i]] = 1;
		break;
	}
}

void dfs(int x, int fa) {
	static int q[maxN];
	int tq = 0;
	fore (e, x, y) if (y != fa && !vis[y]) {
		dfs(y, x);
		q[++tq] = val[y][0];
	}
	sort(q+1, q+tq+1);
	tq = unique(q+1, q+tq+1) - (q+1);
	for (int cur = 0, i = 1; ; ++ cur) {
		if (i <= tq && q[i] == cur) {++ i; continue;}
		if (val[x][0] == -1) val[x][0] = cur;
		else if (val[x][1] == -1) {val[x][1] = cur; break;}
	}
}

bool ok(int x, int y, int kd) {
	if (kd == 1) {
		if (val[x][0] == val[y][0] && f[x][0]) return 1;
		if (val[x][1] == val[y][0] && f[x][1]) return 1;
	}
	else {
		if (val[x][0] != val[y][0] && f[x][0]) return 1;
		if (val[x][1] != val[y][0] && f[x][1]) return 1;
	}
	return 0;
}

int main() {

	n = ri();
	memset(val, -1, sizeof vis);
	rep (i, 1, n) {
		int x = ri();
		e.push(x, i);
		bac[i] = x;
		deg[x]++;
	}
	topu();
	rep (i, 1, tl) dfs(i, 0);

	f[1][0] = 1, f[1][1] = 0;
	rep (i, 2, tl) {
		f[i][0] = ok(i-1, i, 0);
		f[i][1] = ok(i-1, i, 1);
	}
	if (ok(tl, 1, 0)) TAK();

	f[1][0] = 0, f[1][1] = 1;
	rep (i, 2, tl) {
		f[i][0] = ok(i-1, i, 0);
		f[i][1] = ok(i-1, i, 1);
	}
	ok(tl, 1, 1) ? TAK() : NIE();

	return 0;
}

