        Q.push(i);        
    }
    vec<int> vis(N,0);

    if(Q.empty()){
        cout << (N%2? "IMPOSSIBLE":"POSSIBLE") << endl;
        return 0;
    }

    while(!Q.empty()){
        int cur = Q.front(); Q.pop();
        int n = 0;
        vis[cur] = 1;
        while(vs[cur].count(n)) n++;
        num[cur] = n;
