            s = i;
            int n = 0;
            while(vs[i].count(n)) n++;
            X[i].push_back(n);
            n++;
            while(vs[i].count(n)) n++;
            X[i].push_back(n);
        }
    }
    int now = s;
    dp[s][0][0] = dp[s][1][1] = true;
