        for(int k=0;k<2;k++){
            if(X[ne][0]!=X[now][0]) dp[ne][0][k] |= dp[now][0][k];
            if(X[ne][0]!=X[now][1]) dp[ne][0][k] |= dp[now][1][k];
            if(X[ne][0]==X[now][0]) dp[ne][1][k] |= dp[now][0][k];
            if(X[ne][0]==X[now][1]) dp[ne][1][k] |= dp[now][1][k];
        }
        now = ne;
    }
    bool ok = false;
//    cerr << dp[e][0][0] << " " << dp[e][0][1] << " " << dp[e][1][0] << " " << dp[e][1][1] << endl;
