bool DFS(int u){
	vis[u] = true;
	sta.push_back(u);
	for (auto &x: E[u]){
		if (mark[x.nd])
			continue;

		mark[x.nd] = true;
		int v = x.st;
		eput(u, v);
		if (vis[v]){
			for (; sta.back() != v; sta.pop_back())
				cir.push_back(sta.back());
			cir.push_back(v);
			return true;
		}
		if (DFS(v))
			return true;
	}
	sta.pop_back();
	return false;
}

void DFS1(int u){
	vis[u] = true;

	vector<int> son;
	for (auto &x: E[u]){
		int v = x.st;
		if (vis[v])
			continue;
		DFS1(v);
		son.push_back(val[v]);
	}
	sort(all(son));
	for (int &i = val[u] = 0; i < son.size() && son[i] == i; ++i);
}

