using namespace std;
typedef long long ll;
#define mp make_pair

const int N = 2e5 + 10;
vector<int> graph[N];
int prv[N];
bool tmp[N];
bool used[N];
int res[N];

void rebuild(int v) {
	fill(tmp, tmp + graph[v].size(), false);
	for (int u : graph[v]) 
		tmp[res[u]] = true;
	for (int i = 0; i < (int)graph[v].size(); i++)
		if (!tmp[i]) {
			res[v] = i;
			return;
		}
	res[v] = (int)graph[v].size();
}

void dfs(int v) {
	if (used[v])
		return;
	used[v] = true;
	for (int u : graph[v])
		dfs(u);
	rebuild(v);
}

