		a--;
		prv[i] = a;
		graph[a].push_back(i);
	}
	for (int i = 0; i < n; i++)
		dfs(i);
	int v = -1;
	for (int i = 0; i < n; i++) {
		if (res[prv[i]] == res[i]) {
			v = i;
			continue;
		}
	}
	if (v == -1) {
		cout << "POSSIBLE" << endl;
		return 0;
	}
	int st = v;
	int cnt = 0;
	do {
		rebuild(prv[v]);
		v = prv[v];
		if (res[v] != res[prv[v]]) {
			cout << "POSSIBLE" << endl;
			return 0;
		}
		if (v == st)
			cnt++;
	} while (cnt < 3);
	cout << "IMPOSSIBLE" << endl;
	return 0;
}

