const int INF = 1<<28;
const double EPS = 1e-8;
const int MOD = 1000000007;


int T, n, m;

vector<vi> g;

bool check(vector<set<int>> s, vi color, int u, int c){
	int v = g[u][0];
	color[u] = c;
	if(color[u] == color[v]){
		return false;
	}
	s[v].erase(color[u]);
	u = v;

	while(color[u] == -1){
		int v = g[u][0];
		color[u] = *s[u].begin();
		if(color[u] == color[v]){
			return false;
		}
		s[v].erase(color[u]);
		u = v;
	}
	if(color[u] != *s[u].begin()) return false;
	return true;
}

bool solve(){
	cin >> n;
	g.resize(n);
	vi deg(n);
	vector<set<int>> s(n);
	REP(i, n) s[i].insert(0);
	REP(i, n) s[i].insert(1);
	REP(v, n){
		int u;
		cin >> u; u--;
		g[v].pb(u);
		deg[u] ++;
		int t = s[u].size();
		s[u].insert(t);
	}
	vi color(n, -1);
	queue<int> q;
	REP(i, n)if(deg[i] == 0){
		q.push(i);
	}
	while(!q.empty()){
		int u = q.front(); q.pop();
		color[u] = *s[u].begin();
		for(int v : g[u]){
			if(-- deg[v] == 0) q.push(v);
			s[v].erase(color[u]);
		}
	}
	int u = -1;
	REP(v, n)if(u == -1 || (deg[v] && *s[u].begin() < *s[v].begin())) u = v;
	auto it = s[u].begin();
	if(check(s, color, u, *it)) return true;
	if(check(s, color, u, *(++it))) return true;

	return false;
}

int main(int argc, char *argv[]){
	ios::sync_with_stdio(false);
	cout << (solve() ? "POSSIBLE" : "IMPOSSIBLE") << endl;
	return 0;
}

