ll V, p;
vector<ll> G[200000];
vector<ll> rG[200000];
vector<ll> vs;
bool used[200000];
ll cmp[200000];

void add_edge(ll from, ll to) {
  G[from].push_back(to);
  rG[to].push_back(from);
}

void dfs(ll v) {
  used[v] = true;
  for (ll i = 0; i < G[v].size(); i++) {
    if (!used[G[v][i]]) dfs(G[v][i]);
  }
  vs.push_back(v);
}

void rdfs(ll v, ll k) {
  used[v] = true;
  cmp[v] = k;
  for (ll i = 0; i < rG[v].size(); i++) {
    if (!used[rG[v][i]]) rdfs(rG[v][i], k);
  }
}

ll scc() {
  memset(used, 0, sizeof(used));
  vs.clear();
  for (ll v = 0; v < V; v++) {
    if (!used[v]) dfs(v);
  }
  memset(used, 0, sizeof(used));
  ll k = 0;
  for (ll i = vs.size() - 1; i >= 0; i--) {
    if (!used[vs[i]]) rdfs(vs[i], k++);
  }
  return k;
}

ll counter[200001], c2[200001];

ll dfs2(ll num, ll t) {
  if (t == 1) {
    if (G[num].size() <= 1) return 0;
    if (cmp[G[num][0]] == cmp[num]) return dfs2(G[num][1], 0) + 1;
    return dfs2(G[num][0], 0) + 1;
  }
  if (G[num].size() == 0) return 0;
  return dfs2(G[num][0], 0) + 1;
}

int main() {
  scanf("%lld", &V);
  for (ll i = 0; i < V; i++) scanf("%lld", &p), add_edge(p-1, i);
  scc();
  for (ll i = 0; i < V; i++) counter[cmp[i]]++;
  ll mx = 0, num;
  for (ll i = 0; i < V; i++) if (counter[i] > mx) mx = counter[i], num = i;
  if (mx % 2 == 0) {
    bool ok = true, ok2 = true;
    ll now = 1, now2 = -1;
    while (c2[num] == 0) {
      c2[num] = 1;
      ll t = dfs2(num, 1);
