void findCycle()
{
    int x = 1;
    while (!vis[x])
    {
        vis[x] = 1;
        x = p[x];
    }
    head = x;
    do
    {
        onCycle[x] = 1;
        x = p[x];
    }
    while (head != x);
    memset(vis, 0, sizeof(vis));
}

int Mex(int x, int i)
{
    sort(V[x].begin(), V[x].end(), cmp);
    if (V[x].empty() || i > V[x].size())
        return 0;
    if (a[V[x][i - 1]] > 0)
        return 0;
    for (; i < V[x].size(); ++ i)
        if (a[V[x][i]] != a[V[x][i - 1]] + 1)
            return a[V[x][i - 1]] + 1;

    return a[V[x].back()] + 1;
}
void dfs(int x)
{
    vis[x] = 1;
    for (int son : V[x])
        if (!vis[son])
            dfs(son);

    a[x] = Mex(x, 1);
}
