int calcgrundy(int now, bool rec)
{
    set<int> gr_lst;
    for (auto nxt : to[now])
    {
        if (grundy[nxt] < 0 && rec) grundy[nxt] = calcgrundy(nxt, rec);
        gr_lst.insert(grundy[nxt]);
    }
    int res = 0;
    while (gr_lst.find(res) != gr_lst.end()) res++;
    return res;
}

