using namespace std;

const int MAXN = 200001;

int n;
int p[MAXN];
vector<int> nxt[MAXN];
vector<int> cycle;

int vis[MAXN];
void find_cycle(int v) {
	vis[v] = 1;
	for(int w : nxt[v]) {
		if(vis[w] == 1) {
			cycle.push_back(w);
		}	
		if(!vis[w]) find_cycle(w);
	}
	vis[v] = 2;
}

bool marked[MAXN];
int mark[MAXN];
bool in_cycle[MAXN];

void build(int v) {
	set<int> used;
	for(int w : nxt[v]) {
		if(in_cycle[w]) continue;
		build(w);
		used.insert(mark[w]);
	}		
	for(int x = 0;; x++) {
		if(used.find(x) == used.end()) {
			mark[v] = x;
			break;
		}
	}
	marked[v] = used.size() > 0;
}



int main() {

	cin >> n;
	for(int i = 1; i <= n; i++) {
		cin >> p[i];
		nxt[p[i]].push_back(i);
	}

	for(int v = 1; v <= n; v++) {
		if(!vis[v]) find_cycle(v);
	}

	in_cycle[cycle[0]] = 1;

	for(int i = 0; i < (int)cycle.size(); i++) {
		int pv = p[cycle[i]];
		if(pv != cycle[0]) {
			cycle.push_back(pv);
			in_cycle[pv] = 1;
		}
	}

	for(int v : cycle) {
		build(v);
	}

	int m = cycle.size();
	for(int i = 0; i < m; i++) cycle.push_back(cycle[i]);

	int pv = 0;
	for(int v : cycle) {
		if(marked[v]) pv = v;
	}

	if(!pv && (n&1)) {
		cout << "IMPOSSIBLE\n";
		return 0;
	}

	int v = p[pv];
	for(int i = 0; i < 3*m; i++) {
		int pmark = mark[v];
		set<int> used;
		for(int w : nxt[v]) used.insert(mark[w]);
		for(int x = 0;; x++) {
			if(used.find(x) == used.end()) {
				mark[v] = x;
				break;
			}
		}

		if(i > 2*m && mark[v] != pmark) {
			cout << "IMPOSSIBLE\n";
			return 0;
		}
		v = p[v];
	}


	cout << "POSSIBLE\n";

	return 0;
}

