const int MAX = 210000;
int N;
vector<int> G[MAX];

bool seen[MAX];
int grundy[MAX];

int thev = -1, thenum = -1;

bool lastcheck() {
	set<int> se;
	for (auto nv : G[thev]) {
		se.insert(grundy[nv]);
	}
	int res = 0;
	for (res = 0;; ++res) {
		if (!se.count(res)) break;
	}

	if (res == thenum) return true;
	else return false;
}

int rec(int v, bool up = false) {
  seen[v] = true;

  bool iscy = false;
  for (auto nv : G[v]) {
		if (grundy[nv] != -1) continue;
		if (seen[nv]) {
		 iscy = true;
		 continue;
		}
		rec(nv, up);
  }

  set<int> se;
  for (auto nv : G[v]) {
		if (grundy[nv] == -1 && seen[nv]) continue;
		se.insert(grundy[nv]);
  }
  int res = 0;
  for (res = 0;; ++res) {
		if (!se.count(res)) break;
  }

	if (iscy && up) {
		++res;
		for (;; ++res) {
			if (!se.count(res)) break;
		}
	}

	if (iscy) {
		thev = v;
		thenum = res;
	}

	//cout << v << ": " << res << endl;

	return grundy[v] = res;
}


