  while (cin >> N) {
	for (int i = 0; i < MAX; ++i) G[i].clear();
	for (int i = 0; i < N; ++i) {
	  int a;
	  cin >> a;
	  --a;
	  G[a].push_back(i);
	}
	bool res = false;

	memset(seen, 0, sizeof(seen));
	memset(grundy, -1, sizeof(grundy));
	thev = -1, thenum = -1;
	for (int v = 0; v < N; ++v) {
	  if (grundy[v] != -1) continue;
	  rec(v, false);
	}
	//COUT(thev);
	//COUT(thenum);
	if (lastcheck()) res = true;

	memset(seen, 0, sizeof(seen));
	memset(grundy, -1, sizeof(grundy));
	thev = -1, thenum = -1;
	for (int v = 0; v < N; ++v) {
	  if (grundy[v] != -1) continue;
	  rec(v, true);
	}
	//COUT(thev);
	//COUT(thenum);
	if (lastcheck()) res = true;

	if (res) cout << "POSSIBLE" << endl;
	else cout << "IMPOSSIBLE" << endl;
  }
}

