{
    //freopen("input.txt", "r", stdin);
    ios::sync_with_stdio(0);
    cin.tie(0);
    int n;
    cin >> n;
    int p[n], cnt[n] = {0};
    set<pair<int, int>> vrt;
    for(int i = 0; i < n; i++)
    {
        cin >> p[i];
        p[i]--;
        vrt.erase({cnt[p[i]], p[i]});
        cnt[p[i]]++;
        vrt.insert({cnt[p[i]], p[i]});
    }
    set<int> banned[n];
    while(begin(vrt)->first == 0)
    {
        int v = begin(vrt)->second;
        vrt.erase(begin(vrt));
        vrt.erase({cnt[p[v]], p[v]});
        cnt[p[v]]--;
        vrt.insert({cnt[p[v]], p[v]});
        banned[p[v]].insert(mex(banned[v]));
    }
    int m[n][2];
    for(auto it: vrt)
    {
        int v = it.second;
        m[v][0] = mex(banned[v]);
        banned[v].insert(m[v][0]);
        m[v][1] = mex(banned[v]);
    }
    for(auto it: vrt)
    {
        int v = it.second;
        int u = p[v];
        for(int z1 = 0; z1 <= 1; z1++)
            for(int z2 = 0; z2 <= 1; z2++)
                if(m[u][z1] == m[v][z2])
                {
                    add_edge(u, z1, v, !z2);
                    add_edge(v, z2, u, !z1);
                }
        if(m[u][0] == m[v][0])
        {
            add_edge(u, 1, v, 0);
        }
        else if(m[u][0] == m[v][1])
        {
            add_edge(u, 1, v, 1);
        }
        else
        {
            add_edge(u, 1, u, 0);
        }
    }
    try2sat();
}

