#define N 300000

int n,a[N],d[N],sg[N];
bool vis[N];
vector<int> vec[N];
queue<int> q;

void solve(int x){
	d[x]=0;
	for (int i:vec[x]) vis[i]=1;
	for (int i=0;vis[i];++i) sg[x]=i+1;
	for (int i:vec[x]) vis[i]=0;
	int y=a[x],z=x;
	for (;d[y];y=a[y],z=a[z]){
		for (int i:vec[y]) vis[i]=1;
		vis[sg[z]]=1;
		for (int i=0;vis[i];++i) sg[y]=i+1;
		for (int i:vec[y]) vis[i]=0;
		vis[sg[z]]=0;
	}
	if (sg[x]!=sg[z]) return;
	int t=sg[x]; sg[x]=t+1;
	for (int i:vec[x]) vis[i]=1;
	for (int i=t+1;vis[i];++i) sg[x]=i+1;
	for (int i:vec[x]) vis[i]=0;
	y=a[x],z=x;
	for (;d[y];y=a[y],z=a[z]){
		for (int i:vec[y]) vis[i]=1;
		vis[sg[z]]=1;
		sg[y]=0;
		for (int i=0;vis[i];++i) sg[y]=i+1;
		for (int i:vec[y]) vis[i]=0;
		vis[sg[z]]=0;
	}
	if (sg[z]==t) return;
	puts("IMPOSSIBLE");
	exit(0);
}

int main(){
	scanf("%d",&n);
	for (int i=1;i<=n;++i){
		scanf("%d",a+i);
		++d[a[i]];
	}
	for (int i=1;i<=n;++i)
		if (!d[i]) q.push(i);
	while (!q.empty()){
		int x=q.front(); q.pop();
		for (int i:vec[x]) vis[i]=1;
		for (int i=0;vis[i];++i) sg[x]=i+1;
		for (int i:vec[x]) vis[i]=0;
		vec[a[x]].push_back(sg[x]);
		if (!(--d[a[x]])) q.push(a[x]);
	}
	for (int i=1;i<=n;++i)
		if (d[i]){
			solve(i);
			break;
		}
	puts("POSSIBLE");

	return 0;
}

