void grundy(int x, bool isrt, int nxt){
	mark++;
	for (int p = ghead[x]; p; p = g[p].nxt){
		int v = g[p].to; if (v == nxt) continue;
		grundy(v, 0, nxt); vis[mex[v]] = mark;
	}
	int pos = 0;
	for (; vis[pos] == mark; pos++); mex[x] = pos;
	if (isrt){
		candidates[x].x = pos; 
		for (++pos; vis[pos] == mark; ++pos); 
		candidates[x].y = pos;
	}
}
bool verify(){
	for (int i = 0; i < (int)cir.size() - 1; ++i){
		int u = cir[i]; mark++;
		for (int p = ghead[u]; p; p = g[p].nxt)
			vis[mex[g[p].to]] = mark;
		int pos = 0; for (; vis[pos] == mark; pos++); mex[u] = pos;
	}
	int u = *(cir.end() - 1); mark++;
	for (int p = ghead[u]; p; p = g[p].nxt)
		vis[mex[g[p].to]] = mark;
	int pos = 0; for (; vis[pos] == mark; pos++); return pos == mex[u];
}

