	read(n);
	rep(i, 1, n) read(x), add(x, i);
	rep(i, 1, n) if (!vis[i]) mark++, dfs(i);
//	for (int i = 0; i < cir.size(); ++i)
//		cerr << cir[i] << ' '; puts("");
	if (!cir.size()) return 0 * puts("POSSIBLE");
	for (int i = 0; i < cir.size(); ++i)
		grundy(cir[i], 1, cir[(i+cir.size()-1)%cir.size()]);
	mex[*(cir.end() - 1)] = candidates[*(cir.end() - 1)].x;
	if (verify()) return 0 * puts("POSSIBLE");
	mex[*(cir.end() - 1)] = candidates[*(cir.end() - 1)].y;
	if (verify()) return 0 * puts("POSSIBLE");
	puts("IMPOSSIBLE");
	return 0;
}

