struct edge{int to, cost;};

class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vec g;
    bools is_loop;

    Graph(int N): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
        g = vec(N, -1);
        is_loop = bools(N, false);
    }

    void add_edge(int from, int to, int cost = 0){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost = 0){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    //SCC decomposition
    void dfs(int v, vector<bool> &used, vec &vs){
        used[v] = true;
        REP(i, G[v].size()){
            if(!used[G[v][i].to]) dfs(G[v][i].to, used, vs);
        }
        vs.push_back(v);
    }
    void rdfs(int v, int k, vector<bool> &used, vec &cmp){
        used[v] = true;
        cmp[v] = k;
        REP(i, G[v].size()){
            if(!used[G[v][i].to]) rdfs(G[v][i].to, k, used, cmp);
        }
    }
    vec scc(int &k){
        vector<bool> used(N, false);
        vec vs(0), cmp(N);
        REP(i, N){
            if(!used[i]) dfs(i, used, vs);
        }
        //reverse graph
        Graph rG(N);
        REP(v, N) REP(i, G[v].size()) rG.add_edge(G[v][i].to, v, G[v][i].cost);

        fill(used.begin(), used.end(), false);
        k = 0;
        IREP(i, vs.size()){
            if(!used[vs[i]]) rG.rdfs(vs[i], k++, used, cmp);
        }
        return cmp;
    }

    void dfs(int v){
        set<int> s;
        for(auto e: G[v]) if(!is_loop[e.to]) {
            dfs(e.to);
            s.insert(g[e.to]);
        }
        int tmp = 0;
        for(int i: s){
            if(tmp != i){
                g[v] = tmp;
                break;
            }else tmp++;
        }
        if(g[v] == -1) g[v] = tmp;
    }

};

signed main(){

    int N; cin >> N;
    Graph G(N);
    vec p(N); cin >> p;
    REP(i, N){
        p[i]--;
        G.add_edge(p[i], i);
    }

    int k;
    vec cmp = G.scc(k);
    vec cnt(k, 0);
    REP(i, N){
        cnt[cmp[i]]++;
        if(cnt[cmp[i]] >= 2) k = cmp[i];
    }
    vec loop;
    REP(i, N) if(cmp[i] == k){
        loop.pb(i);
        G.is_loop[i] = true;
    }
    //vdebug(loop);
    for(int v: loop) G.dfs(v);

    int S = loop[0];
    bool ans = false;
    //そのまま
    int v = p[S], w = S;
    vec g = G.g;
    while(v != S){
        if(g[v] == g[w]) g[v]++;
        w = v; v = p[v];
    }
    if(g[S] != g[w]) ans = true;
    //+1
    v = p[S], w = S;
    g = G.g;
    g[S]++;
    while(v != S){
        if(g[v] == g[w]) g[v]++;
        w = v; v = p[v];
    }
    if(g[S] == g[w] + 1) ans = true;
    Ans(ans, "POSSIBLE", "IMPOSSIBLE");

    return 0;
}

