            for(int j=0;;j++){if(S[i].count(j)==0){s.F=j; break;}}
            for(int j=(int)s.F+1;;j++){if(S[i].count(j)==0){s.S=j; break;}}
            pll now=s;
            ll w=edge[i][0];
            while(w!=i){
                for(int j=0;;j++){if(S[w].count(j)==0 && j!=now.F){now.F=j; break;}}
                for(int j=0;;j++){if(S[w].count(j)==0 && j!=now.S){now.S=j; break;}}
                for(auto &I:edge[w]){w=I;}
            }
            if(now.F==s.F && now.S==s.S){cout<<"IMPOSSIBLE"<<endl;}
            else{cout<<"POSSIBLE"<<endl;}
            return 0;
        }
    }
    cout<<"POSSIBLE"<<endl;


    return 0;
}

#include <algorithm>
