  for(auto i=0; i<N; ++i) {
    int p;
    cin >> p;
    G[p-1].emplace_back(i);
  }

  vector<int> A;

  function<int(int, int)> dfs = [&](auto u, auto d) {
    if(A[u]!=-1) return A[u];
    A[u] = N;
    set<int> S;
    for(auto v: G[u]) S.emplace(dfs(v, d));
    for(auto i=0; i<N; ++i) if(!S.count(i)) if(!S.count(N) || d--==0) return A[u] = i;
  };

