    }
    return true;
  };

  for(auto d: {0, 1}) {
    A.assign(N, -1);
    for(auto v=0; v<N; ++v) dfs(v, d);
    if(ok()) return "POSSIBLE";
  }
  return "IMPOSSIBLE";
}

