//---------------------------------//

int N;
vector<int> g[212345], rg[212345];
vector<int> sinc[212345];
bool done[212345], cycle[212345];
vector<int> vs;
int an;
int num[212345], tmp[212345];

void dfs(int v) {
	done[v] = true;
	REP(i, g[v].size()) if (!done[g[v][i]]) dfs(g[v][i]);
	vs.push_back(v);
}

void rdfs(int v, int k) {
	done[v] = true;
	sinc[k].push_back(v);
	REP(i, rg[v].size()) if (!done[rg[v][i]]) rdfs(rg[v][i], k);
}

void scc() {
	REP(i, N) if (!done[i]) dfs(i);

	memset(done, 0, sizeof(done));

	an = 0;
	for (int i = (int)vs.size() - 1; i >= 0; i--) {
		if (!done[vs[i]]) rdfs(vs[i], an++);
	}
}

// 閉路頂点st, a_st = kとする
bool solve(int st, int k) {
	num[st] = k;

	queue<int> que;
	que.push(rg[st][0]);

	while (!que.empty()) {
		int u = que.front(); que.pop();

		set<int> ss;
		REP(i, g[u].size()) ss.insert(num[g[u][i]]);
		int g = 0;
		while (ss.find(g) != ss.end()) g++;

		if (num[u] != -1) return num[u] == g;

		num[u] = g;
		que.push(rg[u][0]);
	}

	return true;
}

int main() {
	cin >> N;
	REP(i, N) {
		int p; scanf("%d", &p);
		p--;
		g[p].push_back(i);
		rg[i].push_back(p);
	}

	scc();

	REP(i, an) if (sinc[i].size() > 1) {
		REP(j, sinc[i].size()) {
			cycle[sinc[i][j]] = true;
		}
	}

	memset(num, -1, sizeof(num));

	queue<int> que;
	REP(i, N) if (g[i].size() == 0) {
		num[i] = 0;
		if (!cycle[rg[i][0]]) que.push(rg[i][0]);
	}

	while (!que.empty()) {
		int u = que.front(); que.pop();

		set<int> ss;
		REP(i, g[u].size()) ss.insert(num[g[u][i]]);

		int g = 0;
		while (ss.find(g) != ss.end()) g++;

		if (!cycle[rg[u][0]]) que.push(rg[u][0]);
	}


	int v = -1;
	REP(i, N) if (cycle[i]) { v = i; break; }

	set<int> ss;
	REP(i, g[v].size()) {
		int to = g[v][i];
		if (!cycle[to]) ss.insert(num[g[v][i]]);
	}

	copy(num, num + N, tmp);

	bool ans = false;

	int g = 0;
	while (ss.find(g) != ss.end()) g++;
	ans |= solve(v, g);

	g++;

	copy(tmp, tmp + N, num);
	while (ss.find(g) != ss.end()) g++;
	ans |= solve(v, g);

	puts(ans ? "POSSIBLE" : "IMPOSSIBLE");

	return 0;
}

