typedef long long ll;

const ll INF = 1e9, MOD = 1e9 + 7, MOD2 = 1e6 + 3;

vector <int> g[1000000], cycle[1000000];

int p[1000000], n, cl[1000000], u[1000000], in[1000000];

int d[1000000], d_sec[1000000];

int dfs (int x, int p) {
	if (g[x].size() == 0 || d[x]) return d[x];

	vector <int> v;
	for (int to : g[x])
		if (to != p && !in[to])
			v.push_back(dfs (to, x));

	sort (v.begin(), v.end());
	v.push_back(INF);

	if (v[0] || v.empty()) d[x] = 0;
	else {
		for (int i = 0; i < v.size(); i++)
			if (v[i] + 1 != v[i+1]) {
				d[x] = v[i] + 1;
				break;
			}
	}

	return d[x];
}

int main () {
	cin >> n;

	for (int i = 0; i < n; i++) {
		scanf ("%d", &p[i]);
		p[i]--;

		g[p[i]].push_back(i);
	}

	int color = 0;

	for (int i = 0; i < n; i++) {
		int x = i;

		while (!cl[p[x]]) {
			cl[p[x]] = i + 1;
			x = p[x];
		}

		if (cl[p[x]] == i + 1) {
			cycle[color].push_back(p[x]);
			in[p[x]] = 1;

			int k = p[x];

			while (k != x) {
				k = p[k];
				cycle[color].push_back(k);
				in[k] = 1;
			}
		}
	}

	for (int i = 0; i < n; i++)
		dfs(i, p[i]);

	for (int i = 0; i < n; i++)
		if (in[i]) {
			vector <int> v;

			for (int to : g[i]) 
				if (!in[to]) {
					v.push_back(d[to]);
				}

			v.push_back(d[i]);
			v.push_back(INF);

			sort (v.begin(), v.end());

			if (v[0] || v.empty()) d_sec[i] = 0;
			else {
				for (int j = 0; j < v.size() - 1; j++)
					if (v[j] + 1 != v[j+1])	{
						d_sec[i] = v[j] + 1;
						break;
					}
			}
		}

	for (int c = 0; c <= color; c++) {
		bool b1 = true, b2 = true;

		vector <int> t(cycle[c].size ());

		t[0] = d[cycle[c][0]];
		for (int i = 1; i < cycle[c].size(); i++) {
			if (t[i-1] == d[cycle[c][i]]) {
				t[i] = d_sec[cycle[c][i]];
			}
			else {
				t[i] = d[cycle[c][i]];
			}

			if (t[i-1] == t[i]) {
				b1 = false;
				break;
			}
		}


		if (t[0] == t.back()) b1 = false;

		t[0] = d_sec[cycle[c][0]];
		for (int i = 1; i < cycle[c].size(); i++) {
			if (t[i-1] == d[cycle[c][i]]) {
				t[i] = d_sec[cycle[c][i]];
			}
			else {
				t[i] = d[cycle[c][i]];
			}

			if (t[i-1] == t[i]) {
				b1 = false;
				break;
			}
		}

		if (t.back() != d[cycle[c][0]]) b2 = false;

		if (!b1 && !b2) {
			cout << "IMPOSSIBLE";
			return 0;
		}
	}

	cout << "POSSIBLE";
	return 0;
}

#include <bits/stdc++.h>
