#define X first
#define Y second

int top, cnt;
int sta[MAXN], SG[MAXN], q[MAXN];
bool instack[MAXN], vis[MAXN], circle[MAXN];
vector<int> E[MAXN];


void DFS(int x)
{
	sta[++top] = x;
	vis[x] = instack[x] = true;
	for (int i = 0; i < E[x].size(); ++i)
	{
		int y = E[x][i];
		if (!vis[y]) DFS(y);
		else if (instack[y])
		{
			for (int j = 1; j <= top; ++j)
				circle[q[j] = sta[j]] = true;
			cnt = top;
		}
	}
	instack[x] = false; --top;
}

void Calc_SG(int x, bool f)
{
	//cout << x << " " << f << endl;
	if (SG[x] != -1) return;
	for (int i = 0; i < E[x].size(); ++i)
	{
		int y = E[x][i];
		if (f && circle[y]) continue;
		//cout << x << " " << y << endl;
		Calc_SG(y, f);
		vis[SG[y]] = true;
	}

	SG[x] = 0;
	while (vis[SG[x]]) ++SG[x];

	for (int i = 0; i < E[x].size(); ++i)
	{
		int y = E[x][i];
		if (f && circle[y]) continue;
		vis[SG[y]] = false;
	}
}

bool Check(int N)
{
	for (int i = 1; i <= cnt; ++i)
		SG[q[i]] = -1;
	Calc_SG(q[1], 1);
	return 0;
	for (int i = cnt; i > 1; --i)
	 	Calc_SG(q[i], 0);

	for (int i = 0; i < E[q[1]].size(); ++i)
	{
		int y = E[q[1]][i];
		vis[SG[y]] = true;
	}
	if (!vis[SG[q[1]]]) return true;


	return 1;

	memset(vis, 0, sizeof(vis));
	for (int i = 1; i <= cnt; ++i)
		SG[q[i]] = -1;
	for (int i = 0; i < E[q[1]].size(); ++i)
	{
		int y = E[q[1]][i];
		if (circle[y]) continue;
		vis[SG[y]] = true;
	}

	SG[q[1]] = 0;
	while (vis[SG[q[1]]]) ++SG[q[1]];
	++SG[q[1]];
	while (vis[SG[q[1]]]) ++SG[q[1]];
	memset(vis, 0, sizeof(vis));


	for (int i = cnt; i > 1; --i)
		Calc_SG(q[i], 0);

	for (int i = 0; i < E[q[1]].size(); ++i)
	{
		int y = E[q[1]][i];
		vis[SG[y]] = true;
		//cout << y << " " <<SG[y] << endl;
	}
	int t = 0;
	while (vis[t]) ++t;
	return t == SG[q[1]];
}


