		if (!vis[i]) top = 0, DFS(i);

	memset(vis, 0, sizeof(vis));
	memset(SG, -1, sizeof(SG));
	for (int i = 1; i <= N; ++i)
		Calc_SG(i, 1);

	puts(Check(N)? "POSSIBLE":"IMPOSSIBLE");
	return 0;
}

