    cin >> N;
    for (int j = 0; j < N; ++j) {
        cin >> p[j]; --p[j];
        g[p[j]].push_back(j);
        rg[j].push_back(p[j]);
    }

    int start = -1;
    for (int j = 0; j < N; ++j) {
        if (g[j].size() > 0) {
            start = j;
            break;
        }
    }

    bool r = false;
    fill(a, a+N, -1);
    r = check(start, 1);
    if (!r) {
        fill(a, a+N, -1);
        r = check(start, (g[start].size() <= 1) ? 0 : 2);
    }
    cout << (r ? POSSIBLE : IMPOSSIBLE) << endl;
    return 0;
}

