#include <bits/stdc++.h>
using namespace std;
const int maxn = 2e5 + 10;
int n, rt = 1;
bool incir[maxn], vis[maxn];
int p[maxn];
vector<int> cir, E[maxn];
set<int> sg[maxn], tmp[maxn];
void dfs(int x)
{
	vis[x] = 1;
	for(auto v : E[x])
	{
		if(!vis[v])
			dfs(v);
		if(incir[v])
		{
			incir[x] = 1;
			cir.push_back(x);
		}
		else
			sg[x].erase(*sg[v].begin());
	}
}
void solve(int x)
{
	int m = cir.size();
	for(int i = 0; i < m; ++i) tmp[i] = sg[cir[i]];
	if(!tmp[0].count(x)) return;
	for(int i = 1; i < m; ++i) tmp[i].erase(i == 1 ? x : *tmp[i - 1].begin());
	tmp[0].erase(*tmp[m - 1].begin());
	if(*tmp[0].begin() != x) return;
	puts("POSSIBLE");
	exit(0); 
}
int main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i)
	{
		scanf("%d", &p[i]);
		E[p[i]].push_back(i);
		if(E[p[i]].size() > 1) rt = p[i];
		sg[i] = {0, 1, 2}; 
	}
	incir[rt] = 1;
	dfs(rt);
	for(int i = 0; i <= 2; ++i) solve(i);
	puts("IMPOSSIBLE");
	return 0;
}

