inline void dfs(int v)
{
	used[v] = 1;
	for(int to : g[v])
	{
		if(used[to] == 1)
		{
		   if(fnd ) continue;
		   fnd = 1;
			int x = v;
			while(x != to)
			{
				cycle[x] = 1;
				x = p[x];
			}	
			cycle[to] = 1;
		}
		else if(!used[to])
			dfs(to);
   }
   used[v] = 2;
}
int GOOD = 0;

inline void go(int v)
{
	vector<int> q;
	int son = 0;
	for(int to : g[v])
	{
		if(cycle[to] && !GOOD) 
		{
			son = to;
			continue;
		}
		q.pb(dp[to]);
	}
	if(cycle[v]) 
	{
		sort(q.begin(), q.end());
		int val = -1;
		if(!q.empty()) val = q.back();
		if(val + 1 < mn)
		{
			mn = val + 1;
			vertex = v;
		}
		return;
	}
	int cur = 0;
	sort(q.begin(), q.end());
	for(int i = 0; i < q.size(); ++i)
	{
		if(q[i] > cur)
		{
			dp[v] = cur;
			return;
		}
		if(q[i] == cur)
			cur++;
	}
	dp[v] = cur;
}
inline void check(int x)
{
