	vector<int> q;     
	for(int i = 0; i < g[x].size(); ++i)
		q.pb(dp[g[x][i]]);
	sort(q.begin(), q.end());
	for(int i = 0; i < q.size(); ++i)
	{
		if(q[i] > cur)
		{
			dp[x] = cur;
			return;
		}
		if(q[i] == cur)
			cur++;
	}
	if(ass[x] && dp[x] != cur)
	{
		cout << "IMPOSSIBLE";
		exit(0);
	}
	dp[x] = cur;
}

