#define ABS(a)		((a)>0?(a):-(a))
#define FOR(i,s,n)	for(int i=s;i<(int)n;++i)

int n;
vector<int> es[200000], esr[200000];

int cn;
vector<int> cy;

void cycle() {
	int v = 0;
	vector<int> temp;
	REP(i, n + 1) {
		temp.push_back(v);
		v = esr[v][0];
	}
	int t = temp[temp.size() - 1];
	cy.push_back(t);
	REP(i, n + 1) {
		int u = temp[temp.size() - 2 - i];
		cy.push_back(u);
		if (u == t) break;
	}
	cn = cy.size() - 1;
}

int gr[200000][2], cand[200000];

int dfs(int v, int u) {
	int candi = 0;
	REP(i, es[v].size()) if (es[v][i] != u) cand[candi++] = dfs(es[v][i], -1);
	sort(cand, cand + candi);
	gr[v][0] = 0;
	REP(i, candi) {
		if (cand[i] == gr[v][0]) ++gr[v][0];
		else if (cand[i] > gr[v][0]) {
			gr[v][1] = gr[v][0] + 1;
			FOR(j, i, candi) {
				if (cand[j] == gr[v][1]) ++gr[v][1];
				else if (cand[i] > gr[v][1]) break;
			}
			break;
		}
	}
	if (gr[v][1] <= gr[v][0]) gr[v][1] = gr[v][0] + 1;
	return gr[v][0];
}

int arr[200001];
int assign[200000];

bool solve(int gri) {
	arr[cn] = gr[cy[0]][gri];
	REP(i, cn) {
		int ci = cn - 1 - i;
		int v = cy[ci];
		if (arr[ci + 1] == gr[v][0]) arr[ci] = gr[v][1];
		else arr[ci] = gr[v][0];
		if (arr[ci] == arr[ci + 1]) return false;
	}
	if (arr[cn] != arr[0]) return false;
	REP(i, n) assign[i] = gr[i][0];
	REP(i, cn) assign[cy[i]] = arr[i];
	REP(i, n) {
		if (assign[i] == assign[esr[i][0]]) return false;
		set<int> s;
		REP(j, es[i].size()) if (assign[es[i][j]] < assign[i]) s.insert(assign[es[i][j]]);
		if (s.size() != assign[i]) return false;
	}
	return true;
}

int main(int argc, char **argv) {
	cin >> n;
	REP(i, n) {
		int p;
		cin >> p;
		--p;
		es[p].push_back(i);
		esr[i].push_back(p);
	}
	cycle();
	REP(i, cn) dfs(cy[i], cy[i + 1]);
	cout << (solve(0) || solve(1) ? "POSSIBLE" : "IMPOSSIBLE") << endl;
	return 0;
}

