template<class T> using V = vector<T>;
template<class T> using VV = V<V<T>>;
constexpr ll TEN(int n) { return (n==0) ? 1 : 10*TEN(n-1); }

int n;
V<int> p;
VV<int> g;

array<int, 2> chk(const V<int> &a, int v) {
    set<int> s;
    for (int d: g[v]) s.insert(a[d]);
    array<int, 2> ans;
    int u = 0;
    while (s.count(u)) u++;
    ans[0] = u;
    u++;
    while (s.count(u)) u++;
    ans[1] = u;
    return ans;
}

V<int> pre(const V<int> &b) {
    V<int> a = b;
    queue<int> q;
    V<ll> deg = V<ll>(n);
    for (int i = 0; i < n; i++) {
        if (a[i] != -1) continue;
        for (int d: g[i]) if (a[d] == -1) deg[i]++;
        if (deg[i] == 0) {
            q.push(i);
        }
    }
    while (!q.empty()) {
        int v = q.front(); q.pop();
        a[v] = chk(a, v)[0];
        if (a[p[v]] != -1) continue;
        deg[p[v]]--;
        if (!deg[p[v]]) q.push(p[v]);
    }
    return a;
}

bool solve() {
    scanf("%d", &n);
    p = V<int>(n);
    g = VV<int>(n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &(p[i])); p[i]--;
        g[p[i]].push_back(i);
    }
    auto a = pre(V<int>(n, -1));
    int v = -1;

    for (int i = 0; i < n; i++) {
        if (a[i] == -1) {
            v = i;
            break;
        }
    }

    auto p = chk(a, v);
    a[v] = p[0];
    if (chk(pre(a), v)[0] == a[v]) {
        return true;
    }
    a[v] = p[1];
    if (chk(pre(a), v)[0] == a[v]) {
        return true;
    }
    return false;
}

int main() {
    if (!solve()) {
        cout << "IM";
    }
    cout << "POSSIBLE" << endl;
}

#include <bits/stdc++.h>

using namespace std;

int const N = 1234567;

int was[N], g[N], ng[N], p[N], cycle[N];

vector<int> edges[N];

int dfs(int v, int bad) {
  if (g[v] >= 0) return g[v];
  int children = (int) edges[v].size();
  for (int i = 0; i <= children; i++) was[i] = false;
  for (int to : edges[v]) {
    if (to == bad) continue;
    int got = dfs(to, bad);
    if (got <= children) was[got] = true;
  }
  int i = 0;
  while (was[i]) ++i;
  g[v] = i;
  return i;
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", p + i);
    --p[i];
    edges[p[i]].push_back(i);
    g[i] = -1;
  }
  int v = 0;
  for (int i = 0; i < n; i++) v = p[v];
  int cc = 0;
  int start = v;
  while (true) {
    cycle[cc++] = v;
    v = p[v];
    if (start == v) break;
  }
  dfs(cycle[0], cycle[cc - 1]);
  int gv = g[cycle[0]];
  for (int i = 0; i < n; i++) ng[i] = g[i];
  for (int value = gv; value <= gv + 1; value++) {
    for (int i = 0; i < n; i++) g[i] = ng[i];
    g[cycle[0]] = value;
    for (int i = 0; i < cc; i++) {
      int v = cycle[i];
      if (g[v] < 0) dfs(v, -1);
    }
    int last = cycle[cc - 1];
    if (value == gv && g[last] == gv) {
      continue;
    }
    if (value == gv + 1 && g[last] != gv) continue;
    puts("POSSIBLE");
    return 0;
  }
  puts("IMPOSSIBLE");
}

