    It begin(){return {b, (b < e? 1: -1)};}
    It end(){return {e, 0};}
    int b, e;
};

template<typename T> inline T& UMAX(T& x, T y){if(x < y)x = y; return x;}
template<typename T> inline T& UMIN(T& x, T y){if(y < x)x = y; return x;}
template<typename T, typename... Args> struct ArithmiticPromotion { typedef decltype(T() + typename ArithmiticPromotion<Args...>::type()) type; };
template<typename T, typename U> struct ArithmiticPromotion<T, U> { typedef decltype(T() + U()) type; };
template<typename T> struct ArithmiticPromotion<T, T> { typedef T type; };
template<typename T> struct ArithmiticPromotion<T> { typedef T type; };
template<typename T, typename U> typename ArithmiticPromotion<T, U>::type MAX(T a, U b) { return a < b? b: a; }
template<typename T, typename... Args> typename ArithmiticPromotion<T, Args...>::type MAX(T a, Args... args) { return MAX(a, MAX(args...)); }
template<typename T, typename U> typename ArithmiticPromotion<T, U>::type MIN(T a, U b) { return a < b? a: b; }
template<typename T, typename... Args> typename ArithmiticPromotion<T, Args...>::type MIN(T a, Args... args) { return MIN(a, MIN(args...)); }




namespace XX
{
    class StronglyConnectedComponent: public Graph<>
    {
        public:
            std::vector<int> component;
            std::vector<int> low;
            std::vector<int> dfn;
            std::vector<std::vector<int>> child;
            template<typename... Args>
            StronglyConnectedComponent(Graph<Args...>& g)
                :component(g.size()), low(g.size()), dfn(g.size())
            {
                int n = g.size();
                std::vector<bool> in(n);
                std::stack<int> stk;
                int alc = 0;
                int total = 0;
                std::function<int(int)> dfs = [&](int u)
                {
                    int order = ++alc;
                    dfn[u] = low[u] = order;
                    stk.push(u);
                    in[u] = true;
                    for(auto& e: g[u])
                    {
                        if(!low[e.to])
                            UMIN(low[u], dfs(e.to));
                        else if(in[e.to])
                            UMIN(low[u], dfn[e.to]);
                    }

                    if(low[u] == order)
                    {
                        int v;
                        do
                        {
                            v = stk.top();
                            stk.pop();
                            component[v] = total;
                            in[v] = false;
                        }
                        while(v != u);
                        total++;
                    }
                    return low[u];
                };
                for(int i = 0; i < n; i++)
                    if(!low[i])
                        dfs(i);
                resize(total);
                child.resize(total);
                for(int i = 0; i < n; i++)
                    child[component[i]].push_back(i);
                std::vector<int> buf(total);
                for(int c = 0; c < total; c++)
                    for(int ch: child[c])
                        for(auto& e: g[ch])
                        {
                            int toc = component[e.to];
                            if(toc != c && buf[toc] != c + 1)
                            {
                                buf[toc] = c + 1;
                                this->add(c, toc);
                            }
                        }
            }
    };

}






namespace XX
{
    template<typename... EdgeTs>
    std::vector<int> topologicalsort(Graph<EdgeTs...>& g)
    {
        std::vector<int> deg(g.size());
        for(auto& e: g.edges())
            deg[e.to]++;

        std::vector<int> ret(deg.size());
        unsigned len = 0;
        std::queue<int> que;
        for(unsigned i = 0; i < deg.size(); i++)
            if(deg[i] == 0)
                que.push(i);

        while(que.size())
        {
            int u = que.front();
            que.pop();
            ret[len++] = u;
            for(auto& e: g[u])
                if(--deg[e.to] == 0)
                    que.push(e.to);
        }

        if(len < ret.size())
            ret.resize(len);
        return ret;
    }
}


namespace XX
{
    struct TwoSAT
    {
        Graph<> imp;
        int varnum;
        std::vector<bool> assignment;
        TwoSAT(int n):imp(2 * n), varnum(n), assignment(n){}

        void add(int v1, bool neg1, int v2, bool neg2)
        {
            imp.add(v1 * 2 + !neg1, v2 * 2 + neg2);
            imp.add(v2 * 2 + !neg2, v1 * 2 + neg1);
        }

        void add(int v1, bool neg1)
        {
            imp.add(v1 * 2 + !neg1, v1 * 2 + neg1);
        }

        operator bool(){return satisfiable();}

        bool check()
        {
            StronglyConnectedComponent scc(imp);
            for(int i = 0; i < varnum; i++)
                if(scc.component[2 * i] == scc.component[2 * i + 1])
                    return false;
            return true;
        }
        bool solve()
        {
            StronglyConnectedComponent scc(imp);
            for(int i = 0; i < varnum; i++)
                if(scc.component[2 * i] == scc.component[2 * i + 1])
                    return false;

            std::vector<bool> done(varnum);
            auto ts = topologicalsort(scc);
            for(int i = ts.size() - 1; i >= 0; i--)
                for(int c: scc.child[ts[i]])
                    if(!done[c >> 1])
                    {
                        done[c >> 1] = true;
                        assignment[c >> 1] = !(c & 1);
                    }
            return true;
        }
        bool operator[](int idx){return assignment[idx];}
        bool satisfiable() { return assignment.size(); }
    };
}





