bool dfs(int now, int past){
    reach[now] = 1;
    bool f = false, g = false;
    for (int next : e[now]){
        if (next == past) continue;
        if (reach[next]){
            c = next;
            len = dist[now] - dist[next] + 1;
            f = true;
        }else{
            dist[next] = dist[now] + 1;
            g |= dfs(next, now);
        }
    }
    for (int next : e[now]){
        if (next == c && !f) g = false;
    }
    loop[now] = f | g;
    return f | g;
}

