            find(to);
            if (fr[{v, to}] == v) curVl.push_back(c[to]);
        }
    }

    ll pr = -1;
    curVl.push_back(INF);
    sort(curVl.begin(), curVl.end());

    ll mx = -1;
    for (auto cur : curVl) {
        if (cur == pr) continue;

        if (pr + 1 < cur) {
            mx = pr + 1;
            break;
        }
        pr = cur;
    }

    c[v] = mx;
}

