bool flg = true ;
int n, e, ter[M], nxt[M], lnk[N], opt[N], mex[N], d[N], pre[N] ;
map <int, bool> h[N] ;

void add(int x, int y) {
	ter[++ e] = y, nxt[e] = lnk[x], lnk[x] = e ;
}

bool cmp(int x, int y) {
	return mex[x] < mex[y] ;
}

void solve(int x) {
	if (d[pre[x]]) {
		if (mex[pre[x]] > mex[x]) ; else solve(pre[x]) ;
	} 
	if (mex[pre[x]] == mex[x]) ++ mex[x] ;
	d[x] = 0 ;
}

int main() {
