	int x ;
	rep(i, 1, n) scanf("%d", &x), add(x, i), add(i, x), ++ d[x] ;
	int he = 0, ta = 0 ;
	rep(i, 1, n) if (!d[i]) opt[++ ta] = i  ;
	for ( ; he != ta ; ) {
		++ he ;
		int u = opt[he] ;
		for ( ; h[u][mex[u]] ; ++ mex[u]) ;
		for (int i = lnk[u] ; i; i = nxt[i]) if (!(i & 1)) {
			int v = ter[i] ;
			-- d[v] ;
			h[v][mex[u]] = true ;
			if (!d[v]) opt[++ ta] = v ;
		}
	}
	ta = 0 ;
	rep(i, 1, n) if (d[i]) {
		for ( ; h[i][mex[i]] ; ++ mex[i]) ;
		for (int j = lnk[i]; j; j = nxt[j]) if (j & 1) if (d[ter[j]]) pre[i] = ter[j] ;
		opt[++ ta] = i ;
	}
	sort(opt + 1, opt + ta + 1, cmp) ;
	if (mex[opt[1]] == mex[opt[ta]]) {
		if (ta & 1) flg = false ;
	} else {
		rep(i, 1, ta) solve(opt[i]) ;
	}
	if (flg) puts("POSSIBLE") ; else puts("IMPOSSIBLE") ; 
	return 0 ; 
}

