int a[maxn], b[maxn], back[maxn], nxt[maxn], ans[maxn];
bool vis[maxn];
vector<int> c, e[maxn];
void circle(){
	int hd;
	for (int u = 1;; u = back[u]){
		if (vis[u]){
			hd = u;
			break;
		}
		vis[u] = 1;
	}
	for (int u = hd; ;){
		c.pb(u);
		nxt[back[u]] = u; 
		u = back[u];
		if (u == hd) break;
	}
}
void dfs(int u){
	vector<int> tmp;
	tmp.clear();
	for (int v : e[u]){
		if (v != nxt[u]){
			dfs(v);
			tmp.pb(a[v]);
		}
	}
	sort(tmp.begin(), tmp.end());
	tmp.erase(unique(tmp.begin(), tmp.end()), tmp.end());
	int i = 0;
	while (tmp.size() > i && tmp[i] == i) ++i;
	a[u] = i;
	while (tmp.size() > i && tmp[i] == i + 1) ++i;
	b[u] = i + 1;
	//cout << u << ' ' << a[u] << ' ' << b[u] << endl;
}
void solve(){
	cin >> n;
	for (int i = 1; i <= n; ++i){
		cin >> x;
		e[x].pb(i);
		back[i] = x;
	}
	circle();
	for (int i : c) dfs(i);
	//
	ans[c[0]] = a[c[0]];
	for (int u = back[c[0]]; u != c[0]; u = back[u]){
		ans[u] = (ans[nxt[u]] == a[u]) ? b[u] : a[u];
	}
	if (a[c[0]] != ans[nxt[c[0]]]){
		puts("POSSIBLE");
		return;
	}
	ans[c[0]] = b[c[0]];
	for (int u = back[c[0]]; u != c[0]; u = back[u]){
		ans[u] = (ans[nxt[u]] == a[u]) ? b[u] : a[u];
	}
	if (a[c[0]] == ans[nxt[c[0]]]){
		puts("POSSIBLE");
		return;
	}
	puts("IMPOSSIBLE");
}

