	int rep = ord[0];
	bool sm = true;
	for(int i=0;i<ord.size();i++) {
		if(ds(rep) != ds(ord[i])) {
			sm = false;break;
		}
	}
	bool poss = (!sm) || (ord.size()%2 == 0);
	printf("%sPOSSIBLE\n",poss?"":"IM");
}

