int grundy(int s)
{
    for(auto a : ad[s])
        vis[ans[a]]=1;
    int x=0;
    while(vis[x])
        x++;
    for(auto a : ad[s])
        vis[ans[a]]=0;
    return x;
}
void hatao(int s)
{
    st.erase({sz(edge[s]),s});
    int p=par[s];
    st.erase({sz(edge[p]),p});
    edge[p].erase(s);
    st.insert({sz(edge[p]),p});
    ans[s]=grundy(s);
}
int call(int s)
{
    int p=par[s];
    vi loop;
    loop.pb(p),st.erase({sz(edge[p]),p});
    while(p!=s)
        p=par[p],loop.pb(p),st.erase({sz(edge[p]),p});
    int a=loop.size();
    if(a%2==0)
        return 0;
    vi ar;
    for(auto a : loop)
        ar.pb(grundy(a));
    a=*min_element(all(ar));
    p=*max_element(all(ar));
    return (a==p);
}
