void process_node(int nd)
{
    processed[nd] = true;
    set<int> possible_vals;
    for0(i,sz(children[nd])+1)
        possible_vals.insert(i);

    int cnt_unknown = 0;
    iter(children[nd]) {
        if (val[*it] != -1) {
            if (used_vals[nd].find(val[*it]) == used_vals[nd].end()) {
                possible_vals.erase(val[*it]);
                used_vals[nd].insert(val[*it]);
            }
            else {
                set<int>::iterator max_val = possible_vals.end(); max_val--;
                possible_vals.erase(max_val);
            }
        }
        else {
            cnt_unknown++;
            cycle_next[nd] = *it;
        }
    }
    assert(cnt_unknown == 1);
    iter(possible_vals) {
        poss_vals[nd].pb(*it);
    } 
}


