    for0(i,n) {
        if (!processed[i]) {
            cycle_start = i;
            process_node(i);
        }
    }

    int cur = cycle_start;
    TwoSAT twosat = TwoSAT();
    int cur_lit = twosat.next_lit();
    do {
        int nxt = cycle_next[cur];
        int next_lit;
        if (nxt == cycle_start)
            next_lit = 1;
        else 
            next_lit = twosat.next_lit();
        //prl(cur);
