		scanf("%d",&t);
		add(i,t),add(t,i);
	}
	getloop(1);
	memset(vis,0,sizeof(vis));
	for(int i = 1;i<=cnt;i++)dfs(loop[i]);
	int mn = n+1,mx = -1;
	for(int i = 1;i<=cnt;i++){
		mn = min(mn,dp[loop[i]]);
		mx = max(mx,dp[loop[i]]);
	}
	if(mn==mx&&(cnt%2==1))printf("IMPOSSIBLE");
	else printf("POSSIBLE");
	return 0;
}

