void findcircle(int x){
	if(found) return;inq[x]=vis[x]=1;
	for(int i=hr[x];i;i=e[i].nex){
		if(inq[e[i].to]){for(int j=x;j!=e[i].to;j=last[j]) cir[++mem]=j;cir[++mem]=e[i].to;found=true;}
		else if(!vis[e[i].to]) last[e[i].to]=x,findcircle(e[i].to);
	}
	inq[x]=false;
}
