	register int i;
	for(i=hr[x];i;i=e[i].nex) if(!cime[e[i].to]) dp(e[i].to);
	++now;for(i=hr[x];i;i=e[i].nex) if(!cime[e[i].to]) vis[sg[e[i].to]]=now;
