bool assign(int u, int root) {
    if (vis[u]) return true;
    vis[u] = true;
    V<int> chv;
    for (int v : ch[u]) {
        if (v == root)
            return false;
        else if (!assign(v, root))
            return false;
        else {
            chv.pb(ass[v]);
        }
    }
    ass[u] = se(chv);
    return true;
}

bool test(V<int> cy, int x) {
    //P(x);
    int val[S(cy)+1];
    val[0] = x;
    F(i,S(cy)+1) if (i) {
        int pre = cy[i-1], cur = cy[i%S(cy)];
        V<int> chv;
        for (int v : ch[cur]) if (v != pre)
            chv.pb(ass[v]);
        chv.pb(val[i-1]);
        val[i] = se(chv);
    }
    //F(i,S(cy)+1) cout<<val[i]<<" \n"[i==S(cy)];
    return (val[S(cy)] == x);
}

