int N;
const int M = 200000;
const int INF = 1e9;
int prv[M], grundy[M];
vector<int> nxt[M];
bitset<M> cycle;
int c;

void find_cycle(){
    int i = 0;
    bitset<M> visited;
    stack<int> st;
    while(true){
        visited[i] = true;
        st.push(i);
        if(visited[prv[i]]){
            c = prv[i];
            while(true){
                int j = st.top(); st.pop();
                cycle[j] = true;
                if(prv[i] == j) return;
            }
        }
        i = prv[i];
    }
}

int calc_grundy(int i){
    vector<int> v = {INF};
    for(int j : nxt[i]) v.push_back(grundy[j]);
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    for(int j=0; j<v.size(); j++){
        if(v[j] != j) return j;
    }
}

vector<int> calc_grundy_cand2(int i){
    vector<int> v = {INF, INF+1};
    for(int j : nxt[i]) if(!cycle[j]) v.push_back(grundy[j]);
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    vector<int> ans;
    for(int j=0; j<v.size(); j++){
        if(v[j-ans.size()] != j) ans.push_back(j);
        if(ans.size() == 2) return ans;
    }
}

bitset<M> visited2;
int dfs(int i){
    visited2[i] = true;
    if(nxt[i].size() == 0) return 0;
    for(int j : nxt[i]) if(!visited2[j]) dfs(j);
    grundy[i] = calc_grundy(i);
    return grundy[i];
}

void check(int num){
    grundy[c] = num;
    int i = prv[c];
    while(i != c){
        grundy[i] = calc_grundy(i);
        i = prv[i];
    }

    if(calc_grundy(c) == grundy[c]){
        cout << "POSSIBLE" << endl;
        exit(0);
    }
}

int main(){
    cin >> N;
    for(int i=0; i<N; i++){
        cin >> prv[i];
        prv[i]--;
        nxt[prv[i]].push_back(i);
    }

    find_cycle();
    for(int i=0; i<N; i++) if(!cycle[i] && !visited2[i]) dfs(i);

    auto cand = calc_grundy_cand2(c);
    for(int num : cand) check(num);
    cout << "IMPOSSIBLE" << endl;
    return 0;
}

