public class Main {

    static int N;
    static int[] P;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        P = sc.nextIntArray(N, -1);

        System.out.println(solve());
    }

    static String solve() {
        int[] U = new int[N];
        int[] V = new int[N];
        for (int i = 0; i < N; i++) {
            int p = P[i];
            // i -> p
            // 逆に見なしたほうがうれしい
            U[i] = i;
            V[i] = p;
        }

        int[][] G = adjD(N, U, V);
        int[][] F = adjD(N, V, U);

        // cyrcleの部分以外に数を割り当てる
        int[] A = reliefCircle(G, F);

        int start = -1;
        for (int i = 0; i < N; i++) {
            if( A[i] == -1 ) {
                start = i;
                break;
            }
        }

        boolean ok = check(start, grundy(start, A, F), Arrays.copyOf(A, N), G, F);
        if( ok ) return "POSSIBLE";

        ok = check(start, nextGrundy(start, A, F), A, G, F);
        return ok ? "POSSIBLE" : "IMPOSSIBLE";
    }

    static boolean check(int start, int a_start, int[] A, int[][] G, int[][] F) {
        A[start] = a_start;

        int curr = start;
        while(true) {
            int next = G[curr][0];
            int a = grundy(next, A, F);
            if( next == start ) {
                return a == a_start;

            } else {
                A[next] = a;
                curr = next;
            }
        }
    }

    static int[] reliefCircle(int[][] G, int[][] F) {
        int[] deg = new int[N];
        for (int[] tos : G) {
            for (int to : tos) {
                deg[to]++;
            }
        }

        int[] A = new int[N];
        Arrays.fill(A, -1);
        int[] q = new int[N];
        int s = 0, t = 0;
        for (int v = 0; v < N; v++) {
            if( deg[v] == 0 ) {
                q[t++] = v;
                A[v] = 0;
            }
        }

        int idx = 0;
        while( s != t ) {
            int v = q[s++];
            for (int to : G[v]) {
                deg[to]--;
                if( deg[to] == 0 ) {
                    A[to] = grundy(to, A, F);
                    q[t++] = to;
                }
            }
        }

        return A;
    }

    // mexだっけ？
    static int grundy(int v, int[] A, int[][] F) {
        Set<Integer> num = new HashSet<>();
        for (int from : F[v]) {
            num.add(A[from]);
        }
        for (int i = 0; i < N; i++) {
            if( !num.contains(i) ) {
                return i;
            }
        }
        throw new IllegalArgumentException("wtf");
    }

    static int nextGrundy(int v, int[] A, int[][] F) {
        Set<Integer> num = new HashSet<>();
        num.add(grundy(v, A, F));
        for (int from : F[v]) {
            num.add(A[from]);
        }
        for (int i = 0; i < N; i++) {
            if( !num.contains(i) ) {
                return i;
            }
        }
        throw new IllegalArgumentException("wtf");
    }

    static int[][] adjD(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
        }
        return adj;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
