import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.NoSuchElementException;
import java.util.TreeSet;

public class Main {

  private ArrayList<Integer> getOneCycle(ArrayList<ArrayList<Integer>> tree) {
    int N = tree.size();
    int[] scc = decompose(tree);
    int[] count = new int[N];
    ArrayList<Integer> cycle = new ArrayList<>();
    for (int s : scc) {
      count[s]++;
    }
    for (int i = 0; i < N; i++) {
      if (count[scc[i]] > 1) {
        cycle.add(i);
      }
    }

    return cycle;
  }

  private void solve(FastScanner in, PrintWriter out) {
    int N = in.nextInt();
    ArrayList<ArrayList<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < N; i++) {
      tree.add(new ArrayList<>());
    }

    int[] parent = new int[N];
    for (int i = 0; i < N; i++) {
      int p = in.nextInt() - 1;
      parent[i] = p;
      tree.get(p).add(i);
    }

    ArrayList<Integer> cycle = getOneCycle(tree);
    if (cycle.isEmpty()) {
      out.println("POSSIBLE");
      return;
    }

    TreeSet<Integer>[] children = new TreeSet[N];
    for (int i = 0; i < N; i++) {
      children[i] = new TreeSet<>();
    }

    ArrayDeque<Integer> bfs = new ArrayDeque<>();
    int[] vis = new int[N];
    int[] grundy = new int[N];
    Arrays.fill(grundy, -1);
    for (int i = 0; i < N; i++) {
      if (tree.get(i).isEmpty()) {
        bfs.add(i);
        grundy[i] = 0;
      }
    }
    while (!bfs.isEmpty()) {
      int v = bfs.poll();
      int p = parent[v];
      vis[p]++;
      if (vis[p] == tree.get(p).size()) {
        bfs.add(p);
      }
      if (tree.get(v).isEmpty()) {
        continue;
      }
      TreeSet<Integer> set = children[v];
      for (int u : tree.get(v)) {
        set.add(grundy[u]);
      }
      grundy[v] = getGrundy(set);
    }

    for (int c : cycle) {
      for (int u : tree.get(c)) {
        if (grundy[u] >= 0) {
          children[c].add(grundy[u]);
        }
      }
    }

    int x = cycle.get(0);
    int g1 = getGrundy(children[x]);
    grundy[x] = g1;
    {
      int M = cycle.size();
      int cur = x;
      TreeSet<Integer>[] copy = copy(children);
      for (int i = 0; i < M; i++) {
        int p = parent[cur];
        copy[p].add(grundy[cur]);
        grundy[p] = getGrundy(copy[p]);
        cur = p;
      }
      if (g1 == grundy[x]) {
        out.println("POSSIBLE");
        return;
      }
    }
    children[x].add(g1);
    int g2 = getGrundy(children[x]);
    children[x].remove(g1);
    grundy[x] = g2;
    {
      int M = cycle.size();
      int cur = x;
      TreeSet<Integer>[] copy = copy(children);
      for (int i = 0; i < M; i++) {
        int p = parent[cur];
        copy[p].add(grundy[cur]);
        grundy[p] = getGrundy(copy[p]);
        cur = p;
      }
      if (g2 == grundy[x]) {
        out.println("POSSIBLE");
        return;
      }
    }
    out.println("IMPOSSIBLE");

  }

  private TreeSet<Integer>[] copy(TreeSet<Integer>[] children) {
    TreeSet<Integer>[] array = new TreeSet[children.length];
    for (int i = 0; i < children.length; i++) {
      array[i] = new TreeSet<>(children[i]);
    }
    return array;
  }

  private int getGrundy(TreeSet<Integer> set) {
    int grundy = 0;
    for (int s : set) {
      if (s == grundy) {
        grundy++;
      } else {
        return grundy;
      }
    }
    return grundy;
  }

  public static int[] decompose(ArrayList<ArrayList<Integer>> G) {
    ArrayList<Integer> vs = new ArrayList<>();
    int V = G.size();
    int[] cmp = new int[V];

    ArrayList<ArrayList<Integer>> rG = new ArrayList<>(V);
    for (int i = 0; i < V; i++) {
      rG.add(new ArrayList<>());
    }
    for (int i = 0; i < V; i++) {
      for (int v : G.get(i)) {
        rG.get(v).add(i);
      }
    }
    boolean[] used = new boolean[V];

    ArrayDeque<Integer> stack = new ArrayDeque<>();
    boolean[] added = new boolean[V];
    for (int i = 0; i < V; i++) {
      if (!used[i]) {
        stack.addFirst(i);
        while (!stack.isEmpty()) {
          int v = stack.peekFirst();
          used[v] = true;
          boolean pushed = false;
          for (int j = G.get(v).size() - 1; j >= 0; j--) {
            int u = G.get(v).get(j);
            if (!used[u]) {
              stack.addFirst(u);
              pushed = true;
            }
          }
          if (!pushed) {
            stack.pollFirst();
            if (!added[v]) {
              vs.add(v);
              added[v] = true;
            }
          }
        }
      }
    }

    Arrays.fill(used, false);
    int k = 0;
    Collections.reverse(vs);
    for (int i : vs) {
      if (!used[i]) {
        stack.push(i);
        used[i] = true;
        cmp[i] = k;
        while (!stack.isEmpty()) {
          int v = stack.peek();
          boolean pushed = false;
          for (int u : rG.get(v)) {
            if (!used[u]) {
              used[u] = true;
              cmp[u] = k;
              stack.push(u);
              pushed = true;
            }
          }
          if (!pushed) {
            stack.pop();
          }
        }
        k++;
      }
    }
    return cmp;
  }

  public static void main(String[] args) {
    FastScanner in = new FastScanner();
    PrintWriter out = new PrintWriter(System.out);
    new Main().solve(in, out);
    out.close();
  }

  private static class FastScanner {

    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int bufferLength = 0;

    private boolean hasNextByte() {
      if (ptr < bufferLength) {
        return true;
      } else {
        ptr = 0;
        try {
          bufferLength = in.read(buffer);
        } catch (IOException e) {
          e.printStackTrace();
        }
        if (bufferLength <= 0) {
          return false;
        }
      }
      return true;
    }

    private int readByte() {
      if (hasNextByte()) {
        return buffer[ptr++];
      } else {
        return -1;
      }
    }

    private static boolean isPrintableChar(int c) {
      return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
      while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
        ptr++;
      }
    }

    boolean hasNext() {
      skipUnprintable();
      return hasNextByte();
    }

    public String next() {
      if (!hasNext()) {
        throw new NoSuchElementException();
      }
      StringBuilder sb = new StringBuilder();
      int b = readByte();
      while (isPrintableChar(b)) {
        sb.appendCodePoint(b);
        b = readByte();
      }
      return sb.toString();
    }

    long nextLong() {
      if (!hasNext()) {
        throw new NoSuchElementException();
      }
      long n = 0;
      boolean minus = false;
      int b = readByte();
      if (b == '-') {
        minus = true;
        b = readByte();
      }
      if (b < '0' || '9' < b) {
        throw new NumberFormatException();
      }
      while (true) {
        if ('0' <= b && b <= '9') {
          n *= 10;
          n += b - '0';
        } else if (b == -1 || !isPrintableChar(b)) {
          return minus ? -n : n;
        } else {
          throw new NumberFormatException();
        }
        b = readByte();
      }
    }

    double nextDouble() {
      return Double.parseDouble(next());
    }

    double[] nextDoubleArray(int n) {
      double[] array = new double[n];
      for (int i = 0; i < n; i++) {
        array[i] = nextDouble();
      }
      return array;
    }

    double[][] nextDoubleMap(int n, int m) {
      double[][] map = new double[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextDoubleArray(m);
      }
      return map;
    }

    public int nextInt() {
      return (int) nextLong();
    }

    public int[] nextIntArray(int n) {
      int[] array = new int[n];
      for (int i = 0; i < n; i++) {
        array[i] = nextInt();
      }
      return array;
    }

    public long[] nextLongArray(int n) {
      long[] array = new long[n];
      for (int i = 0; i < n; i++) {
        array[i] = nextLong();
      }
      return array;
    }

    public String[] nextStringArray(int n) {
      String[] array = new String[n];
      for (int i = 0; i < n; i++) {
        array[i] = next();
      }
      return array;
    }

    public char[][] nextCharMap(int n) {
      char[][] array = new char[n][];
      for (int i = 0; i < n; i++) {
        array[i] = next().toCharArray();
      }
      return array;
    }

    public int[][] nextIntMap(int n, int m) {
      int[][] map = new int[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextIntArray(m);
      }
      return map;
    }
  }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Iterator;
import java.util.Collection;
import java.io.IOException;
import java.util.Queue;
import java.util.ArrayDeque;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskF solver = new TaskF();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskF {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] from = new int[n];
            IntList[] graph = new IntList[n];
            int[] deg = new int[n];
            for (int i = 0; i < n; ++i) {
                graph[i] = new IntList();
            }
            for (int i = 0; i < n; ++i) {
                from[i] = in.nextInt() - 1;
                graph[from[i]].add(i);
                deg[from[i]]++;
            }
            Queue<Integer> q = new ArrayDeque<>();
            for (int i = 0; i < n; ++i) {
                if (deg[i] == 0) {
                    q.add(i);
                }
            }
            boolean[] used = new boolean[n];
            int[] color = new int[n];
            while (!q.isEmpty()) {
                int node = q.poll();
                for (IntIterator it = graph[node].iterator(); it.hasNext(); ) {
                    int to = it.nextInt();
                    used[color[to]] = true;
                }
                while (used[color[node]]) {
                    color[node]++;
                }
                Arrays.fill(used, 0, color[node], false);
                if (--deg[from[node]] == 0) {
                    q.add(from[node]);
                }
            }
            int k = 0;
            for (int i = 0; i < n; ++i) {
                if (deg[i] != 0) {
                    k++;
                    for (IntIterator it = graph[i].iterator(); it.hasNext(); ) {
                        int to = it.nextInt();
                        if (deg[to] == 0) {
                            used[color[to]] = true;
                        }
                    }
                    while (used[color[i]]) {
                        color[i]++;
                    }
                    Arrays.fill(used, 0, color[i], false);
                }
            }
            int[] initColor = color.clone();
            int[] nodes = new int[k];
            k = 0;
            for (int i = 0; i < n; ++i) {
                if (deg[i] != 0) {
                    nodes[k++] = i;
                    for (int j = from[i]; j != i; j = from[j]) {
                        nodes[k++] = j;
                    }
                    break;
                }
            }
            TwoSat s = new TwoSat(n);
            for (int i = 0; i < k; ++i) {
                int node = nodes[i];
                int next = nodes[(i + 1) % k];
                if (color[node] == color[next]) {
                    s.addXor(node, next);
                } else if (color[node] + 1 == color[next]) {
                    s.addOr(s.non(node), next);
                } else if (color[next] + 1 == color[node]) {
                    s.addOr(s.non(next), node);
                }
            }
            s.solveSystem();
            out.println(s.hasSolution() ? "POSSIBLE" : "IMPOSSIBLE");

        }

    }

    static class TwoSat {
        private static final int initialCapacity = 1;
        private int[] firstEdge;
        private int[] edgeTo;
        private int[] nextEdge;
        private int[] t_firstEdge;
        private int[] t_edgeTo;
        private int[] t_nextEdge;
        private boolean[] values;
        int size;
        int edges;
        int capacity;

        public TwoSat(int size) {
            this.size = size;
            firstEdge = new int[2 * size];
            Arrays.fill(firstEdge, -1);
            t_firstEdge = firstEdge.clone();
            edgeTo = new int[initialCapacity];
            nextEdge = new int[initialCapacity];
            t_edgeTo = new int[initialCapacity];
            t_nextEdge = new int[initialCapacity];
            edges = 0;
            capacity = initialCapacity;
            values = null;
        }

        public void addOr(int from, int to) {
            addImply(non(from), to);
            addImply(non(to), from);
        }

        public void addXor(int from, int to) {
            addOr(from, to);
            addOr(non(from), non(to));
        }

        private void addImply(int from, int to) {
            ensureEdgeCapacity(edges + 1);
            edgeTo[edges] = to;
            nextEdge[edges] = firstEdge[from];
            firstEdge[from] = edges;

            t_edgeTo[edges] = from;
            t_nextEdge[edges] = t_firstEdge[to];
            t_firstEdge[to] = edges++;
        }

        public void solveSystem() {
            boolean[] used = new boolean[2 * size];
            int[] order = new int[2 * size];
            int pos = 0;
            for (int i = 0; i < 2 * size; ++i)
                if (!used[i])
                    pos = dfs1(used, order, pos, i);
            values = new boolean[2 * size];
            for (int i = 2 * size - 1; i >= 0; --i) {
                int node = order[i];
                if (!values[node] && !values[non(node)])
                    dfs2(used, node);
            }

            for (int i = 0; i < 2 * size; ++i) {
                for (int p = firstEdge[i]; p != -1; p = nextEdge[p]) {
                    int to = edgeTo[p];
                    if (values[i] && !values[to]) {
                        values = new boolean[0];
                        return;
                    }
                }
                if (values[i] == values[non(i)]) {
                    values = new boolean[0];
                    return;
                }
            }
        }

        public boolean hasSolution() {
            if (values == null) solveSystem();
            return values.length != 0;
        }

        public int non(int x) {
            return x < size ? x + size : x - size;
        }

        private void ensureEdgeCapacity(int edges) {
            if (edges > capacity) {
                capacity = 2 * capacity + 1;
                edgeTo = resize(edgeTo, capacity);
                nextEdge = resize(nextEdge, capacity);
                t_edgeTo = resize(t_edgeTo, capacity);
                t_nextEdge = resize(t_nextEdge, capacity);
            }
        }

        private int[] resize(int[] a, int newSize) {
            int[] b = new int[newSize];
            System.arraycopy(a, 0, b, 0, a.length);
            return b;
        }

        private int dfs1(boolean[] used, int[] order, int pos, int node) {
            used[node] = true;
            for (int p = firstEdge[node]; p != -1; p = nextEdge[p])
                if (!used[edgeTo[p]])
                    pos = dfs1(used, order, pos, edgeTo[p]);
            order[pos++] = node;
            return pos;
        }

        private void dfs2(boolean[] used, int node) {
            used[node] = false;
            values[non(node)] = true;
            for (int p = t_firstEdge[node]; p != -1; p = t_nextEdge[p])
                if (used[t_edgeTo[p]])
                    dfs2(used, t_edgeTo[p]);
        }

    }

    static interface IntIterator extends Iterator<Integer> {
        int nextInt();

    }

    static class IntList implements Iterable<Integer> {
        int[] elem;
        int size;

        public IntList() {
            this(0, 0, 1);
        }

        public IntList(int size) {
            this(size, 0, Math.max(1, size));
        }

        public IntList(int size, int value) {
            this(size, value, Math.max(1, size));
        }

        public IntList(int size, int value, int capacity) {
            elem = new int[capacity];
            Arrays.fill(elem, 0, size, value);
            this.size = size;
        }

        private IntList(int... e) {
            elem = e.clone();
            size = e.length;
        }

        public void add(int e) {
            if (size + 1 > elem.length) {
                increaseCapacity();
            }
            elem[size++] = e;
        }

        private void increaseCapacity() {
            changeCapacity(3 * elem.length / 2 + 1);
        }

        private void changeCapacity(int newCapacity) {
            int[] nElem = new int[newCapacity];
            System.arraycopy(elem, 0, nElem, 0, Math.min(elem.length, newCapacity));
            elem = nElem;
        }

        public IntIterator iterator() {
            return new IntIterator() {
                int pos = 0;


                public Integer next() {
                    return IntList.this.elem[pos++];
                }


                public boolean hasNext() {
                    return pos < IntList.this.size;
                }


                public int nextInt() {
                    return IntList.this.elem[pos++];
                }
            };
        }

        public int hashCode() {
            int hashCode = 0;
            for (int i = 0; i < size; ++i) {
                hashCode = 31 * hashCode + elem[i];
            }
            return hashCode;
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new UnknownError();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

import java.io.*;
import java.util.*;

public class MainF {
	static final StdIn in = new StdIn();
	static final PrintWriter out = new PrintWriter(System.out);
	static List<Integer>[] adj;
	static boolean[] vis, act, ic;
	static List<Integer> cyc = new ArrayList<Integer>();
	static int[] a;

	public static void main(String[] args) {
		int n=in.nextInt();
		adj = new List[n];
		for(int i=0; i<n; ++i)
			adj[i] = new ArrayList<Integer>();
		for(int i=0; i<n; ++i)
			adj[in.nextInt()-1].add(i);
		vis = new boolean[n];
		act = new boolean[n];
		ic = new boolean[n];
		a = new int[n];
		for(int i=0; i<n; ++i)
			if(!vis[i]&&dfs1(i))
				break;
		cyc.remove(cyc.size()-1);
//		System.out.println(cyc);
		Arrays.fill(a, -1);
		a[cyc.get(0)]=n;
		if(dfs2(cyc.get(0))!=a[cyc.get(1)]) {
			System.out.println("POSSIBLE");
			return;
		}
		int a1=a[cyc.get(0)];
		Arrays.fill(a, -1);
		a[cyc.get(0)]=a1;
		if(dfs2(cyc.get(0))==a1)
			System.out.println("POSSIBLE");
		else
			System.out.println("IMPOSSIBLE");
		out.close();
	}

	static boolean dfs1(int u) {
		vis[u]=true;
		act[u]=true;
		for(int v : adj[u]) {
			if(act[v]) {
				cyc.add(v);
				ic[v]=true;
				cyc.add(u);
				ic[u]=true;
				return true;
			}
			if(dfs1(v)) {
				if(ic[v]&&v!=cyc.get(0)) {
					cyc.add(u);
					ic[u]=true;
				}
				return true;
			}
		}
		act[u]=false;
		return false;
	}

	static int dfs2(int u) {
		List<Integer> b = new ArrayList<Integer>();
		b.add(0);
		b.add(Integer.MAX_VALUE);
		for(int v : adj[u])
			b.add(a[v]==-1?dfs2(v):a[v]);
		Collections.sort(b);
		for(int i=0; ; ++i)
			if(b.get(i+1)>b.get(i)+1)
				return a[u]=b.get(i)+1;
	}

	static class StdIn {
    	final private int BUFFER_SIZE = 1 << 16;
    	private DataInputStream din;
    	private byte[] buffer;
    	private int bufferPointer, bytesRead;
    	public StdIn() {
    		din = new DataInputStream(System.in);
    		buffer = new byte[BUFFER_SIZE];
    		bufferPointer = bytesRead = 0;
    	}
    	public StdIn(InputStream in) {
    		try{
    			din = new DataInputStream(in);
    		} catch(Exception e) {
    			throw new RuntimeException();
    		}
    		buffer = new byte[BUFFER_SIZE];
    		bufferPointer = bytesRead = 0;
    	}
    	public int nextInt() {
    		int ret = 0;
    		byte c = read();
    		while (c <= ' ')
    			c = read();
    		boolean neg = (c == '-');
    		if (neg)
    			c = read();
    		do
    			ret = ret * 10 + c - '0';
    		while ((c = read()) >= '0' && c <= '9');

    		if (neg)
    			return -ret;
    		return ret;
    	}
    	public int[] readIntArray(int n) {
    		int[] ar = new int[n];
    		for(int i=0; i<n; ++i)
    			ar[i]=nextInt();
    		return ar;
    	}
    	private void fillBuffer() throws IOException {
    		bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
    		if (bytesRead == -1)
    			buffer[0] = -1;
    	}
    	private byte read() {
    		try{
    			if (bufferPointer == bytesRead)
    				fillBuffer();
    			return buffer[bufferPointer++];
    		} catch(IOException e) {
    			throw new RuntimeException();
    		}
    	}
    	public void close() throws IOException {
    		if (din == null)
    			return;
    		din.close();
    	}
    }
}

