    static abstract class DFS<V> {
        protected final int n;
        protected final Graph graph;
        protected final boolean[] visited;
        private final ListIterator<Edge>[] is;

        public DFS(Graph graph) {
            this.graph = graph;
            n = graph.size();
            visited = new boolean[n];
            //noinspection unchecked
            is = new ListIterator[n];
            for (int i = 0; i < n; i++) is[i] = graph.edges(i).listIterator();
        }

        public V run() {
            return run(ArrayUtils.createOrder(n));
        }

        public V run(int[] order) {
            Arrays.fill(visited, false);
            for (int vertex : order)
                if (!visited[vertex]) {
                    enterRoot(vertex);
                    run(vertex);
                }
            return result();
        }

        private void run(int vertex) {
            Stack<Edge> path = new Stack<Edge>();
            Edge parent = new SimpleEdge(-1, vertex);
            path.push(null);
            enter(parent);
            while (!path.isEmpty()) {
                visited[parent.to()] = true;
                boolean found = false;
                for (; is[parent.to()].hasNext();
                     is[parent.to()].next()
                        ) {
                    Edge e = is[parent.to()].next();
                    is[parent.to()].previous();
                    if (e.transposed() != parent) {
                        if (enter(e)) {
                            found = true;
                            path.push(parent);
                            is[parent.to()].next();
                            parent = e;
                            break;
                        }
                    }
                }
                if (!found) {
                    exit(parent);
                    if (parent.from() >= 0)
                        process(parent);
                    parent = path.pop();
                }
            }
        }

        protected V result() {
            return null;
        }

        protected void enterRoot(int root) {
        }

        protected boolean enter(Edge e) {
            return true;
        }

        protected void exit(Edge e) {
        }

        protected void process(Edge e) {
        }

    }

    static class GraphUtils {
        public static Graph transposed(Graph graph) {
            Graph res = new Graph(graph.size());
            for (int i = 0; i < graph.size(); i++) {
                for (Edge e : graph.edges(i)) {
                    res.add(e.transposed());
                }
            }
            return res;
        }

    }

    static class MyScanner {
        private final InputStream in;
        private static final int BUFSIZE = 65536;
        int bufLen;
        int bufPtr;
        byte[] buf = new byte[BUFSIZE];

        public MyScanner(InputStream in) {
            this.in = in;
        }

        public int read() {
            if (bufLen == -1)
                throw new InputMismatchException();
            if (bufPtr >= bufLen) {
                bufPtr = 0;
                try {
                    bufLen = in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (bufLen <= 0)
                    return -1;
            }
            return buf[bufPtr++];
        }

        public int nextInt() {
            int c = read();
            if (c == -1) throw new NoSuchElementException();
            while (c != '-' && (c < '0' || '9' < c)) {
                c = read();
                if (c == -1) throw new NoSuchElementException();
            }
            if (c == '-') return -nextInt();
            int res = 0;
            do {
                res *= 10;
                res += c - '0';
                c = read();
            } while ('0' <= c && c <= '9');
            return res;
        }

    }
