		out.close();
	}

	static class TaskF {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int[] p = new int[n];
			for (int i = 0; i < n; i++) {
				p[i] = in.nextInt() - 1;
			}
			List<Integer>[] invP = new List[n];
			for (int i = 0; i < n; i++) {
				invP[i] = new ArrayList<>();
			}
			for (int i = 0; i < n; i++) {
				invP[p[i]].add(i);
			}

			int[] a = new int[n];
			boolean[] used = new boolean[n];
			for (int step = 0; step < 80; step++) {
				for (int i = 0; i < n; i++) {
					for (int j : invP[i]) {
						used[a[j]] = true;
					}
					a[i] = 0;
					while (used[a[i]]) {
						++a[i];
					}
					for (int j : invP[i]) {
						used[a[j]] = false;
					}
				}
			}

			boolean ans = true;
			for (int i = 0; i < n; i++) {
				if (a[i] == a[p[i]]) {
					ans = false;
				}
			}
			for (int i = 0; i < n; i++) {
				for (int j : invP[i]) {
					used[a[j]] = true;
				}
				for (int c = 0; c < a[i]; c++) {
					if (!used[c]) {
						ans = false;
					}
				}
				for (int j : invP[i]) {
					used[a[j]] = false;
				}
