public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[] f = na(n);
		for(int i = 0;i < n;i++){
			f[i] = f[i]-1;
		}
		int[] from = new int[n];
		int[] to = new int[n];
		for(int i = 0;i < n;i++){
			from[i] = f[i];
			to[i] = i;
		}
		int[][] g = packU(n, from, to);
		int[][] sp = split(g);
		int[] par = sp[0], next = sp[1];
		int[] ord = makeOrder(g, par);
		int[] dp = new int[n];
		long[] ptns = new long[n];
		for(int i = n-1;i >= 0;i--){
			int cur = ord[i];
			dp[cur] = Long.numberOfTrailingZeros(~ptns[cur]);;
			if(par[cur] != -1){
				ptns[par[cur]] |= 1L<<dp[cur];
			}
		}
		int[] cycle = cycle(g, next);
		if(f[cycle[0]] == cycle[1]){
			for(int i = 1, j = cycle.length-1;i < j;i++,j--){
				int d = cycle[i]; cycle[i] = cycle[j]; cycle[j] = d;
			}
		}

		for(int j = 0;j < 32;j++){
			if(ptns[cycle[0]]<<~j>=0){
				int cval = j;
				for(int i = 0;i < cycle.length;i++){
					cval = Long.numberOfTrailingZeros(~(ptns[cycle[(i+1)%cycle.length]] | 1L<<cval));
				}
				if(cval == j){
					out.println("POSSIBLE");
					return;
				}
			}
		}
		out.println("IMPOSSIBLE");
	}

	public static int[] cycle(int[][] g, int[] next)
	{
		int n = g.length;
		int[] which = new int[n];
		int p = 0;
		for(int i = 0;i < n;i++){
			if(next[i] != -1){
				int u = i;
				while(true){
					which[p++] = u;
					u = next[u];
					if(u == i)break;
				}
				break;
			}
		}
		return Arrays.copyOf(which, p);
	}

	public static int[][] split(int[][] g)
	{
		int n = g.length;
		int[] deg = new int[n];
		int[] par = new int[n];
		Arrays.fill(par, -1);
		for(int i = 0;i < n;i++){
			deg[i] = g[i].length;
		}
		Queue<Integer> q = new ArrayDeque<Integer>();
		for(int i = 0;i < n;i++){
			if(deg[i] == 1){
				q.add(i);
			}
		}
		while(!q.isEmpty()){
			int cur = q.poll();
			deg[cur] = -9999999;
			for(int e : g[cur]){
				deg[e]--;
				if(deg[e] >= 0){
					par[cur] = e;
				}
				if(deg[e] >= 0 && deg[e] <= 1){
					q.add(e);
				}
			}
		}
		boolean[] ved = new boolean[n];
		int[] next = new int[n];
		Arrays.fill(next, -1);
		for(int i = 0;i < n;i++){
			if(!ved[i] && deg[i] == 2){
				ved[i] = true;
				int cur = i;
				outer:
				while(true){
					for(int e : g[cur]){
						if(deg[e] == 2 && !ved[e]){
							next[cur] = e;
							ved[e] = true;
							cur = e;
							continue outer;
						}
					}
					next[cur] = i;
					break;
				}
			}
		}

		return new int[][]{par, next};
	}

	public static int[] makeOrder(int[][] g, int[] par)
	{
		int n = g.length;
		int[] ord = new int[n];
		int p = 0;
		boolean[] ved = new boolean[n];
		for(int i = 0;i < n;i++){
			if(par[i] == -1){
				ord[p++] = i;
				ved[i] = true;
			}
		}
		for(int r = 0;r < n;r++){
			for(int e : g[ord[r]]){
				if(!ved[e]){
					ved[e] = true;
					ord[p++] = e;
				}
			}
		}
		return ord;
	}


	static int[][] packU(int n, int[] from, int[] to) {
		int[][] g = new int[n][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]];
		for (int i = 0; i < from.length; i++) {
			g[from[i]][--p[from[i]]] = to[i];
			g[to[i]][--p[to[i]]] = from[i];
		}
		return g;
	}

	public static class DJSet {
		public int[] upper;

		public DJSet(int n) {
			upper = new int[n];
			Arrays.fill(upper, -1);
		}

		public int root(int x) {
			return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
		}

		public boolean equiv(int x, int y) {
			return root(x) == root(y);
		}

		public boolean union(int x, int y) {
			x = root(x);
			y = root(y);
			if (x != y) {
				if (upper[y] < upper[x]) {
					int d = x;
					x = y;
					y = d;
				}
				upper[x] += upper[y];
				upper[y] = x;
			}
			return x == y;
		}

		public int count() {
			int ct = 0;
			for (int u : upper)
				if (u < 0)
					ct++;
			return ct;
		}
	}


	public static ResultCluster cluster(int[] f)
	{
		int n = f.length;
		DJSet ds = new DJSet(n);
		int[] red = new int[n+1];
		int p = 0;
		for(int i = 0;i < n;i++){
			if(ds.union(i, f[i]))red[p++] = f[i];
		}
		int[] clus = new int[n]; Arrays.fill(clus, -1);
		int cidgen = 0;
		for(int i = 0;i < n;i++)if(ds.upper[i] < 0)clus[i] = cidgen++;
		for(int i = 0;i < n;i++)clus[i] = clus[ds.root(i)];

		int[][] cycles = new int[p][];
		int[] temp = new int[n+1];
		for(int i = 0;i < p;i++){
			temp[0] = red[i];
			int j = 1;
			for(;;j++){
				temp[j] = f[temp[j-1]];
				if(temp[j] == temp[0])break;
			}
			cycles[clus[red[i]]] = Arrays.copyOf(temp, j);
		}
		ResultCluster rc = new ResultCluster();
		rc.clus = clus;
		rc.cycles = cycles;
		return rc;
	}

	public static class ResultCluster {
		int[] clus;
		int[][] cycles;
	}


