    static int dfs(int p, List<int>[] chld, bool[] inloop, int[] num) {
        if (num[p] >= 0) return num[p];

        var lis = new List<int>();
        foreach (var item in chld[p])
        {
            if (!inloop[item]) {
                lis.Add(dfs(item, chld, inloop, num));
            }
        }
        if (lis.Count == 0) {
            return num[p] = 0;
        }
        lis.Sort();
        if (lis[0] != 0) {
            return num[p] = 0;
        }
        for (int i = 0; i < lis.Count - 1; i++)
        {
            if (lis[i] + 1 < lis[i + 1]) {
                return num[p] = lis[i] + 1;
            }
        }
        return num[p] = lis[lis.Count - 1] + 1;
    }

