                    }
                }
                if (nenum[ili] == lis[lis.Count - 1] + 1) {
                    DBG("POSSIBLE");
                    return;
                }
            }
        }
        {
            int ss = ili;
            var nenum = new int[n];
            for (int i = 0; i < n; i++)
            {
                nenum[i] = num[i];
            }
            ++nenum[ili];
            while (par[ss] != ili)
            {
                ss = par[ss];
                var lis = new List<int>();
                foreach (var item in chld[ss])
                {
                    lis.Add(nenum[item]);
                }
                lis.Sort();
                if (lis[0] != 0) {
                    nenum[ss] = 0;
                    continue;
                }
                for (int i = 0; i < lis.Count - 1; i++)
                {
                    if (lis[i] + 1 < lis[i + 1]) {
                        nenum[ss] = lis[i] + 1;
                        goto A;
                    }
                }
                nenum[ss] = lis[lis.Count - 1] + 1;
                A:
                continue;
            }
            {
                var lis = new List<int>();
                foreach (var item in chld[ili])
                {
                    lis.Add(nenum[item]);
                }
                lis.Sort();
                if (lis[0] != 0) {
                    if (nenum[ili] == 0) {
                        DBG("POSSIBLE");
                        return;
                    }
                }
                for (int i = 0; i < lis.Count - 1; i++)
                {
                    if (lis[i] + 1 < lis[i + 1]) {
                        if (nenum[ili] == lis[i] + 1) {
                            DBG("POSSIBLE");
                            return;
                        }
                    }
                }
                if (nenum[ili] == lis[lis.Count - 1] + 1) {
                    DBG("POSSIBLE");
                    return;
                }
            }
        }
        Prt("IMPOSSIBLE");
        sw.Flush();
    }
    static int dfs(int p, List<int>[] chld, bool[] inloop, int[] num) {
        if (num[p] >= 0) return num[p];

        var lis = new List<int>();
        foreach (var item in chld[p])
        {
            if (!inloop[item]) {
                lis.Add(dfs(item, chld, inloop, num));
            }
        }
        if (lis.Count == 0) {
            return num[p] = 0;
        }
        lis.Sort();
        if (lis[0] != 0) {
            return num[p] = 0;
        }
        for (int i = 0; i < lis.Count - 1; i++)
        {
            if (lis[i] + 1 < lis[i + 1]) {
                return num[p] = lis[i] + 1;
            }
        }
        return num[p] = lis[lis.Count - 1] + 1;
    }

