class SCC {

	// Mem: component number for each vertice;
	// Compo: num of Component
	public int[] Mem;
	public int Compo;

	public List<int>[] E;
	public List<int>[] XE;
	public int N;

	public void Init(int n,List<int>[] e, List<int>[] xe, bool deepCopy = false){
		N = n;
		Mem = new int[N];
		if(!deepCopy){
			E = e;
			XE = xe;
			return;
		}

		E = new List<int>[N];
		XE = new List<int>[N];
		for(int i=0;i<N;i++){
			E[i] = new List<int>(e[i]);
			XE[i] = new List<int>(xe[i]);
		}
	}

	public void CalcCompo(){

		used = new bool[N];
		vs = new List<int>();
		for(int i=0;i<N;i++){
			if(!used[i]) dfs(i);
		}

		used = new bool[N];
		int k = 0;
		for(int i=vs.Count-1;i>=0;i--){
			if(!used[vs[i]]) rdfs(vs[i], k++);
		}

		Compo = k;
	}

	bool[] used;
	List<int> vs;

	void dfs(int now){
		used[now] = true;
		foreach(var nxt in E[now]){
			if(!used[nxt]) dfs(nxt);
		}
		vs.Add(now);
	}

	void rdfs(int now, int k){
		used[now] = true;
		Mem[now] = k;
		foreach(var nxt in XE[now]){
			if(!used[nxt]) rdfs(nxt, k);
		}
	}

}

