                    lis.Add(nenum[item]);
                }
                lis.Sort();
                if (lis[0] != 0) {
                    nenum[ss] = 0;
                    continue;
                }
                for (int i = 0; i < lis.Count - 1; i++)
                {
                    if (lis[i] + 1 < lis[i + 1]) {
                        nenum[ss] = lis[i] + 1;
                        goto A;
                    }
                }
                nenum[ss] = lis[lis.Count - 1] + 1;
                A:
                continue;
            }
            {
                var lis = new List<int>();
                foreach (var item in chld[ili])
                {
                    lis.Add(nenum[item]);
                }
                lis.Sort();
                if (lis[0] != 0) {
                    if (nenum[ili] == 0) {
                        DBG("POSSIBLE");
                        return;
                    }
                }
                for (int i = 0; i < lis.Count - 1; i++)
                {
                    if (lis[i] + 1 < lis[i + 1]) {
                        if (nenum[ili] == lis[i] + 1) {
                            DBG("POSSIBLE");
                            return;
                        }
                    }
                }
                if (nenum[ili] == lis[lis.Count - 1] + 1) {
                    DBG("POSSIBLE");
