class Solve{
    List<int>[] G;
    List<int>[] G2;
    bool[] b;
    int[] grundy;
    int cycle1 = 0;
    int cycle2 = 0;
    public Solve(){}
    StringBuilder sb;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = int.Parse(Console.ReadLine());
        string[] str = Console.ReadLine().Split(' ');
        int[] A = new int[N];
        for(int i=0;i<N;i++){
            A[i] = int.Parse(str[i])-1;
        }
        G = new List<int>[N];
        G2 = new List<int>[N];
        for(int i=0;i<N;i++){
            G[i] = new List<int>();
            G2[i] = new List<int>();
        }
        for(int i=0;i<N;i++){
            G[A[i]].Add(i);
            G2[A[i]].Add(i);
            G2[i].Add(A[i]);
        }
        b = new bool[N];
        GetCycle(0,-1);
        grundy = new int[N];
        b = new bool[N];
        for(int i=0;i<N;i++){
            if(!b[i]){
                dfs(i,-1);
            }
        }
        sb.Append(grundy[cycle1] == grundy[cycle2] ? "IMPOSSIBLE\n" : "POSSIBLE\n");
    }
    void GetCycle(int v,int f){
        b[v] = true;
        for(int i=0;i<G2[v].Count;i++){
            int t = G2[v][i];
            if(!b[t]){
                GetCycle(t,v);
            }
            else if(t != f){
                cycle1 = v;
                cycle2 = t;
            }
        }
    }
    int dfs(int v,int f){
        Heap H = new Heap(G[v].Count+1);
        for(int i=0;i<G[v].Count;i++){
            int t = G[v][i];
            if((t == cycle1 && v == cycle2) || (t == cycle2 && v == cycle1)){
                continue;
            }
            else{
                if(!b[t]){
                    dfs(t,v);
                }
                H.push(grundy[t]);
            }
        }
        int c = 0;
        int p = -1;
        while(H.size != 0){
            while(p < c){
                p = H.pop();
            }
            if(p == c){
                c++;
            }
            else{
                grundy[v] = c;
                return c;
            }
        }
        grundy[v] = c;
        return grundy[v];
    }
}
class Heap{
    public int size;
    int[] obj;
    public Heap(int maxsize){
        size = 0;
        obj = new int[maxsize];
    }
    public bool Compare(int a,int b){
        return a<=b;
    }
    public void push(int a){
        int i = size;
        size++;
        while(i > 0){
            int p = (i - 1)/2;
            if(Compare(obj[p],a)){
                obj[i] = a;
                break;
            }
            obj[i] = obj[p];
            i = p;
        }
        if(i == 0){
            obj[0] = a;
        }
    }
    public int pop(){
        int t = obj[0];
        int i = 0;
        size--;
        while(2*i+1 < size){
            int p = 2*i+1;
            if(p+1 < size && Compare(obj[p+1],obj[p])){
                p++;
            }
            if(Compare(obj[p],obj[size])){
                obj[i] = obj[p];
                i = p;
            }
            else{
                obj[i] = obj[size];
                break;
            }
        }
        if(2*i+1 >= size){
            obj[i] = obj[size];
        }
        return t;
    }
}

