    if !vis[i] && dfs1(i) { break }
  }
  c = c[:len(c)-1]
  a[c[0]] = n
  if dfs2(c[0]) != a[c[1]] { fmt.Println("POSSIBLE");return }
  for i:=0;i<n;i++ {
    if i == c[0] { continue }
    a[i] = -1
  }
