  }
}

func dfs1(u int) bool {
  vis[u],act[u] = true,true
  for _,v := range g[u] {
    if act[v] {
      c = append(c,v)
      c = append(c,u)
      isc[u],isc[v] = true,true
      return true
    }
    if dfs1(v) {
      if isc[v] && (len(c) == 0 || (len(c) > 0 && v != c[0])) {
        c = append(c,u)
        isc[u] = true
        return true
      }
    }
  }
  act[u] = false
  return false
}

func dfs2(u int) int {
  b := []int{0,INF}
  for _,v := range g[u] {
    if a[v] == -1 { b = append(b,dfs2(v));continue }
    b = append(b,a[v])
  }
  sort.Ints(b)
  for i:=0;;i++ {
    if b[i+1] > b[i]+1 {
      a[u] = b[i]+1
      return a[u]
    }
  }
}

