	N := next.Int()
	g, G, h := make([][]int, N), make([][]int, N), make([]int, N)
	for i := 0; i < N; i++ {
		p := next.Int() - 1

		g[p] = append(g[p], i)
		G[i] = append(G[i], p)
		h[p] += 1
	}

	qu := NewQueue()
	for i := 0; i < N; i++ {
		if h[i] == 0 {
			qu.push(i)
		}
	}

	x := make([]int, N)
	foot := make([]bool, N)
	for !qu.empty() {
		p := qu.frontInt()
		qu.pop()

		foot[p] = true
		mp := make(map[int]bool)

		for to := range g[p] {
			mp[x[to]] = true
		}

		x[p] = 0
		for k, _ := range mp {
			if k != x[p] {
				break
			}

			x[p] += 1
		}

		for to := range G[p] {
			h[to] -= 1

			if h[to] == 0 {
				qu.push(to)
			}
		}
	}

	latte := make([]int, 0)
	mp := make(map[int]bool)
	for i := 0; i < N; i++ {
		if !foot[i] {
			latte = append(latte, i)
		}
	}

	for v := range latte {
