        bool ok = true;
        foreach (i; 0..N) if (B[n] == -1 || G[n].map!(m => B[n] == B[m]).any) ok = false;
        return ok;
    }

    writeln((solve(n, p1) || solve(n, p2)) ? "POSSIBLE" : "IMPOSSIBLE");
