        foreach (i; 0..N) {
            foreach (j; G[i]) 
                if (A[i] == A[j]) 
                    return false;
            auto m = mex(G[i].map!(j => A[j]).array.sort().uniq().array);
            if (m != A[i])
                return false;
        }
