import std.stdio;
import std.string;
import std.conv;
import std.typecons;
import std.algorithm;
import std.functional;
import std.bigint;
import std.numeric;
import std.array;
import std.math;
import std.range;
import std.container;
import std.ascii;
import std.concurrency;

const int INF = int.max/3;
class Vertex{
    Edge[] es;
    Edge rev;
    int a = INF;
    bool visited = false;
    bool hasLoop = false;
}
struct Edge{
    Vertex s, g;
}
void main() {
    int N = readln.chomp.to!int;
    Vertex[] vs = N.rep!(() => new Vertex);
    readln.split.to!(int[]).map!"a-1".enumerate.each!(
        (a) {
            vs[a.value].es ~= Edge(vs[a.value], vs[a.index]);
            vs[a.index].rev = Edge(vs[a.value], vs[a.index]);
        }
    );

    Vertex po;

    int f(Vertex v, Vertex root) {
        if (v.visited) return v.a;

        v.visited = true;
        auto tree = redBlackTree!("a<b", false, int);
        foreach(e; v.es) {
            if (e.g is root) {
                tree.insert(-1);
            } else {
                tree.insert(f(e.g, root));
            }
        }
        if (tree.empty) {
            return v.a = 0;
        } else if (tree.front < 0) {
            po = v;
            v.hasLoop = true;
            return v.a = -1;
        } else {
            foreach(n; 0..v.es.length+1) {
                if (n == tree.front) {
                    tree.removeFront;
                } else {
                    return v.a = n.to!int;
                }
            }
            assert(false);
        }
    }
    vs.each!(v => f(v, v));

    assert(po !is null && po.hasLoop);

    int g(Vertex v, int k=0) {
        auto tree = redBlackTree!("a<b", false, int);
        foreach(e; v.es) {
            if (e.g.a>=0) tree.insert(e.g.a);
        }
        foreach(n; 0..v.es.length+2) {
            if (!tree.empty && n == tree.front) {
                tree.removeFront;
            } else {
                if (k--==0) return n.to!int;
                if (!tree.empty)tree.removeFront;
            }
        }
        assert(false);
    }

    2.iota.map!(i => g(po, i)).array.any!(
        (n) {
            po.a = n;
            bool h(Vertex v) {
                if (v is po) {
                    return g(v) == po.a;
                } else {
                    v.a = g(v);
                    return h(v.rev.s);
                }
            }
            return h(po.rev.s);
        }
    ).pipe!(flg => flg?"POSSIBLE":"IMPOSSIBLE").writeln;
}

