void times(alias fun)(int n) {
    // n.iota.each!(i => fun());
    foreach(i; 0..n) fun();
}
auto rep(alias fun, T = typeof(fun()))(int n) {
    // return n.iota.map!(i => fun()).array;
    T[] res = new T[n];
    foreach(ref e; res) e = fun();
    return res;
}

// fold was added in D 2.071.0
static if (__VERSION__ < 2071) {
    template fold(fun...) if (fun.length >= 1) {
        auto fold(R, S...)(R r, S seed) {
            static if (S.length < 2) {
                return reduce!fun(seed, r);
            } else {
                return reduce!fun(tuple(seed), r);
            }
        }
    }
}

// cumulativeFold was added in D 2.072.0
static if (__VERSION__ < 2072) {
    template cumulativeFold(fun...)
    if (fun.length >= 1)
    {
        import std.meta : staticMap;
        private alias binfuns = staticMap!(binaryFun, fun);

        auto cumulativeFold(R)(R range)
        if (isInputRange!(Unqual!R))
        {
            return cumulativeFoldImpl(range);
        }

        auto cumulativeFold(R, S)(R range, S seed)
        if (isInputRange!(Unqual!R))
        {
            static if (fun.length == 1)
                return cumulativeFoldImpl(range, seed);
            else
                return cumulativeFoldImpl(range, seed.expand);
        }

        private auto cumulativeFoldImpl(R, Args...)(R range, ref Args args)
        {
            import std.algorithm.internal : algoFormat;

            static assert(Args.length == 0 || Args.length == fun.length,
                algoFormat("Seed %s does not have the correct amount of fields (should be %s)",
                    Args.stringof, fun.length));

            static if (args.length)
                alias State = staticMap!(Unqual, Args);
            else
                alias State = staticMap!(ReduceSeedType!(ElementType!R), binfuns);

            foreach (i, f; binfuns)
            {
                static assert(!__traits(compiles, f(args[i], e)) || __traits(compiles,
                        { args[i] = f(args[i], e); }()),
                    algoFormat("Incompatible function/seed/element: %s/%s/%s",
                        fullyQualifiedName!f, Args[i].stringof, E.stringof));
            }

            static struct Result
            {
            private:
                R source;
                State state;

                this(R range, ref Args args)
                {
                    source = range;
                    if (source.empty)
                        return;

                    foreach (i, f; binfuns)
                    {
                        static if (args.length)
                            state[i] = f(args[i], source.front);
                        else
                            state[i] = source.front;
                    }
                }

            public:
                @property bool empty()
                {
                    return source.empty;
                }

                @property auto front()
                {
                    assert(!empty, "Attempting to fetch the front of an empty cumulativeFold.");
                    static if (fun.length > 1)
                    {
                        import std.typecons : tuple;
                        return tuple(state);
                    }
                    else
                    {
                        return state[0];
                    }
                }

                void popFront()
                {
                    assert(!empty, "Attempting to popFront an empty cumulativeFold.");
                    source.popFront;

                    if (source.empty)
                        return;

                    foreach (i, f; binfuns)
                        state[i] = f(state[i], source.front);
                }

                static if (isForwardRange!R)
                {
                    @property auto save()
                    {
                        auto result = this;
                        result.source = source.save;
                        return result;
                    }
                }

                static if (hasLength!R)
                {
                    @property size_t length()
                    {
                        return source.length;
                    }
                }
            }

            return Result(range, args);
        }
    }
}

// minElement/maxElement was added in D 2.072.0
static if (__VERSION__ < 2072) {
    auto minElement(alias map, Range)(Range r)
    if (isInputRange!Range && !isInfinite!Range)
    {
        alias mapFun = unaryFun!map;
        auto element = r.front;
        auto minimum = mapFun(element);
        r.popFront;
        foreach(a; r) {
            auto b = mapFun(a);
            if (b < minimum) {
                element = a;
                minimum = b;
            }
        }
        return element;
    }
    auto maxElement(alias map, Range)(Range r)
    if (isInputRange!Range && !isInfinite!Range)
    {
        alias mapFun = unaryFun!map;
        auto element = r.front;
        auto maximum = mapFun(element);
        r.popFront;
        foreach(a; r) {
            auto b = mapFun(a);
            if (b > maximum) {
                element = a;
                maximum = b;
            }
        }
        return element;
    }
}

import std.stdio, std.array, std.string, std.conv, std.algorithm;
import std.typecons, std.range, std.random, std.math, std.container;
import std.numeric, std.bigint, core.bitop, std.bitmanip;

void main() {
    auto N = readln.chomp.to!int;
    auto P = readln.split.map!(to!int).array;
    auto G = new int[][](N);
    auto H = new int[][](N);
    foreach (i; 0..N) G[P[i]-1] ~= i, H[i] ~= P[i]-1;
    auto D = N.iota.map!(i => G[i].length.to!int).array;
    auto A = new int[](N);
    A.fill(-1);

    auto stack = N.iota.filter!(i => D[i] == 0).array;
    while (!stack.empty) {
        auto n = stack.back;
        stack.popBack;
        A[n] = G[n].length.to!int;
        foreach (m; H[n]) {
            D[m] -= 1;
            if (D[m] == 0) stack ~= m;
        }
    }

    foreach (i; 0..N) {
        int[] to_remove;
        foreach (j; 0..G[i].length) if (A[G[i][j]] != -1) to_remove ~= j.to!int;
        foreach_reverse (j; to_remove) G[i].remove(j);
    }

    int n = -1;
    foreach (i; 0..N) if (A[i] == -1) n = i;

    if (n == -1) {
        writeln("POSSIBLE");
        return;
    }

    auto mex = G[n].map!(m => A[m]).array;
    mex = mex.filter!(m => m != -1).array;
    mex.sort();
    int p1 = 0;
    while (p1 < mex.length && mex[p1] == p1) ++p1;
    mex ~= p1;
    mex.sort();
    int p2 = 0;
    while (p2 < mex.length && mex[p2] == p2) ++p2;

    bool solve(int root, int x) {
        auto B = A.dup;
        auto E = D.dup;
        B[root] = x;
        E[root] = 0;
        int[] stack;
        foreach (m; H[root]) {
            if (E[m] == 0) continue;
            E[m] -= 1;
            if (E[m] == 0) stack ~= m;
        }

        while (!stack.empty) {
            auto n = stack.back;
            stack.popBack;
            auto mex = G[n].map!(m => B[m]).array;
            mex = mex.sort().uniq().array;
            int p = 0;
            while (p < mex.length && mex[p] == p) p++;
            B[n] = p;
            foreach (m; H[n]) {
                if (E[m] == 0) continue;
                E[m] -= 1;
                if (E[m] == 0) stack ~= m;
            }
        }

        bool ok = true;
        foreach (i; 0..N) if (B[n] == -1 || G[n].map!(m => B[n] == B[m]).any) ok = false;
        return ok;
    }

    writeln((solve(n, p1) || solve(n, p2)) ? "POSSIBLE" : "IMPOSSIBLE");
}

import strutils
