use std::collections::{BTreeSet, VecDeque};

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let mut graph = vec![vec![]; n];
    let mut parent = vec![0; n];
    for i in 0..n {
        let p = sc.read::<usize>() - 1;
        graph[p].push(i);
        parent[i] = p;
    }

    let mut q = VecDeque::new();
    let mut a = vec![-1; n];
    for i in 0..n {
        let is_leaf = graph[i].is_empty();
        if is_leaf {
            q.push_back(i);
            a[i] = 0;
        }
    }

    let mut reach = vec![0; n];
    while let Some(v) = q.pop_front() {
        let parent = parent[v];
        reach[parent] += 1;
        if reach[parent] == graph[parent].len() {
            let children = graph[parent]
                .iter()
                .map(|&child| a[child])
                .collect::<BTreeSet<_>>();
            a[parent] = (0..).find(|&a| !children.contains(&a)).unwrap();
            q.push_back(parent);
        }
    }

    let v = (0..n).find(|&i| a[i] == -1).unwrap();
    let v_children = graph[v]
        .iter()
        .filter(|&&i| a[i] != -1)
        .map(|&i| a[i])
        .collect::<BTreeSet<_>>();
    let candidates = (0..)
        .filter(|&i| !v_children.contains(&i))
        .take(2)
        .collect::<Vec<_>>();

    for candidate in candidates.into_iter() {
        a[v] = candidate;
        let mut cur = parent[v];
        while cur != v {
            let children = graph[cur].iter().map(|&i| a[i]).collect::<BTreeSet<_>>();
            a[cur] = (0..).find(|&i| !children.contains(&i)).unwrap();
            cur = parent[cur];
        }
        let check = graph[v].iter().map(|&i| a[i]).collect::<BTreeSet<_>>();
        if !check.contains(&a[v]) {
            println!("POSSIBLE");
            return;
        }
    }
    println!("IMPOSSIBLE");
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write_all(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

