fn get_grundy_number(from: usize, graph: &Graph, grundy: &Vec<i32>) -> i32 {
    let mut childs = vec![];
    for edge in graph[from].iter() {
        if grundy[edge.dest] == -1 {
            continue;
        }
        childs.push(grundy[edge.dest]);
    }
    childs.sort();
    childs.dedup();
    for i in 0..childs.len() {
        if childs[i] != i as i32 {
            return i as i32;
        }
    }
    childs.len() as i32
}

fn naive(graph: &Graph, rev_graph: &Graph, grundy: &mut Vec<i32>) {
    let n = graph.len();
    let mut cnts = vec![0; n];
    let mut stack = vec![];
    for i in 0..n {
        if grundy[i] != -1 {
            continue;
        }
        for edge in graph[i].iter() {
            if grundy[edge.dest] != -1 {
                continue;
            }
            cnts[i] += 1;
        }
        if cnts[i] == 0 {
            stack.push(i);
        }
    }
    while let Some(from) = stack.pop() {
        grundy[from] = get_grundy_number(from, &graph, &grundy);
        for edge in rev_graph[from].iter() {
            let to = edge.dest;
            if grundy[to] != -1 {
                continue;
            }
            cnts[to] -= 1;
            if cnts[to] == 0 {
                stack.push(to);
            }
        }
    }
}

fn get_target(grundy: &Vec<i32>) -> Option<usize> {
    let n = grundy.len();
    for i in 0..n {
        if grundy[i] == -1 {
            return Some(i);
        }
    }
    None
}

fn valid(graph: &Graph, grundy: &Vec<i32>) -> bool {
    let n = graph.len();
    for i in 0..n {
        if grundy[i] == -1 || grundy[i] != get_grundy_number(i, graph, grundy) {
            return false;
        }
    }
    true
}

