    dep[u] = d;
    for i in 0..e[u].len() {
        let to = e[u][i];
        if p == to {
            continue;
        }
        dfs(e, to, u, dep, d + 1);
    }
}
fn get_path(e: &Vec<Vec<usize>>, u: usize, v: usize, n: usize) -> Vec<usize> {
    let mut d = vec![0; n];
    dfs(e, u, n, &mut d, 0);
    let mut path = vec![];
    let mut p = v;
    path.push(p);
    while p != u {
        for i in 0..e[p].len() {
            let to = e[p][i];
            if d[p] > d[to] {
                p = to;
                break;
            }
        }
        path.push(p);
    }
    path
}
