fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };

    let n = sc.read();
    let mut graph = vec![vec![]; n];
    let mut parents = vec![0; n];
    for i in 0..n {
        let p = sc.read::<usize>() - 1;
        graph[p].push(i);
        parents[i] = p;
    }

    let mut vis = vec![false; n];
    let mut cur = 0;
    loop {
        if vis[cur] {
            break;
        }
        vis[cur] = true;
        cur = parents[cur];
    }

    let mut is_cycle = vec![false; n];
    loop {
        if is_cycle[cur] {
            break;
        }
        is_cycle[cur] = true;
        cur = parents[cur];
    }

    let mut grundy = vec![n; n];
    for i in 0..n {
        if is_cycle[i] {
            for &next in graph[i].iter() {
                if !is_cycle[next] {
                    dfs(next, &graph, &mut grundy);
                }
            }
        }
    }

    let mut first = n;
    for i in 0..n {
        if is_cycle[i] {
            first = i;
            break;
        }
    }
    let second = parents[first];

    if solve(first, grundy.clone(), &parents, &graph) || solve(second, grundy, &parents, &graph) {
        println!("POSSIBLE");
    } else {
        println!("IMPOSSIBLE");
    }
}

fn solve(v: usize, mut grundy: Vec<usize>, parents: &Vec<usize>, graph: &Vec<Vec<usize>>) -> bool {
    let mut cur = v;
    loop {
        let mut set = BTreeSet::new();
        for &next in graph[cur].iter() {
            set.insert(grundy[next]);
        }
        for i in 0.. {
            if !set.contains(&i) {
                grundy[cur] = i;
                break;
            }
        }
        cur = parents[cur];
        if cur == v {
            break;
        }
    }
    let mut set = BTreeSet::new();
    for &next in graph[v].iter() {
        set.insert(grundy[next]);
    }
    for i in 0.. {
        if !set.contains(&i) {
            if grundy[v] == i {
                return true;
            } else {
                return false;
            }
        }
    }
    unreachable!()
}

fn dfs(v: usize, graph: &Vec<Vec<usize>>, grundy: &mut Vec<usize>) {
    let mut set = BTreeSet::new();
    for &next in graph[v].iter() {
        dfs(next, graph, grundy);
        set.insert(grundy[next]);
    }
    for i in 0.. {
        if set.contains(&i) {
            continue;
        }
        grundy[v] = i;
        break;
    }
}

