    next_nums.sort();
    let mut grundy = 0;
    for &num in next_nums.iter() {
        if grundy == num {
            grundy += 1;
        }
    }
    grundy
}

fn dfs(v: usize, graph: &Vec<Vec<usize>>, num: &mut Vec<usize>, is_cycle: &Vec<bool>) -> usize {
