        .iter()
        .filter(|&&next| !is_cycle[next])
        .map(|&next| dfs(next, graph, num, is_cycle))
        .collect();
    next_nums.sort();

    let mut cur = 0;
    for &next_num in next_nums.iter() {
        if cur == next_num {
