    let mut graph = vec![vec![]; n];
    let mut inverted = vec![0; n];
    for i in 0..n {
        let from = p[i] - 1;
        let to = i;
        graph[from].push(to);
        inverted[to] = from;
    }

    let mut path = vec![];
    let mut visit = vec![false; n];
    let mut cur = (0..n).filter(|&i| graph[i].is_empty()).next().unwrap_or(0);
    path.push(cur);
    visit[cur] = true;
    loop {
        cur = inverted[cur];

        if visit[cur] {
            path = path
                .iter()
                .rev()
                .take_while(|&&v| v != cur)
                .map(|&v| v)
                .collect::<Vec<_>>();
            path.push(cur);
            break;
        }

        path.push(cur);
        visit[cur] = true;
    }

    let mut in_cycle = vec![false; n];
    for &p in path.iter() {
        in_cycle[p] = true;
    }
    let trees: Vec<Vec<usize>> = graph
        .iter()
        .map(|nexts| {
            nexts
                .iter()
                .filter(|&&next| !in_cycle[next])
                .map(|&next| next)
                .collect()
        })
        .collect();

    let mut num = vec![INF; n];
    for &c in path.iter() {
        dfs(c, &trees, &mut num);
    }
    adjust(&path, &mut num);
