}

fn validate(v: usize, graph: &Vec<Vec<usize>>, num: &Vec<usize>) -> bool {
    let mut checked = vec![false; num[v]];
    for &next in graph[v].iter() {
        if num[next] == num[v] {
            return false;
        }
        if checked.len() < num[next] {
            continue;
        }
        checked[num[next]] = true;
    }
    checked.iter().all(|&b| b)
}

fn adjust(path: &Vec<usize>, num: &mut Vec<usize>) {
    let n = path.len();
    for i in (0..n).rev() {
        let (i, j) = (path[(n + i - 1) % n], path[i]);
        if num[i] == num[j] {
            num[i] += 1;
        }
    }
}

fn dfs(v: usize, graph: &Vec<Vec<usize>>, num: &mut Vec<usize>) {
    if graph[v].is_empty() {
        num[v] = 0;
        return;
    }
    for &next in graph[v].iter() {
        dfs(next, graph, num);
    }
    let mut nexts = graph[v].iter().map(|&next| num[next]).collect::<Vec<_>>();
    nexts.sort();
    let mut cur = 0;
    for &next in nexts.iter() {
        if cur == next {
            cur += 1;
        } else if cur < next {
            num[v] = cur;
            return;
        }
    }
    num[v] = cur;
}

