fn dfs(e: &Vec<Vec<usize>>, u: usize, p: usize, dep: &mut Vec<usize>, d: usize) {
    dep[u] = d;
    for i in 0..e[u].len() {
        let to = e[u][i];
        if p == to {
            continue;
        }
        dfs(e, to, u, dep, d + 1);
    }
}
fn get_path(e: &Vec<Vec<usize>>, u: usize, v: usize, n: usize) -> Vec<usize> {
    let mut d = vec![0; n];
    dfs(e, u, n, &mut d, 0);
    let mut path = vec![];
    let mut p = v;
    path.push(p);
    while p != u {
        for i in 0..e[p].len() {
            let to = e[p][i];
            if d[p] > d[to] {
                p = to;
                break;
            }
        }
        path.push(p);
    }
    path
}
fn dfs2(e: &Vec<Vec<usize>>, u: usize, val: &mut Vec<usize>, cycle: &Vec<bool>, n: usize) -> usize {
    let mut v = vec![false; n];
    for i in 0..e[u].len() {
        let to = e[u][i];
        if cycle[to] {
            continue;
        }
        v[dfs2(e, to, val, cycle, n)] = true;
    }
    let mut h = 0;
    for i in 0..n {
        if !v[i] {
            val[u] = i;
            h = i;
            break;
        }
    }
    h
}
fn dfs3(
    e: &Vec<Vec<usize>>,
    u: usize,
    val: &mut Vec<usize>,
    cycle: &Vec<bool>,
    n: usize,
    last: usize,
) -> usize {
    let mut v = vec![false; n];
    for i in 0..e[u].len() {
        let to = e[u][i];
        if cycle[to] && to != last {
            v[dfs3(e, to, val, cycle, n, last)] = true;
        } else {
            v[val[to]] = true;
        }
    }
    //println!("{} visited", u);
    let mut h = 0;
    for i in 0..n {
        if !v[i] {
            val[u] = i;
            h = i;
            break;
        }
    }
    h
}
