    let mut flag = true;
    for i in 0..n {
        let mut v = vec![false; val[i]];
        let mut cnt = 0;
        for j in 0..e[i].len() {
            if val[i] == val[e[i][j]] {
                flag = false;
            }
            if val[i] > val[e[i][j]] && !v[val[e[i][j]]] {
                cnt += 1;
            }
        }
        if cnt != val[i] {
            flag = false;
            break;
        }
    }
    flag
}

