    rank: Vec<usize>,
    count: Vec<usize>,
}
#[allow(dead_code)]
impl UFind {
    pub fn new(n: usize) -> UFind {
        let mut par = vec![0; n];
        for i in 0..n {
            par[i] = i;
        }
        UFind {
            n: n,
            par: par,
            rank: vec![0; n],
            count: vec![1; n],
        }
    }

    pub fn find(&mut self, x: usize) -> usize {
        if self.par[x] == x {
            x
        } else {
            let par = self.par[x];
            let find = self.find(par);
            self.par[x] = find;
            find
        }
    }
    fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }
    fn size(&mut self, a: usize) -> usize {
        let b = self.find(a);
        self.count[b]
    }
    fn unite(&mut self, a: usize, b: usize) {
        let _a = self.find(a);
        let _b = self.find(b);
        if self.rank[_a] > self.rank[_b] {
            self.par[_b] = _a;
            self.count[_a] += self.count[_b];
        } else {
            self.par[_a] = _b;
            self.count[_b] += self.count[_a];
            if self.rank[_a] == self.rank[_b] {
                self.rank[_b] += 1;
            }
        }
    }
}

