    }

    let mut leaf = n;
    for i in 0..n {
        if graph[i].is_empty() {
            leaf = i;
            break;
        }
    }

    if leaf == n {
        // big one cycle
        if n % 2 == 0 {
            println!("POSSIBLE");
        } else {
            println!("IMPOSSIBLE");
        }
        return;
    }

    let mut vis = vec![false; n];
    vis[leaf] = true;
    let mut cur = parents[leaf];
    loop {
        if vis[cur] {
            break;
        }
        vis[cur] = true;
        cur = parents[cur];
    }

    let mut is_cycle = vec![false; n];
    loop {
        if is_cycle[cur] {
            break;
        }
        is_cycle[cur] = true;
        cur = parents[cur];
    }

    let mut grundy = vec![n; n];
    for i in 0..n {
        if is_cycle[i] {
            for &next in graph[i].iter() {
                if !is_cycle[next] {
                    dfs(next, &graph, &mut grundy);
                }
            }
        }
    }

    let mut first = n;
    for i in 0..n {
        if is_cycle[i] {
            first = i;
