fn solve(v: usize, mut grundy: Vec<usize>, parents: &Vec<usize>, graph: &Vec<Vec<usize>>) -> bool {
    let mut cur = v;
    loop {
        let mut set = BTreeSet::new();
        for &next in graph[cur].iter() {
            set.insert(grundy[next]);
        }
        for i in 0.. {
            if !set.contains(&i) {
                grundy[cur] = i;
                break;
            }
        }
        cur = parents[cur];
        if cur == v {
            break;
        }
    }
    let mut set = BTreeSet::new();
    for &next in graph[v].iter() {
        set.insert(grundy[next]);
    }
    for i in 0.. {
        if !set.contains(&i) {
            if grundy[v] == i {
                return true;
            } else {
                return false;
            }
        }
    }
    unreachable!()
}

fn dfs(v: usize, graph: &Vec<Vec<usize>>, grundy: &mut Vec<usize>) {
    let mut set = BTreeSet::new();
    for &next in graph[v].iter() {
        dfs(next, graph, grundy);
        set.insert(grundy[next]);
    }
    for i in 0.. {
        if set.contains(&i) {
            continue;
        }
        grundy[v] = i;
        break;
    }
}

