            for &next in graph[i].iter() {
                if !is_cycle[next] {
                    dfs(next, &graph, &mut grundy);
                }
            }
        }
    }

    let head = is_cycle
        .iter()
        .enumerate()
        .filter(|&(_, &is_cycle)| is_cycle)
        .map(|(v, _)| v)
        .next()
        .unwrap();

    let set = graph[head]
        .iter()
        .map(|&next| grundy[next])
