fn solve(
    head: usize,
    grundy: &mut Vec<usize>,
    parents: &Vec<usize>,
    graph: &Vec<Vec<usize>>,
) -> bool {
    let mut cur = parents[head];
    while cur != head {
        let set = graph[cur]
            .iter()
            .map(|&next| grundy[next])
            .collect::<BTreeSet<usize>>();
        grundy[cur] = (0..).filter(|i| !set.contains(i)).next().unwrap();
        cur = parents[cur];
    }
    let set = graph[head]
        .iter()
        .map(|&next| grundy[next])
        .collect::<BTreeSet<usize>>();
    grundy[head] == (0..).filter(|i| !set.contains(i)).next().unwrap()
}

