}
#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let s = stdin
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect::<String>();
    s.parse::<T>().unwrap_or_else(
        |_| panic!("Faild to parse {}", s),
    )
}

use std::collections::BTreeSet;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };

    let n = sc.read();
    let p = (0..n).map(|_| sc.read::<usize>() - 1).collect::<Vec<_>>();
    let mut graph = vec![vec![]; n];
    for (i, &p) in p.iter().enumerate() {
        graph[p].push(i);
    }

    let mut is_cycle = vec![false; n];
    {
        let mut cur = 0;
        let mut vis = vec![false; n];
        while !vis[cur] {
            vis[cur] = true;
            cur = p[cur];
        }

        is_cycle[cur] = true;
        let mut x = p[cur];
        while x != cur {
            is_cycle[x] = true;
            x = p[x];
        }
    }

    let mut grundy = vec![0; n];
    for v in (0..n).filter(|&i| is_cycle[i]) {
        dfs(v, &mut grundy, &graph, &is_cycle);
    }

    let start = (0..n).filter(|&i| is_cycle[i]).next().unwrap();
    let mut start_set = graph[start]
        .iter()
        .filter(|&&next| !is_cycle[next])
        .map(|&next| grundy[next])
        .collect::<BTreeSet<_>>();
    grundy[start] = (0..)
        .skip_while(|&i| start_set.contains(&i))
        .next()
        .unwrap();
    let mut cur = p[start];
    while cur != start {
        let set = graph[cur]
            .iter()
            .map(|&next| grundy[next])
            .collect::<BTreeSet<_>>();
        grundy[cur] = (0..).skip_while(|&i| set.contains(&i)).next().unwrap();
        cur = p[cur];
    }

    {
        let set = graph[start]
            .iter()
            .map(|&next| grundy[next])
            .collect::<BTreeSet<_>>();
        if grundy[start] == (0..).skip_while(|&i| set.contains(&i)).next().unwrap() {
            println!("POSSIBLE");
            return;
        }
    }

    start_set.insert(grundy[start]);
    grundy[start] = (0..)
        .skip_while(|&i| start_set.contains(&i))
        .next()
        .unwrap();
    let mut cur = p[start];
    while cur != start {
        let set = graph[cur]
            .iter()
            .map(|&next| grundy[next])
            .collect::<BTreeSet<_>>();
        grundy[cur] = (0..).skip_while(|&i| set.contains(&i)).next().unwrap();
        cur = p[cur];
    }
    {
        let set = graph[start]
            .iter()
            .map(|&next| grundy[next])
            .collect::<BTreeSet<_>>();
        if grundy[start] == (0..).skip_while(|&i| set.contains(&i)).next().unwrap() {
            println!("POSSIBLE");
            return;
        }
    }
    println!("IMPOSSIBLE");
}

fn dfs(v: usize, grundy: &mut [usize], graph: &[Vec<usize>], is_cycle: &[bool]) {
    let next_grundy = graph[v]
        .iter()
        .filter(|&&next| !is_cycle[next])
        .map(|&next| {
            dfs(next, grundy, graph, is_cycle);
            grundy[next]
        })
        .collect::<BTreeSet<_>>();
    grundy[v] = (0..)
        .skip_while(|i| next_grundy.contains(&i))
        .next()
        .unwrap();
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

type Weight = i32;
#[allow(dead_code)]
#[derive(Clone, Debug, Eq, PartialEq)]
struct Edge {
    index: usize,
    src: usize,
    dest: usize,
    weight: Weight,
}
#[allow(dead_code)]
impl Edge {
    fn new(index: usize, src: usize, dest: usize, weight: Weight) -> Edge {
        Edge {
            index: index,
            src: src,
            dest: dest,
            weight: weight,
        }
    }
}
impl std::cmp::Ord for Edge {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        (self.weight, self.src, self.dest).cmp(&(other.weight, other.src, other.dest))
    }
}
impl std::cmp::PartialOrd for Edge {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
type Edges = Vec<Edge>;
type Graph = Vec<Edges>;
#[allow(dead_code)]
fn graph_new(n: usize) -> Graph {
    vec![vec![]; n]
}
#[allow(dead_code)]
fn add_bi_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    graph[dest].push(Edge::new(*index, dest, src, weight));
    *index += 1;
}
#[allow(dead_code)]
fn add_uni_edge(graph: &mut Graph, index: &mut usize, src: usize, dest: usize, weight: Weight) {
    graph[src].push(Edge::new(*index, src, dest, weight));
    *index += 1;
}

fn get_grundy_number(from: usize, graph: &Graph, grundy: &Vec<i32>, add_value: i32) -> i32 {
    let mut childs = vec![];
    if add_value != -1 {
        childs.push(add_value);
    }
    for edge in graph[from].iter() {
        if grundy[edge.dest] == -1 {
            continue;
        }
        childs.push(grundy[edge.dest]);
    }
    childs.sort();
    childs.dedup();
    for i in 0..childs.len() {
        if childs[i] != i as i32 {
            return i as i32;
        }
    }
    childs.len() as i32
}

fn naive(graph: &Graph, rev_graph: &Graph, grundy: &mut Vec<i32>) {
    let n = graph.len();
    let mut cnts = vec![0; n];
    let mut stack = vec![];
    for i in 0..n {
        if grundy[i] != -1 {
            continue;
        }
        for edge in graph[i].iter() {
            if grundy[edge.dest] != -1 {
                continue;
            }
            cnts[i] += 1;
        }
        if cnts[i] == 0 {
            stack.push(i);
        }
    }
    while let Some(from) = stack.pop() {
        grundy[from] = get_grundy_number(from, &graph, &grundy, -1);
        for edge in rev_graph[from].iter() {
            let to = edge.dest;
            if grundy[to] != -1 {
                continue;
            }
            cnts[to] -= 1;
            if cnts[to] == 0 {
                stack.push(to);
            }
        }
    }
}

fn get_target(grundy: &Vec<i32>) -> Option<usize> {
    let n = grundy.len();
    for i in 0..n {
        if grundy[i] == -1 {
            return Some(i);
        }
    }
    None
}

fn valid(graph: &Graph, grundy: &Vec<i32>) -> bool {
    let n = graph.len();
    for i in 0..n {
        if grundy[i] == -1 || grundy[i] != get_grundy_number(i, graph, grundy, -1) {
            return false;
        }
    }
    true
}

fn main() {
    let n = read::<usize>();
    let mut graph = graph_new(n);
    let mut rev_graph = graph_new(n);
    let mut e = 0;
    for i in 0..n {
        let from = read::<usize>() - 1;
        add_uni_edge(&mut graph, &mut e, from, i, 0);
        e -= 1;
        add_uni_edge(&mut rev_graph, &mut e, i, from, 0);
    }
    let mut grundy = vec![-1; n];
    naive(&graph, &rev_graph, &mut grundy);
    // println!("{:?}", grundy);
    let target = get_target(&grundy);
    if let Some(target) = target {
        let min_number = get_grundy_number(target, &graph, &grundy, -1);
        let next_number = get_grundy_number(target, &graph, &grundy, min_number);
        for &candidate in [min_number, next_number].iter() {
            let mut temp_grundy = grundy.clone();
            temp_grundy[target] = candidate;
            naive(&graph, &rev_graph, &mut temp_grundy);
            // println!("{:?}", temp_grundy);
            if valid(&graph, &temp_grundy) {
                println!("POSSIBLE");
                return;
            }
        }
    } else {
        println!("POSSIBLE");
        return;
    }
    println!("IMPOSSIBLE");
}
